NORMAS = {"actualizado":"2026-10-15","fuente":"Textos consolidados del BOE (www.boe.es), leídos con la herramienta web_fetch de la API de Anthropic; troceados por artículo con tools/ia/normas.mjs","normas":[{"id":"CC","nombre":"Código Civil","corto":"CC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","boe":"BOE-A-1889-4763","consolidacion":"2025-01-03","arts":540},{"id":"LISD","nombre":"Ley 29/1987, del Impuesto sobre Sucesiones y Donaciones","corto":"Ley 29/1987","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1987-28141","boe":"BOE-A-1987-28141","consolidacion":"2022-12-28","arts":40},{"id":"RISD","nombre":"Real Decreto 1629/1991, Reglamento del Impuesto sobre Sucesiones y Donaciones","corto":"RD 1629/1991","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1991-27678","boe":"BOE-A-1991-27678","consolidacion":"2023-04-05","arts":101},{"id":"TRLRHL","nombre":"Real Decreto Legislativo 2/2004, texto refundido de la Ley Reguladora de las Haciendas Locales","corto":"TRLRHL","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-4214","boe":"BOE-A-2004-4214","consolidacion":"2026-10-07","arts":7},{"id":"LGT","nombre":"Ley 58/2003, General Tributaria","corto":"LGT","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-23186","boe":"BOE-A-2003-23186","consolidacion":"2024-12-21","arts":3},{"id":"LH","nombre":"Ley Hipotecaria (Decreto de 8 de febrero de 1946)","corto":"LH","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1946-2453","boe":"BOE-A-1946-2453","consolidacion":"2025-01-03","arts":1},{"id":"RH","nombre":"Reglamento Hipotecario (Decreto de 14 de febrero de 1947)","corto":"RH","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1947-3843","boe":"BOE-A-1947-3843","consolidacion":"2020-11-26","arts":5},{"id":"AND","nombre":"Ley 5/2021, de 20 de octubre, de Tributos Cedidos de la Comunidad Autónoma de Andalucía","corto":"Ley andaluza 5/2021","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2021-17915","boe":"BOE-A-2021-17915","consolidacion":"2025-12-31","ccaa":"AND","arts":23},{"id":"MAD","nombre":"Decreto Legislativo 1/2010, de 21 de octubre, texto refundido de tributos cedidos de la Comunidad de Madrid","corto":"DLeg madrileño 1/2010","url":"https://www.boe.es/buscar/act.php?id=BOCM-m-2010-90068","boe":"BOCM-m-2010-90068","consolidacion":"2026-07-10","ccaa":"MAD","arts":11},{"id":"VAL","nombre":"Ley 13/1997, de 23 de diciembre, de la Generalitat Valenciana (tramo autonómico del IRPF y tributos cedidos)","corto":"Ley valenciana 13/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1998-8202","boe":"BOE-A-1998-8202","consolidacion":"2026-08-10","ccaa":"VAL","arts":7},{"id":"CAT","nombre":"Decreto Legislativo 1/2024, de 12 de marzo, libro sexto del Código tributario de Cataluña","corto":"DLeg catalán 1/2024","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2024-6951","boe":"BOE-A-2024-6951","consolidacion":"2026-05-22","ccaa":"CAT","arts":82}],"arts":[{"n":"CC","a":"657","t":"","x":"Los derechos a la sucesión de una persona se transmiten desde el momento de su muerte.","u":"#art657","c":"LIBRO TERCERO De los diferentes modos de adquirir la propiedad · TÍTULO III De las sucesiones Disposiciones generales"},{"n":"CC","a":"658","t":"","x":"La sucesión se defiere por la voluntad del hombre manifestada en testamento y, a falta de éste, por disposición de la ley. La primera se llama testamentaria, y la segunda, legítima. Podrá también deferirse en una parte por voluntad del hombre, y en otra por disposición de la ley.","u":"#art658","c":"LIBRO TERCERO De los diferentes modos de adquirir la propiedad · TÍTULO III De las sucesiones Disposiciones generales"},{"n":"CC","a":"659","t":"","x":"La herencia comprende todos los bienes, derechos y obligaciones de una persona que no se extingan por su muerte.","u":"#art659","c":"LIBRO TERCERO De los diferentes modos de adquirir la propiedad · TÍTULO III De las sucesiones Disposiciones generales"},{"n":"CC","a":"660","t":"","x":"Llámase heredero al que sucede a título universal, y legatario al que sucede a título particular.","u":"#art660","c":"LIBRO TERCERO De los diferentes modos de adquirir la propiedad · TÍTULO III De las sucesiones Disposiciones generales"},{"n":"CC","a":"661","t":"","x":"Los herederos suceden al difunto por el hecho solo de su muerte en todos sus derechos y obligaciones.","u":"#art661","c":"LIBRO TERCERO De los diferentes modos de adquirir la propiedad · TÍTULO III De las sucesiones Disposiciones generales"},{"n":"CC","a":"662","t":"","x":"Pueden testar todos aquellos a quienes la ley no lo prohíbe expresamente.","u":"#art662","c":"CAPÍTULO I De los testamentos · Sección 1.ª De la capacidad para disponer por testamento"},{"n":"CC","a":"663","t":"","x":"No pueden testar: 1.º La persona menor de catorce años. 2.º La persona que en el momento de testar no pueda conformar o expresar su voluntad ni aun con ayuda de medios o apoyos para ello.","u":"#art663","c":"CAPÍTULO I De los testamentos · Sección 1.ª De la capacidad para disponer por testamento"},{"n":"CC","a":"664","t":"","x":"El testamento hecho antes de la enajenación mental es válido.","u":"#art664","c":"CAPÍTULO I De los testamentos · Sección 1.ª De la capacidad para disponer por testamento"},{"n":"CC","a":"665","t":"","x":"La persona con discapacidad podrá otorgar testamento cuando, a juicio del Notario, pueda comprender y manifestar el alcance de sus disposiciones. El Notario procurará que la persona otorgante desarrolle su propio proceso de toma de decisiones apoyándole en su comprensión y razonamiento y facilitando, con los ajustes que resulten necesarios, que pueda expresar su voluntad, deseos y preferencias.","u":"#art665","c":"CAPÍTULO I De los testamentos · Sección 1.ª De la capacidad para disponer por testamento"},{"n":"CC","a":"666","t":"","x":"Para apreciar la capacidad del testador se atenderá únicamente al estado en que se halle al tiempo de otorgar el testamento.","u":"#art666","c":"CAPÍTULO I De los testamentos · Sección 1.ª De la capacidad para disponer por testamento"},{"n":"CC","a":"667","t":"","x":"El acto por el cual una persona dispone para después de su muerte de todos sus bienes o de parte de ellos se llama testamento.","u":"#art667","c":"CAPÍTULO I De los testamentos · Sección 2.ª De los testamentos en general"},{"n":"CC","a":"668","t":"","x":"El testador puede disponer de sus bienes a título de herencia o de legado. En la duda, aunque el testador no haya usado materialmente la palabra heredero, si su voluntad está clara acerca de este concepto, valdrá la disposición como hecha a título universal o de herencia.","u":"#art668","c":"CAPÍTULO I De los testamentos · Sección 2.ª De los testamentos en general"},{"n":"CC","a":"669","t":"","x":"No podrán testar dos o más personas mancomunadamente, o en un mismo instrumento, ya lo hagan en provecho recíproco, ya en beneficio de un tercero.","u":"#art669","c":"CAPÍTULO I De los testamentos · Sección 2.ª De los testamentos en general"},{"n":"CC","a":"670","t":"","x":"El testamento es un acto personalísimo: no podrá dejarse su formación, en todo ni en parte, al arbitrio de un tercero, ni hacerse por medio de comisario o mandatario. Tampoco podrá dejarse al arbitrio de un tercero la subsistencia del nombramiento de herederos o legatarios, ni la designación de las porciones en que hayan de suceder cuando sean instituidos nominalmente.","u":"#art670","c":"CAPÍTULO I De los testamentos · Sección 2.ª De los testamentos en general"},{"n":"CC","a":"671","t":"","x":"Podrá el testador encomendar a un tercero la distribución de las cantidades que deje en general a clases determinadas, como a los parientes, a los pobres o a los establecimientos de beneficencia, así como la elección de las personas o establecimientos a quienes aquéllas deban aplicarse.","u":"#art671","c":"CAPÍTULO I De los testamentos · Sección 2.ª De los testamentos en general"},{"n":"CC","a":"672","t":"","x":"Toda disposición que sobre institución de heredero, mandas o legados haga el testador, refiriéndose a cédulas o papeles privados que después de su muerte aparezcan en su domicilio o fuera de él, será nula si en las cédulas o papeles no concurren los requisitos prevenidos para el testamento ológrafo.","u":"#art672","c":"CAPÍTULO I De los testamentos · Sección 2.ª De los testamentos en general"},{"n":"CC","a":"673","t":"","x":"Será nulo el testamento otorgado con violencia, dolo o fraude.","u":"#art673","c":"CAPÍTULO I De los testamentos · Sección 2.ª De los testamentos en general"},{"n":"CC","a":"674","t":"","x":"El que con dolo, fraude o violencia impidiere que una persona, de quien sea heredero abintestato, otorgue libremente su última voluntad, quedará privado de su derecho a la herencia, sin perjuicio de la responsabilidad criminal en que haya incurrido.","u":"#art674","c":"CAPÍTULO I De los testamentos · Sección 2.ª De los testamentos en general"},{"n":"CC","a":"675","t":"","x":"Toda disposición testamentaria deberá entenderse en el sentido literal de sus palabras, a no ser que aparezca claramente que fue otra la voluntad del testador. En caso de duda se observará lo que aparezca más conforme a la intención del testador, según el tenor del mismo testamento. El testador no puede prohibir que se impugne el testamento en los casos en que haya nulidad declarada por la ley.","u":"#art675","c":"CAPÍTULO I De los testamentos · Sección 2.ª De los testamentos en general"},{"n":"CC","a":"676","t":"","x":"El testamento puede ser común o especial. El común puede ser ológrafo, abierto o cerrado.","u":"#art676","c":"CAPÍTULO I De los testamentos · Sección 3.ª De la forma de los testamentos"},{"n":"CC","a":"677","t":"","x":"Se consideran testamentos especiales el militar, el marítimo y el hecho en país extranjero.","u":"#art677","c":"CAPÍTULO I De los testamentos · Sección 3.ª De la forma de los testamentos"},{"n":"CC","a":"678","t":"","x":"Se llama ológrafo el testamento cuando el testador lo escribe por sí mismo en la forma y con los requisitos que se determinan en el artículo 688.","u":"#art678","c":"CAPÍTULO I De los testamentos · Sección 3.ª De la forma de los testamentos"},{"n":"CC","a":"679","t":"","x":"Es abierto el testamento siempre que el testador manifiesta su última voluntad en presencia de las personas que deben autorizar el acto, quedando enteradas de lo que en él se dispone.","u":"#art679","c":"CAPÍTULO I De los testamentos · Sección 3.ª De la forma de los testamentos"},{"n":"CC","a":"680","t":"","x":"El testamento es cerrado cuando el testador, sin revelar su última voluntad, declara que ésta se halla contenida en el pliego que presenta a las personas que han de autorizar el acto.","u":"#art680","c":"CAPÍTULO I De los testamentos · Sección 3.ª De la forma de los testamentos"},{"n":"CC","a":"681","t":"","x":"No podrán ser testigos en los testamentos: Primero. Los menores de edad, salvo lo dispuesto en el artículo 701. Segundo. Sin contenido. Tercero. Los que no entiendan el idioma del testador. Cuarto. Los que no presenten el discernimiento necesario para desarrollar la labor testifical. Quinto. El cónyuge o los parientes dentro del cuarto grado de consanguinidad o segundo de afinidad del Notario autorizante y quienes tengan con éste relación de trabajo.","u":"#art681","c":"CAPÍTULO I De los testamentos · Sección 3.ª De la forma de los testamentos"},{"n":"CC","a":"682","t":"","x":"En el testamento abierto tampoco podrán ser testigos los herederos y legatarios en él instituidos, sus cónyuges, ni los parientes de aquéllos, dentro del cuarto grado de consanguinidad o segundo de afinidad. No están comprendidos en esta prohibición los legatarios ni sus cónyuges o parientes cuando el legado sea de algún objeto mueble o cantidad de poca importancia con relación al caudal hereditario.","u":"#art682","c":"CAPÍTULO I De los testamentos · Sección 3.ª De la forma de los testamentos"},{"n":"CC","a":"683","t":"","x":"Para que un testigo sea declarado inhábil es necesario que la causa de su incapacidad exista al tiempo de otorgarse el testamento.","u":"#art683","c":"CAPÍTULO I De los testamentos · Sección 3.ª De la forma de los testamentos"},{"n":"CC","a":"684","t":"","x":"Cuando el testador exprese su voluntad en lengua que el Notario no conozca, se requerirá la presencia de un intérprete, elegido por aquél, que traduzca la disposición testamentaria a la oficial en el lugar del otorgamiento que emplee el Notario. El instrumento se escribirá en las dos lenguas con indicación de cuál ha sido la empleada por el testador. El testamento abierto y el acta del cerrado se escribirán en la lengua extranjera en que se exprese el testador y en la oficial que emplee el Notario, aún cuando éste conozca aquélla.","u":"#art684","c":"CAPÍTULO I De los testamentos · Sección 3.ª De la forma de los testamentos"},{"n":"CC","a":"685","t":"","x":"El Notario deberá conocer al testador y si no lo conociese se identificará su persona con dos testigos que le conozcan y sean conocidos del mismo Notario, o mediante la utilización de documentos expedidos por las autoridades públicas cuyo objeto sea identificar a las personas. También deberá el Notario asegurarse de que, a su juicio, tiene el testador la capacidad legal necesaria para testar. En los casos de los artículos 700 y 701, los testigos tendrán obligación de conocer al testador y procurarán asegurarse de su capacidad.","u":"#art685","c":"CAPÍTULO I De los testamentos · Sección 3.ª De la forma de los testamentos"},{"n":"CC","a":"686","t":"","x":"Si no pudiere identificarse la persona del testador en la forma prevenida en el artículo que precede, se declarará esta circunstancia por el Notario, o por los testigos en su caso, reseñando los documentos que el testador presente con dicho objeto y las señas personales del mismo. Si fuere impugnado el testamento por tal motivo, corresponderá al que sostenga su validez la prueba de la identidad del testador.","u":"#art686","c":"CAPÍTULO I De los testamentos · Sección 3.ª De la forma de los testamentos"},{"n":"CC","a":"687","t":"","x":"Será nulo el testamento en cuyo otorgamiento no se hayan observado las formalidades respectivamente establecidas en este capítulo.","u":"#art687","c":"CAPÍTULO I De los testamentos · Sección 3.ª De la forma de los testamentos"},{"n":"CC","a":"688","t":"","x":"El testamento ológrafo solo podrá otorgarse por personas mayores de edad. Para que sea válido este testamento deberá estar escrito todo él y firmado por el testador, con expresión del año, mes y día en que se otorgue. Si contuviese palabras tachadas, enmendadas o entre renglones, las salvará el testador bajo su firma. Los extranjeros podrán otorgar testamento ológrafo en su propio idioma.","u":"#art688","c":"CAPÍTULO I De los testamentos · Sección 4.ª Del testamento ológrafo"},{"n":"CC","a":"689","t":"","x":"El testamento ológrafo deberá protocolizarse, presentándolo, en los cinco años siguientes al fallecimiento del testador, ante Notario. Este extenderá el acta de protocolización de conformidad con la legislación notarial.","u":"#art689","c":"CAPÍTULO I De los testamentos · Sección 4.ª Del testamento ológrafo"},{"n":"CC","a":"690","t":"","x":"La persona que tenga en su poder un testamento ológrafo deberá presentarlo ante Notario competente en los diez días siguientes a aquel en que tenga conocimiento del fallecimiento del testador. El incumplimiento de este deber le hará responsable de los daños y perjuicios que haya causado. También podrá presentarlo cualquiera que tenga interés en el testamento como heredero, legatario, albacea o en cualquier otro concepto.","u":"#art690","c":"CAPÍTULO I De los testamentos · Sección 4.ª Del testamento ológrafo"},{"n":"CC","a":"691","t":"","x":"Presentado el testamento ológrafo y acreditado el fallecimiento del testador, se procederá a su adveración conforme a la legislación notarial.","u":"#art691","c":"CAPÍTULO I De los testamentos · Sección 4.ª Del testamento ológrafo"},{"n":"CC","a":"692","t":"","x":"Adverado el testamento y acreditada la identidad de su autor, se procederá a su protocolización.","u":"#art692","c":"CAPÍTULO I De los testamentos · Sección 4.ª Del testamento ológrafo"},{"n":"CC","a":"693","t":"","x":"El Notario, si considera acreditada la autenticidad del testamento, autorizará el acta de protocolización, en la que hará constar las actuaciones realizadas y, en su caso, las observaciones manifestadas. Si el testamento no fuera adverado, por no acreditarse suficientemente la identidad del otorgante, se procederá al archivo del expediente sin protocolizar aquel. Autorizada o no la protocolización del testamento ológrafo, los interesados no conformes podrán ejercer sus derechos en el juicio que corresponda.","u":"#art693","c":"CAPÍTULO I De los testamentos · Sección 4.ª Del testamento ológrafo"},{"n":"CC","a":"694","t":"","x":"El testamento abierto deberá ser otorgado ante Notario hábil para actuar en el lugar del otorgamiento. Sólo se exceptuarán de esta regla los casos expresamente determinados en esta misma Sección","u":"#art694","c":"CAPÍTULO I De los testamentos · Sección 5.ª Del testamento abierto"},{"n":"CC","a":"695","t":"","x":"El testador expresará oralmente, por escrito o mediante cualquier medio técnico, material o humano su última voluntad al Notario. Redactado por este el testamento con arreglo a ella y con expresión del lugar, año, mes, día y hora de su otorgamiento y advertido el testador del derecho que tiene a leerlo por sí, lo leerá el Notario en alta voz para que el testador manifieste si está conforme con su voluntad. Si lo estuviere, será firmado en el acto por el testador que pueda hacerlo y, en su caso, por los testigos y demás personas que deban concurrir. Si el testador declara que no sabe o no puede firmar, lo hará por él y a su ruego uno de los testigos. Cuando el testador tenga dificultad o imposibilidad para leer el testamento o para oír la lectura de su contenido, el Notario se asegurará, utilizando los medios técnicos, materiales o humanos adecuados, de que el testador ha entendido la información y explicaciones necesarias y de que conoce que el testamento recoge fielmente su voluntad.","u":"#art695","c":"CAPÍTULO I De los testamentos · Sección 5.ª Del testamento abierto"},{"n":"CC","a":"696","t":"","x":"El Notario dará fe de conocer al testador o de haberlo identificado debidamente y, en su defecto, efectuará la declaración prevista en el artículo 686. También hará constar que, a su juicio, se halla el testador con la capacidad legal necesaria para otorgar testamento.","u":"#art696","c":"CAPÍTULO I De los testamentos · Sección 5.ª Del testamento abierto"},{"n":"CC","a":"697","t":"","x":"Al acto de otorgamiento deberán concurrir dos testigos idóneos: 1.° Cuando el testador declare que no sabe o no puede firmar el testamento. 2.° Cuando el testador o el Notario lo soliciten.","u":"#art697","c":"CAPÍTULO I De los testamentos · Sección 5.ª Del testamento abierto"},{"n":"CC","a":"698","t":"","x":"Al otorgamiento también deberán concurrir: 1.° Los testigos de conocimiento, si los hubiera, quienes podrán intervenir además como testigos instrumentales. 2.° Los facultativos que hubieran reconocido al testador incapacitado. 3.° El intérprete que hubiera traducido la voluntad del testador a la lengua oficial empleada por el Notario.","u":"#art698","c":"CAPÍTULO I De los testamentos · Sección 5.ª Del testamento abierto"},{"n":"CC","a":"699","t":"","x":"Todas las formalidades expresadas en esta Sección se practicarán en un solo acto que comenzará con la lectura del testamento, sin que sea lícita ninguna interrupción, salvo la que pueda ser motivada por algún accidente pasajero.","u":"#art699","c":"CAPÍTULO I De los testamentos · Sección 5.ª Del testamento abierto"},{"n":"CC","a":"700","t":"","x":"Si el testador se hallare en peligro inminente de muerte, puede otorgarse el testamento ante cinco testigos idóneos, sin necesidad de Notario.","u":"#art700","c":"CAPÍTULO I De los testamentos · Sección 5.ª Del testamento abierto"},{"n":"CC","a":"701","t":"","x":"En caso de epidemia puede igualmente otorgarse el testamento sin intervención de Notario ante tres testigos mayores de dieciséis años.","u":"#art701","c":"CAPÍTULO I De los testamentos · Sección 5.ª Del testamento abierto"},{"n":"CC","a":"702","t":"","x":"En los casos de los dos artículos anteriores se escribirá el testamento, siendo posible; no siéndolo, el testamento valdrá aunque los testigos no sepan escribir.","u":"#art702","c":"CAPÍTULO I De los testamentos · Sección 5.ª Del testamento abierto"},{"n":"CC","a":"703","t":"","x":"El testamento otorgado con arreglo a las disposiciones de los tres artículos anteriores quedará ineficaz si pasaren dos meses desde que el testador haya salido del peligro de muerte, o cesado la epidemia. Cuando el testador falleciere en dicho plazo, también quedará ineficaz el testamento si dentro de los tres meses siguientes al fallecimiento no se acude al Notario competente para que lo eleve a escritura pública, ya se haya otorgado por escrito, ya verbalmente.","u":"#art703","c":"CAPÍTULO I De los testamentos · Sección 5.ª Del testamento abierto"},{"n":"CC","a":"704","t":"","x":"Los testamentos otorgados sin autorización del Notario serán ineficaces si no se elevan a escritura pública y se protocolizan en la forma prevenida en la legislación notarial.","u":"#art704","c":"CAPÍTULO I De los testamentos · Sección 5.ª Del testamento abierto"},{"n":"CC","a":"705","t":"","x":"Declarado nulo un testamento abierto por no haberse observado las solemnidades establecidas para cada caso, el Notario que lo haya autorizado será responsable de los daños y perjuicios que sobrevengan, si la falta procediere de su malicia, o de negligencia o ignorancia inexcusables.","u":"#art705","c":"CAPÍTULO I De los testamentos · Sección 5.ª Del testamento abierto"},{"n":"CC","a":"706","t":"","x":"El testamento cerrado habrá de ser escrito. Si lo escribiese por su puño y letra el testador pondrá al final su firma. Si estuviese escrito por cualquier medio técnico o por otra persona a ruego del testador, este pondrá su firma en todas sus hojas y al pie del testamento. Si el testamento se ha redactado en soporte electrónico, deberá firmarse con una firma electrónica reconocida. Cuando el testador no sepa o no pueda firmar, lo hará a su ruego al pie y en todas las hojas otra persona, expresando la causa de la imposibilidad. En todo caso, antes de la firma se salvarán las palabras enmendadas, tachadas o escritas entre renglones.","u":"#art706","c":"CAPÍTULO I De los testamentos · Sección 6.ª Del testamento cerrado"},{"n":"CC","a":"707","t":"","x":"En el otorgamiento del testamento cerrado se observarán las solemnidades siguientes: 1.ª El papel que contenga el testamento se pondrá dentro de una cubierta, cerrada y sellada de suerte que no pueda extraerse aquél sin romper ésta. 2.a El testador comparecerá con el testamento cerrado y sellado, o lo cerrará y sellará en el acto, ante el Notario que haya de autorizarlo. 3.a En presencia del Notario, manifestará el testador por sí, o por medio del intérprete previsto en el artículo 684, que el pliego que presenta contiene su testamento, expresando si se halla escrito y firmado por él o si está escrito de mano ajena o por cualquier medio mecánico y firmado al final y en todas sus hojas por él o por otra persona a su ruego. 4.a Sobre la cubierta del testamento extenderá el Notario la correspondiente acta de su otorgamiento, expresando el número y la marca de los sellos con que está cerrado, y dando fe del conocimiento del testador o de haberse identificado su persona en la forma prevenida en los artículos 685 y 686, y de hallarse, a su juicio, el testador con la capacidad legal necesaria para otorgar testamento. 5.a Extendida y leída el acta, la firmará el testador que pueda hacerlo y, en su caso, las personas que deban concurrir, y la autorizará el Notario con su signo y firma. Si el testador declara que no sabe o no puede firmar, lo hará por él y a su ruego uno de los dos testigos idóneos que en este caso deben concurrir. 6.a También se expresará en el acta esta circunstancia, además del lugar, hora, día, mes y año del otorgamiento. 7.a Concurrirán al acto de otorgamiento dos testigos idóneos, si así lo solicitan el testador o el Notario.","u":"#art707","c":"CAPÍTULO I De los testamentos · Sección 6.ª Del testamento cerrado"},{"n":"CC","a":"708","t":"","x":"No pueden hacer testamento cerrado las personas que no sepan o no puedan leer. Las personas con discapacidad visual podrán otorgarlo, utilizando medios mecánicos o tecnológicos que les permitan escribirlo y leerlo, siempre que se observen los restantes requisitos de validez establecidos en este Código.","u":"#art708","c":"CAPÍTULO I De los testamentos · Sección 6.ª Del testamento cerrado"},{"n":"CC","a":"709","t":"","x":"Las personas que no puedan expresarse verbalmente, pero sí escribir, podrán otorgar testamento cerrado, observándose lo siguiente: 1.° El testamento ha de estar firmado por el testador. En cuanto a los demás requisitos, se estará a lo dispuesto en el artículo 706 2.° Al hacer su presentación, el testador escribirá en la parte superior de la cubierta, a presencia del Notario, que dentro de ella se contiene su testamento, expresando cómo está escrito y que está firmado por él. 3.° A continuación de lo escrito por el testador se extenderá el acta de otorgamiento, dando fe el Notario de haberse cumplido lo prevenido en el número anterior y lo demás que se dispone en el artículo 707 en lo que sea aplicable al caso. Las personas con discapacidad visual, al hacer la presentación del testamento, deberán haber expresado en la cubierta, por medios mecánicos o tecnológicos que les permitan leer lo escrito, que dentro de ella se contiene su testamento, expresando el medio empleado y que el testamento está firmado por ellas.","u":"#art709","c":"CAPÍTULO I De los testamentos · Sección 6.ª Del testamento cerrado"},{"n":"CC","a":"710","t":"","x":"Autorizado el testamento cerrado, el Notario lo entregará al testador, después de poner en el protocolo corriente copia autorizada del acta de otorgamiento.","u":"#art710","c":"CAPÍTULO I De los testamentos · Sección 6.ª Del testamento cerrado"},{"n":"CC","a":"711","t":"","x":"El testador podrá conservar en su poder el testamento cerrado, o encomendar su guarda a persona de su confianza, o depositarlo en poder del Notario autorizante para que lo guarde en su archivo. En este último caso el Notario dará recibo al testador y hará constar en su protocolo corriente, al margen o a continuación de la copia del acta de otorgamiento, que queda el testamento en su poder. Si lo retirare después el testador, firmará un recibo a continuación de dicha nota.","u":"#art711","c":"CAPÍTULO I De los testamentos · Sección 6.ª Del testamento cerrado"},{"n":"CC","a":"712","t":"","x":"1. La persona que tenga en su poder un testamento cerrado deberá presentarlo ante Notario competente en los diez días siguientes a aquel en que tenga conocimiento del fallecimiento del testador. 2. El Notario autorizante de un testamento cerrado, constituido en depositario del mismo por el testador, deberá comunicar, en los diez días siguientes a que tenga conocimiento de su fallecimiento, la existencia del testamento al cónyuge sobreviviente, a los descendientes y a los ascendientes del testador y, en defecto de éstos, a los parientes colaterales hasta el cuarto grado. 3. En los dos supuestos anteriores, de no conocer la identidad o domicilio de estas personas, o si se ignorase su existencia, el Notario deberá dar la publicidad que determine la legislación notarial. El incumplimiento de este deber, así como el de la presentación del testamento por quien lo tenga en su poder o por el Notario, le hará responsable de los daños y perjuicios causados.","u":"#art712","c":"CAPÍTULO I De los testamentos · Sección 6.ª Del testamento cerrado"},{"n":"CC","a":"713","t":"","x":"El que con dolo deje de presentar el testamento cerrado que obre en su poder dentro del plazo fijado en el artículo anterior, además de la responsabilidad que en él se determina, perderá todo derecho a la herencia, si lo tuviere como heredero abintestato o como heredero o legatario por testamento. En esta misma pena incurrirán el que sustrajere dolosamente el testamento cerrado del domicilio del testador o de la persona que lo tenga en guarda o depósito y el que lo oculte, rompa o inutilice de otro modo, sin perjuicio de la responsabilidad criminal que proceda.","u":"#art713","c":"CAPÍTULO I De los testamentos · Sección 6.ª Del testamento cerrado"},{"n":"CC","a":"714","t":"","x":"Para la apertura y protocolización del testamento cerrado se observará lo previsto en la legislación notarial.","u":"#art714","c":"CAPÍTULO I De los testamentos · Sección 6.ª Del testamento cerrado"},{"n":"CC","a":"715","t":"","x":"Es nulo el testamento cerrado en cuyo otorgamiento no se hayan observado las formalidades establecidas en esta sección; y el Notario que lo autorice será responsable de los daños y perjuicios que sobrevengan, si se probare que la falta procedió de su malicia o de negligencia o ignorancia inexcusables. Será válido, sin embargo, como testamento ológrafo, si todo él estuviere escrito y firmado por el testador y tuviere las demás condiciones propias de este testamento.","u":"#art715","c":"CAPÍTULO I De los testamentos · Sección 6.ª Del testamento cerrado"},{"n":"CC","a":"716","t":"","x":"En tiempo de guerra, los militares en campaña, voluntarios, rehenes, prisioneros y demás individuos empleados en el ejército, o que sigan a éste, podrán otorgar su testamento ante un Oficial que tenga por lo menos la categoría de Capitán. Es aplicable esta disposición a los individuos de un ejército que se halle en país extranjero. Si el testador estuviere enfermo o herido, podrá otorgarlo ante el Capellán o el Facultativo que le asista. Si estuviere en destacamento, ante el que lo mande, aunque sea subalterno. En todos los casos de este artículo será siempre necesaria la presencia de dos testigos idóneos.","u":"#art716","c":"CAPÍTULO I De los testamentos · Sección 7.ª Del testamento militar"},{"n":"CC","a":"717","t":"","x":"También podrán las personas mencionadas en el artículo anterior otorgar testamento cerrado ante un Comisario de guerra, que ejercerá en este caso las funciones de Notario, observándose las disposiciones de los artículos 706 y siguientes.","u":"#art717","c":"CAPÍTULO I De los testamentos · Sección 7.ª Del testamento militar"},{"n":"CC","a":"718","t":"","x":"Los testamentos otorgados con arreglo a los dos artículos anteriores deberán ser remitidos con la mayor brevedad posible al Cuartel General y, por este, al Ministerio de Defensa. El Ministerio, si hubiese fallecido el testador, remitirá el testamento al Colegio Notarial correspondiente al último domicilio del difunto, y de no ser conocido éste, lo remitirá al Colegio Notarial de Madrid. El Colegio Notarial remitirá el testamento al Notario correspondiente al último domicilio del testador. Recibido por el Notario deberá comunicar, en los diez días siguientes, su existencia a los herederos y demás interesados en la sucesión, para que comparezcan ante él al objeto de protocolizarlo de acuerdo con lo dispuesto legalmente.","u":"#art718","c":"CAPÍTULO I De los testamentos · Sección 7.ª Del testamento militar"},{"n":"CC","a":"719","t":"","x":"Los testamentos mencionados en el artículo 716 caducarán cuatro meses después que el testador haya dejado de estar en campaña.","u":"#art719","c":"CAPÍTULO I De los testamentos · Sección 7.ª Del testamento militar"},{"n":"CC","a":"720","t":"","x":"Durante una batalla, asalto, combate y generalmente en todo peligro próximo de acción de guerra, podrá otorgarse testamento militar de palabra ante dos testigos. Pero este testamento quedará ineficaz si el testador se salva del peligro en cuya consideración testó. Aunque no se salvare, será ineficaz el testamento si no se formaliza por los testigos ante el Auditor de guerra o funcionario de justicia que siga al ejército, procediéndose después en la forma prevenida en el artículo 718.","u":"#art720","c":"CAPÍTULO I De los testamentos · Sección 7.ª Del testamento militar"},{"n":"CC","a":"721","t":"","x":"Si fuese cerrado el testamento militar, se observará lo prevenido en los artículos 706 y 707; pero se otorgará ante el Oficial y los dos testigos que para el abierto exige el artículo 716, debiendo firmar todos ellos el acta de otorgamiento, como asimismo el testador, si pudiere.","u":"#art721","c":"CAPÍTULO I De los testamentos · Sección 7.ª Del testamento militar"},{"n":"CC","a":"722","t":"","x":"Los testamentos, abiertos o cerrados, de los que durante un viaje marítimo vayan a bordo, se otorgarán en la forma siguiente: Si el buque es de guerra, ante el Contador o el que ejerza sus funciones, en presencia de dos testigos idóneos, que vean y entiendan al testador. El Comandante del buque, o el que haga sus veces, pondrá además su visto bueno. En los buques mercantes autorizará el testamento el Capitán, o el que haga sus veces, con asistencia de dos testigos idóneos. En uno y otro caso los testigos se elegirán entre los pasajeros, si los hubiere; pero uno de ellos, por lo menos, ha de poder firmar, el cual lo hará por sí y por el testador, si éste no sabe o no puede hacerlo. Si el testamento fuera abierto, se observará además lo prevenido en el artículo 695, y si fuere cerrado, lo que se ordena en la sección sexta de este capítulo, con exclusión de lo relativo al número de testigos e intervención del Notario.","u":"#art722","c":"CAPÍTULO I De los testamentos · Sección 8.ª Del testamento marítimo"},{"n":"CC","a":"723","t":"","x":"El testamento del Contador del buque de guerra y el del Capitán del mercante serán autorizados por quien deba sustituirlos en el cargo, observándose para lo demás lo dispuesto en el artículo anterior.","u":"#art723","c":"CAPÍTULO I De los testamentos · Sección 8.ª Del testamento marítimo"},{"n":"CC","a":"724","t":"","x":"Los testamentos abiertos hechos en alta mar serán custodiados por el Comandante o por el Capitán, y se hará mención de ellos en el Diario de navegación. La misma mención se hará de los ológrafos y los cerrados.","u":"#art724","c":"CAPÍTULO I De los testamentos · Sección 8.ª Del testamento marítimo"},{"n":"CC","a":"725","t":"","x":"Si el buque arribase a un puerto extranjero donde haya Agente diplomático o consular de España, el Comandante del de guerra, o el Capitán del mercante, entregará a dicho Agente copia del testamento abierto o del acta de otorgamiento del cerrado, y de la nota tomada en el Diario. La copia del testamento o del acta deberá llevar las mismas firmas que el original, si viven y están a bordo los que lo firmaron; en otro caso será autorizada por el Contador o Capitán que hubiese recibido el testamento, o el que haga sus veces, firmando también los que estén a bordo de los que intervinieron en el testamento. El Agente diplomático o consular hará extender por escrito diligencia de la entrega y, cerrada y sellada la copia del testamento o la del acta del otorgamiento si fuere cerrado, la remitirá con la nota del Diario por el conducto correspondiente al Ministro de Marina, quien mandará que se deposite en el Archivo de su Ministerio. El Comandante o Capitán que haga la entrega recogerá del Agente diplomático o consular certificación de haberlo verificado, y tomará nota de ella en el Diario de navegación.","u":"#art725","c":"CAPÍTULO I De los testamentos · Sección 8.ª Del testamento marítimo"},{"n":"CC","a":"726","t":"","x":"Cuando el buque, sea de guerra o mercante, arribe al primer puerto del Reino, el Comandante o Capitán entregará el testamento original, cerrado y sellado, a la Autoridad marítima local, con copia de la nota tomada en el Diario; y, si hubiese fallecido el testador, certificación que lo acredite. La entrega se acreditará en la forma prevenida en el artículo anterior, y la Autoridad marítima lo remitirá todo sin dilación al Ministro de Marina.","u":"#art726","c":"CAPÍTULO I De los testamentos · Sección 8.ª Del testamento marítimo"},{"n":"CC","a":"727","t":"","x":"Si hubiese fallecido el testador y fuere abierto el testamento, el Ministro de Marina practicará lo que se dispone en el artículo 718.","u":"#art727","c":"CAPÍTULO I De los testamentos · Sección 8.ª Del testamento marítimo"},{"n":"CC","a":"728","t":"","x":"Cuando el testamento haya sido otorgado por un extranjero en buque español, el Ministro de Marina remitirá el testamento al de Estado, para que por la vía diplomática se le dé el curso que corresponda.","u":"#art728","c":"CAPÍTULO I De los testamentos · Sección 8.ª Del testamento marítimo"},{"n":"CC","a":"729","t":"","x":"Si fuere ológrafo el testamento y durante el viaje falleciera el testador, el Comandante o Capitán recogerá el testamento para custodiarlo, haciendo mención de ello en el Diario, y lo entregará a la Autoridad marítima local, en la forma y para los efectos prevenidos en el artículo anterior, cuando el buque arribe al primer puerto del Reino. Lo mismo se practicará cuando sea cerrado el testamento, si lo conservaba en su poder el testador al tiempo de su muerte.","u":"#art729","c":"CAPÍTULO I De los testamentos · Sección 8.ª Del testamento marítimo"},{"n":"CC","a":"730","t":"","x":"Los testamentos, abiertos y cerrados, otorgados con arreglo a lo prevenido en esta sección, caducarán pasados cuatro meses, contados desde que el testador desembarque en un punto donde pueda testar en la forma ordinaria.","u":"#art730","c":"CAPÍTULO I De los testamentos · Sección 8.ª Del testamento marítimo"},{"n":"CC","a":"731","t":"","x":"Si hubiera peligro de naufragio, será aplicable a las tripulaciones y pasajeros de los buques de guerra o mercantes lo dispuesto en el artículo 720.","u":"#art731","c":"CAPÍTULO I De los testamentos · Sección 8.ª Del testamento marítimo"},{"n":"CC","a":"732","t":"","x":"Los españoles podrán testar fuera del territorio nacional sujetándose a las formas establecidas por las leyes del país en que se hallen. También podrán testar en alta mar durante su navegación en un buque extranjero, con sujeción a las leyes de la Nación a que el buque pertenezca. Podrán asimismo hacer testamento ológrafo, con arreglo al art. 688, aun en los países cuyas leyes no admitan dicho testamento.","u":"#art732","c":"CAPÍTULO I De los testamentos · Sección 9.ª Del testamento hecho en país extranjero"},{"n":"CC","a":"733","t":"","x":"No será válido en España el testamento mancomunado, prohibido por el artículo 669, que los españoles otorguen en país extranjero, aunque lo autoricen las leyes de la nación donde se hubiese otorgado.","u":"#art733","c":"CAPÍTULO I De los testamentos · Sección 9.ª Del testamento hecho en país extranjero"},{"n":"CC","a":"734","t":"","x":"También podrán los españoles que se encuentren en país extranjero otorgar su testamento, abierto o cerrado, ante el funcionario diplomático o consular de España que ejerza funciones notariales en el lugar del otorgamiento. En estos casos se observarán respectivamente todas las formalidades establecidas en las Secciones quinta y sexta de este capítulo.","u":"#art734","c":"CAPÍTULO I De los testamentos · Sección 9.ª Del testamento hecho en país extranjero"},{"n":"CC","a":"735","t":"","x":"El Agente diplomático o consular remitirá, autorizada con su firma y sello, copia del testamento abierto, o del acta de otorgamiento del cerrado, al Ministerio de Estado para que se deposite en su Archivo.","u":"#art735","c":"CAPÍTULO I De los testamentos · Sección 9.ª Del testamento hecho en país extranjero"},{"n":"CC","a":"736","t":"","x":"El Agente diplomático o consular, en cuyo poder hubiese depositado su testamento ológrafo o cerrado un español, lo remitirá al Ministerio de Estado cuando fallezca el testador, con el certificado de defunción. El Ministerio de Estado hará publicar en la Gaceta de Madrid la noticia del fallecimiento, para que los interesados en la herencia puedan recoger el testamento y gestionar su protocolización en la forma prevenida.","u":"#art736","c":"CAPÍTULO I De los testamentos · Sección 9.ª Del testamento hecho en país extranjero"},{"n":"CC","a":"737","t":"","x":"Todas las disposiciones testamentarias son esencialmente revocables, aunque el testador exprese en el testamento su voluntad o resolución de no revocarlas. Se tendrán por no puestas las cláusulas derogatorias de las disposiciones futuras, y aquellas en que ordene el testador que no valga la revocación del testamento si no la hiciere con ciertas palabras o señales.","u":"#art737","c":"CAPÍTULO I De los testamentos · Sección 10.ª De la revocación e ineficacia de los testamentos"},{"n":"CC","a":"738","t":"","x":"El testamento no puede ser revocado en todo ni en parte sino con las solemnidades necesarias para testar.","u":"#art738","c":"CAPÍTULO I De los testamentos · Sección 10.ª De la revocación e ineficacia de los testamentos"},{"n":"CC","a":"739","t":"","x":"El testamento anterior queda revocado de derecho por el posterior perfecto, si el testador no expresa en éste su voluntad de que aquél subsista en todo o en parte. Sin embargo, el testamento anterior recobra su fuerza si el testador revoca después el posterior y declara expresamente ser su voluntad que valga el primero.","u":"#art739","c":"CAPÍTULO I De los testamentos · Sección 10.ª De la revocación e ineficacia de los testamentos"},{"n":"CC","a":"740","t":"","x":"La revocación producirá su efecto aunque el segundo testamento caduque por incapacidad del heredero o de los legatarios en él nombrados, o por renuncia de aquél o de éstos.","u":"#art740","c":"CAPÍTULO I De los testamentos · Sección 10.ª De la revocación e ineficacia de los testamentos"},{"n":"CC","a":"741","t":"","x":"El reconocimiento de un hijo no pierde su fuerza legal aunque se revoque el testamento en que se hizo o éste no contenga otras disposiciones, o sean nulas las demás que contuviere.","u":"#art741","c":"CAPÍTULO I De los testamentos · Sección 10.ª De la revocación e ineficacia de los testamentos"},{"n":"CC","a":"742","t":"","x":"Se presume revocado el testamento cerrado que aparezca en el domicilio del testador con las cubiertas rotas o los sellos quebrantados, o borradas, raspadas o enmendadas las firmas que lo autoricen. El testamento será, sin embargo, válido cuando se probare haber ocurrido el desperfecto sin voluntad ni conocimiento del testador o hallándose este afectado por alteraciones graves en su salud mental; pero si apareciere rota la cubierta o quebrantados los sellos, será necesario probar además la autenticidad del testamento para su validez. Si el testamento se encontrare en poder de otra persona, se entenderá que el vicio procede de ella y no será aquél válido como no se pruebe su autenticidad, si estuvieren rota la cubierta o quebrantados los sellos; y si una y otros se hallaren íntegros, pero con las firmas borradas, raspadas o enmendadas, será válido el testamento, como no se justifique haber sido entregado el pliego en esta forma por el mismo testador.","u":"#art742","c":"CAPÍTULO I De los testamentos · Sección 10.ª De la revocación e ineficacia de los testamentos"},{"n":"CC","a":"743","t":"","x":"Caducarán los testamentos, o serán ineficaces en todo o en parte las disposiciones testamentarias, sólo en los casos expresamente prevenidos en este Código.","u":"#art743","c":"CAPÍTULO I De los testamentos · Sección 10.ª De la revocación e ineficacia de los testamentos"},{"n":"CC","a":"744","t":"","x":"Podrán suceder por testamento o abintestato los que no estén incapacitados por la ley.","u":"#art744","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"745","t":"","x":"Son incapaces de suceder: 1.º Las criaturas abortivas, entendiéndose tales las que no reúnan las circunstancias expresadas en el artículo 30. 2.º Las asociaciones o corporaciones no permitidas por la ley.","u":"#art745","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"746","t":"","x":"Las iglesias y los cabildos eclesiásticos, las Diputaciones provinciales y las provincias, los Ayuntamientos y Municipios, los establecimientos de hospitalidad, beneficencia e instrucción pública, las asociaciones autorizadas o reconocidas por la ley y las demás personas jurídicas pueden adquirir por testamento con sujeción a lo dispuesto en el artículo 38.","u":"#art746","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"747","t":"","x":"Si el testador dispusiere del todo o parte de sus bienes para sufragios y obras piadosas en beneficio de su alma, haciéndolo indeterminadamente y sin especificar su aplicación, los albaceas venderán los bienes y distribuirán su importe, dando la mitad al Diocesano para que lo destine a los indicados sufragios y a las atenciones y necesidades de la Iglesia, y la otra mitad al Gobernador civil correspondiente para los establecimientos benéficos del domicilio del difunto, y, en su defecto, para los de la provincia.","u":"#art747","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"748","t":"","x":"La institución hecha a favor de un establecimiento público bajo condición o imponiéndole un gravamen sólo será válida si el Gobierno la aprueba.","u":"#art748","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"749","t":"","x":"Las disposiciones hechas a favor de los pobres en general, sin designación de personas ni de población, se entenderán limitadas a los del domicilio del testador en la época de su muerte, si no constare claramente haber sido otra su voluntad. La calificación de los pobres y la distribución de los bienes se harán por la persona que haya designado el testador, en su defecto por los albaceas, y, si no los hubiere, por el Párroco, el Alcalde y el Juez municipal, los cuales resolverán, por mayoría de votos, las dudas que ocurran. Esto mismo se hará cuando el testador haya dispuesto de sus bienes en favor de los pobres de una parroquia o pueblo determinado.","u":"#art749","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"750","t":"","x":"Toda disposición en favor de persona incierta será nula, a menos que por algún evento pueda resultar cierta.","u":"#art750","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"751","t":"","x":"La disposición hecha genéricamente en favor de los parientes del testador se entiende hecha en favor de los más próximos en grado.","u":"#art751","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"752","t":"","x":"No producirán efecto las disposiciones testamentarias que haga el testador durante su última enfermedad en favor del sacerdote que en ella le hubiese confesado, de los parientes del mismo dentro del cuarto grado, o de su iglesia, cabildo, comunidad o instituto.","u":"#art752","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"753","t":"","x":"Tampoco surtirá efecto la disposición testamentaria en favor de quien sea tutor o curador representativo del testador, salvo cuando se haya hecho después de la extinción de la tutela o curatela. Será nula la disposición hecha por las personas que se encuentran internadas por razones de salud o asistencia, a favor de sus cuidadores que sean titulares, administradores o empleados del establecimiento público o privado en el que aquellas estuvieran internadas. También será nula la disposición realizada a favor de los citados establecimientos. Las demás personas físicas que presten servicios de cuidado, asistenciales o de naturaleza análoga al causante, solo podrán ser favorecidas en la sucesión de este si es ordenada en testamento notarial abierto. Serán, sin embargo, válidas las disposiciones hechas en favor del tutor, curador o cuidador que sea pariente con derecho a suceder ab intestato.","u":"#art753","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"754","t":"","x":"El testador no podrá disponer del todo o parte de su herencia en favor del Notario que autorice su testamento, o del cónyuge, parientes o afines del mismo dentro del cuarto grado, con la excepción establecida en el artículo 682. Esta prohibición será aplicable a los testigos del testamento abierto, otorgado con o sin Notario. Las disposiciones de este artículo son también aplicables a los testigos y personas ante quienes se otorguen los testamentos especiales.","u":"#art754","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"755","t":"","x":"Será nula la disposición testamentaria a favor de un incapaz, aunque se la disfrace bajo la forma de contrato oneroso o se haga a nombre de persona interpuesta.","u":"#art755","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"756","t":"","x":"Son incapaces de suceder por causa de indignidad: 1.º El que fuera condenado por sentencia firme por haber atentado contra la vida, o a pena grave por haber causado lesiones o por haber ejercido habitualmente violencia física o psíquica en el ámbito familiar al causante, su cónyuge, persona a la que esté unida por análoga relación de afectividad o alguno de sus descendientes o ascendientes. 2.º El que fuera condenado por sentencia firme por delitos contra la libertad, la integridad moral y la libertad e indemnidad sexual, si el ofendido es el causante, su cónyuge, la persona a la que esté unida por análoga relación de afectividad o alguno de sus descendientes o ascendientes. Asimismo el condenado por sentencia firme a pena grave por haber cometido un delito contra los derechos y deberes familiares respecto de la herencia de la persona agraviada. También el privado por resolución firme de la patria potestad, o removido del ejercicio de la tutela o acogimiento familiar de un menor o del ejercicio de la curatela de una persona con discapacidad por causa que le sea imputable, respecto de la herencia del mismo. 3.º El que hubiese acusado al causante de delito para el que la ley señala pena grave, si es condenado por denuncia falsa. 4.º El heredero mayor de edad que, sabedor de la muerte violenta del testador, no la hubiese denunciado dentro de un mes a la justicia cuando ésta no hubiera procedido ya de oficio. Cesará esta prohibición en los casos en que, según la Ley, no hay la obligación de acusar. 5.º El que, con amenaza, fraude o violencia, obligare al testador a hacer testamento o a cambiarlo. 6.º El que por iguales medios impidiere a otro hacer testamento, o revocar el que tuviese hecho, o suplantare, ocultare o alterare otro posterior. 7.º Tratándose de la sucesión de una persona con discapacidad, las personas con derecho a la herencia que no le hubieren prestado las atenciones debidas, entendiendo por tales las reguladas en los artículos 142 y 146 del Código Civil.","u":"#art756","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"757","t":"","x":"Las causas de indignidad dejan de surtir efecto si el testador las conocía al tiempo de hacer testamento, o si habiéndolas sabido después, las remitiere en documento público.","u":"#art757","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"758","t":"","x":"Para calificar la capacidad del heredero o legatario se atenderá al tiempo de la muerte de la persona de cuya sucesión se trate. En los casos 2.º y 3.º del artículo 756 se esperará a que se dicte la sentencia firme, y en el número 4.º a que transcurra el mes señalado para la denuncia. Si la institución o legado fuere condicional, se atenderá además al tiempo en que se cumpla la condición.","u":"#art758","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"759","t":"","x":"El heredero o legatario que muera antes de que la condición se cumpla, aunque sobreviva al testador, no transmite derecho alguno a sus herederos.","u":"#art759","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"760","t":"","x":"El incapaz de suceder, que, contra la prohibición de los anteriores artículos, hubiese entrado en la posesión de los bienes hereditarios, estará obligado a restituirlos con sus accesiones y con todos los frutos y rentas que haya percibido.","u":"#art760","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"761","t":"","x":"Si el excluido de la herencia por incapacidad fuera hijo o descendiente del testador y tuviere hijos o descendientes, adquirirán éstos su derecho a la legítima.","u":"#art761","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"762","t":"","x":"No puede deducirse acción para declarar la incapacidad pasados cinco años desde que el incapaz esté en posesión de la herencia o legado.","u":"#art762","c":"CAPÍTULO II De la herencia · Sección 1.ª De la capacidad para suceder por testamento y sin él"},{"n":"CC","a":"763","t":"","x":"El que no tuviere herederos forzosos puede disponer por testamento de todos sus bienes o de parte de ellos en favor de cualquiera persona que tenga capacidad para adquirirlos. El que tuviere herederos forzosos sólo podrá disponer de sus bienes en la forma y con las limitaciones que se establecen en la sección quinta de este capítulo.","u":"#art763","c":"CAPÍTULO II De la herencia · Sección 2.ª De la institución de heredero"},{"n":"CC","a":"764","t":"","x":"El testamento será válido aunque no contenga institución de heredero, o ésta no comprenda la totalidad de los bienes, y aunque el nombrado no acepte la herencia, o sea incapaz de heredar. En estos casos se cumplirán las disposiciones testamentarias hechas con arreglo a las leyes, y el remanente de los bienes pasará a los herederos legítimos.","u":"#art764","c":"CAPÍTULO II De la herencia · Sección 2.ª De la institución de heredero"},{"n":"CC","a":"765","t":"","x":"Los herederos instituidos sin designación de partes heredarán por partes iguales.","u":"#art765","c":"CAPÍTULO II De la herencia · Sección 2.ª De la institución de heredero"},{"n":"CC","a":"766","t":"","x":"El heredero voluntario que muere antes que el testador, el incapaz de heredar y el que renuncia a la herencia no transmiten ningún derecho a sus herederos, salvo lo dispuesto en los artículos 761 y 857.","u":"#art766","c":"CAPÍTULO II De la herencia · Sección 2.ª De la institución de heredero"},{"n":"CC","a":"767","t":"","x":"La expresión de una causa falsa de la institución de heredero o del nombramiento de legatario será considerada como no escrita, a no ser que del testamento resulte que el testador no habría hecho tal institución o legado si hubiese conocido la falsedad de la causa. La expresión de una causa contraria a derecho, aunque sea verdadera, se tendrá también por no escrita.","u":"#art767","c":"CAPÍTULO II De la herencia · Sección 2.ª De la institución de heredero"},{"n":"CC","a":"768","t":"","x":"El heredero instituido en una cosa cierta y determinada será considerado como legatario.","u":"#art768","c":"CAPÍTULO II De la herencia · Sección 2.ª De la institución de heredero"},{"n":"CC","a":"769","t":"","x":"Cuando el testador nombre unos herederos individualmente y otros colectivamente, como si dijere: «Instituyo por mis herederos a N. y a N., y a los hijos de N», los colectivamente nombrados se considerarán como si lo fueran individualmente, a no ser que conste de un modo claro que ha sido otra la voluntad del testador.","u":"#art769","c":"CAPÍTULO II De la herencia · Sección 2.ª De la institución de heredero"},{"n":"CC","a":"770","t":"","x":"Si el testador instituye a sus hermanos, y los tiene carnales y de padre o madre solamente, se dividirá la herencia como en el caso de morir intestado.","u":"#art770","c":"CAPÍTULO II De la herencia · Sección 2.ª De la institución de heredero"},{"n":"CC","a":"771","t":"","x":"Cuando el testador llame a la sucesión a una persona y a sus hijos, se entenderán todos instituidos simultánea y no sucesivamente.","u":"#art771","c":"CAPÍTULO II De la herencia · Sección 2.ª De la institución de heredero"},{"n":"CC","a":"772","t":"","x":"El testador designará al heredero por su nombre y apellidos, y cuando haya dos que los tengan iguales deberá señalar alguna circunstancia por la que se conozca al instituido. Aunque el testador haya omitido el nombre del heredero, si lo designare de modo que no pueda dudarse quién sea el instituido valdrá la institución. En el testamento del adoptante la expresión genérica hijo o hijos comprende a los adoptivos.","u":"#art772","c":"CAPÍTULO II De la herencia · Sección 2.ª De la institución de heredero"},{"n":"CC","a":"773","t":"","x":"El error en el nombre, apellido o cualidades del heredero no vicia la institución cuando de otra manera puede saberse ciertamente cuál sea la persona nombrada. Si entre personas del mismo nombre y apellidos hay igualdad de circunstancias y éstas son tales que no permiten distinguir al instituido, ninguno será heredero.","u":"#art773","c":"CAPÍTULO II De la herencia · Sección 2.ª De la institución de heredero"},{"n":"CC","a":"774","t":"","x":"Puede el testador sustituir una o más personas al heredero o herederos instituidos para el caso en que mueran antes que él, o no quieran, o no puedan aceptar la herencia. La sustitución simple, y sin expresión de casos, comprende los tres expresados en el párrafo anterior, a menos que el testador haya dispuesto lo contrario.","u":"#art774","c":"CAPÍTULO II De la herencia · Sección 3.ª De la sustitución"},{"n":"CC","a":"775","t":"","x":"Los padres y demás ascendientes podrán nombrar sustitutos a sus descendientes menores de catorce años, de ambos sexos, para el caso de que mueran antes de dicha edad.","u":"#art775","c":"CAPÍTULO II De la herencia · Sección 3.ª De la sustitución"},{"n":"CC","a":"777","t":"","x":"Las sustituciones de que hablan los dos artículos anteriores, cuando el sustituido tenga herederos forzosos, sólo serán válidas en cuanto no perjudiquen los derechos legitimarios de éstos.","u":"#art777","c":"CAPÍTULO II De la herencia · Sección 3.ª De la sustitución"},{"n":"CC","a":"778","t":"","x":"Pueden ser sustituidas dos o más personas a una sola; y al contrario, una sola a dos o más herederos.","u":"#art778","c":"CAPÍTULO II De la herencia · Sección 3.ª De la sustitución"},{"n":"CC","a":"779","t":"","x":"Si los herederos instituidos en partes desiguales fueren sustituidos recíprocamente, tendrán en la sustitución las mismas partes que en la institución, a no ser que claramente aparezca haber sido otra la voluntad del testador.","u":"#art779","c":"CAPÍTULO II De la herencia · Sección 3.ª De la sustitución"},{"n":"CC","a":"780","t":"","x":"El sustituto quedará sujeto a las mismas cargas y condiciones impuestas al instituido, a menos que el testador haya dispuesto expresamente lo contrario, o que los gravámenes o condiciones sean meramente personales del instituido.","u":"#art780","c":"CAPÍTULO II De la herencia · Sección 3.ª De la sustitución"},{"n":"CC","a":"781","t":"","x":"Las sustituciones fideicomisarias en cuya virtud se encarga al heredero que conserve y transmita a un tercero el todo o parte de la herencia, serán válidas y surtirán efecto siempre que no pasen del segundo grado, o que se hagan en favor de personas que vivan al tiempo del fallecimiento del testador.","u":"#art781","c":"CAPÍTULO II De la herencia · Sección 3.ª De la sustitución"},{"n":"CC","a":"782","t":"","x":"Las sustituciones fideicomisarias nunca podrán gravar la legítima, salvo cuando se establezcan, en los términos establecidos en el artículo 808, en beneficio de uno o varios hijos del testador que se encuentren en una situación de discapacidad. Si la sustitución fideicomisaria recayere sobre el tercio destinado a mejora, solo podrá establecerse a favor de los descendientes.","u":"#art782","c":"CAPÍTULO II De la herencia · Sección 3.ª De la sustitución"},{"n":"CC","a":"783","t":"","x":"Para que sean válidos los llamamientos a la sustitución fideicomisaria, deberán ser expresos. El fiduciario estará obligado a entregar la herencia al fideicomisario, sin otras deducciones que las que correspondan por gastos legítimos, créditos y mejoras, salvo el caso en que el testador haya dispuesto otra cosa.","u":"#art783","c":"CAPÍTULO II De la herencia · Sección 3.ª De la sustitución"},{"n":"CC","a":"784","t":"","x":"El fideicomisario adquirirá derecho a la sucesión desde la muerte del testador, aunque muera antes que el fiduciario. El derecho de aquél pasará a sus herederos.","u":"#art784","c":"CAPÍTULO II De la herencia · Sección 3.ª De la sustitución"},{"n":"CC","a":"785","t":"","x":"No surtirán efecto: 1.º Las sustituciones fideicomisarias que no se hagan de una manera expresa, ya dándoles este nombre, ya imponiendo al sustituido la obligación terminante de entregar los bienes a un segundo heredero. 2.º Las disposiciones que contengan prohibición perpetua de enajenar, y aun la temporal, fuera del límite señalado en el artículo 781. 3.º Las que impongan al heredero el encargo de pagar a varias personas sucesivamente, más allá del segundo grado, cierta renta o pensión. 4.º Las que tengan por objeto dejar a una persona el todo o parte de los bienes hereditarios para que los aplique o invierta según instrucciones reservadas que le hubiese comunicado el testador.","u":"#art785","c":"CAPÍTULO II De la herencia · Sección 3.ª De la sustitución"},{"n":"CC","a":"786","t":"","x":"La nulidad de la sustitución fideicomisaria no perjudicará a la validez de la institución ni a los herederos del primer llamamiento; sólo se tendrá por no escrita la cláusula fideicomisaria.","u":"#art786","c":"CAPÍTULO II De la herencia · Sección 3.ª De la sustitución"},{"n":"CC","a":"787","t":"","x":"La disposición en que el testador deje a una persona el todo o parte de la herencia, y a otra el usufructo, será válida. Si llamare al usufructo a varias personas no simultánea, sino sucesivamente, se estará a lo dispuesto en el artículo 781.","u":"#art787","c":"CAPÍTULO II De la herencia · Sección 3.ª De la sustitución"},{"n":"CC","a":"788","t":"","x":"Será válida la disposición que imponga al heredero la obligación de invertir ciertas cantidades periódicamente en obras benéficas, como dotes para doncellas pobres, pensiones para estudiantes o en favor de los pobres o de cualquiera establecimiento de beneficencia o de instrucción pública, bajo las condiciones siguientes: Si la carga se impusiere sobre bienes inmuebles y fuere temporal, el heredero o herederos podrán disponer de la finca gravada, sin que cese el gravamen mientras que su inscripción no se cancele. Si la carga fuere perpetua, el heredero podrá capitalizarla e imponer el capital a interés con primera y suficiente hipoteca. La capitalización e imposición del capital se hará interviniendo el Gobernador civil de la provincia y con audiencia del Ministerio Público. En todo caso, cuando el testador no hubiere establecido un orden para la administración y aplicación de la manda benéfica, lo hará la Autoridad administrativa a quien corresponda con arreglo a las leyes.","u":"#art788","c":"CAPÍTULO II De la herencia · Sección 3.ª De la sustitución"},{"n":"CC","a":"789","t":"","x":"Todo lo dispuesto en este capítulo respecto a los herederos se entenderá también aplicable a los legatarios.","u":"#art789","c":"CAPÍTULO II De la herencia · Sección 3.ª De la sustitución"},{"n":"CC","a":"790","t":"","x":"Las disposiciones testamentarias, tanto a título universal como particular, podrán hacerse bajo condición.","u":"#art790","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"791","t":"","x":"Las condiciones impuestas a los herederos y legatarios, en lo que no esté prevenido en esta sección, se regirán por las reglas establecidas para las obligaciones condicionales.","u":"#art791","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"792","t":"","x":"Las condiciones imposibles y las contrarias a las leyes o a las buenas costumbres se tendrán por no puestas y en nada perjudicarán al heredero o legatario, aun cuando el testador disponga otra cosa.","u":"#art792","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"793","t":"","x":"La condición absoluta de no contraer primero o ulterior matrimonio se tendrá por no puesta, a menos que lo haya sido al viudo o viuda por su difunto consorte o por los ascendientes o descendientes de éste. Podrá, sin embargo, legarse a cualquiera el usufructo, uso o habitación, o una pensión o prestación personal, por el tiempo que permanezca soltero o viudo.","u":"#art793","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"794","t":"","x":"Será nula la disposición hecha bajo condición de que el heredero o legatario haga en su testamento alguna disposición en favor del testador o de otra persona.","u":"#art794","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"795","t":"","x":"La condición puramente potestativa impuesta al heredero o legatario ha de ser cumplida por éstos, una vez enterados de ella, después de la muerte del testador. Exceptúase el caso en que la condición, ya cumplida, no pueda reiterarse.","u":"#art795","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"796","t":"","x":"Cuando la condición fuere casual o mixta, bastará que se realice o cumpla en cualquier tiempo, vivo o muerto el testador, si éste no hubiese dispuesto otra cosa. Si hubiese existido o se hubiese cumplido al hacerse el testamento, y el testador lo ignoraba, se tendrá por cumplida. Si lo sabía, sólo se tendrá por cumplida cuando fuere de tal naturaleza que no pueda ya existir o cumplirse de nuevo.","u":"#art796","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"797","t":"","x":"La expresión del objeto de la institución o legado, o la aplicación que haya de darse a lo dejado por el testador, o la carga que el mismo impusiere, no se entenderán como condición, a no parecer que ésta era su voluntad. Lo dejado de esta manera puede pedirse desde luego, y es transmisible a los herederos que afiancen el cumplimiento de lo mandado por el testador, y la devolución de lo percibido con sus frutos e intereses, si faltaren a esta obligación.","u":"#art797","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"798","t":"","x":"Cuando, sin culpa o hecho propio del heredero o legatario, no pueda tener efecto la institución o el legado de que trata el artículo precedente en los mismos términos que haya ordenado el testador, deberá cumplirse en otros, los más análogos y conformes a su voluntad. Cuando el interesado en que se cumpla, o no, impidiere su cumplimiento sin culpa o hecho propio del heredero o legatario, se considerará cumplida la condición.","u":"#art798","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"799","t":"","x":"La condición suspensiva no impide al heredero o legatario adquirir sus respectivos derechos y transmitirlos a sus herederos, aun antes de que se verifique su cumplimiento.","u":"#art799","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"800","t":"","x":"Si la condición potestativa impuesta al heredero o legatario fuere negativa, o de no hacer o no dar, cumplirán con afianzar que no harán o no darán lo que fue prohibido por el testador, y que, en caso de contravención, devolverán lo percibido con sus frutos e intereses.","u":"#art800","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"801","t":"","x":"Si el heredero fuere instituido bajo condición suspensiva, se pondrán los bienes de la herencia en administración hasta que la condición se realice o haya certeza de que no podrá cumplirse. Lo mismo se hará cuando el heredero o legatario no preste la fianza en el caso del artículo anterior.","u":"#art801","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"802","t":"","x":"La administración de que habla el artículo precedente se confiará al heredero o herederos instituidos sin condición, cuando entre ellos y el heredero condicional hubiere derecho de acrecer. Lo mismo se entenderá respecto de los legatarios.","u":"#art802","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"803","t":"","x":"Si el heredero condicional no tuviere coherederos, o teniéndolos no existiese entre ellos derecho de acrecer, entrará aquél en la administración, dando fianza. Si no la diere, se conferirá la administración al heredero presunto, también bajo fianza; y, si ni uno ni otro afianzaren, los Tribunales nombrarán tercera persona, que se hará cargo de ella, también bajo fianza, la cual se prestará con intervención del heredero.","u":"#art803","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"804","t":"","x":"Los administradores tendrán los mismos derechos y obligaciones que los que lo son de los bienes de un ausente.","u":"#art804","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"805","t":"","x":"Será válida la designación de día o de tiempo en que haya de comenzar o cesar el efecto de la institución de heredero o del legado. En ambos casos, hasta que llegue el término señalado, o cuando éste concluya, se entenderá llamado el sucesor legítimo. Mas en el primer caso, no entrará éste en posesión de los bienes sino después de prestar caución suficiente, con intervención del instituido.","u":"#art805","c":"CAPÍTULO II De la herencia · Sección 4.ª De la institución de heredero y del legado condicional o a término"},{"n":"CC","a":"806","t":"","x":"Legítima es la porción de bienes de que el testador no puede disponer por haberla reservado la ley a determinados herederos, llamados por esto herederos forzosos.","u":"#art806","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"807","t":"","x":"Son herederos forzosos: 1.° Los hijos y descendientes respecto de sus padres y ascendientes. 2.° A falta de los anteriores, los padres y ascendientes respecto de sus hijos y descendientes. 3.° El viudo o viuda en la forma y medida que establece este Código.","u":"#art807","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"808","t":"","x":"Constituyen la legítima de los hijos y descendientes las dos terceras partes del haber hereditario de los progenitores. Sin embargo, podrán estos disponer de una parte de las dos que forman la legítima, para aplicarla como mejora a sus hijos o descendientes. La tercera parte restante será de libre disposición. Cuando alguno o varios de los legitimarios se encontraren en una situación de discapacidad, el testador podrá disponer a su favor de la legítima estricta de los demás legitimarios sin discapacidad. En tal caso, salvo disposición contraria del testador, lo así recibido por el hijo beneficiado quedará gravado con sustitución fideicomisaria de residuo a favor de los que hubieren visto afectada su legítima estricta y no podrá aquel disponer de tales bienes ni a título gratuito ni por acto mortis causa. Cuando el testador hubiere hecho uso de la facultad que le concede el párrafo anterior, corresponderá al hijo que impugne el gravamen de su legítima estricta acreditar que no concurre causa que la justifique.","u":"#art808","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"809","t":"","x":"Constituye la legítima de los padres o ascendientes la mitad del haber hereditario de los hijos y descendientes salvo el caso en que concurrieren con el cónyuge viudo del descendiente causante, en cuyo supuesto será de una tercera parte de la herencia.","u":"#art809","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"810","t":"","x":"La legítima reservada a los padres se dividirá entre los dos por partes iguales; si uno de ellos hubiere muerto, recaerá toda en el sobreviviente. Cuando el testador no deje padre ni madre, pero sí ascendientes, en igual grado, de las líneas paterna y materna, se dividirá la herencia por mitad entre ambas líneas. Si los ascendientes fueren de grado diferente, corresponderá por entero a los más próximos de una u otra línea.","u":"#art810","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"811","t":"","x":"El ascendiente que heredare de su descendiente bienes que éste hubiese adquirido por título lucrativo de otro ascendiente, o de un hermano, se halla obligado a reservar los que hubiere adquirido por ministerio de la ley en favor de los parientes que estén dentro del tercer grado y pertenezcan a la línea de donde los bienes proceden.","u":"#art811","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"812","t":"","x":"Los ascendientes suceden con exclusión de otras personas en las cosas dadas por ellos a sus hijos o descendientes muertos sin posteridad, cuando los mismos objetos donados existan en la sucesión. Si hubieren sido enajenados, sucederán en todas las acciones que el donatario tuviera con relación a ellos, y en el precio si se hubieren vendido, o en los bienes con que se hayan sustituido, si los permutó o cambió.","u":"#art812","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"813","t":"","x":"El testador no podrá privar a los herederos de su legítima sino en los casos expresamente determinados por la ley. Tampoco podrá imponer sobre ella gravamen, ni condición, ni sustitución de ninguna especie, salvo lo dispuesto en cuanto al usufructo del viudo y lo establecido en los artículos 782 y 808.","u":"#art813","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"814","t":"","x":"La preterición de un heredero forzoso no perjudica la legítima. Se reducirá la institución de heredero antes que los legados, mejoras y demás disposiciones testamentarias. Sin embargo, la preterición no intencional de hijos o descendientes producirá los siguientes efectos: 1.° Si resultaren preteridos todos, se anularán las disposiciones testamentarias de contenido patrimonial. 2.° En otro caso, se anulará la institución de herederos, pero valdrán las mandas y mejoras ordenadas por cualquier título, en cuanto unas y otras no sean inoficiosas. No obstante, la institución de heredero a favor del cónyuge sólo se anulará en cuanto perjudique a las legítimas. Los descendientes de otro descendiente que no hubiere sido preterido, representan a éste en la herencia del ascendiente y no se consideran preteridos. Si los herederos forzosos preteridos mueren antes que el testador, el testamento surtirá todos sus efectos. A salvo las legítimas tendrá preferencia en todo caso lo ordenado por el testador.","u":"#art814","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"815","t":"","x":"El heredero forzoso a quien el testador haya dejado por cualquier título menos de la legítima que le corresponda, podrá pedir el complemento de la misma.","u":"#art815","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"816","t":"","x":"Toda renuncia o transacción sobre la legítima futura entre el que la debe y sus herederos forzosos es nula, y éstos podrán reclamarla cuando muera aquél; pero deberán traer a colación lo que hubiesen recibido por la renuncia o transacción.","u":"#art816","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"817","t":"","x":"Las disposiciones testamentarias que mengüen la legítima de los herederos forzosos se reducirán, a petición de éstos, en lo que fueren inoficiosas o excesivas.","u":"#art817","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"818","t":"","x":"Para fijar la legítima se atenderá al valor de los bienes que quedaren a la muerte del testador, con deducción de las deudas y cargas, sin comprender entre ellas las impuestas en el testamento. Al valor líquido de los bienes hereditarios se agregará el de las donaciones colacionables.","u":"#art818","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"819","t":"","x":"Las donaciones hechas a los hijos, que no tengan el concepto de mejoras, se imputarán en su legítima. Las donaciones hechas a extraños se imputarán a la parte libre de que el testador hubiese podido disponer por su última voluntad. En cuanto fueren inoficiosas o excedieren de la cuota disponible, se reducirán según las reglas de los artículos siguientes.","u":"#art819","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"820","t":"","x":"Fijada la legítima con arreglo a los dos artículos anteriores, se hará la reducción como sigue: 1.º Se respetarán las donaciones mientras pueda cubrirse la legítima, reduciendo o anulando, si necesario fuere, las mandas hechas en testamento. 2.º La reducción de éstas se hará a prorrata, sin distinción alguna. Si el testador hubiere dispuesto que se pague cierto legado con preferencia a otros, no sufrirá aquél reducción sino después de haberse aplicado éstos por entero al pago de la legítima. 3.º Si la manda consiste en un usufructo o renta vitalicia, cuyo valor se tenga por superior a la parte disponible, los herederos forzosos podrán escoger entre cumplir la disposición testamentaria o entregar al legatario la parte de la herencia de que podía disponer libremente el testador.","u":"#art820","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"821","t":"","x":"Cuando el legado sujeto a reducción consista en una finca que no admita cómoda división, quedará ésta para el legatario si la reducción no absorbe la mitad de su valor, y en caso contrario para los herederos forzosos; pero aquél y éstos deberán abonarse su respectivo haber en dinero. El legatario que tenga derecho a legítima podrá retener toda la finca, con tal que su valor no supere, el importe de la porción disponible y de la cuota que le corresponda por legítima. Si los herederos o legatarios no quieren usar del derecho que se les concede en este artículo se venderá la finca en pública subasta, a instancia de cualquiera de los interesados.","u":"#art821","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"822","t":"","x":"La donación o legado de un derecho de habitación sobre la vivienda habitual que su titular haga a favor de un legitimario que se encuentre en una situación de discapacidad, no se computará para el cálculo de las legítimas si en el momento del fallecimiento ambos estuvieren conviviendo en ella. Este derecho de habitación se atribuirá por ministerio de la ley en las mismas condiciones al legitimario que se halle en la situación prevista en el párrafo anterior, que lo necesite y que estuviere conviviendo con el fallecido, a menos que el testador hubiera dispuesto otra cosa o lo hubiera excluido expresamente, pero su titular no podrá impedir que continúen conviviendo los demás legitimarios mientras lo necesiten. El derecho a que se refieren los dos párrafos anteriores será intransmisible. Lo dispuesto en los dos primeros párrafos no impedirá la atribución al cónyuge de los derechos regulados en los artículos 1406 y 1407 de este Código, que coexistirán con el de habitación.","u":"#art822","c":"CAPÍTULO II De la herencia · Sección 5.ª De las legítimas"},{"n":"CC","a":"823","t":"","x":"El padre o la madre podrán disponer en concepto de mejora a favor de alguno o algunos de sus hijos o descendientes, ya lo sean por naturaleza ya por adopción, de una de las dos terceras partes destinadas a legítima.","u":"#art823","c":"CAPÍTULO II De la herencia · Sección 6.ª De las mejoras"},{"n":"CC","a":"824","t":"","x":"No podrán imponerse sobre la mejora otros gravámenes que los que se establezcan en favor de los legitimarios o sus descendientes.","u":"#art824","c":"CAPÍTULO II De la herencia · Sección 6.ª De las mejoras"},{"n":"CC","a":"825","t":"","x":"Ninguna donación por contrato entre vivos, sea simple o por causa onerosa, en favor de hijos o descendientes, que sean herederos forzosos, se reputará mejora, si el donante no ha declarado de una manera expresa su voluntad de mejorar.","u":"#art825","c":"CAPÍTULO II De la herencia · Sección 6.ª De las mejoras"},{"n":"CC","a":"826","t":"","x":"La promesa de mejorar o no mejorar, hecha por escritura pública en capitulaciones matrimoniales, será válida. La disposición del testador contraria a la promesa no producirá efecto.","u":"#art826","c":"CAPÍTULO II De la herencia · Sección 6.ª De las mejoras"},{"n":"CC","a":"827","t":"","x":"La mejora, aunque se haya verificado con entrega de bienes, será revocable, a menos que se haya hecho por capitulaciones matrimoniales o por contrato oneroso celebrado con un tercero.","u":"#art827","c":"CAPÍTULO II De la herencia · Sección 6.ª De las mejoras"},{"n":"CC","a":"828","t":"","x":"La manda o legado hecho por el testador a uno de los hijos o descendientes no se reputará mejora sino cuando el testador haya declarado expresamente ser ésta su voluntad, o cuando no quepa en la parte libre.","u":"#art828","c":"CAPÍTULO II De la herencia · Sección 6.ª De las mejoras"},{"n":"CC","a":"829","t":"","x":"La mejora podrá señalarse en cosa determinada. Si el valor de ésta excediere del tercio destinado a la mejora y de la parte de legítima correspondiente al mejorado, deberá éste abonar la diferencia en metálico a los demás interesados.","u":"#art829","c":"CAPÍTULO II De la herencia · Sección 6.ª De las mejoras"},{"n":"CC","a":"830","t":"","x":"La facultad de mejorar no puede encomendarse a otro.","u":"#art830","c":"CAPÍTULO II De la herencia · Sección 6.ª De las mejoras"},{"n":"CC","a":"831","t":"","x":"1. No obstante lo dispuesto en el artículo anterior, podrán conferirse facultades al cónyuge en testamento para que, fallecido el testador, pueda realizar a favor de los hijos o descendientes comunes mejoras incluso con cargo al tercio de libre disposición y, en general, adjudicaciones o atribuciones de bienes concretos por cualquier título o concepto sucesorio o particiones, incluidas las que tengan por objeto bienes de la sociedad conyugal disuelta que esté sin liquidar. Estas mejoras, adjudicaciones o atribuciones podrán realizarse por el cónyuge en uno o varios actos, simultáneos o sucesivos. Si no se le hubiere conferido la facultad de hacerlo en su propio testamento o no se le hubiere señalado plazo, tendrá el de dos años contados desde la apertura de la sucesión o, en su caso, desde la emancipación del último de los hijos comunes. Las disposiciones del cónyuge que tengan por objeto bienes específicos y determinados, además de conferir la propiedad al hijo o descendiente favorecido, le conferirán también la posesión por el hecho de su aceptación, salvo que en ellas se establezca otra cosa. 2. Corresponderá al cónyuge sobreviviente la administración de los bienes sobre los que pendan las facultades a que se refiere el párrafo anterior. 3. El cónyuge, al ejercitar las facultades encomendadas, deberá respetar las legítimas estrictas de los descendientes comunes y las mejoras y demás disposiciones del causante en favor de ésos. De no respetarse la legítima estricta de algún descendiente común o la cuota de participación en los bienes relictos que en su favor hubiere ordenado el causante, el perjudicado podrá pedir que se rescindan los actos del cónyuge en cuanto sea necesario para dar satisfacción al interés lesionado. Se entenderán respetadas las disposiciones del causante a favor de los hijos o descendientes comunes y las legítimas cuando unas u otras resulten suficientemente satisfechas aunque en todo o en parte lo hayan sido con bienes pertenecientes sólo al cónyuge que ejercite las facultades. 4. La concesión al cónyuge de las facultades expresadas no alterará el régimen de las legítimas ni el de las disposiciones del causante, cuando el favorecido por unas u otras no sea descendiente común. En tal caso, el cónyuge que no sea pariente en línea recta del favorecido tendrá poderes, en cuanto a los bienes afectos a esas facultades, para actuar por cuenta de los descendientes comunes en los actos de ejecución o de adjudicación relativos a tales legítimas o disposiciones. Cuando algún descendiente que no lo sea del cónyuge supérstite hubiera sufrido preterición no intencional en la herencia del premuerto, el ejercicio de las facultades encomendadas al cónyuge no podrá menoscabar la parte del preterido. 5. Las facultades conferidas al cónyuge cesarán desde que hubiere pasado a ulterior matrimonio o a relación de hecho análoga o tenido algún hijo no común, salvo que el testador hubiera dispuesto otra cosa. 6. Las disposiciones de los párrafos anteriores también serán de aplicación cuando las personas con descendencia común no estén casadas entre sí.","u":"#art831","c":"CAPÍTULO II De la herencia · Sección 6.ª De las mejoras"},{"n":"CC","a":"832","t":"","x":"Cuando la mejora no hubiere sido señalada en cosa determinada, será pagada con los mismos bienes hereditarios, observándose, en cuanto puedan tener lugar, las reglas establecidas en los artículos 1.061 y 1.062 para procurar la igualdad de los herederos en la partición de bienes.","u":"#art832","c":"CAPÍTULO II De la herencia · Sección 6.ª De las mejoras"},{"n":"CC","a":"833","t":"","x":"El hijo o descendiente mejorado podrá renunciar a la herencia y aceptar la mejora.","u":"#art833","c":"CAPÍTULO II De la herencia · Sección 6.ª De las mejoras"},{"n":"CC","a":"834","t":"","x":"El cónyuge que al morir su consorte no se hallase separado de éste legalmente o de hecho, si concurre a la herencia con hijos o descendientes, tendrá derecho al usufructo del tercio destinado a mejora.","u":"#art834","c":"CAPÍTULO II De la herencia · Sección 7.ª Derechos del cónyuge viudo"},{"n":"CC","a":"835","t":"","x":"Si entre los cónyuges separados hubiera mediado reconciliación notificada al Juzgado que conoció de la separación o al Notario que otorgó la escritura pública de separación de conformidad con el artículo 84 de este Código, el sobreviviente conservará sus derechos.","u":"#art835","c":"CAPÍTULO II De la herencia · Sección 7.ª Derechos del cónyuge viudo"},{"n":"CC","a":"837","t":"","x":"No existiendo descendientes, pero sí ascendientes, el cónyuge sobreviviente tendrá derecho al usufructo de la mitad de la herencia.","u":"#art837","c":"CAPÍTULO II De la herencia · Sección 7.ª Derechos del cónyuge viudo"},{"n":"CC","a":"838","t":"","x":"No existiendo descendientes ni ascendientes el cónyuge sobreviviente tendrá derecho al usufructo de los dos tercios de la herencia.","u":"#art838","c":"CAPÍTULO II De la herencia · Sección 7.ª Derechos del cónyuge viudo"},{"n":"CC","a":"839","t":"","x":"Los herederos podrán satisfacer al cónyuge su parte de usufructo, asignándole una renta vitalicia, los productos de determinados bienes, o un capital en efectivo, procediendo de mutuo acuerdo y, en su defecto, por virtud de mandato judicial. Mientras esto no se realice, estarán afectos todos los bienes de la herencia al pago de la parte de usufructo que corresponda al cónyuge.","u":"#art839","c":"CAPÍTULO II De la herencia · Sección 7.ª Derechos del cónyuge viudo"},{"n":"CC","a":"840","t":"","x":"Cuando el cónyuge viudo concurra con hijos sólo del causante, podrá exigir que su derecho de usufructo le sea satisfecho, a elección de los hijos, asignándole un capital en dinero o un lote de bienes hereditarios.","u":"#art840","c":"CAPÍTULO II De la herencia · Sección 7.ª Derechos del cónyuge viudo"},{"n":"CC","a":"841","t":"","x":"El testador, o el contador-partidor expresamente autorizado por aquél, podrá adjudicar todos los bienes hereditarios o parte de ellos a alguno de los hijos o descendientes ordenando que se pague en metálico la porción hereditaria de los demás legitimarios. También corresponderá la facultad de pago en metálico en el mismo supuesto del párrafo anterior al contador partidor dativo a que se refiero el artículo 1.057 del Código Civil.","u":"#art841","c":"CAPÍTULO II De la herencia · Sección 8.ª Pago de la porción hereditaria en casos especiales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"842","t":"","x":"No obstante lo dispuesto en el artículo anterior, cualquiera de los hijos o descendientes obligados a pagar en metálico la cuota hereditaria de sus hermanos podrá exigir que dicha cuota sea satisfecha en bienes de la herencia, debiendo observarse, en tal caso, lo prescrito por los artículos 1.058 a 1.063 de este Código.","u":"#art842","c":"CAPÍTULO II De la herencia · Sección 8.ª Pago de la porción hereditaria en casos especiales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"843","t":"","x":"Salvo confirmación expresa de todos los hijos o descendientes la partición a que se refieren los dos artículos anteriores requerirá aprobación por el Secretario judicial o Notario.","u":"#art843","c":"CAPÍTULO II De la herencia · Sección 8.ª Pago de la porción hereditaria en casos especiales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"844","t":"","x":"La decisión de pago en metálico no producirá efectos si no se comunica a los perceptores en el plazo de un año desde la apertura de la sucesión. El pago deberá hacerse en el plazo de otro año más, salvo pacto en contrario. Corresponderán al perceptor de la cantidad las garantías legales establecidas para el legatario de cantidad. Transcurrido el plazo sin que el pago haya tenido lugar, caducará la facultad conferida a los hijos o descendientes por el testador o el contador-partidor y se procederá a repartir la herencia según las disposiciones generales sobre la partición.","u":"#art844","c":"CAPÍTULO II De la herencia · Sección 8.ª Pago de la porción hereditaria en casos especiales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"845","t":"","x":"La opción de que tratan los artículos anteriores no afectará a los legados de cosa específica.","u":"#art845","c":"CAPÍTULO II De la herencia · Sección 8.ª Pago de la porción hereditaria en casos especiales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"846","t":"","x":"Tampoco afectará a las disposiciones particionales del testador señaladas en cosas determinadas.","u":"#art846","c":"CAPÍTULO II De la herencia · Sección 8.ª Pago de la porción hereditaria en casos especiales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"847","t":"","x":"Para fijar la suma que haya de abonarse a los hijos o descendientes se atenderá al valor que tuvieren los bienes al tiempo de liquidarles la porción correspondiente, teniendo en cuenta los frutos o rentas hasta entonces producidas. Desde la liquidación, el crédito metálico devengará el interés legal.","u":"#art847","c":"CAPÍTULO II De la herencia · Sección 8.ª Pago de la porción hereditaria en casos especiales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"848","t":"","x":"La desheredación sólo podrá tener lugar por alguna de las causas que expresamente señala la ley.","u":"#art848","c":"CAPÍTULO II De la herencia · Sección 9.ª De la desheredación"},{"n":"CC","a":"849","t":"","x":"La desheredación sólo podrá hacerse en testamento, expresando en él la causa legal en que se funde.","u":"#art849","c":"CAPÍTULO II De la herencia · Sección 9.ª De la desheredación"},{"n":"CC","a":"850","t":"","x":"La prueba de ser cierta la causa de la desheredación corresponderá a los herederos del testador si el desheredado la negare.","u":"#art850","c":"CAPÍTULO II De la herencia · Sección 9.ª De la desheredación"},{"n":"CC","a":"851","t":"","x":"La desheredación hecha sin expresión de causa, o por causa cuya certeza, si fuere contradicha, no se probare, o que no sea una de las señaladas en los cuatro siguientes artículos, anulará la institución de heredero en cuanto perjudique al desheredado; pero valdrán los legados, mejoras y demás disposiciones testamentarias en lo que no perjudiquen a dicha legítima.","u":"#art851","c":"CAPÍTULO II De la herencia · Sección 9.ª De la desheredación"},{"n":"CC","a":"852","t":"","x":"Son justas causas para la desheredación, en los términos que específicamente determinan los artículos ochocientos cincuenta y tres, ochocientos cincuenta y cuatro y ochocientos cincuenta y cinco, las de incapacidad por indignidad para suceder, señaladas en el artículo setecientos cincuenta y seis con los números 1º, 2º, 3º, 5º y 6º.","u":"#art852","c":"CAPÍTULO II De la herencia · Sección 9.ª De la desheredación"},{"n":"CC","a":"853","t":"","x":"Serán también justas causas para desheredar a los hijos y descendientes, además de las señaladas en el artículo 756 con los números 2, 3, 5 y 6, las siguientes: 1.ª Haber negado, sin motivo legítimo, los alimentos al padre o ascendiente que le deshereda. 2.ª Haberle maltratado de obra o injuriado gravemente de palabra.","u":"#art853","c":"CAPÍTULO II De la herencia · Sección 9.ª De la desheredación"},{"n":"CC","a":"854","t":"","x":"Serán justas causas para desheredar a los padres y ascendientes, además de las señaladas en el artículo 756 con los números 1, 2, 3, 5 y 6, las siguientes: 1.ª Haber perdido la patria potestad por las causas expresadas en el artículo 170. 2.ª Haber negado los alimentos a sus hijos o descendientes sin motivo legítimo. 3.ª Haber atentado uno de los padres contra la vida del otro, si no hubiere habido entre ellos reconciliación.","u":"#art854","c":"CAPÍTULO II De la herencia · Sección 9.ª De la desheredación"},{"n":"CC","a":"855","t":"","x":"Serán justas causas para desheredar al cónyuge, además de las señaladas en el artículo 756 con los números 2.º, 3.º, 5.º y 6.º, las siguientes: 1.ª Haber incumplido grave o reiteradamente los deberes conyugales. 2.ª Las que dan lugar a la pérdida de la patria potestad, conforme el artículo 170. 3.ª Haber negado alimentos a los hijos o al otro cónyuge. 4.ª Haber atentado contra la vida del cónyuge testador, si no hubiere mediado reconciliación.","u":"#art855","c":"CAPÍTULO II De la herencia · Sección 9.ª De la desheredación"},{"n":"CC","a":"856","t":"","x":"La reconciliación posterior del ofensor y del ofendido priva a éste del derecho de desheredar, y deja sin efecto la desheredación ya hecha.","u":"#art856","c":"CAPÍTULO II De la herencia · Sección 9.ª De la desheredación"},{"n":"CC","a":"857","t":"","x":"Los hijos o descendientes del desheredado ocuparán su lugar y conservarán los derechos de herederos forzosos respecto a la legítima.","u":"#art857","c":"CAPÍTULO II De la herencia · Sección 9.ª De la desheredación"},{"n":"CC","a":"858","t":"","x":"El testador podrá gravar con mandas y legados no sólo a su heredero, sino también a los legatarios. Éstos no estarán obligados a responder del gravamen sino hasta donde alcance el valor del legado.","u":"#art858","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"859","t":"","x":"Cuando el testador grave con un legado a uno de los herederos, él sólo quedará obligado a su cumplimiento. Si no gravare a ninguno en particular, quedarán obligados todos en la misma proporción en que sean herederos.","u":"#art859","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"860","t":"","x":"El obligado a la entrega del legado responderá en caso de evicción, si la cosa fuere indeterminada y se señalase sólo por género o especie.","u":"#art860","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"861","t":"","x":"El legado de cosa ajena si el testador, al legarla, sabía que lo era, es válido. El heredero estará obligado a adquirirla para entregarla al legatario; y, no siéndole posible, a dar a éste su justa estimación. La prueba de que el testador sabía que la cosa era ajena corresponde al legatario.","u":"#art861","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"862","t":"","x":"Si el testador ignoraba que la cosa que legaba era ajena, será nulo el legado. Pero será válido si la adquiere después de otorgado el testamento.","u":"#art862","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"863","t":"","x":"Será válido el legado hecho a un tercero de una cosa propia del heredero o de un legatario, quienes, al aceptar la sucesión, deberán entregar la cosa legada o su justa estimación, con la limitación establecida en el artículo siguiente. Lo dispuesto en el párrafo anterior se entiende sin perjuicio de la legítima de los herederos forzosos.","u":"#art863","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"864","t":"","x":"Cuando el testador, heredero o legatario tuviesen sólo una parte o un derecho en la cosa legada, se entenderá limitado el legado a esta parte o derecho, a menos que el testador declare expresamente que lega la cosa por entero.","u":"#art864","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"865","t":"","x":"Es nulo el legado de cosas que están fuera del comercio.","u":"#art865","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"866","t":"","x":"No producirá efecto el legado de cosa que al tiempo de hacerse el testamento fuera ya propia del legatario, aunque en ella tuviese algún derecho otra persona. Si el testador dispone expresamente que la cosa sea liberada de este derecho o gravamen, valdrá en cuanto a esto el legado.","u":"#art866","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"867","t":"","x":"Cuando el testador legare una cosa empeñada o hipotecada para la seguridad de alguna deuda exigible, el pago de ésta quedará a cargo del heredero. Si por no pagar el heredero lo hiciere el legatario, quedará éste subrogado en el lugar y derechos del acreedor para reclamar contra el heredero. Cualquiera otra carga perpetua o temporal, a que se halle afecta la cosa legada, pasa con ésta al legatario; pero en ambos casos las rentas y los intereses o réditos devengados hasta la muerte del testador son carga de la herencia.","u":"#art867","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"868","t":"","x":"Si la cosa legada estuviere sujeta a usufructo, uso o habitación, el legatario deberá respetar estos derechos hasta que legalmente se extingan.","u":"#art868","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"869","t":"","x":"El legado quedará sin efecto: 1.º Si el testador transforma la cosa legada, de modo que no conserve ni la forma ni la denominación que tenía. 2.º Si el testador enajena, por cualquier título o causa, la cosa legada o parte de ella, entendiéndose en este último caso que el legado queda sólo sin efecto respecto a la parte enajenada. Si después de la enajenación volviere la cosa al dominio del testador, aunque sea por la nulidad del contrato, no tendrá después de este hecho fuerza el legado, salvo el caso en que la readquisición se verifique por pacto de retroventa. 3.º Si la cosa legada perece del todo viviendo el testador o después de su muerte sin culpa del heredero. Sin embargo, el obligado a pagar el legado responderá por evicción, si la cosa legada no hubiere sido determinada en especie, según lo dispuesto en el artículo 860.","u":"#art869","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"870","t":"","x":"El legado de un crédito contra tercero, o el de perdón o liberación de una deuda del legatario, sólo surtirá efecto en la parte del crédito o de la deuda subsistente al tiempo de morir el testador. En el primer caso, el heredero cumplirá con ceder al legatario todas las acciones que pudieran competirle contra el deudor. En el segundo, con dar al legatario carta de pago, si la pidiere. En ambos casos, el legado comprenderá los intereses que por el crédito o la deuda se debieren al morir el testador.","u":"#art870","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"871","t":"","x":"Caduca el legado de que se habla en el artículo anterior si el testador, después de haberlo hecho, demandare judicialmente al deudor para el pago de su deuda, aunque éste no se haya realizado al tiempo del fallecimiento. Por el legado hecho al deudor de la cosa empeñada sólo se entiende remitido el derecho de prenda.","u":"#art871","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"872","t":"","x":"El legado genérico de liberación o perdón de las deudas comprende las existentes al tiempo de hacerse el testamento, no las posteriores.","u":"#art872","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"873","t":"","x":"El legado hecho a un acreedor no se imputará en pago de su crédito, a no ser que el testador lo declare expresamente. En este caso, el acreedor tendrá derecho a cobrar el exceso del crédito o del legado.","u":"#art873","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"874","t":"","x":"En los legados alternativos se observará lo dispuesto para las obligaciones de la misma especie, salvas las modificaciones que se deriven de la voluntad expresa del testador.","u":"#art874","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"875","t":"","x":"El legado de cosa mueble genérica será válido aunque no haya cosas de su género en la herencia. El legado de cosa inmueble no determinada sólo será válido si la hubiere de su género en la herencia. La elección será del heredero, quien cumplirá con dar una cosa que no sea de la calidad inferior ni de la superior.","u":"#art875","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"876","t":"","x":"Siempre que el testador deje expresamente la elección al heredero o al legatario, el primero podrá dar, o el segundo elegir, lo que mejor les pareciere.","u":"#art876","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"877","t":"","x":"Si el heredero o legatario no pudiere hacer la elección en el caso de haberle sido concedida, pasará su derecho a los herederos; pero, una vez hecha la elección, será irrevocable.","u":"#art877","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"878","t":"","x":"Si la cosa legada era propia del legatario a la fecha del testamento, no vale el legado, aunque después haya sido enajenada. Si el legatario la hubiese adquirido por título lucrativo después de aquella fecha, nada podrá pedir por ello; mas, si la adquisición se hubiese hecho por título oneroso, podrá pedir al heredero que le indemnice de lo que haya dado por adquirirla.","u":"#art878","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"879","t":"","x":"El legado de educación dura hasta que el legatario sea mayor de edad. El de alimentos dura mientras viva el legatario, si el testador no dispone otra cosa. Si el testador no hubiere señalado cantidad para estos legados, se fijará según el estado y condición del legatario y el importe de la herencia. Si el testador acostumbró en vida dar al legatario cierta cantidad de dinero u otras cosas por vía de alimentos, se entenderá legada la misma cantidad, si no resultare en notable desproporción con la cuantía de la herencia.","u":"#art879","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"880","t":"","x":"Legada una pensión periódica o cierta cantidad anual, mensual o semanal, el legatario podrá exigir la del primer período, así que muera el testador, y la de los siguientes en el principio de cada uno de ellos, sin que haya lugar a la devolución aunque el legatario muera antes que termine el período comenzado.","u":"#art880","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"881","t":"","x":"El legatario adquiere derecho a los legados puros y simples desde la muerte del testador, y lo transmite a sus herederos.","u":"#art881","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"882","t":"","x":"Cuando el legado es de cosa específica y determinada, propia del testador, el legatario adquiere su propiedad desde que aquél muere, y hace suyos los frutos o rentas pendientes, pero no las rentas devengadas y no satisfechas antes de la muerte. La cosa legada correrá desde el mismo instante a riesgo del legatario, que sufrirá, por lo tanto, su pérdida o deterioro, como también se aprovechará de su aumento o mejora.","u":"#art882","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"883","t":"","x":"La cosa legada deberá ser entregada con todos sus accesorios y en el estado en que se halle al morir el testador.","u":"#art883","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"884","t":"","x":"Si el legado no fuere de cosa específica y determinada, sino genérico o de cantidad, sus frutos e intereses desde la muerte del testador corresponderán al legatario cuando el testador lo hubiese dispuesto expresamente.","u":"#art884","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"885","t":"","x":"El legatario no puede ocupar por su propia autoridad la cosa legada, sino que debe pedir su entrega y posesión al heredero o al albacea, cuando éste se halle autorizado para darla.","u":"#art885","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"886","t":"","x":"El heredero debe dar la misma cosa legada, pudiendo hacerlo, y no cumple con dar su estimación. Los legados en dinero deberán ser pagados en esta especie, aunque no lo haya en la herencia. Los gastos necesarios para la entrega de la cosa legada serán a cargo de la herencia, pero sin perjuicio de la legítima.","u":"#art886","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"887","t":"","x":"Si los bienes de la herencia no alcanzaren para cubrir todos los legados, el pago se hará en el orden siguiente: 1.º Los legados remuneratorios. 2.º Los legados de cosa cierta y determinada, que forme parte del caudal hereditario. 3.º Los legados que el testador haya declarado preferentes. 4.º Los de alimentos. 5.º Los de educación. 6.º Los demás a prorrata.","u":"#art887","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"888","t":"","x":"Cuando el legatario no pueda o no quiera admitir el legado, o éste, por cualquier causa, no tenga efecto, se refundirá en la masa de la herencia, fuera de los casos de sustitución y derecho de acrecer.","u":"#art888","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"889","t":"","x":"El legatario no podrá aceptar una parte del legado y repudiar la otra, si ésta fuere onerosa. Si muriese antes de aceptar el legado dejando varios herederos, podrá uno de éstos aceptar y otro repudiar la parte que le corresponda en el legado.","u":"#art889","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"890","t":"","x":"El legatario de dos legados, de los que uno fuere oneroso, no podrá renunciar éste y aceptar el otro. Si los dos son onerosos o gratuitos, es libre para aceptarlos todos o repudiar el que quiera. El heredero que sea al mismo tiempo legatario podrá renunciar la herencia y aceptar el legado, o renunciar éste y aceptar aquélla.","u":"#art890","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"891","t":"","x":"Si toda la herencia se distribuye en legados, se prorratearán las deudas y gravámenes de ella entre los legatarios a proporción de sus cuotas, a no ser que el testador hubiera dispuesto otra cosa.","u":"#art891","c":"CAPÍTULO II De la herencia · Sección 10.ª De las mandas y legados"},{"n":"CC","a":"892","t":"","x":"El testador podrá nombrar uno o más albaceas.","u":"#art892","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"893","t":"","x":"No podrá ser albacea el que no tenga capacidad para obligarse. El menor no podrá serlo, ni aún con la autorización del padre o del tutor.","u":"#art893","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"894","t":"","x":"El albacea puede ser universal o particular. En todo caso, los albaceas podrán ser nombrados mancomunada, sucesiva o solidariamente.","u":"#art894","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"895","t":"","x":"Cuando los albaceas fueren mancomunados, sólo valdrá lo que todos hagan de consuno, o lo que haga uno de ellos legalmente autorizado por los demás, o lo que, en caso de disidencia, acuerde el mayor número.","u":"#art895","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"896","t":"","x":"En los casos de suma urgencia podrá uno de los albaceas mancomunados practicar, bajo su responsabilidad personal, los actos que fueren necesarios, dando cuenta inmediatamente a los demás.","u":"#art896","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"897","t":"","x":"Si el testador no establece claramente la solidaridad de los albaceas, ni fija el orden en que deben desempeñar su encargo, se entenderán nombrados mancomunadamente y desempeñarán el cargo como previenen los dos artículos anteriores.","u":"#art897","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"898","t":"","x":"El albaceazgo es cargo voluntario, y se entenderá aceptado por el nombrado para desempeñarlo si no se excusa dentro de los seis días siguientes a aquel en que tenga noticia de su nombramiento, o, si éste le era ya conocido, dentro de los seis días siguientes al en que supo la muerte del testador.","u":"#art898","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"899","t":"","x":"El albacea que acepta el cargo se constituye en la obligación de desempeñarlo; pero lo podrá renunciar alegando causa justa al criterio del Secretario judicial o del Notario.","u":"#art899","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"900","t":"","x":"El albacea que no acepte el cargo, o lo renuncie sin justa causa, perderá lo que le hubiese dejado el testador, salvo siempre el derecho que tuviere a la legítima.","u":"#art900","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"901","t":"","x":"Los albaceas tendrán todas las facultades que expresamente les haya conferido el testador y no sean contrarias a las leyes.","u":"#art901","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"902","t":"","x":"No habiendo el testador determinado especialmente las facultades de los albaceas, tendrán las siguientes: 1.ª Disponer y pagar los sufragios y el funeral del testador con arreglo a lo dispuesto por él en el testamento; y, en su defecto, según la costumbre del pueblo. 2.ª Satisfacer los legados que consistan en metálico, con el conocimiento y beneplácito del heredero. 3.ª Vigilar sobre la ejecución de todo lo demás ordenado en el testamento, y sostener, siendo justo, su validez en juicio y fuera de él. 4.ª Tomar las precauciones necesarias para la conservación y custodia de los bienes, con intervención de los herederos presentes.","u":"#art902","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"903","t":"","x":"Si no hubiere en la herencia dinero bastante para el pago de funerales y legados, y los herederos no lo aprontaren de lo suyo, promoverán los albaceas la venta de los bienes muebles; y no alcanzando éstos, la de los inmuebles, con intervención de los herederos. Si estuviere interesado en la herencia algún menor, ausente, corporación o establecimiento público, la venta de los bienes se hará con las formalidades prevenidas por las leyes para tales casos.","u":"#art903","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"904","t":"","x":"El albacea, a quien el testador no haya fijado plazo, deberá cumplir su encargo dentro de un año, contado desde su aceptación, o desde que terminen los litigios que se promovieren sobre la validez o nulidad del testamento o de algunas de sus disposiciones.","u":"#art904","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"905","t":"","x":"Si el testador quisiera ampliar el plazo legal, deberá señalar expresamente el de la prórroga. Si no lo hubiese señalado, se entenderá prorrogado el plazo por un año. Si, transcurrida esta prórroga, no se hubiese cumplido todavía la voluntad del testador, podrá el Secretario judicial o el Notario conceder otra por el tiempo que fuere necesario, atendidas las circunstancias del caso.","u":"#art905","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"906","t":"","x":"Los herederos y legatarios podrán, de común acuerdo, prorrogar el plazo del albaceazgo por el tiempo que crean necesario; pero, si el acuerdo fuese sólo por mayoría, la prórroga no podrá exceder de un año.","u":"#art906","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"907","t":"","x":"Los albaceas deberán dar cuenta de su encargo a los herederos. Si hubieren sido nombrados no para entregar los bienes a herederos determinados, sino para darles la inversión o distribución que el testador hubiese dispuesto en los casos permitidos por derecho, rendirán sus cuentas al Juez. Toda disposición del testador contraria a este artículo será nula.","u":"#art907","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"908","t":"","x":"El albaceazgo es cargo gratuito. Podrá, sin embargo, el testador señalar a los albaceas la remuneración que tenga por conveniente; todo sin perjuicio del derecho que les asista para cobrar lo que les corresponda por los trabajos de partición u otros facultativos. Si el testador lega o señala conjuntamente a los albaceas alguna retribución, la parte de los que no admitan el cargo acrecerá a los que lo desempeñen.","u":"#art908","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"909","t":"","x":"El albacea no podrá delegar el cargo si no tuviese expresa autorización del testador.","u":"#art909","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"910","t":"","x":"Termina el albaceazgo por la muerte, imposibilidad, renuncia o remoción del albacea, y por el lapso del término señalado por el testador, por la ley y, en su caso, por los interesados. La remoción deberá ser apreciada por el Juez.","u":"#art910","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"911","t":"","x":"En los casos del artículo anterior, y en el de no haber el albacea aceptado el cargo, corresponderá a los herederos la ejecución de la voluntad del testador.","u":"#art911","c":"CAPÍTULO II De la herencia · Sección 11.ª De los albaceas o testamentarios"},{"n":"CC","a":"912","t":"","x":"La sucesión legítima tiene lugar: 1.º Cuando uno muere sin testamento, o con testamento nulo, o que haya perdido después su validez. 2.º Cuando el testamento no contiene institución de heredero en todo o en parte de los bienes o no dispone de todos los que corresponden al testador. En este caso, la sucesión legítima tendrá lugar solamente respecto de los bienes de que no hubiese dispuesto. 3.º Cuando falta la condición puesta a la institución del heredero, o éste muere antes que el testador, o repudia la herencia sin tener sustituto y sin que haya lugar al derecho de acrecer. 4.º Cuando el heredero instituido es incapaz de suceder.","u":"#art912","c":"CAPÍTULO III De la sucesión intestada · Sección 1.ª Disposiciones generales"},{"n":"CC","a":"913","t":"","x":"A falta de herederos testamentarios, la ley defiere a los parientes del difunto, al viudo o viuda y al Estado.","u":"#art913","c":"CAPÍTULO III De la sucesión intestada · Sección 1.ª Disposiciones generales"},{"n":"CC","a":"914","t":"","x":"Lo dispuesto sobre la incapacidad para suceder por testamento es aplicable igualmente a la sucesión intestada.","u":"#art914","c":"CAPÍTULO III De la sucesión intestada · Sección 1.ª Disposiciones generales"},{"n":"CC","a":"914 bis","t":"","x":"A falta de disposición testamentaria relativa a los animales de compañía propiedad del causante, estos se entregarán a los herederos o legatarios que los reclamen de acuerdo con las leyes. Si no fuera posible hacerlo de inmediato, para garantizar el cuidado del animal de compañía y solo cuando sea necesario por falta de previsiones sobre su atención, se entregará al órgano administrativo o centro que tenga encomendada la recogida de animales abandonados hasta que se resuelvan los correspondientes trámites por razón de sucesión. Si ninguno de los sucesores quiere hacerse cargo del animal de compañía, el órgano administrativo competente podrá cederlo a un tercero para su cuidado y protección. Si más de un heredero reclama el animal de compañía y no hay acuerdo unánime sobre el destino del mismo, la autoridad judicial decidirá su destino teniendo en cuenta el bienestar del animal.","u":"#a9-2","c":"CAPÍTULO III De la sucesión intestada · Sección 1.ª Disposiciones generales"},{"n":"CC","a":"915","t":"","x":"La proximidad del parentesco se determina por el número de generaciones. Cada generación forma un grado.","u":"#art915","c":"CAPÍTULO III De la sucesión intestada · Sección 2.ª Del parentesco"},{"n":"CC","a":"916","t":"","x":"La serie de grados forma la línea, que puede ser directa o colateral. Se llama directa la constituida por la serie de grados entre personas que descienden una de otra. Y colateral la constituida por la serie de grados entre personas que no descienden unas de otras, pero que proceden de un tronco común.","u":"#art916","c":"CAPÍTULO III De la sucesión intestada · Sección 2.ª Del parentesco"},{"n":"CC","a":"917","t":"","x":"Se distingue la línea recta en descendente y ascendente. La primera une al cabeza de familia con los que descienden de él. La segunda liga a una persona con aquellos de quienes desciende.","u":"#art917","c":"CAPÍTULO III De la sucesión intestada · Sección 2.ª Del parentesco"},{"n":"CC","a":"918","t":"","x":"En las líneas se cuentan tantos grados como generaciones o como personas, descontando la del progenitor. En la recta se sube únicamente hasta el tronco. Así, el hijo dista del padre un grado, dos del abuelo y tres del bisabuelo. En la colateral se sube hasta el tronco común y después se baja hasta la persona con quien se hace la computación. Por esto, el hermano dista dos grados del hermano, tres del tío, hermano de su padre o madre, cuatro del primo hermano y así en adelante.","u":"#art918","c":"CAPÍTULO III De la sucesión intestada · Sección 2.ª Del parentesco"},{"n":"CC","a":"919","t":"","x":"El cómputo de que trata el artículo anterior rige en todas las materias.","u":"#art919","c":"CAPÍTULO III De la sucesión intestada · Sección 2.ª Del parentesco"},{"n":"CC","a":"920","t":"","x":"Llámase doble vínculo al parentesco por parte del padre y de la madre conjuntamente.","u":"#art920","c":"CAPÍTULO III De la sucesión intestada · Sección 2.ª Del parentesco"},{"n":"CC","a":"921","t":"","x":"En las herencias, el pariente más próximo en grado excluye al más remoto, salvo el derecho de representación en los casos en que deba tener lugar. Los parientes que se hallaren en el mismo grado heredarán por partes iguales, salvo lo que se dispone en el artículo 949 sobre el doble vínculo.","u":"#art921","c":"CAPÍTULO III De la sucesión intestada · Sección 2.ª Del parentesco"},{"n":"CC","a":"922","t":"","x":"Si hubiere varios parientes de un mismo grado, y alguno o algunos no quisieren o no pudieren suceder, su parte acrecerá a los otros del mismo grado, salvo el derecho de representación cuando deba tener lugar.","u":"#art922","c":"CAPÍTULO III De la sucesión intestada · Sección 2.ª Del parentesco"},{"n":"CC","a":"923","t":"","x":"Repudiando la herencia el pariente más próximo, si es solo, o, si fueren varios, todos los parientes más próximos llamados por la ley heredarán los del grado siguiente por su propio derecho y sin que puedan representar al repudiante.","u":"#art923","c":"CAPÍTULO III De la sucesión intestada · Sección 2.ª Del parentesco"},{"n":"CC","a":"924","t":"","x":"Llámase derecho de representación el que tienen los parientes de una persona para sucederle en todos los derechos que tendría si viviera o hubiera podido heredar.","u":"#art924","c":"CAPÍTULO III De la sucesión intestada · Sección 3.ª De la representación"},{"n":"CC","a":"925","t":"","x":"El derecho de representación tendrá siempre lugar en la línea recta descendente, pero nunca en la ascendente. En la línea colateral sólo tendrá lugar en favor de los hijos de hermanos, bien sean de doble vínculo, bien de un solo lado.","u":"#art925","c":"CAPÍTULO III De la sucesión intestada · Sección 3.ª De la representación"},{"n":"CC","a":"926","t":"","x":"Siempre que se herede por representación, la división de la herencia se hará por estirpes, de modo que el representante o representantes no hereden más de lo que heredaría su representado, si viviera.","u":"#art926","c":"CAPÍTULO III De la sucesión intestada · Sección 3.ª De la representación"},{"n":"CC","a":"927","t":"","x":"Quedando hijos de uno o más hermanos del difunto, heredarán a éste por representación si concurren con sus tíos. Pero si concurren solos, heredarán por partes iguales.","u":"#art927","c":"CAPÍTULO III De la sucesión intestada · Sección 3.ª De la representación"},{"n":"CC","a":"928","t":"","x":"No se pierde el derecho de representar a una persona por haber renunciado su herencia.","u":"#art928","c":"CAPÍTULO III De la sucesión intestada · Sección 3.ª De la representación"},{"n":"CC","a":"929","t":"","x":"No podrá representarse a una persona viva sino en los casos de desheredación o incapacidad.","u":"#art929","c":"CAPÍTULO III De la sucesión intestada · Sección 3.ª De la representación"},{"n":"CC","a":"930","t":"","x":"La sucesión corresponde en primer lugar a la línea recta descendente.","u":"#art930","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 1.ª De la línea recta descendente"},{"n":"CC","a":"931","t":"","x":"Los hijos y sus descendientes suceden a sus padres y demás ascendientes sin distinción de sexo, edad o filiación.","u":"#art931","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 1.ª De la línea recta descendente"},{"n":"CC","a":"932","t":"","x":"Los hijos del difunto le heredarán siempre por su derecho propio, dividiendo la herencia en partes iguales.","u":"#art932","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 1.ª De la línea recta descendente"},{"n":"CC","a":"933","t":"","x":"Los nietos y demás descendientes heredarán por derecho de representación, y, si alguno hubiese fallecido dejando varios herederos, la porción que le corresponda se dividirá entre éstos por partes iguales.","u":"#art933","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 1.ª De la línea recta descendente"},{"n":"CC","a":"934","t":"","x":"Si quedaren hijos y descendientes de otros hijos que hubiesen fallecido, los primeros heredarán por derecho propio, y los segundos, por derecho de representación.","u":"#art934","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 1.ª De la línea recta descendente"},{"n":"CC","a":"935","t":"","x":"A falta de hijos y descendientes del difunto le heredarán sus ascendientes.","u":"#art935","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 2.ª De la línea recta ascendente"},{"n":"CC","a":"936","t":"","x":"El padre y la madre heredarán por partes iguales.","u":"#art936","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 2.ª De la línea recta ascendente"},{"n":"CC","a":"937","t":"","x":"En el caso de que sobreviva uno solo de los padres, éste sucederá al hijo en toda su herencia.","u":"#art937","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 2.ª De la línea recta ascendente"},{"n":"CC","a":"938","t":"","x":"A falta de padre y de madre sucederán los ascendientes más próximos en grado.","u":"#art938","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 2.ª De la línea recta ascendente"},{"n":"CC","a":"939","t":"","x":"Si hubiere varios ascendientes de igual grado pertenecientes a la misma línea, dividirán la herencia por cabezas.","u":"#art939","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 2.ª De la línea recta ascendente"},{"n":"CC","a":"940","t":"","x":"Si los ascendientes fueren de líneas diferentes, pero de igual grado, la mitad corresponderá a los ascendientes paternos y la otra mitad a los maternos.","u":"#art940","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 2.ª De la línea recta ascendente"},{"n":"CC","a":"941","t":"","x":"En cada línea la división se hará por cabezas.","u":"#art941","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 2.ª De la línea recta ascendente"},{"n":"CC","a":"942","t":"","x":"Lo dispuesto en esta Sección se entiende sin perjuicio de lo ordenado en los artículos 811 y 812, que es aplicable a la sucesión intestada y a la testamentaria.","u":"#art942","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 2.ª De la línea recta ascendente"},{"n":"CC","a":"943","t":"","x":"A falta de las personas comprendidas en las dos Secciones que preceden, heredarán el cónyuge y los parientes colaterales por el orden que se establece en los artículos siguientes.","u":"#art943","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 3.ª De la sucesión del cónyuge y de los colaterales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"944","t":"","x":"En defecto de ascendientes y descendientes, y antes que los colaterales, sucederá en todos los bienes del difunto el cónyuge sobreviviente.","u":"#art944","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 3.ª De la sucesión del cónyuge y de los colaterales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"945","t":"","x":"No tendrá lugar el llamamiento a que se refiere el artículo anterior si el cónyuge estuviere separado legalmente o de hecho.","u":"#art945","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 3.ª De la sucesión del cónyuge y de los colaterales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"946","t":"","x":"Los hermanos e hijos de hermanos suceden con preferencia a los demás colaterales.","u":"#art946","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 3.ª De la sucesión del cónyuge y de los colaterales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"947","t":"","x":"Si no existieran más que hermanos de doble vínculo, éstos heredarán por partes iguales.","u":"#art947","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 3.ª De la sucesión del cónyuge y de los colaterales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"948","t":"","x":"Si concurrieren hermanos con sobrinos, hijos de hermanos de doble vínculo, los primeros heredarán por cabezas y los segundos por estirpes.","u":"#art948","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 3.ª De la sucesión del cónyuge y de los colaterales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"949","t":"","x":"Si concurrieren hermanos de padre y madre con medio hermanos, aquéllos tomarán doble porción que éstos en la herencia.","u":"#art949","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 3.ª De la sucesión del cónyuge y de los colaterales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"950","t":"","x":"En el caso de no existir sino medio hermanos, unos por parte de padre y otros por la de la madre, heredarán todos por partes iguales, sin ninguna distinción de bienes.","u":"#art950","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 3.ª De la sucesión del cónyuge y de los colaterales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"951","t":"","x":"Los hijos de los medio hermanos sucederán por cabezas o por estirpes, según las reglas establecidas para los hermanos de doble vínculo.","u":"#art951","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 3.ª De la sucesión del cónyuge y de los colaterales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"954","t":"","x":"No habiendo cónyuge supérstite, ni hermanos ni hijos de hermanos, sucederán en la herencia del difunto los demás parientes del mismo en línea colateral hasta el cuarto grado, más allá del cual no se extiende el derecho de heredar abintestato.","u":"#art954","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 3.ª De la sucesión del cónyuge y de los colaterales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"955","t":"","x":"La sucesión de estos colaterales se verificará sin distinción de líneas ni preferencia entre ellos por razón del doble vínculo.","u":"#art955","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 3.ª De la sucesión del cónyuge y de los colaterales Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"956","t":"","x":"A falta de personas que tengan derecho a heredar conforme a lo dispuesto en las precedentes Secciones, heredará el Estado quien, realizada la liquidación del caudal hereditario, ingresará la cantidad resultante en el Tesoro Público, salvo que, por la naturaleza de los bienes heredados, el Consejo de Ministros acuerde darles, total o parcialmente, otra aplicación. Dos terceras partes del valor de ese caudal relicto será destinado a fines de interés social, añadiéndose a la asignación tributaria que para estos fines se realice en los Presupuestos Generales del Estado.","u":"#art956","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 4.ª De la sucesión del Estado Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"957","t":"","x":"Los derechos y obligaciones del Estado serán los mismos que los de los demás herederos, pero se entenderá siempre aceptada la herencia a beneficio de inventario, sin necesidad de declaración alguna sobre ello, a los efectos que enumera el artículo 1023.","u":"#art957","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 4.ª De la sucesión del Estado Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"958","t":"","x":"Para que el Estado pueda tomar posesión de los bienes y derechos hereditarios habrá de preceder declaración administrativa de heredero, adjudicándose los bienes por falta de herederos legítimos.","u":"#art958","c":"CAPÍTULO IV Del orden de suceder según la diversidad de líneas · Sección 4.ª De la sucesión del Estado Se modifica la rúbrica por el art. 6 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"958 bis","t":"","x":"Todas las referencias realizadas a la viuda en esta sección, se entenderán hechas a la viuda o al cónyuge supérstite gestante.","u":"#a","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 1.ª De las precauciones que deben adoptarse cuando la viuda queda encinta"},{"n":"CC","a":"959","t":"","x":"Cuando la viuda crea haber quedado encinta, deberá ponerlo en conocimiento de los que tengan a la herencia un derecho de tal naturaleza que deba desaparecer o disminuir por el nacimiento del póstumo.","u":"#art959","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 1.ª De las precauciones que deben adoptarse cuando la viuda queda encinta"},{"n":"CC","a":"960","t":"","x":"Los interesados a que se refiere el precedente artículo podrán pedir al Juez municipal o al de primera instancia, donde lo hubiere, que dicte las providencias convenientes para evitar la suposición de parto, o que la criatura que nazca pase por viable, no siéndolo en realidad. Cuidará el Juez de que las medidas que dicte no ataquen al pudor ni a la libertad de la viuda.","u":"#art960","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 1.ª De las precauciones que deben adoptarse cuando la viuda queda encinta"},{"n":"CC","a":"961","t":"","x":"Háyase o no dado el aviso de que habla el artículo 959, al aproximarse la época del parto, la viuda deberá ponerlo en conocimiento de los mismos interesados. Éstos tendrán derecho a nombrar persona de su confianza que se cerciore de la realidad del alumbramiento. Si la persona designada fuere rechazada por la paciente, hará el Juez el nombramiento, debiendo éste recaer en facultativo o en mujer.","u":"#art961","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 1.ª De las precauciones que deben adoptarse cuando la viuda queda encinta"},{"n":"CC","a":"962","t":"","x":"La omisión de estas diligencias no basta por sí sola para acreditar la suposición del parto o la falta de viabilidad del nacido.","u":"#art962","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 1.ª De las precauciones que deben adoptarse cuando la viuda queda encinta"},{"n":"CC","a":"963","t":"","x":"Cuando el marido hubiere reconocido en documento público o privado la certeza de la preñez de su esposa, estará ésta dispensada de dar el aviso que previene el artículo 959, pero quedará sujeta a cumplir lo dispuesto en el 961.","u":"#art963","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 1.ª De las precauciones que deben adoptarse cuando la viuda queda encinta"},{"n":"CC","a":"964","t":"","x":"La viuda que quede encinta, aun cuando sea rica, deberá ser alimentada de los bienes hereditarios, habida consideración a la parte que en ellos pueda tener el póstumo si naciere y fuere viable.","u":"#art964","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 1.ª De las precauciones que deben adoptarse cuando la viuda queda encinta"},{"n":"CC","a":"965","t":"","x":"En el tiempo que medie hasta que se verifique el parto, o se adquiera la certidumbre de que éste no tendrá lugar, ya por haber ocurrido aborto, ya por haber pasado con exceso el término máximo para la gestación, se proveerá a la seguridad y administración de los bienes en la forma establecida para el juicio necesario de testamentaría.","u":"#art965","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 1.ª De las precauciones que deben adoptarse cuando la viuda queda encinta"},{"n":"CC","a":"966","t":"","x":"La división de la herencia se suspenderá hasta que se verifique el parto o el aborto, o resulte por el transcurso del tiempo que la viuda no estaba encinta. Sin embargo, el administrador podrá pagar a los acreedores, previo mandato judicial.","u":"#art966","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 1.ª De las precauciones que deben adoptarse cuando la viuda queda encinta"},{"n":"CC","a":"967","t":"","x":"Verificado el parto o el aborto, o transcurrido el término de la gestación, el administrador de los bienes hereditarios cesará en su encargo y dará cuenta de su desempeño a los herederos o a sus legítimos representantes.","u":"#art967","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 1.ª De las precauciones que deben adoptarse cuando la viuda queda encinta"},{"n":"CC","a":"968","t":"","x":"Además de la reserva impuesta en el artículo 811, el viudo o viuda que pase a segundo matrimonio estará obligado a reservar a los hijos y descendientes del primero la propiedad de todos los bienes que haya adquirido de su difunto consorte por testamento, por sucesión intestada, donación u otro cualquier título lucrativo; pero no su mitad de gananciales.","u":"#art968","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 2.ª De los bienes sujetos a reserva"},{"n":"CC","a":"969","t":"","x":"La disposición del artículo anterior es aplicable a los bienes que, por los títulos en él expresados, haya adquirido el viudo o viuda de cualquiera de los hijos de su primer matrimonio y los que haya habido de los parientes del difunto por consideración a éste.","u":"#art969","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 2.ª De los bienes sujetos a reserva"},{"n":"CC","a":"970","t":"","x":"Cesará la obligación de reservar cuando los hijos de un matrimonio, mayores de edad, que tengan derecho a los bienes, renuncien expresamente a él, o cuando se trate de cosas dadas o dejadas por los hijos a su padre o a su madre, sabiendo que estaban segunda vez casados.","u":"#art970","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 2.ª De los bienes sujetos a reserva"},{"n":"CC","a":"971","t":"","x":"Cesará además la reserva si al morir el padre o la madre que contrajo segundo matrimonio no existen hijos ni descendientes del primero.","u":"#art971","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 2.ª De los bienes sujetos a reserva"},{"n":"CC","a":"972","t":"","x":"A pesar de la obligación de reservar, podrá el padre o madre, segunda vez casado, mejorar en los bienes reservables a cualquiera de los hijos o descendientes del primer matrimonio, conforme a lo dispuesto en el artículo 823.","u":"#art972","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 2.ª De los bienes sujetos a reserva"},{"n":"CC","a":"973","t":"","x":"Si el padre o la madre no hubiere usado, en todo o en parte, de la facultad que le concede el artículo anterior, los hijos y descendientes del primer matrimonio sucederán en los bienes sujetos a reserva, conforme a las reglas prescritas para la sucesión en línea descendente, aunque a virtud de testamento hubiesen heredado desigualmente al cónyuge premuerto o hubiesen repudiado su herencia. El hijo desheredado justamente por el padre o por la madre perderá todo derecho a la reserva, pero si tuviere hijos o descendientes, se estará a lo dispuesto en el artículo 857 y en el número 2 del artículo 164.","u":"#art973","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 2.ª De los bienes sujetos a reserva"},{"n":"CC","a":"974","t":"","x":"Serán válidas las enajenaciones de los bienes inmuebles reservables hechas por el cónyuge sobreviviente antes de celebrar segundas bodas, con la obligación, desde que las celebrare, de asegurar el valor de aquéllos a los hijos y descendientes del primer matrimonio.","u":"#art974","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 2.ª De los bienes sujetos a reserva"},{"n":"CC","a":"975","t":"","x":"La enajenación que de los bienes inmuebles sujetos a reserva hubiere hecho el viudo o la viuda después de contraer segundo matrimonio subsistirá únicamente si a su muerte no quedan hijos ni descendientes del primero, sin perjuicio de lo dispuesto en la Ley Hipotecaria.","u":"#art975","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 2.ª De los bienes sujetos a reserva"},{"n":"CC","a":"976","t":"","x":"Las enajenaciones de los bienes muebles hechas antes o después de contraer segundo matrimonio serán válidas, salva siempre la obligación de indemnizar.","u":"#art976","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 2.ª De los bienes sujetos a reserva"},{"n":"CC","a":"977","t":"","x":"El viudo o la viuda, al repetir matrimonio, hará inventariar todos los bienes sujetos a reserva, anotar en el Registro de la Propiedad la calidad de reservables de los inmuebles con arreglo a lo dispuesto en la Ley Hipotecaria y tasar los muebles.","u":"#art977","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 2.ª De los bienes sujetos a reserva"},{"n":"CC","a":"978","t":"","x":"Estará, además, obligado el viudo o viuda, al repetir matrimonio, a asegurar con hipoteca: 1.º La restitución de los bienes muebles no enajenados en el estado que tuvieren al tiempo de su muerte. 2.º El abono de los deterioros ocasionados o que se ocasionaren por su culpa o negligencia. 3.º La devolución del precio que hubiese recibido por los bienes muebles enajenados o la entrega del valor que tenían al tiempo de la enajenación, si ésta se hubiese hecho a título gratuito. 4.º El valor de los bienes inmuebles válidamente enajenados.","u":"#art978","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 2.ª De los bienes sujetos a reserva"},{"n":"CC","a":"979","t":"","x":"Lo dispuesto en los artículos anteriores para el caso de segundo matrimonio rige igualmente en el tercero y ulteriores.","u":"#art979","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 2.ª De los bienes sujetos a reserva"},{"n":"CC","a":"980","t":"","x":"La obligación de reservar impuesta en los anteriores artículos será también aplicable: 1.° Al viudo que durante el matrimonio haya tenido o en estado de viudez tenga un hijo no matrimonial. 2.° Al viudo que adopte a otra persona. Se exceptúa el caso de que el adoptado sea hijo del consorte de quien descienden los que serían reservatarios. Dicha obligación de reservar surtirá efecto, respectivamente, desde el nacimiento o la adopción del hijo.","u":"#art980","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 2.ª De los bienes sujetos a reserva"},{"n":"CC","a":"981","t":"","x":"En las sucesiones legítimas la parte del que repudia la herencia acrecerá siempre a los coherederos.","u":"#art981","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 3.ª Del derecho de acrecer"},{"n":"CC","a":"982","t":"","x":"Para que en la sucesión testamentaria tenga lugar el derecho de acrecer, se requiere: 1.º Que dos o más sean llamados a una misma herencia, o a una misma porción de ella, sin especial designación de partes. 2.º Que uno de los llamados muera antes que el testador, o que renuncie la herencia, o sea incapaz de recibirla.","u":"#art982","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 3.ª Del derecho de acrecer"},{"n":"CC","a":"983","t":"","x":"Se entenderá hecha la designación por partes sólo en el caso de que el testador haya determinado expresamente una cuota para cada heredero. La frase «por mitad o por partes iguales» u otras que, aunque designen parte alícuota, no fijan ésta numéricamente o por señales que hagan a cada uno dueño de un cuerpo de bienes separado, no excluyen el derecho de acrecer.","u":"#art983","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 3.ª Del derecho de acrecer"},{"n":"CC","a":"984","t":"","x":"Los herederos a quienes acrezca la herencia sucederán en todos los derechos y obligaciones que tendría el que no quiso o no pudo recibirla.","u":"#art984","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 3.ª Del derecho de acrecer"},{"n":"CC","a":"985","t":"","x":"Entre los herederos forzosos el derecho de acrecer sólo tendrá lugar cuando la parte de libre disposición se deje a dos o más de ellos, o a alguno de ellos y a un extraño. Si la parte repudiada fuere la legítima, sucederán en ella los coherederos por su derecho propio, y no por el derecho de acrecer.","u":"#art985","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 3.ª Del derecho de acrecer"},{"n":"CC","a":"986","t":"","x":"En la sucesión testamentaria, cuando no tenga lugar el derecho de acrecer, la porción vacante del instituido, a quien no se hubiese designado sustituto, pasará a los herederos legítimos del testador, los cuales la recibirán con las mismas cargas y obligaciones.","u":"#art986","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 3.ª Del derecho de acrecer"},{"n":"CC","a":"987","t":"","x":"El derecho de acrecer tendrá también lugar entre los legatarios y los usufructuarios en los términos establecidos para los herederos.","u":"#art987","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 3.ª Del derecho de acrecer"},{"n":"CC","a":"988","t":"","x":"La aceptación y repudiación de la herencia son actos enteramente voluntarios y libres.","u":"#art988","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"989","t":"","x":"Los efectos de la aceptación y de la repudiación se retrotraen siempre al momento de la muerte de la persona a quien se hereda.","u":"#art989","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"990","t":"","x":"La aceptación o la repudiación de la herencia no podrá hacerse en parte, a plazo, ni condicionalmente.","u":"#art990","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"991","t":"","x":"Nadie podrá aceptar ni repudiar sin estar cierto de la muerte de la persona a quien haya de heredar y de su derecho a la herencia.","u":"#art991","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"992","t":"","x":"Pueden aceptar o repudiar una herencia todos los que tienen la libre disposición de sus bienes. La aceptación de la que se deje a los pobres corresponderá a las personas designadas por el testador para calificarlos y distribuir los bienes, y en su defecto a las que señala el artículo 749, y se entenderá aceptada a beneficio de inventario.","u":"#art992","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"993","t":"","x":"Los legítimos representantes de las asociaciones, corporaciones y fundaciones capaces de adquirir podrán aceptar la herencia que a las mismas se dejare; mas para repudiarla necesitan la aprobación judicial, con audiencia del Ministerio público.","u":"#art993","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"994","t":"","x":"Los establecimientos públicos oficiales no podrán aceptar ni repudiar herencia sin la aprobación del Gobierno.","u":"#art994","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"995","t":"","x":"Cuando la herencia sea aceptada sin beneficio de inventario, por persona casada y no concurra el otro cónyuge, prestando su consentimiento a la aceptación, no responderán de las deudas hereditarias los bienes de la sociedad conyugal.","u":"#art995","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"996","t":"","x":"La aceptación de la herencia por la persona con discapacidad se prestará por esta, salvo que otra cosa resulte de las medidas de apoyo establecidas.","u":"#art996","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"997","t":"","x":"La aceptación y la repudiación de la herencia, una vez hechas, son irrevocables, y no podrán ser impugnadas sino cuando adoleciesen de algunos de los vicios que anulan el consentimiento, o apareciese un testamento desconocido.","u":"#art997","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"998","t":"","x":"La herencia podrá ser aceptada pura y simplemente o a beneficio de inventario.","u":"#art998","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"999","t":"","x":"La aceptación pura y simple puede ser expresa o tácita. Expresa es la que se hace en documento público o privado. Tácita es la que se hace por actos que suponen necesariamente la voluntad de aceptar, o que no habría derecho a ejecutar sino con la cualidad de heredero. Los actos de mera conservación o administración provisional no implican la aceptación de la herencia, si con ellos no se ha tomado el título o la cualidad de heredero.","u":"#art999","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"1000","t":"","x":"Entiéndese aceptada la herencia: 1.º Cuando el heredero vende, dona o cede su derecho a un extraño, a todos sus coherederos o a alguno de ellos. 2.º Cuando el heredero la renuncia, aunque sea gratuitamente, a beneficio de uno o más de sus coherederos. 3.º Cuando la renuncia por precio a favor de todos sus coherederos indistintamente; pero, si esta renuncia fuere gratuita y los coherederos a cuyo favor se haga son aquellos a quienes debe acrecer la porción renunciada, no se entenderá aceptada la herencia.","u":"#art1000","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"1001","t":"","x":"Si el heredero repudia la herencia en perjuicio de sus propios acreedores, podrán éstos pedir al Juez que los autorice para aceptarla en nombre de aquél. La aceptación sólo aprovechará a los acreedores en cuanto baste a cubrir el importe de sus créditos. El exceso, si lo hubiere, no pertenecerá en ningún caso al renunciante, sino que se adjudicará a las personas a quienes corresponda según las reglas establecidas en este Código.","u":"#art1001","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"1002","t":"","x":"Los herederos que hayan sustraído u ocultado algunos efectos de la herencia pierden la facultad de renunciarla y quedan con el carácter de herederos puros y simples, sin perjuicio de las penas en que hayan podido incurrir.","u":"#art1002","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"1003","t":"","x":"Por la aceptación pura y simple, o sin beneficio de inventario, quedará el heredero responsable de todas las cargas de la herencia, no sólo con los bienes de ésta, sino también con los suyos propios.","u":"#art1003","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"1004","t":"","x":"Hasta pasados nueve días después de la muerte de aquel de cuya herencia se trate, no podrá intentarse acción contra el heredero para que acepte o repudie.","u":"#art1004","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"1005","t":"","x":"Cualquier interesado que acredite su interés en que el heredero acepte o repudie la herencia podrá acudir al Notario para que éste comunique al llamado que tiene un plazo de treinta días naturales para aceptar pura o simplemente, o a beneficio de inventario, o repudiar la herencia. El Notario le indicará, además, que si no manifestare su voluntad en dicho plazo se entenderá aceptada la herencia pura y simplemente.","u":"#art1005","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"1006","t":"","x":"Por muerte del heredero sin aceptar ni repudiar la herencia pasará a los suyos el mismo derecho que él tenía.","u":"#art1006","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"1007","t":"","x":"Cuando fueren varios los herederos llamados a la herencia, podrán los unos aceptarla y los otros repudiarla. De igual libertad gozará cada uno de los herederos para aceptarla pura y simplemente o a beneficio de inventario.","u":"#art1007","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"1008","t":"","x":"La repudiación de la herencia deberá hacerse ante Notario en instrumento público.","u":"#art1008","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"1009","t":"","x":"El que es llamado a una misma herencia por testamento y ab intestato y la repudia por el primer título, se entiende haberla repudiado por los dos. Repudiándola como heredero ab intestato y sin noticia de su título testamentario, podrá todavía aceptarla por éste.","u":"#art1009","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 4.ª De la aceptación y repudiación de la herencia"},{"n":"CC","a":"1010","t":"","x":"Todo heredero puede aceptar la herencia a beneficio de inventario, aunque el testador se lo haya prohibido. También podrá pedir la formación de inventario antes de aceptar o repudiar la herencia, para deliberar sobre este punto.","u":"#art1010","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1011","t":"","x":"La declaración de hacer uso del beneficio de inventario deberá hacerse ante Notario.","u":"#art1011","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1012","t":"","x":"Si el heredero a que se refiere el artículo anterior se hallare en país extranjero, podrá hacer dicha declaración ante el Agente diplomático o consular de España que esté habilitado para ejercer las funciones de Notario en el lugar del otorgamiento.","u":"#art1012","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1013","t":"","x":"La declaración a que se refieren los artículos anteriores no producirá efecto alguno si no va precedida o seguida de un inventario fiel y exacto de todos los bienes de la herencia, hecho con las formalidades y dentro de los plazos que se expresarán en los artículos siguientes.","u":"#art1013","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1014","t":"","x":"El heredero que tenga en su poder la herencia o parte de ella y quiera utilizar el beneficio de inventario o el derecho de deliberar, deberá comunicarlo ante Notario y pedir en el plazo de treinta días a contar desde aquél en que supiere ser tal heredero la formación de inventario notarial con citación a los acreedores y legatarios para que acudan a presenciarlo si les conviniere.","u":"#art1014","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1015","t":"","x":"Cuando el heredero no tenga en su poder la herencia o parte de ella, ni haya practicado gestión alguna como tal heredero, el plazo expresado en el artículo anterior se contará desde el día siguiente a aquel en que expire el plazo que se le hubiese fijado para aceptar o repudiar la herencia conforme al artículo 1005, o desde el día en que la hubiese aceptado o hubiera gestionado como heredero.","u":"#art1015","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1016","t":"","x":"Fuera de los casos a que se refieren los dos anteriores artículos, si no se hubiere presentado ninguna demanda contra el heredero, podrá éste aceptar a beneficio de inventario, o con el derecho de deliberar, mientras no prescriba la acción para reclamar la herencia.","u":"#art1016","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1017","t":"","x":"El inventario se principiará dentro de los treinta días siguientes a la citación de los acreedores y legatarios, y concluirá dentro de otros sesenta. Si por hallarse los bienes a larga distancia o ser muy cuantiosos, o por otra causa justa, parecieren insuficientes dichos sesenta días, podrá el Notario prorrogar este término por el tiempo que estime necesario, sin que pueda exceder de un año.","u":"#art1017","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1018","t":"","x":"Si por culpa o negligencia del heredero no se principiare o no se concluyere el inventario en los plazos y con las solemnidades prescritas en los artículos anteriores, se entenderá que acepta la herencia pura y simplemente.","u":"#art1018","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1019","t":"","x":"El heredero que se hubiese reservado el derecho de deliberar, deberá manifestar al Notario, dentro de treinta días contados desde el siguiente a aquel en que se hubiese concluido el inventario, si repudia o acepta la herencia y si hace uso o no del beneficio de inventario. Pasados los treinta días sin hacer dicha manifestación, se entenderá que la acepta pura y simplemente.","u":"#art1019","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1020","t":"","x":"Durante la formación del inventario y hasta la aceptación de la herencia, a instancia de parte, el Notario podrá adoptar las provisiones necesarias para la administración y custodia de los bienes hereditarios con arreglo a lo que se prescribe en este Código y en la legislación notarial.","u":"#art1020","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1021","t":"","x":"El que reclame judicialmente una herencia de que otro se halle en posesión por más de un año, si venciere en el juicio, no tendrá obligación de hacer inventario para gozar de este beneficio, y sólo responderá de las cargas de la herencia con los bienes que le sean entregados.","u":"#art1021","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1022","t":"","x":"El inventario hecho por el heredero que después repudie la herencia aprovechará a los sustitutos y a los herederos ab intestato, respecto de los cuales los treinta días para deliberar y para hacer la manifestación que previene el artículo 1.019 se contarán desde el siguiente al en que tuvieren conocimiento de la repudiación.","u":"#art1022","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1023","t":"","x":"El beneficio de inventario produce en favor del heredero los efectos siguientes: 1.º El heredero no queda obligado a pagar las deudas y demás cargas de la herencia sino hasta donde alcancen los bienes de la misma. 2.º Conserva contra el caudal hereditario todos los derechos y acciones que tuviera contra el difunto. 3.º No se confunden para ningún efecto, en daño del heredero, sus bienes particulares con los que pertenezcan a la herencia.","u":"#art1023","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1024","t":"","x":"El heredero perderá el beneficio de inventario: 1.º Si a sabiendas dejare de incluir en el inventario alguno de los bienes, derechos o acciones de la herencia. 2.º Si antes de completar el pago de las deudas y legados enajenase bienes de la herencia sin autorización de todos los interesados, o no diese al precio de lo vendido la aplicación determinada al concederle la autorización. No obstante, podrá disponer de valores negociables que coticen en un mercado secundario a través de la enajenación en dicho mercado, y de los demás bienes mediante su venta en subasta pública notarial previamente notificada a todos los interesados, especificando en ambos casos la aplicación que se dará al precio obtenido.","u":"#art1024","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1025","t":"","x":"Durante la formación del inventario y el término para deliberar no podrán los legatarios demandar el pago de sus legados.","u":"#art1025","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1026","t":"","x":"Hasta que resulten pagados todos los acreedores conocidos y los legatarios, se entenderá que se halla la herencia en administración. El administrador, ya lo sea el mismo heredero, ya cualquiera otra persona, tendrá, en ese concepto, la representación de la herencia para ejercitar las acciones que a ésta competan y contestar a las demandas que se interpongan contra la misma.","u":"#art1026","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1027","t":"","x":"El administrador no podrá pagar los legados sino después de haber pagado a todos los acreedores.","u":"#art1027","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1028","t":"","x":"Cuando haya juicio pendiente entre los acreedores sobre la preferencia de sus créditos, serán pagados por el orden y según el grado que señale la sentencia firme de graduación. No habiendo juicio pendiente entre los acreedores, serán pagados los que primero se presenten; pero, constando que alguno de los créditos conocidos es preferente, no se hará el pago sin previa caución a favor del acreedor de mejor derecho.","u":"#art1028","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1029","t":"","x":"Si después de pagados los legados aparecieren otros acreedores, éstos sólo podrán reclamar contra los legatarios en el caso de no quedar en la herencia bienes suficientes para pagarles.","u":"#art1029","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1030","t":"","x":"Cuando para el pago de los créditos y legados sea necesaria la venta de bienes hereditarios, se realizará ésta en la forma establecida en el párrafo segundo del número 2.º del artículo 1024 de este Código, salvo si todos los herederos, acreedores y legatarios acordaren otra cosa.","u":"#art1030","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1031","t":"","x":"No alcanzando los bienes hereditarios para el pago de las deudas y legados, el administrador dará cuenta de su administración a los acreedores y legatarios que no hubiesen cobrado por completo, y será responsable de los perjuicios causados a la herencia por culpa o negligencia suya.","u":"#art1031","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1032","t":"","x":"Pagados los acreedores y legatarios, quedará el heredero en el pleno goce del remanente de la herencia. Si la herencia hubiese sido administrada por otra persona, ésta rendirá al heredero la cuenta de su administración, bajo la responsabilidad que impone el artículo anterior.","u":"#art1032","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1033","t":"","x":"Los gastos del inventario y las demás actuaciones a que dé lugar la administración de la herencia aceptada a beneficio de inventario y la defensa de sus derechos, serán de cargo de la misma herencia. Exceptúanse aquellos gastos imputables al heredero que hubiese sido condenado personalmente por su dolo o mala fe. Lo mismo se entenderá respecto de los gastos causados para hacer uso del derecho de deliberar, si el heredero repudia la herencia.","u":"#art1033","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1034","t":"","x":"Los acreedores particulares del heredero no podrán mezclarse en las operaciones de la herencia aceptada por éste a beneficio de inventario hasta que sean pagados los acreedores de la misma y los legatarios; pero podrán pedir la retención o embargo del remanente que pueda resultar a favor del heredero.","u":"#art1034","c":"CAPÍTULO V Disposiciones comunes a las herencias por testamento o sin él · Sección 5.ª Del beneficio de inventario y del derecho de deliberar"},{"n":"CC","a":"1035","t":"","x":"El heredero forzoso que concurra, con otros que también lo sean, a una sucesión deberá traer a la masa hereditaria los bienes o valores que hubiese recibido del causante de la herencia, en vida de éste, por dote, donación u otro título lucrativo, para computarlo en la regulación de las legítimas y en la cuenta de partición.","u":"#art1035","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1036","t":"","x":"La colación no tendrá lugar entre los herederos forzosos si el donante así lo hubiese dispuesto expresamente o si el donatario repudiare la herencia, salvo el caso en que la donación deba reducirse por inoficiosa.","u":"#art1036","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1037","t":"","x":"No se entiende sujeto a colación lo dejado en testamento si el testador no dispusiere lo contrario, quedando en todo caso a salvo las legítimas.","u":"#art1037","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1038","t":"","x":"Cuando los nietos sucedan al abuelo en representación del padre, concurriendo con sus tíos o primos, colacionarán todo lo que debiera colacionar el padre si viviera, aunque no lo hayan heredado. También colacionarán lo que hubiesen recibido del causante de la herencia durante la vida de éste, a menos que el testador hubiese dispuesto lo contrario, en cuyo caso deberá respetarse su voluntad si no perjudicare a la legítima de los coherederos.","u":"#art1038","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1039","t":"","x":"Los padres no estarán obligados a colacionar en la herencia de sus ascendientes lo donado por éstos a sus hijos.","u":"#art1039","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1040","t":"","x":"Tampoco se traerán a colación las donaciones hechas al consorte del hijo; pero si hubieren sido hechas por el padre conjuntamente a los dos, el hijo estará obligado a colacionar la mitad de la cosa donada.","u":"#art1040","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1041","t":"","x":"No estarán sujetos a colación los gastos de alimentos, educación, curación de enfermedades, aunque sean extraordinarias, aprendizaje, ni los regalos de costumbre. Tampoco estarán sujetos a colación los gastos realizados por los progenitores y ascendientes para cubrir las necesidades especiales de sus hijos o descendientes requeridas por su situación de discapacidad.","u":"#art1041","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1042","t":"","x":"No se traerán a colación, sino cuando el padre lo disponga o perjudiquen a la legítima, los gastos que éste hubiere hecho para dar a sus hijos una carrera profesional o artística; pero cuando proceda colacionarlos, se rebajará de ellos lo que el hijo habría gastado viviendo en la casa y compañía de sus padres.","u":"#art1042","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1043","t":"","x":"Serán colacionables las cantidades satisfechas por el padre para redimir a sus hijos de la suerte de soldado, pagar sus deudas, conseguirles un título de honor y otros gastos análogos.","u":"#art1043","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1044","t":"","x":"Los regalos de boda, consistentes en joyas, vestidos y equipos, no se reducirán como inoficiosos sino en la parte que excedan en un décimo o más de la cantidad disponible por testamento.","u":"#art1044","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1045","t":"","x":"No han de traerse a colación y partición las mismas cosas donadas, sino su valor al tiempo en que se evalúen los bienes hereditarios. El aumento o deterioro físico posterior a la donación y aun su pérdida total, casual o culpable, será a cargo y riesgo o beneficio del donatario.","u":"#art1045","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1046","t":"","x":"La dote o donación hecha por ambos cónyuges se colacionará por mitad en la herencia de cada uno de ellos. La hecha por uno solo se colacionará en su herencia.","u":"#art1046","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1047","t":"","x":"El donatario tomará de menos en la masa hereditaria tanto como ya hubiese recibido, percibiendo sus coherederos el equivalente, en cuanto sea posible, en bienes de la misma naturaleza, especie y calidad.","u":"#art1047","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1048","t":"","x":"No pudiendo verificarse lo prescrito en el artículo anterior, si los bienes donados fueren inmuebles, los coherederos tendrán derecho a ser igualados en metálico o valores mobiliarios al tipo de cotización; y, no habiendo dinero ni valores cotizables en la herencia, se venderán otros bienes en pública subasta en la cantidad necesaria. Cuando los bienes donados fueren muebles, los coherederos sólo tendrán derecho a ser igualados en otros muebles de la herencia por el justo precio, a su libre elección.","u":"#art1048","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1049","t":"","x":"Los frutos e intereses de los bienes sujetos a colación no se deben a la masa hereditaria sino desde el día en que se abra la sucesión. Para regularlos, se atenderá a las rentas e intereses de los bienes hereditarios de la misma especie que los colacionados.","u":"#art1049","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1050","t":"","x":"Si entre los coherederos surgiere contienda sobre la obligación de colacionar o sobre los objetos que han de traerse a colación, no por eso dejará de proseguirse la partición, prestando la correspondiente fianza.","u":"#art1050","c":"CAPÍTULO VI De la colación y partición · Sección 1.ª De la colación"},{"n":"CC","a":"1051","t":"","x":"Ningún coheredero podrá ser obligado a permanecer en la indivisión de la herencia, a menos que el testador prohíba expresamente la división. Pero, aun cuando la prohíba, la división tendrá siempre lugar mediante alguna de las causas por las cuales se extingue la sociedad.","u":"#art1051","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1052","t":"","x":"Todo coheredero que tenga la libre administración y disposición de sus bienes podrá pedir en cualquier tiempo la partición de la herencia. Lo harán sus representantes legales si el coheredero está en situación de ausencia. Si el coheredero contase con medidas de apoyo por razón de discapacidad, se estará a lo que se disponga en estas.","u":"#art1052","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1053","t":"","x":"Cualquiera de los cónyuges podrá pedir la partición de la herencia sin intervención del otro.","u":"#art1053","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1054","t":"","x":"Los herederos bajo condición no podrán pedir la partición hasta que aquélla se cumpla. Pero podrán pedirla los otros coherederos, asegurando competentemente el derecho de los primeros para el caso de cumplirse la condición; y, hasta saberse que ésta ha faltado o no puede ya verificarse, se entenderá provisional la partición.","u":"#art1054","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1055","t":"","x":"Si antes de hacerse la partición muere uno de los coherederos, dejando dos o más herederos, bastará que uno de éstos la pida; pero todos los que intervengan en este último concepto deberán comparecer bajo una sola representación.","u":"#art1055","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1056","t":"","x":"Cuando el testador hiciere, por acto entre vivos o por última voluntad, la partición de sus bienes, se pasará por ella, en cuanto no perjudique a la legítima de los herederos forzosos. El testador que en atención a la conservación de la empresa o en interés de su familia quiera preservar indivisa una explotación económica o bien mantener el control de una sociedad de capital o grupo de éstas podrá usar de la facultad concedida en este artículo, disponiendo que se pague en metálico su legítima a los demás interesados. A tal efecto, no será necesario que exista metálico suficiente en la herencia para el pago, siendo posible realizar el abono con efectivo extrahereditario y establecer por el testador o por el contador-partidor por él designado aplazamiento, siempre que éste no supere cinco años a contar desde el fallecimiento del testador; podrá ser también de aplicación cualquier otro medio de extinción de las obligaciones. Si no se hubiere establecido la forma de pago, cualquier legitimario podrá exigir su legítima en bienes de la herencia. No será de aplicación a la partición así realizada lo dispuesto en el artículo 843 y en el párrafo primero del artículo 844.","u":"#art1056","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1057","t":"","x":"El testador podrá encomendar por acto «inter vivos» o «mortis causa» para después de su muerte la simple facultad de hacer la partición a cualquier persona que no sea uno de los coherederos. No habiendo testamento, contador-partidor en él designado o vacante el cargo, el Secretario judicial o el Notario, a petición de herederos y legatarios que representen, al menos, el 50 por 100 del haber hereditario, y con citación de los demás interesados, si su domicilio fuere conocido, podrá nombrar un contador-partidor dativo, según las reglas que la Ley de Enjuiciamiento Civil y del Notariado establecen para la designación de peritos. La partición así realizada requerirá aprobación del Secretario judicial o del Notario, salvo confirmación expresa de todos los herederos y legatarios. Lo dispuesto en este artículo y en el anterior se observará aunque entre los coherederos haya alguno sujeto a patria potestad o tutela; pero el contador-partidor deberá en estos casos inventariar los bienes de la herencia, con citación de los representantes legales de dichas personas. Si el coheredero tuviera dispuestas medidas de apoyo, se estará a lo establecido en ellas.","u":"#art1057","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1058","t":"","x":"Cuando el testador no hubiese hecho la partición, ni encomendado a otro esta facultad, si los herederos fueren mayores y tuvieren la libre administración de sus bienes, podrán distribuir la herencia de la manera que tengan por conveniente.","u":"#art1058","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1059","t":"","x":"Cuando los herederos mayores de edad no se entendieren sobre el modo de hacer la partición, quedará a salvo su derecho para que lo ejerciten en la forma prevenida en la Ley de Enjuiciamiento Civil.","u":"#art1059","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1060","t":"","x":"Cuando los menores estén legalmente representados en la partición, no será necesaria la intervención ni la autorización judicial, pero el tutor necesitará aprobación judicial de la ya efectuada. El defensor judicial designado para representar a un menor en una partición, deberá obtener la aprobación de la autoridad judicial, si el Letrado de la Administración de Justicia no hubiera dispuesto otra cosa al hacer el nombramiento. Tampoco será necesaria autorización ni intervención judicial en la partición realizada por el curador con facultades de representación. La partición una vez practicada requerirá aprobación judicial. La partición realizada por el defensor judicial designado para actuar en la partición en nombre de un menor o de una persona a cuyo favor se hayan establecido medidas de apoyo, necesitará la aprobación judicial, salvo que se hubiera dispuesto otra cosa al hacer el nombramiento.","u":"#art1060","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1061","t":"","x":"En la partición de la herencia se ha de guardar la posible igualdad, haciendo lotes o adjudicando a cada uno de los coherederos cosas de la misma naturaleza, calidad o especie.","u":"#art1061","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1062","t":"","x":"Cuando una cosa sea indivisible o desmerezca mucho por su división, podrá adjudicarse a uno, a calidad de abonar a los otros el exceso en dinero. Pero bastará que uno solo de los herederos pida su venta en pública subasta, y con admisión de licitadores extraños, para que así se haga.","u":"#art1062","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1063","t":"","x":"Los coherederos deben abonarse recíprocamente en la partición las rentas y frutos que cada uno haya percibido de los bienes hereditarios, las impensas útiles y necesarias hechas en los mismos, y los daños ocasionados por malicia o negligencia.","u":"#art1063","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1064","t":"","x":"Los gastos de partición, hechos en interés común de todos los coherederos, se deducirán de la herencia; los hechos en interés particular de uno de ellos, serán a cargo del mismo.","u":"#art1064","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1065","t":"","x":"Los títulos de adquisición o pertenencia serán entregados al coheredero adjudicatario de la finca o fincas a que se refieran.","u":"#art1065","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1066","t":"","x":"Cuando el mismo título comprenda varias fincas adjudicadas a diversos coherederos, o una sola que se haya dividido entre dos o más, el título quedará en poder del mayor interesado en la finca o fincas, y se facilitarán a los otros copias fehacientes, a costa del caudal hereditario. Si el interés fuere igual, el título se entregará, a falta de acuerdo, a quien por suerte corresponda. Siendo original, aquel en cuyo poder quede deberá también exhibirlo a los demás interesados cuando lo pidieren.","u":"#art1066","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1067","t":"","x":"Si alguno de los herederos vendiere a un extraño su derecho hereditario antes de la partición, podrán todos o cualquiera de los coherederos subrogarse en lugar del comprador, reembolsándole el precio de la compra, con tal que lo verifiquen en término de un mes, a contar desde que esto se les haga saber.","u":"#art1067","c":"CAPÍTULO VI De la colación y partición · Sección 2.ª De la partición"},{"n":"CC","a":"1068","t":"","x":"La partición legalmente hecha confiere a cada heredero la propiedad exclusiva de los bienes que le hayan sido adjudicados.","u":"#art1068","c":"CAPÍTULO VI De la colación y partición · Sección 3.ª De los efectos de la partición"},{"n":"CC","a":"1069","t":"","x":"Hecha la partición, los coherederos estarán recíprocamente obligados a la evicción y saneamiento de los bienes adjudicados.","u":"#art1069","c":"CAPÍTULO VI De la colación y partición · Sección 3.ª De los efectos de la partición"},{"n":"CC","a":"1070","t":"","x":"La obligación a que se refiere el artículo anterior sólo cesará en los siguientes casos: 1.º Cuando el mismo testador hubiese hecho la partición, a no ser que aparezca, o racionalmente se presuma, haber querido lo contrario, y salva siempre la legítima. 2.º Cuando se hubiese pactado expresamente al hacer la partición. 3.º Cuando la evicción proceda de causa posterior a la partición, o fuere ocasionada por culpa del adjudicatario.","u":"#art1070","c":"CAPÍTULO VI De la colación y partición · Sección 3.ª De los efectos de la partición"},{"n":"CC","a":"1071","t":"","x":"La obligación recíproca de los coherederos a la evicción es proporcionada a su respectivo haber hereditario; pero si alguno de ellos resultare insolvente, responderán de su parte los demás coherederos en la misma proporción, deduciéndose la parte correspondiente al que deba ser indemnizado. Los que pagaren por el insolvente conservarán su acción contra él para cuando mejore de fortuna.","u":"#art1071","c":"CAPÍTULO VI De la colación y partición · Sección 3.ª De los efectos de la partición"},{"n":"CC","a":"1072","t":"","x":"Si se adjudicare como cobrable un crédito, los coherederos no responderán de la insolvencia posterior del deudor hereditario, y sólo serán responsables de su insolvencia al tiempo de hacerse la partición. Por los créditos calificados de incobrables no hay responsabilidad; pero, si se cobran en todo o en parte, se distribuirá lo percibido proporcionalmente entre los herederos.","u":"#art1072","c":"CAPÍTULO VI De la colación y partición · Sección 3.ª De los efectos de la partición"},{"n":"CC","a":"1073","t":"","x":"Las particiones pueden rescindirse por las mismas causas que las obligaciones.","u":"#art1073","c":"CAPÍTULO VI De la colación y partición · Sección 4.ª De la rescisión de la partición"},{"n":"CC","a":"1074","t":"","x":"Podrán también ser rescindidas las particiones por causa de lesión en más de la cuarta parte, atendido el valor de las cosas cuando fueron adjudicadas.","u":"#art1074","c":"CAPÍTULO VI De la colación y partición · Sección 4.ª De la rescisión de la partición"},{"n":"CC","a":"1075","t":"","x":"La partición hecha por el difunto no puede ser impugnada por causa de lesión, sino en el caso de que perjudique la legítima de los herederos forzosos o de que aparezca, o racionalmente se presuma, que fue otra la voluntad del testador.","u":"#art1075","c":"CAPÍTULO VI De la colación y partición · Sección 4.ª De la rescisión de la partición"},{"n":"CC","a":"1076","t":"","x":"La acción rescisoria por causa de lesión durará cuatro años, contados desde que se hizo la partición.","u":"#art1076","c":"CAPÍTULO VI De la colación y partición · Sección 4.ª De la rescisión de la partición"},{"n":"CC","a":"1077","t":"","x":"El heredero demandado podrá optar entre indemnizar el daño o consentir que se proceda a nueva partición. La indemnización puede hacerse en numerario o en la misma cosa en que resultó el perjuicio. Si se procede a nueva partición, no alcanzará ésta a los que no hayan sido perjudicados ni percibido más de lo justo.","u":"#art1077","c":"CAPÍTULO VI De la colación y partición · Sección 4.ª De la rescisión de la partición"},{"n":"CC","a":"1078","t":"","x":"No podrá ejercitar la acción rescisoria por lesión el heredero que hubiese enajenado el todo o una parte considerable de los bienes inmuebles que le hubieren sido adjudicados.","u":"#art1078","c":"CAPÍTULO VI De la colación y partición · Sección 4.ª De la rescisión de la partición"},{"n":"CC","a":"1079","t":"","x":"La omisión de alguno o algunos objetos o valores de la herencia no da lugar a que se rescinda la partición por lesión, sino a que se complete o adicione con los objetos o valores omitidos.","u":"#art1079","c":"CAPÍTULO VI De la colación y partición · Sección 4.ª De la rescisión de la partición"},{"n":"CC","a":"1080","t":"","x":"La partición hecha con preterición de alguno de los herederos no se rescindirá, a no ser que se pruebe que hubo mala fe o dolo por parte de los otros interesados; pero éstos tendrán la obligación de pagar al preterido la parte que proporcionalmente le corresponda.","u":"#art1080","c":"CAPÍTULO VI De la colación y partición · Sección 4.ª De la rescisión de la partición"},{"n":"CC","a":"1081","t":"","x":"La partición hecha con uno a quien se creyó heredero sin serlo será nula.","u":"#art1081","c":"CAPÍTULO VI De la colación y partición · Sección 4.ª De la rescisión de la partición"},{"n":"CC","a":"1082","t":"","x":"Los acreedores reconocidos como tales podrán oponerse a que se lleve a efecto la partición de la herencia hasta que se les pague o afiance el importe de sus créditos.","u":"#art1082","c":"CAPÍTULO VI De la colación y partición · Sección 5.ª Del pago de las deudas hereditarias"},{"n":"CC","a":"1083","t":"","x":"Los acreedores de uno o más de los coherederos podrán intervenir a su costa en la partición para evitar que ésta se haga en fraude o perjuicio de sus derechos.","u":"#art1083","c":"CAPÍTULO VI De la colación y partición · Sección 5.ª Del pago de las deudas hereditarias"},{"n":"CC","a":"1084","t":"","x":"Hecha la partición, los acreedores podrán exigir el pago de sus deudas por entero de cualquiera de los herederos que no hubiere aceptado la herencia a beneficio de inventario, o hasta donde alcance su porción hereditaria, en el caso de haberla admitido con dicho beneficio. En uno y otro caso el demandado tendrá derecho a hacer citar y emplazar a sus coherederos, a menos que por disposición del testador, o a consecuencia de la partición, hubiere quedado él solo obligado al pago de la deuda.","u":"#art1084","c":"CAPÍTULO VI De la colación y partición · Sección 5.ª Del pago de las deudas hereditarias"},{"n":"CC","a":"1085","t":"","x":"El coheredero que hubiese pagado más de lo que corresponda a su participación en la herencia podrá reclamar de los demás su parte proporcional. Esto mismo se observará cuando, por ser la deuda hipotecaria o consistir en cuerpo determinado, la hubiese pagado íntegramente. El adjudicatario, en este caso, podrá reclamar de sus coherederos sólo la parte proporcional, aunque el acreedor le haya cedido sus acciones y subrogándole en su lugar.","u":"#art1085","c":"CAPÍTULO VI De la colación y partición · Sección 5.ª Del pago de las deudas hereditarias"},{"n":"CC","a":"1086","t":"","x":"Estando alguna de las fincas de la herencia gravada con renta o carga real perpetua, no se procederá a su extinción, aunque sea redimible, sino cuando la mayor parte de los coherederos lo acordare. No acordándolo así, o siendo la carga irredimible, se rebajará su valor o capital del de la finca, y ésta pasará con la carga al que le toque en lote o por adjudicación.","u":"#art1086","c":"CAPÍTULO VI De la colación y partición · Sección 5.ª Del pago de las deudas hereditarias"},{"n":"CC","a":"1087","t":"","x":"El coheredero acreedor del difunto puede reclamar de los otros el pago de su crédito, deducida su parte proporcional como tal heredero, y sin perjuicio de lo establecido en la sección 5.ª, capítulo VI, de este título.","u":"#art1087","c":"CAPÍTULO VI De la colación y partición · Sección 5.ª Del pago de las deudas hereditarias"},{"n":"CC","a":"1315","t":"","x":"El régimen económico del matrimonio será el que los cónyuges estipulen en capitulaciones matrimoniales, sin otras limitaciones que las establecidas en este Código.","u":"#art1315","c":"TÍTULO II De los contratos · CAPÍTULO I Disposiciones generales"},{"n":"CC","a":"1316","t":"","x":"A falta de capitulaciones o cuando éstas sean ineficaces, el régimen será el de la sociedad de gananciales.","u":"#art1316","c":"TÍTULO II De los contratos · CAPÍTULO I Disposiciones generales"},{"n":"CC","a":"1317","t":"","x":"La modificación del régimen económico matrimonial realizada durante el matrimonio no perjudicará en ningún caso los derechos ya adquiridos por terceros.","u":"#art1317","c":"TÍTULO II De los contratos · CAPÍTULO I Disposiciones generales"},{"n":"CC","a":"1318","t":"","x":"Los bienes de los cónyuges están sujetos al levantamiento de las cargas del matrimonio. Cuando uno de los cónyuges incumpliere su deber de contribuir al levantamiento de estas cargas, el Juez, a instancia del otro, dictará las medidas cautelares que estime conveniente a fin de asegurar su cumplimiento y los anticipos necesarios o proveer a las necesidades futuras. Cuando un cónyuge carezca de bienes propios suficientes, los gastos necesarios causados en litigios que sostenga contra el otro cónyuge sin mediar mala fe o temeridad, o contra tercero si redundan en provecho de la familia, serán a cargo del caudal común y, faltando éste, se sufragarán a costa de los bienes propios del otro cónyuge cuando la posición económica de éste impida al primero, por imperativo de la Ley de Enjuiciamiento Civil, la obtención del beneficio de justicia gratuita.","u":"#art1318","c":"TÍTULO II De los contratos · CAPÍTULO I Disposiciones generales"},{"n":"CC","a":"1319","t":"","x":"Cualquiera de los cónyuges podrá realizar los actos encaminados a atender las necesidades ordinarias de la familia, encomendadas a su cuidado, conforme al uso del lugar y a las circunstancias de la misma. De las deudas contraídas en el ejercicio de esta potestad responderán solidariamente los bienes comunes y los del cónyuge que contraiga la deuda y, subsidiariamente, los del otro cónyuge. El que hubiere aportado caudales propios para satisfacción de tales necesidades tendrá derecho a ser reintegrado de conformidad con su régimen matrimonial.","u":"#art1319","c":"TÍTULO II De los contratos · CAPÍTULO I Disposiciones generales"},{"n":"CC","a":"1320","t":"","x":"Para disponer de los derechos sobre la vivienda habitual y los muebles de uso ordinario de la familia, aunque tales derechos pertenezcan a uno solo de los cónyuges, se requerirá el consentimiento de ambos o, en su caso, autorización judicial. La manifestación errónea o falsa del disponente sobre el carácter de la vivienda no perjudicará al adquirente de buena fe.","u":"#art1320","c":"TÍTULO II De los contratos · CAPÍTULO I Disposiciones generales"},{"n":"CC","a":"1321","t":"","x":"Fallecido uno de los cónyuges, las ropas, el mobiliario y enseres que constituyan el ajuar de la vivienda habitual común de los esposos se entregarán al que sobreviva, sin computárselo en su haber. No se entenderán comprendidos en el ajuar las alhajas, objetos artísticos, históricos y otros de extraordinario valor.","u":"#art1321","c":"TÍTULO II De los contratos · CAPÍTULO I Disposiciones generales"},{"n":"CC","a":"1322","t":"","x":"Cuando la Ley requiera para un acto de administración o disposición que uno de los cónyuges actúe con el consentimiento del otro, los realizados sin él y que no hayan sido expresa o tácitamente confirmados podrán ser anulados a instancia del cónyuge cuyo consentimiento se haya omitido o de sus herederos. No obstante, serán nulos los actos a título gratuito sobre bienes comunes si falta, en tales casos, el consentimiento del otro cónyuge.","u":"#art1322","c":"TÍTULO II De los contratos · CAPÍTULO I Disposiciones generales"},{"n":"CC","a":"1323","t":"","x":"Los cónyuges podrán transmitirse por cualquier título bienes y derechos y celebrar entre sí toda clase de contratos.","u":"#art1323","c":"TÍTULO II De los contratos · CAPÍTULO I Disposiciones generales"},{"n":"CC","a":"1324","t":"","x":"Para probar entre cónyuges que determinados bienes son propios de uno de ellos, será bastante la confesión del otro, pero tal confesión por sí sola no perjudicará a los herederos forzosos del confesante, ni a los acreedores, sean de la comunidad o de cada uno de los cónyuges.","u":"#art1324","c":"TÍTULO II De los contratos · CAPÍTULO I Disposiciones generales"},{"n":"CC","a":"1344","t":"","x":"Mediante la sociedad de gananciales se hacen comunes para los cónyuges las ganancias o beneficios obtenidos indistintamente por cualquiera de ellos, que les serán atribuidos por mitad al disolverse aquella.","u":"#art1344","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 1.ª Disposiciones generales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1345","t":"","x":"La sociedad de gananciales empezará en el momento de la celebración del matrimonio o, posteriormente, al tiempo de pactarse en capitulaciones.","u":"#art1345","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 1.ª Disposiciones generales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1346","t":"","x":"Son privativos de cada uno de los cónyuges: 1.° Los bienes, animales y derechos que le pertenecieran al comenzar la sociedad. 2.° Los que adquiera después por título gratuito. 3.° Los adquiridos a costa o en sustitución de bienes privativos. 4.° Los adquiridos por derecho de retracto perteneciente a uno solo de los cónyuges. 5.° Los bienes y derechos patrimoniales inherentes a la persona y los no transmisibles ínter vivos. 6.° El resarcimiento por daños inferidos a la persona de uno de los cónyuges o a sus bienes privativos. 7.° Las ropas y objetos de uso personal que no sean de extraordinario valor. 8.° Los instrumentos necesarios para el ejercicio de la profesión u oficio, salvo cuando éstos sean parte integrante o pertenencias de un establecimiento o explotación de carácter común. Los bienes mencionados en los apartados 4.° y 8.° no perderán su carácter de privativos por el hecho de que su adquisición se haya realizado con fondos comunes; pero, en este caso, la sociedad será acreedora del cónyuge propietario por el valor satisfecho.","u":"#art1346","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1347","t":"","x":"Son bienes gananciales: 1.° Los obtenidos por el trabajo o la industria de cualquiera de los cónyuges. 2.° Los frutos, rentas o intereses que produzcan tanto los bienes privativos como los gananciales. 3.° Los adquiridos a título oneroso a costa del caudal común, bien se haga la adquisición para la comunidad, bien para uno solo de los esposos. 4.° Los adquiridos por derecho de retracto de carácter ganancial, aun cuando lo fueran con fondos privativos, en cuyo caso la sociedad será deudora del cónyuge por el valor satisfecho. 5.° Las Empresas y establecimientos fundados durante la vigencia de la sociedad por uno cualquiera de los cónyuges a expensas de los bienes comunes. Si a la formación de la Empresa o establecimiento concurren capital privativo y capital común, se aplicará lo dispuesto en el artículo 1.354.","u":"#art1347","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1348","t":"","x":"Siempre que pertenezca privativamente a uno de los cónyuges una cantidad o crédito pagadero en cierto número de años, no serán gananciales las sumas que se cobren en los plazos vencidos durante el matrimonio, sino que se estimarán capital de uno u otro cónyuge, según a quien pertenezca el crédito.","u":"#art1348","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1349","t":"","x":"El derecho de usufructo o de pensión, perteneciente a uno de los cónyuges, formará parte de sus bienes propios; pero los frutos, pensiones o intereses devengados durante el matrimonio serán gananciales.","u":"#art1349","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1350","t":"","x":"Se reputarán gananciales las cabezas de ganado que al disolverse la sociedad excedan del número aportado por cada uno de los cónyuges con carácter privativo.","u":"#art1350","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1351","t":"","x":"Las ganancias obtenidas por cualquiera de los cónyuges en el juego o las procedentes de otras causas que eximan de la restitución pertenecerán a la sociedad de gananciales.","u":"#art1351","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1352","t":"","x":"Las nuevas acciones u otros títulos o participaciones sociales suscritos como consecuencia de la titularidad de otros privativos serán también privativos. Asimismo lo serán las cantidades obtenidas por la enajenación del derecho a suscribir. Si para el pago de la suscripción se utilizaren fondos comunes o se emitieran las acciones con cargo a los beneficios, se reembolsará el valor satisfecho.","u":"#art1352","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1353","t":"","x":"Los bienes donados o dejados en testamento a los cónyuges conjuntamente y sin especial designación de partes, constante la sociedad, se entenderán gananciales, siempre que la liberalidad fuera aceptada por ambos y el donante o testador no hubiere dispuesto lo contrario.","u":"#art1353","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1354","t":"","x":"Los bienes adquiridos mediante precio o contraprestación, en parte ganancial y en parte privativo, corresponderán pro indiviso a la sociedad de gananciales y al cónyuge o cónyuges en proporción al valor de las aportaciones respectivas.","u":"#art1354","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1355","t":"","x":"Podrán los cónyuges, de común acuerdo, atribuir la condición de gananciales a los bienes que adquieran a título oneroso durante el matrimonio, cualquiera que sea la procedencia del precio o contraprestación y la forma y plazos en que se satisfaga. Si la adquisición se hiciere en forma conjunta y sin atribución de cuotas, se presumirá su voluntad favorable al carácter ganancial de tales bienes.","u":"#art1355","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1356","t":"","x":"Los bienes adquiridos por uno de los cónyuges, constante la sociedad por precio aplazado, tendrán naturaleza ganancial si el primer desembolso tuviera tal carácter, aunque los plazos restantes se satisfagan con dinero privativo. Si el primer desembolso tuviere carácter privativo, el bien será de esta naturaleza.","u":"#art1356","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1357","t":"","x":"Los bienes comprados a plazos por uno de los cónyuges antes de comenzar la sociedad tendrán siempre carácter privativo, aun cuando la totalidad o parte del precio aplazado se satisfaga con dinero ganancial. Se exceptúan la vivienda y ajuar familiares, respecto de los cuales se aplicará el artículo 1.354.","u":"#art1357","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1358","t":"","x":"Cuando conforme a este Código los bienes sean privativos o gananciales, con independencia de la procedencia del caudal con que la adquisición se realice, habrá de reembolsarse el valor satisfecho a costa, respectivamente, del caudal común o del propio, mediante el reintegro de su importe actualizado al tiempo de la liquidación.","u":"#art1358","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1359","t":"","x":"Las edificaciones, plantaciones y cualesquiera otras mejoras que se realicen en los bienes gananciales y en los privativos tendrán el carácter correspondiente a los bienes a que afecten, sin perjuicio del reembolso del valor satisfecho. No obstante, si la mejora hecha en bienes privativos fuese debida a la inversión de fondos comunes o a la actividad de cualquiera de los cónyuges, la sociedad será acreedora del aumento del valor que los bienes tengan como consecuencia de la mejora, al tiempo de la disolución de la sociedad o de la enajenación del bien mejorado.","u":"#art1359","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1360","t":"","x":"Las mismas reglas del artículo anterior se aplicarán a los incrementos patrimoniales incorporados a una explotación, establecimiento mercantil u otro género de empresa.","u":"#art1360","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1361","t":"","x":"Se presumen gananciales los bienes existentes en el matrimonio mientras no se pruebe que pertenecen privativamente a uno de los dos cónyuges.","u":"#art1361","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 2.ª De los bienes privativos y comunes Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1362","t":"","x":"Serán de cargo de la sociedad de gananciales los gastos que se originen por alguna de las siguientes causas: 1.ª El sostenimiento de la familia, la alimentación y educación de los hijos comunes y las atenciones de previsión acomodadas a los usos y a las circunstancias de la familia. La alimentación y educación de los hijos de uno solo de los cónyuges correrá a cargo de la sociedad de gananciales cuando convivan en el hogar familiar. En caso contrario, los gastos derivados de estos conceptos serán sufragados por la sociedad de gananciales, pero darán lugar a reintegro en el momento de la liquidación. 2.ª La adquisición, tenencia y disfrute de los bienes comunes. 3.ª La administración ordinaria de los bienes privativos de cualquiera de los cónyuges. 4.ª La explotación regular de los negocios o el desempeño de la profesión, arte u oficio de cada cónyuge.","u":"#art1362","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 3.ª De las cargas y obligaciones de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1363","t":"","x":"Serán también de cargo de la sociedad las cantidades donadas o prometidas por ambos cónyuges de común acuerdo, cuando no hubiesen pactado que hayan de satisfacerse con los bienes privativos de uno de ellos en todo o en parte.","u":"#art1363","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 3.ª De las cargas y obligaciones de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1364","t":"","x":"El cónyuge que hubiere aportado bienes privativos para los gastos o pagos que sean de cargo de la sociedad tendrá derecho a ser reintegrado del valor a costa del patrimonio común.","u":"#art1364","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 3.ª De las cargas y obligaciones de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1365","t":"","x":"Los bienes gananciales responderán directamente frente al acreedor de las deudas contraídas por un cónyuge: 1.° En el ejercicio de la potestad doméstica o de la gestión o disposición de gananciales, que por ley o por capítulos le corresponda. 2.º En el ejercicio de la profesión, arte u oficio o en la administración ordinaria de los propios bienes.","u":"#art1365","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 3.ª De las cargas y obligaciones de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1366","t":"","x":"Las obligaciones extracontractuales de un cónyuge, consecuencia de su actuación en beneficio de la sociedad conyugal o en el ámbito de la administración de los bienes, serán de la responsabilidad y cargo de aquélla, salvo si fuesen debidas a dolo o culpa grave del cónyuge deudor.","u":"#art1366","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 3.ª De las cargas y obligaciones de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1367","t":"","x":"Los bienes gananciales responderán en todo caso de las obligaciones contraídas por los dos cónyuges conjuntamente o por uno de ellos con el consentimiento expreso del otro.","u":"#art1367","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 3.ª De las cargas y obligaciones de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1368","t":"","x":"También responderán los bienes gananciales de las obligaciones contraídas por uno solo de los cónyuges en caso de separación de hecho para atender a los gastos de sostenimiento, previsión y educación de los hijos que estén a cargo de la sociedad de gananciales.","u":"#art1368","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 3.ª De las cargas y obligaciones de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1369","t":"","x":"De las deudas de un cónyuge que sean, además, deudas de la sociedad responderán también solidariamente los bienes de ésta.","u":"#art1369","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 3.ª De las cargas y obligaciones de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1370","t":"","x":"Por el precio aplazado del bien ganancial adquirido por un cónyuge sin el consentimiento del otro responderá siempre el bien adquirido, sin perjuicio de la responsabilidad de otros bienes según las reglas de este Código.","u":"#art1370","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 3.ª De las cargas y obligaciones de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1371","t":"","x":"Lo perdido y pagado durante el matrimonio por alguno de los cónyuges en cualquier clase de juego no disminuirá su parte respectiva de los gananciales siempre que el importe de aquella pérdida pudiere considerarse moderada con arreglo al uso y circunstancias de la familia.","u":"#art1371","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 3.ª De las cargas y obligaciones de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1372","t":"","x":"De lo perdido y no pagado por alguno de los cónyuges en los juegos en que la ley concede acción para reclamar lo que se gane responden exclusivamente los bienes privativos del deudor.","u":"#art1372","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 3.ª De las cargas y obligaciones de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1373","t":"","x":"Cada cónyuge responde con su patrimonio personal de las deudas propias y, si sus bienes privativos no fueran suficientes para hacerlas efectivas, el acreedor podrá pedir el embargo de bienes gananciales, que será inmediatamente notificado al otro cónyuge y éste podrá exigir que en la traba se sustituyan los bienes comunes por la parte que ostenta el cónyuge deudor en la sociedad conyugal, en cuyo caso el embargo llevará consigo la disolución de aquélla. Si se realizase la ejecución sobre bienes comunes, se reputará que el cónyuge deudor tiene recibido a cuenta de su participación el valor de aquéllos al tiempo en que los abone con otros caudales propios o al tiempo de liquidación de la sociedad conyugal.","u":"#art1373","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 3.ª De las cargas y obligaciones de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1374","t":"","x":"Tras la disolución a que se refiere el artículo anterior se aplicará el régimen de separación de bienes, salvo que, en el plazo de tres meses, el cónyuge del deudor opte en documento público por el comienzo de una nueva sociedad de gananciales.","u":"#art1374","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 3.ª De las cargas y obligaciones de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1375","t":"","x":"En defecto de pacto en capitulaciones, la gestión y disposiciones de los bienes gananciales corresponde conjuntamente a los cónyuges, sin perjuicio de lo que se determina en los artículos siguientes.","u":"#art1375","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1376","t":"","x":"Cuando en la realización de actos de administración fuere necesario el consentimiento de ambos cónyuges y uno se hallare impedido para prestarlo, o se negare injustificadamente a ello, podrá el Juez suplirlo si encontrare fundada la petición.","u":"#art1376","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1377","t":"","x":"Para realizar actos de disposición a título oneroso sobre bienes gananciales se requerirá el consentimiento de ambos cónyuges. Si uno lo negare o estuviere impedido para prestarlo, podrá el Juez autorizar uno o varios actos dispositivos cuando lo considere de interés para la familia. Excepcionalmente acordará las limitaciones o cautelas que estime convenientes.","u":"#art1377","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1378","t":"","x":"Serán nulos los actos a título gratuito si no concurre el consentimiento de ambos cónyuges. Sin embargo, podrá cada uno de ellos realizar con los bienes gananciales liberalidades de uso.","u":"#art1378","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1379","t":"","x":"Cada uno de los cónyuges podrá disponer por testamento de la mitad de los bienes gananciales.","u":"#art1379","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1380","t":"","x":"La disposición testamentaria de un bien ganancial producirá todos sus efectos si fuere adjudicado a la herencia del testador. En caso contrario se entenderá legado el valor que tuviera al tiempo del fallecimiento.","u":"#art1380","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1381","t":"","x":"Los frutos y ganancias de los patrimonios privativos y las ganancias de cualquiera de los cónyuges forman parte del haber de la sociedad y están sujetos a las cargas y responsabilidades de la sociedad de gananciales. Sin embargo, cada cónyuge, como administrador de su patrimonio privativo, podrá a este solo efecto disponer de los frutos y productos de sus bienes.","u":"#art1381","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1382","t":"","x":"Cada cónyuge podrá, sin el consentimiento del otro, pero siempre con su conocimiento, tomar como anticipo el numerario ganancial que le sea necesario, de acuerdo con los usos y circunstancias de la familia, para el ejercicio de su profesión o la administración ordinaria de sus bienes.","u":"#art1382","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1383","t":"","x":"Deben los cónyuges informarse recíproca y periódicamente sobre la situación y rendimientos de cualquier actividad económica suya.","u":"#art1383","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1384","t":"","x":"Serán válidos los actos de administración de bienes y los de disposición de dinero o títulos valores realizados por el cónyuge a cuyo nombre figuren o en cuyo poder se encuentren.","u":"#art1384","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1385","t":"","x":"Los derechos de crédito, cualquiera que sea su naturaleza, serán ejercitados por aquel de los cónyuges a cuyo nombre aparezcan constituidos. Cualquiera de los cónyuges podrá ejercitar la defensa de los bienes y derechos comunes por vía de acción o de excepción.","u":"#art1385","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1386","t":"","x":"Para realizar gastos urgentes de carácter necesario, aun cuando sean extraordinarios, bastará el consentimiento de uno sólo de los cónyuges.","u":"#art1386","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1387","t":"","x":"La administración y disposición de los bienes de la sociedad de gananciales se transferirá por ministerio de la ley al cónyuge nombrado curador de su consorte con discapacidad, cuando le hayan sido atribuidas facultades de representación plena.","u":"#art1387","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1388","t":"","x":"Los Tribunales podrán conferir la administración a uno solo de los cónyuges cuando el otro se encontrare en imposibilidad de prestar consentimiento o hubiere abandonado la familia o existiere separación de hecho.","u":"#art1388","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1389","t":"","x":"El cónyuge en quien recaiga la administración en virtud de lo dispuesto en los dos artículos anteriores tendrá para ello plenas facultades, salvo que el Juez, cuando lo considere de interés para la familia, establezca cautelas o limitaciones. En todo caso, para realizar actos de disposición sobre inmuebles, establecimientos mercantiles, objetos preciosos o valores mobiliarios, salvo el derecho de suscripción preferente, necesitará autorización judicial.","u":"#art1389","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1390","t":"","x":"Si como consecuencia de un acto de administración o de disposición llevado a cabo por uno solo de los cónyuges hubiere éste obtenido un beneficio o lucro exclusivo para él u ocasionado dolosamente un daño a la sociedad, será deudor a la misma por su importe, aunque el otro cónyuge no impugne cuando proceda la eficacia del acto.","u":"#art1390","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1391","t":"","x":"Cuando el cónyuge hubiere realizado un acto en fraude de los derechos de su consorte será, en todo caso, de aplicación lo dispuesto en el artículo anterior y, además, si el adquirente hubiere procedido de mala fe, el acto será rescindible.","u":"#art1391","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 4.ª De la administración de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1392","t":"","x":"La sociedad de gananciales concluirá de pleno derecho: 1.º Cuando se disuelva el matrimonio. 2.º Cuando sea declarado nulo. 3.º Cuando se acuerde la separación legal de los cónyuges. 4.º Cuando los cónyuges convengan un régimen económico distinto en la forma prevenida en este Código.","u":"#art1392","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1393","t":"","x":"También concluirá por decisión judicial la sociedad de gananciales, a petición de uno de los cónyuges, en alguno de los casos siguientes: 1.° Si respecto del otro cónyuge se hubieren dispuesto judicialmente medidas de apoyo que impliquen facultades de representación plena en la esfera patrimonial, si hubiere sido declarado ausente o en concurso, o condenado por abandono de familia. Para que la autoridad judicial acuerde la disolución bastará que el cónyuge que la pidiere presente la correspondiente resolución judicial. 2.° Venir el otro cónyuge realizando por sí solo actos dispositivos o de gestión patrimonial que entrañen fraude, daño o peligro para los derechos del otro en la sociedad. 3.° Llevar separado de hecho más de un año por acuerdo mutuo o por abandono del hogar. 4.° Incumplir grave y reiteradamente el deber de informar sobre la marcha y rendimientos de sus actividades económicas. En cuanto a la disolución de la sociedad por el embargo de la parte de uno de los cónyuges por deudas propias, se estará a lo especialmente dispuesto en este Código.","u":"#art1393","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1394","t":"","x":"Los efectos de la disolución prevista en el artículo anterior se producirán desde la fecha en que se acuerde. De seguirse pleito sobre la concurrencia de la causa de disolución, iniciada la tramitación del mismo, se practicará el inventario, y el Juez adoptará las medidas necesarias para la administración del caudal, requiriéndose, licencia judicial para todos los actos que excedan de la administración ordinaria.","u":"#art1394","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1395","t":"","x":"Cuando la sociedad de gananciales se disuelva por nulidad del matrimonio y uno de los cónyuges hubiera sido declarado de mala fe, podrá el otro optar por la liquidación del régimen matrimonial según las normas de esta Sección o por las disposiciones relativas al régimen de participación, y el contrayente de mala fe no tendrá derecho a participar en las ganancias obtenidas por su consorte.","u":"#art1395","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1396","t":"","x":"Disuelta la sociedad se procederá a su liquidación, que comenzará por un inventario del activo y pasivo de la sociedad.","u":"#art1396","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1397","t":"","x":"Habrán de comprenderse en el activo: 1.° Los bienes gananciales existentes en el momento de la disolución. 2.° El importe actualizado del valor que tenían los bienes al ser enajenados por negocio ilegal o fraudulento si no hubieran sido recuperados. 3.° El importe actualizado de las cantidades pagadas por la sociedad que fueran de cargo sólo de un cónyuge y en general las que constituyen créditos de la sociedad contra éste.","u":"#art1397","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1398","t":"","x":"El pasivo de la sociedad estará integrado por las siguientes partidas: 1.ª Las deudas pendientes a cargo de la sociedad. 2.ª El importe actualizado del valor de los bienes privativos cuando su restitución deba hacerse en metálico por haber sido gastados en interés de la sociedad. Igual regla se aplicará a los deterioros producidos en dichos bienes por su uso en beneficio de la sociedad. 3.ª El importe actualizado de las cantidades que, habiendo sido pagadas por uno solo de los cónyuges, fueran de cargo de la sociedad y, en general, las que constituyan créditos de los cónyuges contra la sociedad.","u":"#art1398","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1399","t":"","x":"Terminado el inventario se pagarán en primer lugar las deudas de la sociedad, comenzando por las alimenticias que, en cualquier caso, tendrán preferencia. Respecto de las demás, si el caudal inventariado no alcanzase para ello, se observará lo dispuesto para la concurrencia y prelación de créditos.","u":"#art1399","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1400","t":"","x":"Cuando no hubiera metálico suficiente para el pago de las deudas podrán ofrecerse con tal fin adjudicaciones de bienes gananciales, pero si cualquier partícipe o acreedor lo pide se procederá a enajenarlos y pagar con su importe.","u":"#art1400","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1401","t":"","x":"Mientras no se hayan pagado por entero las deudas de la sociedad, los acreedores conservarán sus créditos contra el cónyuge deudor. El cónyuge no deudor responderá con los bienes que le hayan sido adjudicados, si se hubiere formulado debidamente, inventario judicial o extrajudicial. Si como consecuencia de ello resultare haber pagado uno de los cónyuges mayor cantidad de la que le fuere imputable, podrá repetir contra el otro.","u":"#art1401","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1402","t":"","x":"Los acreedores de la sociedad de gananciales tendrán en su liquidación los mismos derechos que le reconocen las Leyes en la partición y liquidación de las herencias.","u":"#art1402","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1403","t":"","x":"Pagadas las deudas y cargas de la sociedad se abonarán las indemnizaciones y reintegros debidos a cada cónyuge hasta donde alcance el caudal inventariado, haciendo las compensaciones que correspondan cuando el cónyuge sea deudor de la sociedad.","u":"#art1403","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1404","t":"","x":"Hechas las deducciones en el caudal inventariado que prefijan los artículos anteriores, el remanente constituirá el haber de la sociedad de gananciales, que se dividirá por mitad entre los cónyuges o sus respectivos herederos.","u":"#art1404","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1405","t":"","x":"Si uno de los cónyuges resultare en el momento de la liquidación acreedor personal del otro, podrá exigir que se le satisfaga su crédito adjudicándole bienes comunes, salvo que el deudor pague voluntariamente.","u":"#art1405","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1406","t":"","x":"Cada cónyuge tendrá derecho a que se incluyan con preferencia en su haber, hasta donde éste alcance: 1.° Los bienes de uso personal no incluidos en el número 7 del artículo 1.346. 2.° La explotación económica que gestione efectivamente. 3.° El local donde hubiese venido ejerciendo su profesión. 4.° En caso de muerte del otro cónyuge, la vivienda donde tuviese la residencia habitual.","u":"#art1406","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1407","t":"","x":"En los casos de los números 3 y 4 del artículo anterior podrá el cónyuge pedir, a su elección, que se le atribuyan los bienes en propiedad o que se constituya sobre ellos a su favor un derecho de uso o habitación. Si el valor de los bienes o el derecho superara al del haber del cónyuge adjudicatario, deberá éste abonar la diferencia en dinero.","u":"#art1407","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1408","t":"","x":"De la masa común de bienes se darán alimentos a los cónyuges o, en su caso, al sobreviviente y a los hijos mientras se haga la liquidación del caudal inventariado y hasta que se les entregue su haber; pero se les rebajarán de éste en la parte que excedan de los que les hubiese correspondido en razón de frutos y rentas.","u":"#art1408","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1409","t":"","x":"Siempre que haya de ejecutarse simultáneamente la liquidación de gananciales de dos o más matrimonios contraídos por una misma persona para determinar el capital de cada sociedad se admitirá toda clase de pruebas en defecto de inventarios. En caso de duda se atribuirán los gananciales a las diferentes sociedades proporcionalmente, atendiendo al tiempo de su duración y a los bienes e ingresos de los respectivos cónyuges.","u":"#art1409","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1410","t":"","x":"En todo lo no previsto en este capítulo sobre formación de inventario, reglas sobre tasación y ventas de bienes, división del caudal, adjudicaciones a los partícipes y demás que no se halle expresamente determinado, se observará lo establecido para la partición y liquidación de la herencia.","u":"#art1410","c":"CAPÍTULO IV De la sociedad de gananciales Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981. · Sección 5.ª De la disolución y liquidación de la sociedad de gananciales Se añade por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1411","t":"","x":"En el régimen de participación cada uno de los cónyuges adquiere derecho a participar en las ganancias obtenidas por su consorte durante el tiempo en que dicho régimen haya estado vigente.","u":"#art1411","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1412","t":"","x":"A cada cónyuge le corresponde la administración, el disfrute y la libre disposición tanto de los bienes que le pertenecían en el momento de contraer matrimonio como de los que pueda adquirir después por cualquier título.","u":"#art1412","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1413","t":"","x":"En todo lo no previsto en este capítulo se aplicarán, durante la vigencia del régimen de participación, las normas relativas al de separación de bienes.","u":"#art1413","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1414","t":"","x":"Si los casados en régimen de participación adquirieran conjuntamente algún bien o derecho, les pertenece en pro indiviso ordinario.","u":"#art1414","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1415","t":"","x":"El régimen de participación se extingue en los casos prevenidos para la sociedad de gananciales, aplicándose lo dispuesto en los artículos 1.394 y 1.395.","u":"#art1415","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1416","t":"","x":"Podrá pedir un cónyuge la terminación del régimen de participación cuando la irregular administración del otro comprometa gravemente sus intereses.","u":"#art1416","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1417","t":"","x":"Producida la extinción se determinarán las ganancias por las diferencias entre los patrimonios inicial y final de cada cónyuge.","u":"#art1417","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1418","t":"","x":"Se estimará constituido el patrimonio inicial de cada cónyuge: 1.° Por los bienes y derechos que le pertenecieran al empezar el régimen. 2.° Por los adquiridos después a título de herencia, donación o legado.","u":"#art1418","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1419","t":"","x":"Se deducirán las obligaciones del cónyuge al empezar el régimen y, en su caso, las sucesorias o las cargas inherentes a la donación o legado, en cuanto no excedan de los bienes heredados o donados.","u":"#art1419","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1420","t":"","x":"Si el pasivo fuese superior al activo no habrá patrimonio inicial.","u":"#art1420","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1421","t":"","x":"Los bienes constitutivos del patrimonio inicial se estimarán según el estado y valor que tuvieran al empezar el régimen o, en su caso, al tiempo en que fueron adquiridos. El importe de la estimación deberá actualizarse el día en que el régimen haya cesado.","u":"#art1421","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1422","t":"","x":"El patrimonio final de cada cónyuge estará formado por los bienes y derechos de que sea titular en el momento de la terminación del régimen, con deducción de las obligaciones todavía no satisfechas.","u":"#art1422","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1423","t":"","x":"Se incluirá en el patrimonio final el valor de los bienes de que uno de los cónyuges hubiese dispuesto a título gratuito sin el consentimiento de su consorte, salvo si se tratase de liberalidades de uso.","u":"#art1423","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1424","t":"","x":"La misma regla se aplicará respecto de los actos realizados por uno de los cónyuges en fraude de los derechos del otro.","u":"#art1424","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1425","t":"","x":"Los bienes constitutivos del patrimonio final se estimarán según el estado y valor que tuvieren en el momento de la terminación del régimen y los enajenados gratuita o fraudulentamente, conforme al estado que tenían el día de la enajenación y por el valor que hubieran tenido si se hubiesen conservado hasta el día de la terminación.","u":"#art1425","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1426","t":"","x":"Los créditos que uno de los cónyuges tenga frente al otro, por cualquier título, incluso por haber atendido o cumplido obligaciones de aquél, se computarán también en el patrimonio final del cónyuge acreedor y se deducirán del patrimonio del cónyuge deudor.","u":"#art1426","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1427","t":"","x":"Cuando la diferencia entre los patrimonios final e inicial de uno y otro cónyuge arroje resultado positivo, el cónyuge cuyo patrimonio haya experimentado menor incremento percibirá la mitad de la diferencia entre su propio incremento y el del otro cónyuge.","u":"#art1427","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1428","t":"","x":"Cuando únicamente uno de los patrimonios arroje resultado positivo, el derecho de la participación consistirá, para el cónyuge no titular de dicho patrimonio, en la mitad de aquel incremento.","u":"#art1428","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1429","t":"","x":"Al constituirse el régimen podrá pactarse una participación distinta de la que establecen los dos artículos anteriores, pero deberá regir por igual y en la misma proporción respecto de ambos patrimonios y en favor de ambos cónyuges.","u":"#art1429","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1430","t":"","x":"No podrá convenirse una participación que no sea por mitad si existen descendientes no comunes.","u":"#art1430","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1431","t":"","x":"El crédito de participación deberá ser satisfecho en dinero. Si mediaren dificultades graves para el pago inmediato, el Juez podrá conceder aplazamiento, siempre que no exceda de tres años y que la deuda y sus intereses legales queden suficientemente garantizados.","u":"#art1431","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1432","t":"","x":"El crédito de participación podrá pagarse mediante la adjudicación de bienes concretos, por acuerdo de los interesados o si lo concediese el Juez a petición fundada del deudor.","u":"#art1432","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1433","t":"","x":"Si no hubiese bienes en el patrimonio deudor para hacer efectivo el derecho de participación en ganancias, el cónyuge acreedor podrá impugnar las enajenaciones que hubieren sido hechas a título gratuito sin su consentimiento y aquellas que hubieren sido realizadas en fraude de sus derechos.","u":"#art1433","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1434","t":"","x":"Las acciones de impugnación a que se refiere el artículo anterior caducarán a los dos años de extinguido el régimen de participación y no se darán contra los adquirentes a título oneroso y de buena fe.","u":"#art1434","c":"TÍTULO II De los contratos · CAPÍTULO V Del régimen de participación Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1435","t":"","x":"Existirá entre los cónyuges separación de bienes. 1.° Cuando así lo hubiesen convenido. 2.° Cuando los cónyuges hubieren pactado en capitulaciones matrimoniales que no regirá entre ellos la sociedad de gananciales, sin expresar las reglas por que hayan de regirse sus bienes. 3.° Cuando se extinga, constante matrimonio, la sociedad de gananciales o el régimen de participación, salvo que por voluntad de los interesados fuesen sustituidos por otro régimen distinto.","u":"#art1435","c":"TÍTULO II De los contratos · CAPÍTULO VI Del régimen de separación de bienes Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1436","t":"","x":"La demanda de separación de bienes y la sentencia firme en que se declare se deberán anotar e inscribir, respectivamente, en el Registro de la Propiedad que corresponda, si recayere sobre bienes inmuebles. La sentencia firme se anotará también en el Registro Civil.","u":"#art1436","c":"TÍTULO II De los contratos · CAPÍTULO VI Del régimen de separación de bienes Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1437","t":"","x":"En el régimen de separación pertenecerán a cada cónyuge los bienes que tuviese en el momento inicial del mismo y, los que después adquiera por cualquier título. Asimismo corresponderá a cada uno la administración, goce y libre disposición de tales bienes.","u":"#art1437","c":"TÍTULO II De los contratos · CAPÍTULO VI Del régimen de separación de bienes Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1438","t":"","x":"Los cónyuges contribuirán al sostenimiento de las cargas del matrimonio. A falta de convenio lo harán proporcionalmente a sus respectivos recursos económicos. El trabajo para la casa será computado como contribución a las cargas y dará derecho a obtener una compensación que el Juez señalará, a falta de acuerdo, a la extinción del régimen de separación.","u":"#art1438","c":"TÍTULO II De los contratos · CAPÍTULO VI Del régimen de separación de bienes Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1439","t":"","x":"Si uno de los cónyuges hubiese administrado o gestionado bienes o intereses del otro, tendrá las mismas obligaciones y responsabilidades que un mandatario, pero no tendrá obligación de rendir cuentas de los frutos percibidos y consumidos, salvo cuando se demuestre que los invirtió en atenciones distintas del levantamiento de las cargas del matrimonio.","u":"#art1439","c":"TÍTULO II De los contratos · CAPÍTULO VI Del régimen de separación de bienes Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1440","t":"","x":"Las obligaciones contraídas por cada cónyuge serán de su exclusiva responsabilidad. En cuanto a las obligaciones contraídas en el ejercicio de la potestad doméstica ordinaria responderán ambos cónyuges en la forma determinada por los artículos 1.319 y 1.438 de este Código.","u":"#art1440","c":"TÍTULO II De los contratos · CAPÍTULO VI Del régimen de separación de bienes Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1441","t":"","x":"Cuando no sea posible acreditar a cuál de los cónyuges pertenece algún bien o derecho, corresponderá a ambos por mitad.","u":"#art1441","c":"TÍTULO II De los contratos · CAPÍTULO VI Del régimen de separación de bienes Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1442","t":"","x":"Declarado un cónyuge en concurso, serán de aplicación las disposiciones de la legislación concursal.","u":"#art1442","c":"TÍTULO II De los contratos · CAPÍTULO VI Del régimen de separación de bienes Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1443","t":"","x":"La separación de bienes decretada no se alterará por la reconciliación de los cónyuges en caso de separación personal o por la desaparición de cualquiera de las demás causas que la hubiesen motivado.","u":"#art1443","c":"TÍTULO II De los contratos · CAPÍTULO VI Del régimen de separación de bienes Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"CC","a":"1444","t":"","x":"No obstante lo dispuesto en el artículo anterior, los cónyuges pueden acordar en capitulaciones que vuelvan a regir las mismas reglas que antes de la separación de bienes. Harán constar en las capitulaciones los bienes que cada uno aporte de nuevo y se considerarán éstos privativos, aunque, en todo o en parte, hubieren tenido carácter ganancial antes de la liquidación practicada por causa de la separación.","u":"#art1444","c":"TÍTULO II De los contratos · CAPÍTULO VI Del régimen de separación de bienes Se modifica por el art. 3 de la Ley 11/1981, de 13 de mayo. Ref. BOE-A-1981-11198. Texto añadido, publicado el 19/05/1981, en vigor a partir del 08/06/1981."},{"n":"LISD","a":"1","t":"Naturaleza y objeto.","x":"El Impuesto sobre Sucesiones y Donaciones, de naturaleza directa y subjetiva, grava los incrementos patrimoniales obtenidos a título lucrativo por personas físicas, en los términos previstos en la presente Ley.","u":"#a1","c":"CAPITULO I. Disposiciones generales"},{"n":"LISD","a":"2","t":"Ámbito territorial.","x":"1. El Impuesto sobre Sucesiones y Donaciones se exigirá en todo el territorio español, sin perjuicio de lo dispuesto en los regímenes tributarios forales de Concierto y Convenio Económico vigentes en los Territorios Históricos del País Vasco y la Comunidad Foral de Navarra, respectivamente, y de lo dispuesto en los Tratados o Convenios internacionales que hayan pasado a formar parte del ordenamiento interno.\n2. La cesión del Impuesto a las Comunidades Autónomas se regirá por lo dispuesto en las normas reguladoras de la Cesión de Tributos del Estado a las Comunidades Autónomas y tendrá el alcance y condiciones que para cada una de ellas establezca su específica Ley de Cesión.","u":"#a2","c":"CAPITULO I. Disposiciones generales"},{"n":"LISD","a":"3","t":"Hecho imponible.","x":"1. Constituye el hecho imponible:\na) La adquisición de bienes y derechos por herencia, legado o cualquier otro título sucesorio.\nb) La adquisición de bienes y derechos por donación o cualquier otro negocio jurídico a título gratuito, «intervivos».\nc) La percepción de cantidades por los beneficiarios de contratos de seguros sobre la vida, cuando el contratante sea persona distinta del beneficiario, salvo los supuestos expresamente regulados en el artículo 16.2, a), de la Ley del Impuesto sobre la Renta de las Personas Físicas y otras Normas Tributarias.\n2. Los incrementos de patrimonio a que se refiere el número anterior, obtenidos por personas jurídicas, no están sujetos a este impuesto y se someterán al Impuesto sobre Sociedades.","u":"#a3","c":"CAPITULO II. Hecho imponible"},{"n":"LISD","a":"4","t":"Presunciones de hechos imponibles.","x":"1. Se presumirá la existencia de una transmisión lucrativa cuando de los registros fiscales o de los datos que obren en la Administración resultare la disminución del patrimonio de una persona y simultáneamente o con posterioridad, pero siempre dentro del plazo de prescripción del artículo 25, el incremento patrimonial correspondiente en el cónyuge, descendientes, herederos o legatarios.\n2. En las adquisiciones a título oneroso realizadas por los ascendientes como representantes de los descendientes menores de edad, se presumirá la existencia de una transmisión lucrativa a favor de éstos por el valor de los bienes o derechos transmitidos, a menos que se pruebe la previa existencia de bienes o medios suficientes del menor para realizarla y su aplicación a este fin.\n3. Las presunciones a que se refieren los números anteriores se pondrán en conocimiento de los interesados para que puedan formular cuantas alegaciones y pruebas estimen convenientes a su derecho, antes de girar las liquidaciones correspondientes.","u":"#a4","c":"CAPITULO II. Hecho imponible"},{"n":"LISD","a":"5","t":"Sujetos pasivos.","x":"Estarán obligados al pago del Impuesto a título de contribuyentes, cuando sean personas físicas:\na) En las adquisiciones «mortis causa», los causahabientes.\nb) En las donaciones y demás transmisiones lucrativas «inter vivos» equiparables, el donatario o el favorecido por ellas.\nc) En los seguros sobre la vida, los beneficiarios.","u":"#a5","c":"CAPITULO III. Sujetos pasivos y responsables"},{"n":"LISD","a":"6","t":"Obligación personal.","x":"1. A los contribuyentes que tengan su residencia habitual en España se les exigirá el Impuesto por obligación personal, con independencia de dónde se encuentren situados los bienes o derechos que integren el incremento de patrimonio gravado.\n2. Para la determinación de la residencia habitual se estará a lo establecido en las normas del Impuesto sobre la Renta de las Personas Físicas.\n3. Los representantes y funcionarios del Estado español en el extranjero quedarán sujetos a este Impuesto por obligación personal, atendiendo a idénticas circunstancias y condiciones que las establecidas para tales sujetos pasivos en las normas del Impuesto sobre la Renta de las Personas Físicas.","u":"#a6","c":"CAPITULO III. Sujetos pasivos y responsables"},{"n":"LISD","a":"7","t":"Obligación real.","x":"A los contribuyentes no incluidos en el artículo inmediato anterior se les exigirá el Impuesto, por obligación real, por la adquisición de bienes y derechos, cualquiera que sea su naturaleza, que estuvieran situados, pudieran ejercitarse o hubieran de cumplirse en territorio español, así como por la percepción de cantidades derivadas de contratos de seguros sobre la vida cuando el contrato haya sido realizado con entidades aseguradoras españolas o se haya celebrado en España con entidades extranjeras que operen en ella.","u":"#a7","c":"CAPITULO III. Sujetos pasivos y responsables"},{"n":"LISD","a":"8","t":"Responsables subsidiarios.","x":"1. Serán subsidiariamente responsables del pago del impuesto, salvo que resultaren de aplicación las normas sobre responsabilidad solidaria de la Ley General Tributaria:\na) En las transmisiones \"mortis causa\" de depósitos, garantías o cuentas corrientes, los intermediarios financieros y las demás entidades o personas que hubieren entregado el metálico y valores depositados o devuelto las garantías constituidas.\nA estos efectos no se considerará entrega de metálico o de valores depositados, ni devolución de garantías, el libramiento de cheques bancarios con cargo a los depósitos, garantías o al resultado de la venta de los valores que sea necesario, que tenga como exclusivo fin el pago del propio Impuesto sobre Sucesiones y Donaciones que grave la transmisión \"mortis causa\", siempre que el cheque sea expedido a nombre de la Administración acreedora del impuesto.\nb) En las entregas de cantidades a quienes resulten beneficiarios como herederos o designados en los contratos, las entidades de seguros que las verifiquen.\nA estos efectos no se considerará entrega de cantidades a los beneficiarios de contratos de seguro el pago a cuenta de la prestación que tenga como exclusivo fin el pago del propio Impuesto sobre Sucesiones y Donaciones que grave la percepción de dicha prestación, siempre que se realice mediante la entrega a los beneficiarios de cheque bancario expedido a nombre de la Administración acreedora del impuesto.\nc) Los mediadores en la transmisión de títulos valores que formen parte de la herencia.\nA estos efectos no se considerará que estos mediadores son responsables del tributo cuando se limiten a realizar, por orden de los herederos, la venta de los valores necesarios que tenga como exclusivo fin el pago del propio Impuesto sobre Sucesiones y Donaciones que grave la transmisión \"mortis causa\", siempre que contra el precio obtenido en dicha venta se realice la entrega a los beneficiarios de cheque bancario expedido a nombre de la Administración acreedora del impuesto.\n2. Será también responsable subsidiario el funcionario que autorizase el cambio de sujeto pasivo de cualquier tributo o exacción estatal, autonómica o local, cuando tal cambio suponga, directa o indirectamente, una adquisición gravada por el presente Impuesto y no hubiere exigido previamente la justificación del pago del mismo.","u":"#a8","c":"CAPITULO III. Sujetos pasivos y responsables"},{"n":"LISD","a":"9","t":"Base imponible.","x":"1. Constituye la base imponible del impuesto:\na) En las transmisiones «mortis causa», el valor neto de la adquisición individual de cada causahabiente, entendiéndose como tal el valor de los bienes y derechos minorado por las cargas y deudas que fueren deducibles.\nb) En las donaciones y demás transmisiones lucrativas ''inter vivos'' equiparables, el valor neto de los bienes y derechos adquiridos, entendiéndose como tal el valor de los bienes y derechos minorado por las cargas y deudas que fueren deducibles.\nc) En los seguros sobre la vida, las cantidades percibidas por el beneficiario. Las cantidades percibidas por razón de seguros sobre la vida se liquidarán acumulando su importe al del resto de los bienes y derechos que integran la porción hereditaria del beneficiario cuando el causante sea, a su vez, el contratante del seguro individual o el asegurado en el seguro colectivo.\n2. A efectos de este impuesto, salvo que resulte de aplicación alguna de las reglas contenidas en los siguientes apartados de este artículo o en los artículos siguientes, se considerará valor de los bienes y derechos su valor de mercado. No obstante, si el valor declarado por los interesados es superior al valor de mercado, esa magnitud se tomará como base imponible.\nSe entenderá por valor de mercado el precio más probable por el cual podría venderse, entre partes independientes, un bien libre de cargas.\n3. En el caso de los bienes inmuebles, su valor será el valor de referencia previsto en la normativa reguladora del catastro inmobiliario, a la fecha de devengo del impuesto.\nNo obstante, si el valor del bien inmueble declarado por los interesados es superior a su valor de referencia, se tomará aquel como base imponible.\nCuando no exista valor de referencia o este no pueda ser certificado por la Dirección General del Catastro, la base imponible, sin perjuicio de la comprobación administrativa, será la mayor de las siguientes magnitudes: el valor declarado por los interesados o el valor de mercado.\n4. El valor de referencia solo se podrá impugnar cuando se recurra la liquidación que en su caso realice la Administración Tributaria o con ocasión de la solicitud de rectificación de la autoliquidación, conforme a los procedimientos regulados en la Ley 58/2003, de 17 de diciembre, General Tributaria.\nCuando los obligados tributarios consideren que la determinación del valor de referencia ha perjudicado sus intereses legítimos, podrán solicitar la rectificación de la autoliquidación impugnando dicho valor de referencia.\n5. Cuando los obligados tributarios soliciten una rectificación de autoliquidación por estimar que la determinación del valor de referencia perjudica a sus intereses legítimos o cuando interpongan un recurso de reposición contra la liquidación que en su caso se le practique, impugnando dicho valor de referencia, la Administración Tributaria resolverá previo informe preceptivo y vinculante de la Dirección General del Catastro, que ratifique o corrija el citado valor, a la vista de la documentación aportada.\nLa Dirección General del Catastro emitirá informe vinculante en el que ratifique o corrija el valor de referencia cuando lo solicite la Administración Tributaria encargada de la aplicación de los tributos como consecuencia de las alegaciones y pruebas aportadas por los obligados tributarios.\nAsimismo, emitirá informe preceptivo, corrigiendo o ratificando el valor de referencia, cuando lo solicite la Administración Tributaria encargada de la aplicación de los tributos, como consecuencia de la interposición de reclamaciones económico-administrativas.\nEn los informes que emita la Dirección General del Catastro, el valor de referencia ratificado o corregido será motivado mediante la expresión de la resolución de la que traiga causa, así como de los módulos de valor medio, factores de minoración y demás elementos precisos para su determinación aprobados en dicha resolución.","u":"#a9","c":"CAPITULO IV. Base imponible · Sección 1.ª Normas generales"},{"n":"LISD","a":"10","t":"Determinación de la base.","x":"Con carácter general, la base imponible se determinará por la Administración Tributaria en régimen de estimación directa sin más excepciones que las determinadas en esta Ley y en las normas reguladoras del régimen de estimación indirecta de bases imponibles.","u":"#a10","c":"CAPITULO IV. Base imponible · Sección 1.ª Normas generales"},{"n":"LISD","a":"11","t":"Adición de bienes.","x":"1. En las adquisiciones «mortis causa», a efectos de la determinación de la participación individual de cada causahabiente, se presumirá que forman parte del caudal hereditario:\na) Los bienes de todas clases que hubiesen pertenecido al causante de la sucesión hasta un año antes de su fallecimiento, salvo prueba fehaciente de que tales bienes fueron transmitidos por aquél y de que se hallan en poder de persona distinta de un heredero, legatario, pariente dentro del tercer grado o cónyuge de cualquiera de ellos o del causante. Esta presunción quedará desvirtuada mediante la justificación suficiente de que en el caudal figuran incluidos el metálico u otros bienes subrogados en el lugar de los desaparecidos con valor equivalente.\nb) Los bienes y derechos que durante los tres años anteriores al fallecimiento hubieran sido adquiridos a título oneroso en usufructo por el causante y en nuda propiedad por un heredero, legatario, pariente dentro del tercer grado o cónyuge de cualquiera de ellos o del causante.\nc) Los bienes y derechos que hubieran sido transmitidos por el causante durante los cuatro años anteriores a su fallecimiento, reservándose el usufructo de los mismos o de otros del adquirente o cualquier otro derecho vitalicio, salvo cuando se trate de seguros de renta vitalicia contratados con entidades dedicadas legalmente a este género de operaciones; y\nd) Los valores y efectos depositados y cuyos resguardos se hubieren endosado, si con anterioridad al fallecimiento del endosante no se hubieren retirado aquéllos o tomado razón del endoso en los libros del depositario, y los valores nominativos que hubieren sido igualmente objeto de endoso, si la transferencia no se hubiere hecho constar en los libros de la entidad emisora con anterioridad también al fallecimiento del causante.\nNo tendrá lugar esta presunción cuando conste de un modo suficiente que el precio o equivalencia del valor de los bienes o efectos transmitidos se ha incorporado al patrimonio del vendedor o cedente y figura en el inventario de su herencia, que ha de ser tenido en cuenta para la liquidación del impuesto, o si se justifica suficientemente que la retirada de valores o efectos o la toma de razón del endoso no ha podido verificarse con anterioridad al fallecimiento del causante por causas independientes de la voluntad de éste y del endosatario. Lo dispuesto en este párrafo se entenderá sin perjuicio de lo prevenido bajo las letras a), b) y c) anteriores.\n2. El adquirente y los endosatarios a que se refieren los apartados c) y d) precedentes serán considerados como legatarios si fuesen personas distintas del heredero.\n3. Cuando en cumplimiento de lo dispuesto en este artículo resultare exigible por el Impuesto sobre Sucesiones y Donaciones, una cuota superior a la que se hubiere obtenido, en su caso, en el Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados, lo satisfecho por este último se deducirá de lo que corresponda satisfacer por aquél.\n4. Si los interesados rechazasen la incorporación al caudal hereditario de bienes y derechos en virtud de las presunciones establecidas en este artículo, se excluirá el valor de éstos de la base imponible, hasta la resolución definitiva en vía administrativa de la cuestión suscitada.\n5. Asimismo, serán de aplicación, en su caso, las presunciones de titularidad o cotitularidad contenidas en la Ley General Tributaria y en la Ley del Impuesto sobre el Patrimonio Neto.","u":"#a11","c":"CAPITULO IV. Base imponible · Sección 2.ª Normas especiales para adquisiciones «mortis causa»"},{"n":"LISD","a":"12","t":"Cargas deducibles.","x":"Del valor de los bienes, únicamente serán deducibles las cargas o gravámenes de naturaleza perpetua, temporal o redimibles que aparezcan directamente establecidos sobre los mismos y disminuyan realmente su capital o valor, como los censos y las pensiones, sin que merezcan tal consideración las cargas que constituyan obligación personal del adquirente ni las que, como las hipotecas y las prendas, no suponen disminución del valor de lo transmitido, sin perjuicio, en su caso, de que las deudas que garanticen puedan ser deducidas si concurren los requisitos establecidos en el artículo siguiente.","u":"#a12","c":"CAPITULO IV. Base imponible · Sección 2.ª Normas especiales para adquisiciones «mortis causa»"},{"n":"LISD","a":"13","t":"Deudas deducibles.","x":"1. En las transmisiones por causa de muerte, a efectos de la determinación del valor neto patrimonial, podrán deducirse con carácter general las deudas que dejare contraídas el causante de la sucesión siempre que su existencia se acredite por documento público o por documento privado que reúna los requisitos del artículo 1.227 del Código Civil o se justifique de otro modo la existencia de aquélla, salvo las que lo fuesen a favor de los herederos o de los legatarios de parte alícuota y de los cónyuges, ascendientes, descendientes o hermanos de aquéllos aunque renuncien a la herencia. La Administración podrá exigir que se ratifique la deuda en documento público por los herederos, con la comparecencia del acreedor.\n2. En especial, serán deducibles las cantidades que adeudare el causante por razón de tributos del Estado, de Comunidades Autónomas o de Corporaciones Locales o por deudas de la Seguridad Social y que se satisfagan por los herederos, albaceas o administradores del caudal hereditario, aunque correspondan a liquidaciones giradas después del fallecimiento.","u":"#a13","c":"CAPITULO IV. Base imponible · Sección 2.ª Normas especiales para adquisiciones «mortis causa»"},{"n":"LISD","a":"14","t":"Gastos deducibles.","x":"En las adquisiciones por causa de muerte son deducibles para la determinación de la base imponible:\na) Los gastos que cuando la testamentaría o abintestato adquieran carácter litigioso se ocasionen en el litigio en interés común de todos los herederos por la representación legítima de dichas testamentarías o abintestatos, excepto los de administración del caudal relicto, siempre que resulten aquéllos cumplidamente justificados con testimonio de los autos.\nb) Los gastos de última enfermedad, entierro y funeral, en cuanto se justifiquen. Los de entierro y funeral deberán guardar, además, la debida proporción con el caudal hereditario, conforme a los usos y costumbres de la localidad.","u":"#a14","c":"CAPITULO IV. Base imponible · Sección 2.ª Normas especiales para adquisiciones «mortis causa»"},{"n":"LISD","a":"15","t":"Ajuar doméstico.","x":"El ajuar doméstico formará parte de la masa hereditaria y se valorará en el tres por ciento del importe del caudal relicto del causante, salvo que los interesados asignen a este ajuar un valor superior o prueben fehacientemente su inexistencia o que su valor es inferior al que resulte de la aplicación del referido porcentaje.","u":"#a15","c":"CAPITULO IV. Base imponible · Sección 2.ª Normas especiales para adquisiciones «mortis causa»"},{"n":"LISD","a":"16","t":"Cargas deducibles.","x":"En las donaciones y demás transmisiones lucrativas \"inter vivos\" equiparables, del valor de los bienes y derechos adquiridos se deducirán las cargas que reúnan los requisitos establecidos en el artículo 12 de esta Ley.","u":"#a16","c":"CAPITULO IV. Base imponible · Sección 3.ª Normas especiales para transmisiones lucrativas «inter vivos»"},{"n":"LISD","a":"17","t":"Deudas deducibles.","x":"Del valor de los bienes donados o adquiridos por otro título lucrativo «inter vivos» equiparable, sólo serán deducibles las deudas que estuviesen garantizadas con derechos reales que recaigan sobre los mismos bienes transmitidos, en el caso de que el adquirente haya asumido fehacientemente la obligación de pagar la deuda garantizada.\nSi no asumiese fehacientemente esta obligación no será deducible el importe de la deuda, sin perjuicio del derecho del adquirente a la devolución de la porción de la cuota tributaria correspondiente a dicho importe, si acreditase fehacientemente el pago de la deuda por su cuenta dentro del plazo de prescripción del impuesto. Reglamentariamente se regulará la forma de practicar la devolución.","u":"#a17","c":"CAPITULO IV. Base imponible · Sección 3.ª Normas especiales para transmisiones lucrativas «inter vivos»"},{"n":"LISD","a":"18","t":"Normas generales.","x":"1. La Administración podrá comprobar el valor de los bienes y derechos transmitidos por los medios de comprobación establecidos en el artículo 57 de la Ley General Tributaria, salvo que, en el caso de inmuebles, la base imponible sea su valor de referencia o el valor declarado por ser superior, de acuerdo con lo dispuesto en el artículo 9 de esta Ley.\n2. Los interesados deberán consignar en la declaración que están obligados a presentar según el artículo 31 el valor que atribuyen a cada uno de los bienes y derechos incluidos en la declaración del impuesto. Este valor prevalecerá sobre el comprobado si fuese superior.\nSi el valor al que se refiere el párrafo anterior no hubiera sido comunicado, se les concederá un plazo de diez días para que subsanen la omisión.\n3. Si el nuevo valor así obtenido fuese superior al que resultase de la aplicación de la correspondiente regla del Impuesto sobre el Patrimonio surtirá efecto en relación con las liquidaciones a practicar a cargo del adquirente por dicho Impuesto por la anualidad corriente y las siguientes.\n4. No se aplicará sanción sobre la parte de cuota que corresponda al mayor valor obtenido de la comprobación sobre el declarado cuando el sujeto pasivo se hubiese ajustado en su declaración a las reglas de valoración establecidas en el Impuesto sobre el Patrimonio Neto.","u":"#a18","c":"CAPITULO IV. Base imponible · Seccion 4.ª Comprobación de valores"},{"n":"LISD","a":"20","t":"Base liquidable.","x":"1. En las adquisiciones gravadas por este impuesto, la base liquidable se obtendrá aplicando en la base imponible las reducciones que, conforme a lo previsto en la Ley 21/2001, de 27 de diciembre, por la que se regulan las medidas fiscales y administrativas del nuevo sistema de financiación de las Comunidades Autónomas de régimen común y Ciudades con Estatuto de Autonomía, hayan sido aprobadas por la Comunidad Autónoma. Estas reducciones se practicarán por el siguiente orden: en primer lugar, las del Estado y, a continuación, las de las Comunidades Autónomas.\n2. En las adquisiciones \"mortis causa\", incluidas las de los beneficiarios de pólizas de seguros de vida, si la Comunidad Autónoma no hubiese regulado las reducciones a que se refiere el apartado anterior o no resultase aplicable a los sujetos pasivos la normativa propia de la Comunidad, se aplicarán las siguientes reducciones:\na) La que corresponda de las incluidas en los grupos siguientes:\nGrupo I: adquisiciones por descendientes y adoptados menores de veintiún años, 15.956,87 euros, más 3.990,72 euros por cada año menos de veintiuno que tenga el causahabiente, sin que la reducción pueda exceder de 47.858,59 euros.\nGrupo II: adquisiciones por descendientes y adoptados de veintiuno o más años, cónyuges, ascendientes y adoptantes, 15.956,87 euros.\nGrupo III: adquisiciones por colaterales de segundo y tercer grado, ascendientes y descendientes por afinidad, 7.993,46 euros.\nGrupo IV: en las adquisiciones por colaterales de cuarto grado, grados más distantes y extraños, no habrá lugar a reducción.\nSe aplicará, además de las que pudieran corresponder en función del grado de parentesco con el causante, una reducción de 47.858,59 euros a las personas que tengan la consideración legal de minusválidos, con un grado de discapacidad igual o superior al 33 por 100 e inferior al 65 por 100, de acuerdo con el baremo a que se refiere el artículo 148 del texto refundido de la Ley General de la Seguridad Social, aprobado por el Real Decreto Legislativo 1/1994, de 20 de junio ; la reducción será de 150.253,03 euros para aquellas personas que, con arreglo a la normativa anteriormente citada, acrediten un grado de minusvalía igual o superior al 65 por 100.\nb) Con independencia de las reducciones anteriores, se aplicará una reducción del 100 por ciento, con un límite de 9.195,49 euros, a las cantidades percibidas por los beneficiarios de contratos de seguros sobre vida, cuando su parentesco con el contratante fallecido sea de cónyuge, ascendiente, descendiente, adoptante o adoptado. En los seguros colectivos o contratados por las empresas a favor de sus empleados se estará al grado de parentesco entre el asegurado fallecido y beneficiario.\nLa reducción será única por sujeto pasivo cualquiera que fuese el número de contratos de seguros de vida de los que sea beneficiario, y no será aplicable cuando éste tenga derecho a la establecida en la disposición transitoria cuarta de esta ley.\nLa misma reducción será en todo caso aplicable a los seguros de vida que traigan causa en actos de terrorismo, así como en servicios prestados en misiones internacionales humanitarias o de paz de carácter público, y no estará sometida al límite cuantitativo establecido en el primer párrafo de esta letra, siendo extensible a todos los posibles beneficiarios, sin que sea de aplicación lo previsto en la disposición transitoria cuarta de esta ley.\nc) En los casos en los que en la base imponible de una adquisición \"mortis causa\" que corresponda a los cónyuges, descendientes o adoptados de la persona fallecida, estuviese incluido el valor de una empresa individual, de un negocio profesional o participaciones en entidades, a los que sea de aplicación la exención regulada en el apartado octavo del artículo 4 de la Ley 19/1991, de 6 de junio, del Impuesto sobre el Patrimonio, o el valor de derechos de usufructo sobre los mismos, o de derechos económicos derivados de la extinción de dicho usufructo, siempre que con motivo del fallecimiento se consolidara el pleno dominio en el cónyuge, descendientes o adoptados, o percibieran éstos los derechos debidos a la finalización del usufructo en forma de participaciones en la empresa, negocio o entidad afectada, para obtener la base liquidable se aplicará en la imponible, con independencia de las reducciones que procedan de acuerdo con los apartados anteriores, otra del 95 por 100 del mencionado valor, siempre que la adquisición se mantenga, durante los diez años siguientes al fallecimiento del causante, salvo que falleciera el adquirente dentro de ese plazo.\nEn los supuestos del párrafo anterior, cuando no existan descendientes o adoptados, la reducción será de aplicación a las adquisiciones por ascendientes, adoptantes y colaterales, hasta el tercer grado y con los mismos requisitos recogidos anteriormente. En todo caso, el cónyuge supérstite tendrá derecho a la reducción del 95 por 100.\nDel mismo porcentaje de reducción, con el límite de 122.606,47 euros para cada sujeto pasivo y con el requisito de permanencia señalado anteriormente, gozarán las adquisiciones \"mortis causa\" de la vivienda habitual de la persona fallecida, siempre que los causahabientes sean cónyuge, ascendientes o descendientes de aquél, o bien pariente colateral mayor de sesenta y cinco años que hubiese convivido con el causante durante los dos años anteriores al fallecimiento.\nCuando en la base imponible correspondiente a una adquisición \"mortis causa\" del cónyuge, descendientes o adoptados de la persona fallecida se incluyeran bienes comprendidos en los apartados uno, dos o tres del artículo 4 de la Ley 19/1991, de 6 de junio, del Impuesto sobre el Patrimonio, en cuanto integrantes del Patrimonio Histórico Español o del Patrimonio Histórico o Cultural de las Comunidades Autónomas, se aplicará, asimismo, una reducción del 95 por 100 de su valor, con los mismos requisitos de permanencia señalados en este apartado.\nEn el caso de no cumplirse el requisito de permanencia al que se refiere el presente apartado, deberá pagarse la parte del impuesto que se hubiese dejado de ingresar como consecuencia de la reducción practicada y los intereses de demora.\n3. Si unos mismos bienes en un período máximo de diez años fueran objeto de dos o más transmisiones \"mortis causa\" en favor de descendientes, en la segunda y ulteriores se deducirá de la base imponible, además, el importe de lo satisfecho por el impuesto en las transmisiones precedentes. Se admitirá la subrogación de los bienes cuando se acredite fehacientemente.\n4. En el caso de obligación real de contribuir, las reducciones aplicables serán las establecidas en el apartado 2. Las mismas reducciones serán aplicables en el caso de obligación personal de contribuir cuando el sujeto pasivo o el causante fuesen no residentes en territorio español.\n5. En las adquisiciones por título de donación o equiparable, si la Comunidad Autónoma no hubiese regulado las reducciones a que se refiere el apartado 1 o no resultase aplicable a los sujetos pasivos la normativa propia de la Comunidad, la base liquidable coincidirá, en todo caso, con la imponible, salvo lo dispuesto en los siguientes apartados y en la disposición final primera.\n6. En los casos de transmisión de participaciones \"ínter vivos\", en favor del cónyuge, descendientes o adoptados, de una empresa individual, un negocio profesional o de participaciones en entidades del donante a los que sea de aplicación la exención regulada en el apartado octavo del artículo 4 de la Ley 19/1991, de 6 de junio, del Impuesto sobre el Patrimonio, se aplicará una reducción en la base imponible para determinar la liquidable del 95 por 100 del valor de adquisición, siempre que concurran las condiciones siguientes:\na) Que el donante tuviese sesenta y cinco o más años o se encontrase en situación de incapacidad permanente, en grado de absoluta o gran invalidez.\nb) Que, si el donante viniere ejerciendo funciones de dirección, dejara de ejercer y de percibir remuneraciones por el ejercicio de dichas funciones desde el momento de la transmisión.\nA estos efectos, no se entenderá comprendida entre las funciones de dirección la mera pertenencia al Consejo de Administración de la sociedad.\nc) En cuanto al donatario, deberá mantener lo adquirido y tener derecho a la exención en el Impuesto sobre el Patrimonio durante los diez años siguientes a la fecha de la escritura pública de donación, salvo que falleciera dentro de este plazo.\nAsimismo, el donatario no podrá realizar actos de disposición y operaciones societarias que, directa o indirectamente, puedan dar lugar a una minoración sustancial del valor de la adquisición. Dicha obligación también resultará de aplicación en los casos de adquisiciones \"mortis causa\" a que se refiere la letra c) del apartado 2 de este artículo.\nEn el caso de no cumplirse los requisitos a que se refiere el presente apartado, deberá pagarse la parte del impuesto que se hubiere dejado de ingresar como consecuencia de la reducción practicada y los intereses de demora.\n7. La misma reducción en la base imponible regulada en el apartado anterior y con las condiciones señaladas en sus letras a) y c) se aplicará, en caso de donación, a favor del cónyuge, descendientes o adoptados, de los bienes comprendidos en los apartados uno, dos y tres del artículo 4 de la Ley 19/1991, de 6 de junio, del Impuesto sobre el Patrimonio, en cuanto integrantes del Patrimonio Histórico Español o del Patrimonio Histórico o Cultural de las Comunidades Autónomas.\nA los efectos de las adquisiciones gratuitas de los bienes integrantes del Patrimonio Histórico Español o del Patrimonio Histórico o Cultural de las Comunidades Autónomas, se considerará que el donatario no vulnera el deber de mantenimiento de lo adquirido cuando done, de forma pura, simple e irrevocable, los bienes adquiridos con reducción de la base imponible del impuesto al Estado o a las demás Administraciones públicas territoriales o institucionales.\nEl incumplimiento de los requisitos exigidos llevará consigo el pago del impuesto dejado de ingresar y los correspondientes intereses de demora.","u":"#a20","c":"CAPITULO V. Base liquidable"},{"n":"LISD","a":"21","t":"Tarifa.","x":"1. La cuota íntegra del impuesto se obtendrá aplicando a la base liquidable, calculada según lo dispuesto en el artículo anterior, la escala que, conforme a lo previsto en la Ley 21/2001, de 27 de diciembre, por la que se regulan las medidas fiscales y administrativas del nuevo sistema de financiación de las Comunidades Autónomas de régimen común y Ciudades con Estatuto de Autonomía, haya sido aprobada por la Comunidad Autónoma.\n2. Si la Comunidad Autónoma no hubiese aprobado la escala a que se refiere el apartado anterior o si aquélla no hubiese asumido competencias normativas en materia de Impuesto sobre Sucesiones y Donaciones o no resultase aplicable a los sujetos pasivos la normativa propia de la Comunidad, la base liquidable será gravada a los tipos que se indican en la siguiente escala:\n| Base liquidable<br>-<br>Hasta euros | Cuota íntegra<br>–<br>Euros | Resto base liquidable<br>–<br>Hasta euros | Tipo aplicable<br>–<br>Porcentaje |\n| ----------------------------------- | --------------------------- | ----------------------------------------- | --------------------------------- |\n| 0,00 | | 7.993,46 | 7,65 |\n| 7.993,46 | 611,50 | 7.987,45 | 8,50 |\n| 15.980,91 | 1.290,43 | 7.987,45 | 9,35 |\n| 23.968,36 | 2.037,26 | 7.987,45 | 10,20 |\n| 31.955,81 | 2.851,98 | 7.987,45 | 11,05 |\n| 39.943,26 | 3.734,59 | 7.987,45 | 11,90 |\n| 47.930,72 | 4.685,10 | 7.987,45 | 12,75 |\n| 55.918,17 | 5.703,50 | 7.987,45 | 13,60 |\n| 63.905,62 | 6.789,79 | 7.987,45 | 14,45 |\n| 71.893,07 | 7.943,98 | 7.987,45 | 15,30 |\n| 79.880,52 | 9.166,06 | 39.877,15 | 16,15 |\n| 119.757,67 | 15.606,22 | 39.877,16 | 18,70 |\n| 159.634,83 | 23.063,25 | 79.754,30 | 21,25 |\n| 239.389,13 | 40.011,04 | 159.388,41 | 25,50 |\n| 398.777,54 | 80.655,08 | 398.777,54 | 29,75 |\n| 797.555,08 | 199.291,40 | en adelante | 34,00 |\n3. En el caso de obligación real de contribuir, la tarifa aplicable será la establecida en el apartado anterior. La misma tarifa será aplicable, en el supuesto de obligación personal de contribuir, en los casos de donación de bienes inmuebles situados en el extranjero o cuando el sujeto pasivo o el causante fuesen no residentes en territorio español.","u":"#a21","c":"CAPITULO VI. Tipo de gravamen"},{"n":"LISD","a":"22","t":"Cuota tributaria.","x":"1. La cuota tributaria por este impuesto se obtendrá aplicando a la cuota íntegra el coeficiente multiplicador en función de la cuantía de los tramos del patrimonio preexistente que, conforme a lo previsto en la Ley 21/2001, de 27 de diciembre, por la que se regulan las medidas fiscales y administrativas del nuevo sistema de financiación de las Comunidades Autónomas de régimen común y Ciudades con Estatuto de Autonomía, hayan sido aprobados por la Comunidad Autónoma y del grupo, según el grado de parentesco, señalado en el artículo 20.\n2. Si la Comunidad Autónoma no hubiese aprobado el coeficiente o la cuantía de los tramos a que se refiere el apartado anterior, o no resultase aplicable a los sujetos pasivos la normativa propia de la Comunidad, se aplicará el que corresponda de los que se indican a continuación, establecidos en función del patrimonio preexistente del contribuyente y del grupo, según el grado de parentesco, señalado en el artículo 20:\n| Patrimonio preexistente<br>–<br>Euros | Grupos del artículo 20 | | |\n| ------------------------------------------------------------ | ---------------------- | ------ | ------ |\n| | I y II | III | IV |\n| De 0 a 402.678,11 .......................................... | 1,0000 | 1,5882 | 2,0000 |\n| De más de 402.678,11 a 2.007.380,43...... | 1,0500 | 1,6676 | 2,1000 |\n| De más de 2.007.380,43 a 4.020.770,98... | 1,1000 | 1,7471 | 2,2000 |\n| Más de 4.020.770,98...................................... | 1,2000 | 1,9059 | 2,4000 |\nCuando la diferencia entre la cuota tributaria obtenida por la aplicación del coeficiente multiplicador que corresponda y la que resultaría de aplicar a la misma cuota íntegra el coeficiente multiplicador inmediato inferior sea mayor que la que exista entre el importe del patrimonio preexistente tenido en cuenta para la liquidación y el importe máximo del tramo de patrimonio preexistente que motivaría la aplicación del citado coeficiente multiplicador inferior, aquélla se reducirá en el importe del exceso.\nEn los casos de seguros sobre la vida se aplicará el coeficiente que corresponde al patrimonio preexistente del beneficiario y al grupo en que por su parentesco con el contratante estuviese encuadrado. En los seguros colectivos o contratados por las empresas en favor de sus empleados se estará al coeficiente que corresponda al patrimonio preexistente del beneficiario y al grado de parentesco entre éste y el asegurado.\nSi no fuesen conocidos los causahabientes en una sucesión, se aplicará el coeficiente establecido para los colaterales de cuarto grado y extraños cuando el patrimonio preexistente exceda de 4.020.770,98 euros, sin perjuicio de la devolución que proceda una vez que aquéllos fuesen conocidos.\n3. En la valoración del patrimonio preexistente del contribuyente se aplicarán las siguientes reglas:\na) La valoración se realizará conforme a las reglas del Impuesto sobre el Patrimonio.\nb) Cuando se trate de adquisiciones \"mortis causa\", se excluirá el valor de los bienes y derechos por cuya adquisición se haya satisfecho el impuesto como consecuencia de una donación anterior realizada por el causante. La misma regla se aplicará en el caso de acumulación de donaciones.\nc) En el patrimonio preexistente se incluirá el valor de los bienes y derechos que el cónyuge que hereda perciba como consecuencia de la disolución de la sociedad conyugal.\n4. En el caso de obligación real de contribuir, el coeficiente multiplicador será el establecido en el apartado 2 anterior. El mismo coeficiente multiplicador será aplicable en el supuesto de obligación personal de contribuir, en los casos de donación de bienes inmuebles situados en el extranjero o cuando el sujeto pasivo o el causante fuesen no residentes en territorio español.","u":"#a22","c":"CAPITULO VII. Deuda tributaria"},{"n":"LISD","a":"23","t":"Deducción por doble imposición internacional.","x":"1. Cuando la sujeción al impuesto se produzca por obligación personal, tendrá el contribuyente derecho a deducir la menor de las dos cantidades siguientes:\na) El importe efectivo de lo satisfecho en el extranjero por razón de impuesto similar que afecte al incremento patrimonial sometido a gravamen en España.\nb) El resultado de aplicar el tipo medio efectivo de este impuesto al incremento patrimonial correspondiente a bienes que radiquen o derechos que puedan ser ejercitados fuera de España, cuando hubiesen sido sometidos a gravamen en el extranjero por un impuesto similar.\n2. De acuerdo con lo previsto en la Ley 21/2001, de 27 de diciembre, por la que se regulan las medidas fiscales y administrativas del nuevo sistema de financiación de las Comunidades Autónomas de régimen común y Ciudades con Estatuto de Autonomía, las Comunidades Autónomas podrán aprobar las deducciones y bonificaciones que estimen convenientes.\nEn todo caso, resultarán compatibles con las deducciones y bonificaciones establecidas en la normativa estatal reguladora del impuesto sin que puedan suponer una modificación las mismas. Estas deducciones y bonificaciones autonómicas se aplicarán con posterioridad a las reguladas por la normativa del Estado.","u":"#a23","c":"CAPITULO VII. Deuda tributaria"},{"n":"LISD","a":"23 bis","t":"Bonificación de la cuota en Ceuta y Melilla.","x":"1. En las cuotas de este impuesto derivadas de adquisiciones \"mortis causa\" y las cantidades percibidas por los beneficiarios de seguros sobre la vida, que se acumulen al resto de bienes y derechos que integran la porción hereditaria del beneficiario, se efectuará una bonificación del 50 por 100 de la cuota, siempre que el causante hubiera tenido su residencia habitual a la fecha del devengo en Ceuta o Melilla y durante los cinco años anteriores, contados fecha a fecha, que finalicen el día anterior al del devengo.\nNo obstante, la bonificación a que se refiere el párrafo anterior se elevará al 99 por ciento para los causahabientes comprendidos, según el grado de parentesco, en los grupos I y II señalados en el artículo 20 de esta ley.\n2. En los supuestos de adquisiciones \"inter vivos\", se aplicará una bonificación del 50 por 100 de la parte de la cuota que proporcionalmente corresponda a los inmuebles situados en Ceuta o Melilla. A los efectos de esta bonificación, tendrán la consideración de bienes inmuebles las transmisiones a título gratuito de los valores a que se refiere el artículo 108 de la Ley 24/1988, de 28 de julio, del Mercado de Valores.\n3. En el caso de las demás adquisiciones \"inter vivos\", se aplicará una bonificación del 50 por 100 de la cuota que corresponda cuando el adquirente tenga su residencia habitual en Ceuta o Melilla.\n4. Para la aplicación de estas bonificaciones, se tendrán en cuenta las normas establecidas sobre residencia habitual y puntos de conexión en la Ley 21/2001, de 27 de diciembre, por la que se regulan las medidas fiscales y administrativas del nuevo sistema de financiación de las Comunidades Autónomas de régimen común y Ciudades con Estatuto de Autonomía.\nTexto añadido, publicado el 31/12/2002, en vigor a partir del 01/01/2003.","u":"#a23bis","c":"CAPITULO VII. Deuda tributaria"},{"n":"LISD","a":"24","t":"Devengo.","x":"1. En las adquisiciones por causa de muerte y en los seguros sobre la vida, el impuesto se devengará el día del fallecimiento del causante o del asegurado o cuando adquiera firmeza la declaración de fallecimiento del ausente, conforme al artículo 196 del Código Civil. No obstante, en las adquisiciones producidas en vida del causante como consecuencia de contratos y pactos sucesorios, el impuesto se devengará el día en que se cause o celebre dicho acuerdo.\n2. En las transmisiones lucrativas «inter vivos» el impuesto se devengará el día en que se cause o celebre el acto o contrato.\n3. Toda adquisición de bienes cuya efectividad se halle suspendida por la existencia de una condición, un término, un fideicomiso o cualquier otra limitación, se entenderá siempre realizada el día en que dichas limitaciones desaparezcan.","u":"#a24","c":"CAPITULO VIII. Devengo y prescripción"},{"n":"LISD","a":"25","t":"Prescripción.","x":"1. La prescripción se aplicará de acuerdo con lo previsto en los artículos 64 y siguientes de la Ley General Tributaria.\n2. En el supuesto de escrituras autorizadas por funcionarios extranjeros, el plazo de prescripción se computará desde la fecha de su presentación ante cualquier Administración española, salvo que un Tratado, Convenio o Acuerdo Internacional, suscrito por España, fije otra fecha para el inicio de dicho plazo.","u":"#a25","c":"CAPITULO VIII. Devengo y prescripción"},{"n":"LISD","a":"26","t":"Usufructo y otras instituciones.","x":"Serán de aplicación las normas contenidas en los apartados siguientes a la tributación del derecho de usufructo, tanto a la constitución como a la extinción, de las sustituciones, reservas, fideicomisos e instituciones sucesorias forales:\na) El valor del usufructo temporal se reputará proporcional al valor total de los bienes, en razón del 2 por 100 por cada período de un año, sin exceder del 70 por 100.\nEn los usufructos vitalicios se estimará que el valor es igual al 70 por 100 del valor total de los bienes cuando el usufructuario cuente menos de veinte años, minorando a medida que aumenta la edad, en la proporción de un 1 por 100 menos por cada año más, con el límite mínimo del 10 por 100 del valor total.\nEl valor del derecho de nuda propiedad se computará por la diferencia entre el valor del usufructo y el valor total de los bienes. En los usufructos vitalicios que, a su vez, sean temporales, la nuda propiedad se valorará aplicando, de las reglas anteriores, aquella que le atribuya menor valor.\nAl adquirir la nuda propiedad se efectuará la liquidación, teniendo en cuenta el valor correspondiente a aquélla, minorado, en su caso, por el importe de todas las reducciones a que tenga derecho el contribuyente y con aplicación del tipo medio efectivo de gravamen correspondiente al valor íntegro de los bienes.\nb) El valor de los derechos reales de uso y habitación será el que resulte de aplicar al 75 por 100 del valor de los bienes sobre los que fueron impuestos las reglas correspondientes a la valoración de los usufructos temporales o vitalicios, según los casos.\nc) En la extinción del usufructo se exigirá el impuesto según el título de constitución, aplicando el tipo medio efectivo de gravamen correspondiente a la desmembración del dominio.\nd) Siempre que el adquirente tenga facultad de disponer de los bienes, el impuesto se liquidará en pleno dominio, sin perjuicio de la devolución que, en su caso, proceda.\ne) La atribución del derecho a disfrutar de todo o parte de los bienes de la herencia, temporal o vitaliciamente, tendrá a efectos fiscales la consideración de usufructo, y se valorará conforme a las reglas anteriores.\nf) En la sustitución vulgar se entenderá que el sustituto hereda al causante y en las sustituciones pupilar y ejemplar que hereda al sustituido.","u":"#a26","c":"CAPITULO IX. Normas especiales"},{"n":"LISD","a":"27","t":"Partición y excesos de adjudicación.","x":"1. En las sucesiones por causa de muerte, cualesquiera que sean las particiones y adjudicaciones que los interesados hagan, se considerará para los efectos del impuesto como si se hubiesen hecho con estricta igualdad y con arreglo a las normas reguladoras de la sucesión, estén o no los bienes sujetos al pago del impuesto por la condición del territorio o por cualquier otra causa y, en consecuencia, los aumentos que en la comprobación de valores resulten se prorratearán entre los distintos adquirentes o herederos.\n2. Si los bienes en cuya comprobación resultare aumento de valores o a los que deba aplicarse la no sujeción fuesen atribuidos específicamente por el testador a persona determinada o adjudicados en concepto distinto del de herencia, los aumentos o disminuciones afectarán sólo al que adquiera dichos bienes.\n3. Se liquidarán excesos de adjudicación, según las normas establecidas en el Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados cuando existan diferencias, según el valor declarado, en las adjudicaciones efectuadas a los herederos o legatarios, en relación con el título hereditario; también se liquidarán los excesos de adjudicación cuando el valor comprobado de lo adjudicado a uno de los herederos o legatarios exceda del 50 por 100 del valor que le correspondería en virtud de su título, salvo en el supuesto de que los valores declarados sean iguales o superiores a los que resultarían de la aplicación de las reglas del Impuesto sobre el Patrimonio Neto.","u":"#a27","c":"CAPITULO IX. Normas especiales"},{"n":"LISD","a":"28","t":"Repudiación y renuncia a la herencia.","x":"1. En la repudiación o renuncia pura, simple y gratuita de la herencia o legado, los beneficiarios de la misma tributarán por la adquisición de la parte repudiada o renunciada, aplicando siempre el coeficiente que corresponda a la cuantía de su patrimonio preexistente. En cuanto al parentesco con el causante, se tendrá en cuenta el del renunciante o el del que repudia cuando tenga señalado uno superior al que correspondería al beneficiario.\n2. En los demás casos de renuncia en favor de persona determinada, se exigirá el impuesto al renunciante, sin perjuicio de lo que deba liquidarse, además, por la cesión o donación de la parte renunciada.\n3. La repudiación o renuncia hecha después de prescrito el impuesto correspondiente a la herencia o legado se reputará a efectos fiscales como donación.","u":"#a28","c":"CAPITULO IX. Normas especiales"},{"n":"LISD","a":"29","t":"Donaciones especiales.","x":"Las donaciones con causa onerosa y las remuneratarias tributarán por tal concepto y por su total importe. Si existieran recíprocas prestaciones o se impusiera algún gravamen al donatario, tributarán por el mismo concepto solamente por la diferencia.","u":"#a29","c":"CAPITULO IX. Normas especiales"},{"n":"LISD","a":"30","t":"Acumulación de donaciones y contratos y pactos sucesorios.","x":"1. Las donaciones y demás transmisiones ''inter vivos'' equiparables que se otorguen por un mismo donante a un mismo donatario, así como las adquisiciones producidas en vida del causante como consecuencia de contratos y pactos sucesorios formalizados entre las mismas personas, todas ellas dentro del plazo de tres años, a contar desde la fecha de cada una, se considerarán como una sola transmisión a los efectos de la liquidación del impuesto. Para determinar la cuota tributaria se aplicará, a la base liquidable de la actual adquisición, el tipo medio correspondiente a la base liquidable teórica del total de las adquisiciones acumuladas.\n2. Lo dispuesto en el apartado anterior, a efectos de la determinación de la cuota tributaria, será igualmente aplicable a las donaciones y demás transmisiones ''inter vivos'' equiparables y a las adquisiciones producidas en vida del causante como consecuencia de contratos y pactos sucesorios acumulables a la sucesión que se cause por el donante o causante a favor del donatario o sucesor «mortis causa», siempre que el plazo que medie entre ésta y aquéllas no exceda de cuatro años.\n3. A estos efectos se entenderá por base liquidable teórica del total de las adquisiciones acumuladas la suma de las bases liquidables de las donaciones y demás transmisiones ''inter vivos'' equiparables anteriores, de las herencias, legados o cualesquier otros títulos sucesorios y la de la adquisición actual.","u":"#a30","c":"CAPITULO IX. Normas especiales"},{"n":"LISD","a":"31","t":"Declaración y liquidación.","x":"1. Los sujetos pasivos vendrán obligados a presentar una declaración tributaria, comprensiva de los hechos imponibles a que se refiere esta ley, en los plazos y en la forma que reglamentariamente se fijen. No obstante lo anterior, podrán optar por presentar una autoliquidación, en cuyo caso deberán practicar las operaciones necesarias para determinar el importe de la deuda tributaria y acompañar el documento o declaración en el que se contenga o se constate el hecho imponible.\n2. Los sujetos pasivos deberán aplicar el régimen de autoliquidación del impuesto con carácter obligatorio en las comunidades autónomas en que así se establezca en esta ley.\nLos sujetos pasivos deberán aplicar el régimen de autoliquidación por los hechos imponibles en los que el rendimiento del impuesto se considere producido en el territorio de dichas comunidades autónomas en virtud de los puntos de conexión aplicables de acuerdo con lo previsto en la Ley 21/2001, de 27 de diciembre, por la que se regulan las medidas fiscales y administrativas del nuevo sistema de financiación de las Comunidades Autónomas de régimen común y Ciudades con Estatuto de Autonomía.","u":"#a31","c":"CAPITULO X. Obligaciones formales"},{"n":"LISD","a":"32","t":"Deberes de las autoridades, funcionarios y particulares.","x":"1. Los órganos judiciales remitirán a los organismos de la Administración tributaria de su respectiva jurisdicción relación mensual de los fallos ejecutoriados o que tengan el carácter de sentencia firme de los que se desprenda la existencia de incrementos de patrimonio gravados por el Impuesto sobre Sucesiones y Donaciones.\n2. Los encargados del Registro Civil remitirán a los mismos organismos, dentro de la primera quincena de cada mes, relación nominal de los fallecidos en el mes anterior y de su domicilio.\n3. Los notarios están obligados a facilitar los datos que les reclamen los organismos de la Administración tributaria acerca de los actos en que hayan intervenido en el ejercicio de sus funciones, y a expedir gratuitamente en el plazo de quince días las copias que aquellos les pidan de los documentos que autoricen o tengan en su protocolo, salvo cuando se trate de los instrumentos públicos a que se refieren los artículos 34 y 35 de la Ley de 28 de mayo de 1862 y los relativos a cuestiones matrimoniales, con excepción de los referentes al régimen económico de la sociedad conyugal.\nAsimismo, estarán obligados a remitir, dentro de la primera quincena de cada trimestre, relación o índice comprensivo de todos los documentos autorizados en el trimestre anterior que se refieran a actos o contratos que pudieran dar lugar a los incrementos patrimoniales que constituyen el hecho imponible del impuesto. También están obligados a remitir, dentro del mismo plazo, relación de los documentos privados con el contenido indicado que les hayan sido presentados para su conocimiento o legitimación de firmas.\n4. Los órganos judiciales, intermediarios financieros, asociaciones, fundaciones, sociedades, funcionarios, particulares y cualesquiera otras entidades públicas o privadas no acordarán entregas de bienes a personas distintas de su titular sin que se acredite previamente el pago del impuesto o su exención, a menos que la Administración lo autorice.\n5. Las entidades de seguros no podrán efectuar la liquidación y pago de los concertados sobre la vida de una persona a menos que se justifique haber presentado a liquidación la documentación correspondiente o, en su caso, el ingreso de la autoliquidación practicada.\n6. Se exceptúan de lo dispuesto en los dos números anteriores los supuestos a los que se refiere el número 1 del artículo 8 de esta Ley, en los términos y con las condiciones allí establecidos.\n7. El incumplimiento de las obligaciones establecidas en los números 1 al 5 anteriores se sancionará de acuerdo con lo dispuesto en el artículo 40 de esta Ley.\nCuando se trate de órganos jurisdiccionales, la autoridad competente del Ministerio de Hacienda pondrá los hechos en conocimiento del Consejo General del Poder Judicial, por conducto del Ministerio Fiscal, a los efectos pertinentes.","u":"#a32","c":"CAPITULO X. Obligaciones formales"},{"n":"LISD","a":"33","t":"Efectos de la falta de presentación.","x":"Los documentos que contengan actos o contratos sujetos al Impuesto sobre Sucesiones y Donaciones no se admitirán ni surtirán efecto en oficinas o registros públicos sin que conste la presentación del documento ante los órganos competentes para su liquidación, salvo lo previsto en la legislación hipotecaria o autorización expresa de la Administración. Los Juzgados y Tribunales remitirán a estos órganos copia autorizada de los documentos que admitan en los que no conste la nota de haber sido presentados a liquidación.","u":"#a33","c":"CAPITULO X. Obligaciones formales"},{"n":"LISD","a":"34","t":"Normas generales.","x":"1. La competencia para la gestión y liquidación del impuesto corresponderá a las Delegaciones y Administraciones de Hacienda o, en su caso, a las oficinas con análogas funciones de las Comunidades Autónomas que tengan cedida la gestión del tributo.\n2. Las Comunidades Autónomas podrán regular los aspectos sobre la gestión y liquidación de este impuesto según lo previsto en la Ley 21/2001, de 27 de diciembre, por la que se regulan las medidas fiscales y administrativas del nuevo sistema de financiación de las Comunidades Autónomas de régimen común y Ciudades con Estatuto de Autonomía. Cuando la Comunidad Autónoma no hubiese regulado dichos aspectos, se aplicarán las normas establecidas en esta Ley.\n3. No obstante lo dispuesto en el apartado anterior, la competencia para establecer como obligatorio el régimen de autoliquidación del Impuesto corresponde al Estado, que introducirá en la Ley del Impuesto las Comunidades Autónomas en las que se haya establecido dicho régimen.\n4. De acuerdo con lo dispuesto en el apartado anterior, se establece el régimen de autoliquidación del impuesto con carácter obligatorio en las siguientes Comunidades Autónomas:\n– Comunidad Autónoma de Andalucía.\n– Comunidad Autónoma de Aragón.\n– Comunidad Autónoma del Principado de Asturias.\n– Comunidad Autónoma de las Illes Balears.\n– Comunidad Autónoma de Canarias.\n– Comunidad Autónoma de Cantabria.\n– Comunidad Autónoma de Castilla-La Mancha.\n– Comunidad de Castilla y León.\n– Comunidad Autónoma de Cataluña.\n– Comunidad Autónoma de Galicia.\n– Comunidad Autónoma de la Región de Murcia.\n– Comunidad Autónoma de La Rioja.\n– Comunidad de Madrid.\n– Comunidad Valenciana.","u":"#a34","c":"CAPITULO XI. Gestión del Impuesto · Sección 1.ª Liquidación"},{"n":"LISD","a":"35","t":"Liquidaciones parciales a cuenta.","x":"1. Los interesados en sucesiones hereditarias podrán solicitar que se practique una liquidación parcial del Impuesto a los solos efectos de cobrar seguros sobre la vida, créditos del causante, haberes devengados y no percibidos por el mismo, retirar bienes, valores, efectos o dinero que se hallaren en depósito y demás supuestos análogos.\n2. Reglamentariamente se regulará la forma y plazos para practicar estas liquidaciones y los requisitos para que los interesados puedan proceder al cobro de las cantidades o a la retirada del dinero o los bienes depositados.\nEn las liquidaciones parciales que se practiquen para el cobro de seguros sobre la vida de cualquier tipo se tendrán en cuenta las reducciones previstas en el artículo 20 de esta Ley, con los requisitos y límites establecidos en el mismo.\n3. Las liquidaciones parciales tendrán el carácter de ingresos a cuenta de la liquidación definitiva que proceda por la sucesión hereditaria de que se trate.","u":"#a35","c":"CAPITULO XI. Gestión del Impuesto · Sección 1.ª Liquidación"},{"n":"LISD","a":"36","t":"Pago del Impuesto.","x":"1. Excepción hecha de los supuestos de autoliquidación, que se regirán por sus normas específicas, el pago de las liquidaciones practicadas por la Administración por el Impuesto sobre Sucesiones y Donaciones deberá realizarse en los plazos señalados en el Reglamento General de Recaudación.\n2. (Anulado)\n3. El pago de la deuda tributaria podrá realizarse mediante entrega de bienes integrantes del Patrimonio Histórico Español que estén inscritos en el Inventario General de Bienes Muebles o en el Registro General de Bienes de Interés Cultural, de acuerdo con lo dispuesto en el artículo 69, 2, de la Ley 16/1985, de 25 de junio, del Patrimonio Histórico Español.","u":"#a36","c":"CAPITULO XI. Gestión del Impuesto · Sección 2.ª Pago del Impuesto"},{"n":"LISD","a":"37","t":"Norma general.","x":"Sin perjuicio de lo dispuesto en los artículos siguientes de esta sección, en el Impuesto sobre Sucesiones y Donaciones serán aplicables las normas sobre aplazamiento y fraccionamiento de pago establecidas en el Reglamento General de Recaudación.","u":"#a37","c":"CAPITULO XI. Gestión del Impuesto · Sección 3.ª Aplazamiento y fraccionamiento de pago"},{"n":"LISD","a":"38","t":"Aplazamiento y fraccionamiento por las oficinas de gestión.","x":"1. Los órganos competentes para la gestión y liquidación del Impuesto podrán acordar el aplazamiento, por término de hasta un año, del pago de las liquidaciones practicadas por causa de muerte, siempre que no exista inventariado efectivo o bienes de fácil realización suficientes para el abono de las cuotas liquidadas y se solicite antes de expirar el plazo reglamentario de pago. La concesión del aplazamiento implicará la obligación de abonar el interés de demora correspondiente.\n2. En los mismos supuestos y condiciones podrán acordar el fraccionamiento de pago, en cinco anualidades como máximo, siempre que se garantice el pago en la forma que reglamentariamente se determine.\n3. Asimismo, podrá acordarse el aplazamiento del pago, en las mismas condiciones a que hacen referencia los números anteriores, hasta que fuesen conocidos los causahabientes en una sucesión.","u":"#a38","c":"CAPITULO XI. Gestión del Impuesto · Sección 3.ª Aplazamiento y fraccionamiento de pago"},{"n":"LISD","a":"39","t":"Supuestos especiales de aplazamiento y fraccionamiento.","x":"1. El pago de las liquidaciones giradas como consecuencia de la transmisión por herencia, legado o donación de una empresa individual que ejerza una actividad industrial, comercial, artesanal, agrícola o profesional o de participaciones en entidades a las que sea de aplicación la exención regulada en el punto dos del apartado octavo del artículo 4 de la Ley 19/1991, de 6 de junio, del Impuesto sobre el Patrimonio, podrá aplazarse, a petición del sujeto pasivo deducida antes de expirar el plazo reglamentario de pago o, en su caso, el de presentación de la autoliquidación, durante los cinco años siguientes al día en que termine el plazo para el pago, con obligación de constituir caución suficiente y sin que proceda el abono de intereses durante el período de aplazamiento.\n2. Terminado el plazo de cinco años podrá, con las mismas condiciones y requisitos, fraccionarse el pago en diez plazos semestrales, con el correspondiente abono del interés legal del dinero durante el tiempo de fraccionamiento.\n3. Lo dispuesto en los números anteriores sobre aplazamiento y fraccionamiento de pago será, asimismo, aplicable a las liquidaciones giradas como consecuencia de la transmisión hereditaria de la vivienda habitual de una persona, siempre que el causahabiente sea cónyuge, ascendiente o descendiente de aquél, o bien pariente colateral mayor de sesenta y cinco años, que hubiese convivido con el causante durante los dos años anteriores al fallecimiento.\n4. En los seguros sobre la vida en los que el causante sea a su vez el contratante o el asegurado en el seguro colectivo y cuyo importe se perciba en forma de renta, se fraccionará a solicitud del beneficiario el pago del impuesto correspondiente en el número de años en los que perciba la pensión, si la renta fuera temporal, o en un número máximo de quince años si fuere vitalicia, mientras no se ejercite el derecho de rescate.\nEl aplazamiento no exigirá la constitución de ningún tipo de caución sin que devengue tampoco ningún tipo de interés.\nPor la extinción de la pensión dejarán de ser exigibles los pagos fraccionados pendientes que, no obstante, lo serán en caso de ejercitarse el derecho de rescate.\nReglamentariamente se determinará el procedimiento para la aplicación de lo dispuesto en este apartado.","u":"#a39","c":"CAPITULO XI. Gestión del Impuesto · Sección 3.ª Aplazamiento y fraccionamiento de pago"},{"n":"LISD","a":"40","t":"Régimen sancionador.","x":"1. Las infracciones tributarias del impuesto regulado en esta ley serán calificadas y sancionadas con arreglo a lo dispuesto en la Ley General Tributaria, sin perjuicio de las especialidades previstas en esta ley.\n2. El incumplimiento de la obligación a que se refiere el apartado 2 del artículo 18 de esta ley se considerará infracción grave y la sanción consistirá en multa pecuniaria fija de 500 euros.\nLa sanción se graduará incrementando la cuantía resultante en un 100 por ciento si se produce la comisión repetida de infracciones tributarias.\nLa sanción impuesta de acuerdo con lo previsto en este apartado se reducirá conforme a lo dispuesto en el apartado 3 del artículo 188 de la Ley General Tributaria.","u":"#a40","c":"CAPITULO XII. Infracciones y sanciones"},{"n":"RISD","a":"1","t":"Naturaleza y objeto.","x":"1. El Impuesto sobre Sucesiones y Donaciones, de naturaleza directa y subjetiva, grava los incrementos de patrimonio obtenidos a título lucrativo por personas físicas en los términos establecidos en la Ley 29/1987, de 18 de diciembre, y en este Reglamento.\n2. La obtención por las personas jurídicas de los incrementos de patrimonio a que se refiere este Impuesto no quedará sujeta al mismo y se someterá al Impuesto sobre Sociedades.","u":"#a1-2","c":"CAPITULO I. Disposiciones generales · Sección primera: naturaleza y objeto"},{"n":"RISD","a":"2","t":"Concepto de incremento de patrimonio.","x":"Es incremento de patrimonio sujeto al Impuesto sobre Sucesiones y Donaciones toda incorporación de bienes y derechos que se produzca en el patrimonio de una persona física cuando tenga su causa en la realización de alguno de los hechos imponibles configurados en la Ley y en este Reglamento como determinantes del nacimiento de la obligación tributaria.","u":"#a2-2","c":"CAPITULO I. Disposiciones generales · Sección primera: naturaleza y objeto"},{"n":"RISD","a":"3","t":"Supuestos de no sujeción.","x":"No están sujetos al Impuesto sobre Sucesiones y Donaciones:\na) Los premios obtenidos en juegos autorizados.\nb) Los demás premios y las indemnizaciones exoneradas del Impuesto sobre la Renta de las Personas Físicas.\nc) Las subvenciones, becas, premios, primas, gratificaciones y auxilios que se concedan por entidades públicas o privadas con fines benéficos, docentes, culturales, deportivos o de acción social.\nd) Las cantidades, prestaciones o utilidades entregadas por corporaciones, asociaciones, fundaciones, sociedades, empresas y demás entidades a sus trabajadores, empleados y asalariados cuando deriven directa o indirectamente de un contrato de trabajo, aunque se satisfagan a través de un seguro concertado por aquéllas.\ne) Las cantidades que en concepto de prestaciones se perciban por los beneficiarios de Planes y Fondos de Pensiones o de sus sistemas alternativos, siempre que esté dispuesto que estas prestaciones se integren en la base imponible del Impuesto sobre la Renta del perceptor.\nf) Las cantidades percibidas por un acreedor, en cuanto beneficiario de un contrato de seguro sobre la vida celebrado con el objeto de garantizar el pago de una deuda anterior, siempre que resulten debidamente probadas estas circunstancias.","u":"#a3-2","c":"CAPITULO I. Disposiciones generales · Sección primera: naturaleza y objeto"},{"n":"RISD","a":"4","t":"Incompatibilidad con el Impuesto sobre la Renta de las Personas Físicas.","x":"En ningún caso un mismo incremento de patrimonio podrá quedar gravado por el Impuesto sobre Sucesiones y Donaciones y por el Impuesto sobre la Renta de las Personas Físicas.","u":"#a4","c":"CAPITULO I. Disposiciones generales · Sección primera: naturaleza y objeto"},{"n":"RISD","a":"5","t":"Ámbito de aplicación territorial.","x":"1. El Impuesto sobre Sucesiones y Donaciones se exigirá en todo el territorio español, si bien su aplicación en los territorios históricos del País Vasco y de la Comunidad Foral de Navarra se realizará de conformidad con lo concertado y convenido, respectivamente, en la Ley 12/1981, de 13 de mayo, y en la Ley 28/1990, de 26 de diciembre.\n2. La aplicación del Impuesto en el territorio español dejará a salvo lo dispuesto en los Tratados y Convenios internacionales suscritos o que se suscriban por España.","u":"#a5","c":"CAPITULO I. Disposiciones generales · Sección segunda: ámbito de aplicación territorial"},{"n":"RISD","a":"6","t":"Cesión del rendimiento del Impuesto.","x":"La cesión del rendimiento del Impuesto a las Comunidades Autónomas se regirá por lo dispuesto en la Ley 30/1983, de 28 de diciembre, y tendrá el alcance y condiciones que para cada una de ellas establezca su específica Ley de Cesión.","u":"#a6","c":"CAPITULO I. Disposiciones generales · Sección segunda: ámbito de aplicación territorial"},{"n":"RISD","a":"7","t":"Principio de calificación.","x":"El Impuesto sobre Sucesiones y Donaciones se exigirá con arreglo a la verdadera naturaleza del acto o contrato que sea causa de la adquisición, cualquiera que sea la forma elegida o la denominación utilizada por los interesados, prescindiendo de los defectos intrínsecos o de forma que puedan afectar a su validez y eficacia, sin perjuicio del derecho a la devolución en los casos que proceda.","u":"#a7","c":"CAPITULO I. Disposiciones generales · Sección tercera: el principio de calificación y la afección del impuesto"},{"n":"RISD","a":"8","t":"Concurrencia de condiciones.","x":"Cuando el acto o contrato que sea causa de un incremento patrimonial sujeto al Impuesto esté sometido al cumplimiento de una condición, su calificación se realizará con arreglo a las prescripciones de la legislación civil. Si se calificare como suspensiva no se liquidará el Impuesto hasta que la condición se cumpla, pudiendo procederse a la inscripción de los bienes en los Registros públicos siempre que se haga constar al margen del asiento practicado el aplazamiento de la liquidación. Si se calificare como resolutoria, se exigirá el Impuesto, desde luego, sin perjuicio de la devolución que proceda en el caso de cumplirse la condición.","u":"#a8","c":"CAPITULO I. Disposiciones generales · Sección tercera: el principio de calificación y la afección del impuesto"},{"n":"RISD","a":"9","t":"Afección de los bienes transmitidos.","x":"1. Los bienes y derechos transmitidos quedarán afectos a la responsabilidad del pago del Impuesto, liquidado o no, que grave su adquisición, cualquiera que sea su poseedor, salvo que éste resulte ser un tercero protegido por la fe pública registral o se justifique la adquisición de los bienes con buena fe y justo título en establecimientos abiertos al público, en el caso de bienes muebles no inscribibles.\n2. Siempre que la definitiva efectividad de un beneficio fiscal dependa del ulterior cumplimiento por el contribuyente de cualquier requisito y en los casos en los que la desmembración del dominio deba dar lugar a una liquidación posterior por su consolidación, la oficina gestora hará constar esta circunstancia en el documento antes de su devolución al presentador y los Registradores de la Propiedad y Mercantiles harán constar, por nota marginal, la afección de los bienes transmitidos al pago de las liquidaciones que procedan para el caso de incumplimiento del requisito al que se subordinaba el beneficio fiscal o para el caso de efectiva consolidación del dominio con arreglo a lo dispuesto en este Reglamento.","u":"#a9","c":"CAPITULO I. Disposiciones generales · Sección tercera: el principio de calificación y la afección del impuesto"},{"n":"RISD","a":"10","t":"Hecho imponible.","x":"1. Constituye el hecho imponible:\na) La adquisición de bienes y derechos por herencia, legado o cualquier otro título sucesorio.\nb) La adquisición de bienes y derechos por donación o por cualquier otro negocio jurídico a título gratuito e ««ínter vivos»».\nc) La percepción de cantidades por los beneficiarios de contratos de seguro sobre la vida, cuando el contratante sea persona distinta del beneficiario.\n2. Las adquisiciones a que se refiere la letra a) del apartado anterior se entenderán realizadas el día del fallecimiento del causante, por lo que para exigir el Impuesto bastará que esté probado el hecho originario de la transmisión, aunque no se hayan formalizado ni presentado a liquidación los documentos, inventarios o particiones.","u":"#a1-3","c":"CAPITULO II. El hecho imponible · Sección primera: delimitación del hecho imponible"},{"n":"RISD","a":"11","t":"Títulos sucesorios.","x":"Entre otros, son títulos, sucesorios a los efectos de este Impuesto, además de la herencia y el legado, los siguientes:\na) La donación «mortis causa».\nb) Los contratos o pactos sucesorios.\nc) Los que atribuyan el derecho a la percepción de las cantidades que, cualquiera que sea su modalidad o denominación, las empresas y entidades en general entreguen a los familiares de miembros o empleados fallecidos, siempre que no esté dispuesto expresamente que estas percepciones deban tributar por la letra c) del artículo 10 o en el Impuesto sobre la Renta de las Personas Físicas.\nd) Los que atribuyan el derecho a la percepción de las cantidades asignadas por los testadores a los albaceas por la realización de sus trabajos como tales, en cuanto excedan de lo establecido por los usos y costumbres o del 10 por 100 del valor comprobado del caudal hereditario.","u":"#a1-4","c":"CAPITULO II. El hecho imponible · Sección primera: delimitación del hecho imponible"},{"n":"RISD","a":"12","t":"Negocios jurídicos gratuitos e «ínter vivos».","x":"Entre otros, tienen la consideración de negocios jurídicos gratuitos e «ínter vivos» a los efectos de este Impuesto, además de la donación, los siguientes:\na) La condonación de deuda, total o parcial, realizada con ánimo de liberalidad.\nb) La renuncia de derechos a favor de persona determinada.\nc) La asunción liberatoria de la deuda de otro sin contraprestación, salvo en el caso previsto en el artículo 37 de este Reglamento.\nd) El desistimiento o el allanamiento en juicio o arbitraje en favor de la otra parte, realizados con ánimo de liberalidad, así como la transacción de la que resulte una renuncia, un desistimiento o un allanamiento realizados con el mismo ánimo.\ne) El contrato de seguro sobre la vida, para caso de sobrevivencia del asegurado y el contrato individual de seguro para caso de fallecimiento del asegurado que sea persona distinta del contratante, cuando en uno y otro caso el beneficiario sea persona distinta del contratante.","u":"#a1-5","c":"CAPITULO II. El hecho imponible · Sección primera: delimitación del hecho imponible"},{"n":"RISD","a":"13","t":"Supuestos de sujeción del seguro de accidentes.","x":"La percepción de cantidades por el beneficiario de un seguro de accidentes estará incluida en el hecho imponible de la letra c) del artículo 10 de este Reglamento cuando tenga su causa en el fallecimiento de la persona asegurada.","u":"#a1-6","c":"CAPITULO II. El hecho imponible · Sección primera: delimitación del hecho imponible"},{"n":"RISD","a":"14","t":"Prestaciones periódicas.","x":"1. La percepción de las cantidades a que se refieren la letra c) del artículo 10, las letras c) y d) del artículo 11 y la letra e) del artículo 12, estará sujeta al Impuesto, tanto si se reciben de una sola vez como si se reciben en forma de prestaciones periódicas, vitalicias o temporales.\n2. La percepción de prestaciones periódicas, vitalicias o temporales se regirá por lo dispuesto en el artículo 47 de este Reglamento sobre el devengo del Impuesto.\n3. En los casos del apartado anterior la Administración podrá acudir para determinar la base imponible al cálculo actuarial del valor actual de la pensión a través del dictamen de sus Peritos.","u":"#a1-7","c":"CAPITULO II. El hecho imponible · Sección primera: delimitación del hecho imponible"},{"n":"RISD","a":"15","t":"Presunciones de hechos imponibles.","x":"1. Se presumirá la existencia de una transmisión lucrativa cuando de los Registros Fiscales o de los datos que obren en la Administración, resultare la disminución del patrimonio de una persona y simultáneamente o con posterioridad, pero siempre dentro del plazo de prescripción de cinco años, el incremento patrimonial correspondiente en el cónyuge, descendientes, herederos o legatarios.\n2. En las adquisiciones a título oneroso realizadas por los ascendientes como representantes de los descendientes menores de edad, se presumirá la existencia de una transmisión lucrativa a favor de éstos por el valor de los bienes o derechos transmitidos, a menos que se pruebe la previa existencia de bienes o medios suficientes del menor para realizarla y su aplicación a este fin.\n3. Las presunciones a que se refieren los números anteriores admitirán, en todo caso, prueba en contrario, que podrá hacerse valer en el procedimiento establecido en el artículo 92 de este Reglamento.","u":"#a1-8","c":"CAPITULO II. El hecho imponible · Sección segunda: presunciones de hechos imponibles"},{"n":"RISD","a":"16","t":"Contribuyentes.","x":"1. Estarán obligados al pago del Impuesto a título de contribuyentes:\na) En las adquisiciones «mortis causa», los causahabientes.\nb) En las donaciones y demás transmisiones lucrativas «ínter vivos», el donatario o el favorecido por ellas, considerándose como tal al beneficiario del seguro de vida para caso de sobrevivencia del asegurado o al beneficiario del seguro individual, en el caso de fallecimiento del asegurado que sea persona distinta del contratante.\nc) En los casos de seguro sobre la vida para caso de muerte del asegurado y en los del artículo 13 de este Reglamento, el beneficiario.\n2. Lo dispuesto en el apartado anterior será aplicable cualquiera que sean las estipulaciones establecidas por las partes o las disposiciones ordenadas por el testador.\n3. La disposición testamentaria por la que se ordene que la entrega de legados sea libre del Impuesto o que el pago de éste sea con cargo a la herencia no producirá variación alguna en cuanto a la persona obligada a satisfacerlo.","u":"#a1-9","c":"CAPITULO III. Sujetos pasivos y responsables · Sección primera: contribuyentes"},{"n":"RISD","a":"17","t":"Obligación personal de contribuir.","x":"1. A los contribuyentes que tengan su residencia habitual en España se les exigirá el Impuesto por obligación personal por la totalidad de los bienes y derechos que adquieran, con independencia de donde se encuentren situados o del domicilio o residencia de la persona o entidad pagadora.\n2. Para la determinación de la residencia habitual se estará a lo dispuesto en las normas del Impuesto sobre la Renta de las Personas Físicas, computándose, en su caso, los días de residencia exigidos con relación a los trescientos sesenta y cinco anteriores al del devengo del Impuesto.\n3. Los representantes y funcionarios del Estado español en el extranjero quedarán sujetos a este Impuesto por obligación personal, atendiendo a idénticas circunstancias y condiciones que las establecidas en las normas del Impuesto sobre la Renta de las Personas Físicas.","u":"#a1-10","c":"CAPITULO III. Sujetos pasivos y responsables · Sección primera: contribuyentes"},{"n":"RISD","a":"18","t":"Obligación real de contribuir.","x":"1. A los contribuyentes no incluidos en el artículo inmediato anterior se les exigirá el Impuesto por obligación real por la adquisición de bienes y derechos, cualquiera que sea su naturaleza, que estuvieran situados, pudieran ejercitarse o hubieran de cumplirse en territorio español, así como por la percepción de cantidades derivadas de contratos de seguro sobre la vida cuando el contrato haya sido celebrado con entidades aseguradoras españolas o se haya celebrado en España con entidades extranjeras que operen en ella, salvo que se abonen a personas no residentes en España por establecimientos permanentes de entidades españolas situados en el extranjero, con cargo a los mismos, cuando dichas prestaciones estén directamente vinculadas a la actividad del establecimiento en el extranjero.\n2. A efectos de lo previsto en el número anterior se consideran situados en territorio español:\n1.º Los bienes inmuebles que en él radiquen.\n2.º Los bienes muebles afectados permanentemente a viviendas, fincas, explotaciones o establecimientos industriales situados en territorio español y, en general, los que habitualmente se encuentren en este territorio aunque en el momento del devengo del Impuesto estén fuera del mismo por circunstancias coyunturales o transitorias.\n3. Los extranjeros residentes en España, sometidos a obligación real de contribuir en el Impuesto sobre la Renta de las Personas Físicas por razón de cargo o empleo, estarán sujetos por idéntico tipo de obligación en el Impuesto sobre Sucesiones y Donaciones.\n4. Los contribuyentes por obligación real que no sean residentes en otro Estado miembro de la Unión Europea estarán obligados a nombrar, antes del fin del plazo de declaración de la adquisición de bienes y derechos en España, una persona física o jurídica con residencia en España para que les represente ante la Administración Tributaria en relación con sus obligaciones por este impuesto.\nEn el caso de Estados que formen parte del Espacio Económico Europeo que no sean Estado miembro de la Unión Europea, lo anterior no será de aplicación cuando exista normativa sobre asistencia mutua en materia de intercambio de información tributaria y de recaudación en los términos previstos en la Ley 58/2003, de 17 de diciembre, General Tributaria.\nIgual obligación incumbirá a los contribuyentes por obligación personal que se ausenten de España tras la realización del hecho imponible con destino a un tercer Estado que no sea Estado miembro de la Unión Europea ni del Espacio Económico Europeo con normativa sobre asistencia mutua en materia de intercambio de información tributaria y de recaudación y antes de haber presentado el documento o la declaración, salvo si su regreso se fuera a producir antes de la finalización del plazo reglamentario de presentación de documentos.\nLa designación se comunicará a la oficina territorialmente competente para la presentación del documento o declaración, acompañando a la comunicación la expresa aceptación del representante.","u":"#a1-11","c":"CAPITULO III. Sujetos pasivos y responsables · Sección primera: contribuyentes"},{"n":"RISD","a":"19","t":"Responsables subsidiarios.","x":"1. Serán subsidiariamente responsables del pago del Impuesto, salvo que resultaren de aplicación las normas sobre responsabilidad solidaria de la Ley General Tributaria:\na) En las transmisiones «mortis causa» de depósitos, garantías, certificados de depósito, cuentas corrientes, de ahorro, o cuentas especiales, los intermediarios financieros y demás entidades o personas que hubieran entregado el dinero y valores depositados o devuelto las garantías constituidas.\nb) En las entregas de cantidades a quienes resulten beneficiarios como herederos o designados en los contratos, las entidades de seguros que las verifiquen.\nc) En la transmisión de títulos valores que formen parte de la herencia, los mediadores.\n2. Será también responsable subsidiario el funcionario que autorizase el cambio de sujeto pasivo de cualquier tributo o exacción estatal, autonómica o local, cuando tal cambio suponga, directa o indirectamente, una adquisición gravada por el Impuesto y no hubiera exigido previamente la justificación del pago del mismo.","u":"#a1-12","c":"CAPITULO III. Sujetos pasivos y responsables · Sección segunda: responsables subsidiarios"},{"n":"RISD","a":"20","t":"Extensión y extinción de la responsabilidad subsidiaria.","x":"1. La responsabilidad subsidiaria a que se refiere el artículo anterior estará limitada a la porción de Impuesto que corresponda a la adquisición de los bienes que la originen, entendiéndose como tal el resultado de aplicar al valor comprobado de los bienes el tipo medio efectivo de gravamen, calculado en la forma prevenida en la letra b) del artículo 46 de este Reglamento.\n2. Cuando estuviese autorizada liquidación o autoliquidación parcial, el importe de la misma, practicada conforme a las normas de este Reglamento, constituirá el límite de la posible responsabilidad subsidiaria, si fuese menor que el que resulte de aplicar lo dispuesto en el número anterior.\n3. El ingreso del importe de la liquidación parcial, o el de la autoliquidación parcial practicada conforme a lo dispuesto en el artículo 89 de este Reglamento, extinguirá la responsabilidad subsidiaria que pudiera derivar para las entidades y personas a que se refiere el artículo anterior del impago del Impuesto correspondiente a la transmisión hereditaria de los bienes de que se trate.","u":"#a2-3","c":"CAPITULO III. Sujetos pasivos y responsables · Sección segunda: responsables subsidiarios"},{"n":"RISD","a":"21","t":"Regímenes de determinación.","x":"La base imponible del Impuesto sobre Sucesiones y Donaciones se determinará por la Administración con carácter general por el régimen de estimación directa teniendo en cuenta, en su caso, los preceptos especiales de la Ley y de este Reglamento.\nCuando no pudiera determinarse por estimación directa, la Administración podrá acudir al régimen de estimación indirecta de bases imponibles, siempre que concurran las condiciones y requisitos exigidos para ello por la Ley General Tributaria.","u":"#a2-4","c":"CAPITULO IV. La base imponible · Sección primera: regímenes de determinación"},{"n":"RISD","a":"22","t":"Principio general.","x":"En las adquisiciones por causa de muerte constituye la base imponible del Impuesto el valor neto de la participación individual de cada causahabiente en el caudal hereditario, entendiéndose como tal el valor real de los bienes y derechos adquiridos minorado por las cargas o gravámenes, deudas y gastos que fueren deducibles.","u":"#a2-5","c":"CAPITULO IV. La base imponible · Sección segunda: normas especiales para adquisiciones «mortis causa»"},{"n":"RISD","a":"23","t":"Determinación del caudal hereditario.","x":"1. A efectos de determinar la participación individual de cada causahabiente se incluirán también en el caudal hereditario del causante los bienes siguientes:\na) Los integrantes del ajuar doméstico, aunque no se hayan declarado por los interesados, valorados conforme a las reglas de este Reglamento, previa deducción del valor de aquellos que, por disposición de la Ley, deben entregarse al cónyuge supérstite.\nb) Los que resulten adicionados por el juego de las presunciones establecidas en los artículos 25 a 28 de este Reglamento, salvo que con arreglo a los mismos deban ser imputados en la base imponible de personas determinadas.\n2. Lo dispuesto en el número anterior no se aplicará para determinar la participación individual de aquellos causahabientes a quienes el testador hubiese atribuido bienes determinados con exclusión de cualesquiera otros del caudal hereditario. En el caso de que les atribuyera bienes determinados y una participación en el resto de la masa hereditaria, se les computará la parte del ajuar y de bienes adicionados que proporcionalmente les corresponda, según su participación en el resto de la masa hereditaria.\n3. En el caso de los legados a que se refiere el artículo 16.3 de este Reglamento, el importe del Impuesto no incrementará la base imponible de la liquidación a girar a cargo del legatario, pero, en ningún caso, será deducible a los efectos de determinar la de los demás causahabientes.","u":"#a2-6","c":"CAPITULO IV. La base imponible · Sección segunda: normas especiales para adquisiciones «mortis causa»"},{"n":"RISD","a":"24","t":"Determinación del valor neto de la participación individual.","x":"1. A efectos de fijar el valor neto de la participación individual de cada causahabiente se deducirá del valor de los bienes o derechos:\na) El de las cargas o gravámenes que pesaren sobre los mismos y que sean deducibles según lo establecido en este Reglamento.\nb) El de las deudas que reúnan las condiciones exigidas para su deducción.\nc) El de aquellos que disfruten de algún beneficio fiscal en su adquisición, en la proporción que para el beneficio se establezca.\nd) El importe de los gastos deducibles, según este Reglamento.\n2. Cuando los bienes afectados por la carga o los que disfruten del beneficio fiscal en su adquisición hayan sido atribuidos por el testador en favor de persona determinada o cuando, por disposición del mismo, el pago de la deuda quede a cargo de uno de los causahabientes, la deducción afectará sólo a la persona o causahabiente de que se trate.","u":"#a2-7","c":"CAPITULO IV. La base imponible · Sección segunda: normas especiales para adquisiciones «mortis causa»"},{"n":"RISD","a":"25","t":"Bienes adicionables por haber pertenecido al causante en el año anterior al fallecimiento.","x":"1. En las adquisiciones por causa de muerte se presumirá que forman parte del caudal hereditario los bienes de todas clases que hubiesen pertenecido al causante de la sucesión hasta un año antes del fallecimiento, salvo prueba fehaciente de que tales bienes fueron transmitidos por aquél y de que se hallan en poder de persona distinta de un heredero, legatario, pariente dentro del tercer grado o cónyuge de cualquiera de ellos o del causante. Esta presunción quedará desvirtuada mediante la justificación suficiente de que, en el caudal, figuran incluidos, con valor equivalente, el dinero u otros bienes subrogados en el lugar de los desaparecidos.\nA los efectos del párrafo anterior se presumirá que los bienes pertenecieron al causante por la circunstancia de que los mismos figurasen a su nombre en depósitos, cuentas corrientes o de ahorro, préstamos con garantía o en otros contratos similares o bien inscritos a su nombre en los amillaramientos, catastros, Registros Fiscales, Registros de la Propiedad u otros de carácter público.\nLa no justificación de la existencia de dinero o de bienes subrogados no obstará al derecho de los interesados para probar la realidad de la transmisión.\n2. La adición realizada al amparo de esta presunción afectará a todos los causahabientes en la misma proporción en que fuesen herederos, salvo que fehacientemente se acredite la transmisión a alguna de las personas indicadas en el número 1, en cuyo caso afectará sólo a ésta que asumirá a efectos fiscales, si ya no la tuviese, la condición de heredero o legatario.","u":"#a2-8","c":"CAPITULO IV. La base imponible · Sección segunda: normas especiales para adquisiciones «mortis causa»"},{"n":"RISD","a":"26","t":"Bienes adicionables por haberlos adquirido en usufructo el causante en los tres años anteriores al fallecimiento.","x":"1. Se presumirá que forman parte del caudal hereditario los bienes y derechos que, durante los tres años anteriores al fallecimiento del causante, hubiesen sido adquiridos por éste a título oneroso en usufructo y en nuda propiedad por un heredero, legatario, pariente dentro del tercer grado o cónyuge de cualquiera de ellos o del causante. Esta presunción quedará desvirtuada mediante la justificación suficiente de que el adquirente de la nuda propiedad satisfizo al transmitente el dinero o le entregó bienes o derechos de valor equivalente, suficientes para su adquisición.\nLa no justificación de la existencia de dinero o de bienes subrogados no obstará al derecho de los interesados para probar la realidad de la transmisión onerosa.\n2. La adición realizada al amparo de esta presunción perjudicará exclusivamente al adquirente de la nuda propiedad al que se le liquidará por la adquisición «mortis causa» del pleno dominio del bien o derecho de que se trate. La práctica de esta liquidación excluirá la que hubiese correspondido por la consolidación del pleno dominio.","u":"#a2-9","c":"CAPITULO IV. La base imponible · Sección segunda: normas especiales para adquisiciones «mortis causa»"},{"n":"RISD","a":"27","t":"Bienes adicionables por haber transmitido el causante su nuda propiedad en los cinco años anteriores al fallecimiento.","x":"1. Se presumirá que forman parte del caudal hereditario los bienes y derechos transmitidos por el causante a título oneroso durante los cinco años anteriores a su fallecimiento, reservándose el usufructo de los mismos o de otros del adquirente, o cualquier otro derecho vitalicio, salvo cuando la transmisión se realice a consecuencia de un contrato de renta vitalicia celebrado con una Entidad dedicada legalmente a este género de operaciones. Esta presunción quedará desvirtuada mediante la justificación suficiente de que en el caudal hereditario figura dinero u otros bienes recibidos en contraprestación de la transmisión de la nuda propiedad por valor equivalente.\nLa no justificación de la existencia de dinero o de bienes subrogados no obstará al derecho de los interesados para probar la realidad de la transmisión.\n2. La adición realizada al amparo de esta presunción perjudicará exclusivamente al adquirente de la nuda propiedad, que será considerado como legatario si fuese persona distinta de un heredero y al que se liquidará por la adquisición «mortis causa» del pleno dominio del bien o derecho de que trate. La práctica de esta liquidación excluirá la que hubiese correspondido por la consolidación del pleno dominio.","u":"#a2-10","c":"CAPITULO IV. La base imponible · Sección segunda: normas especiales para adquisiciones «mortis causa»"},{"n":"RISD","a":"28","t":"Bienes adicionables en supuestos de endoso de valores o efectos.","x":"1. Se presumirá que forman parte del caudal hereditario los valores y efectos depositados cuyos resguardos se hubiesen endosado, si con anterioridad al fallecimiento del endosante no se hubiesen retirado aquéllos o tomado razón del endoso en los libros del depositario, y los valores nominativos que hubiesen sido igualmente objeto de endoso, si la transferencia no se hubiese hecho constar en los libros de la entidad emisora con antelación al fallecimiento del causante. Esta presunción quedará desvirtuada cuando conste de modo suficiente que el precio o equivalencia del valor de los bienes y efectos transmitidos se ha incorporado al patrimonio del vendedor o cedente y figura en el inventario de su herencia, que ha de ser tenido en cuenta para la liquidación del Impuesto, o si se justifica suficientemente que la retirada de valores o efectos o la toma de razón del endoso no ha podido verificarse con anterioridad al fallecimiento del causante por causas independientes de la voluntad de éste y del endosatario, sin perjuicio de que la adición pueda tener lugar al amparo de lo dispuesto en los artículos 25 a 27 anteriores.\n2. La adición realizada en base a este artículo afectará exclusivamente al endosatario de los valores, que será considerado como legatario si no tuviese la condición de heredero.","u":"#a2-11","c":"CAPITULO IV. La base imponible · Sección segunda: normas especiales para adquisiciones «mortis causa»"},{"n":"RISD","a":"29","t":"Exclusión de la adición y deducción del Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados.","x":"No habrá lugar a las adiciones a que se refieren los artículos 25 a 28 anteriores, cuando por la transmisión onerosa de los bienes se hubiese satisfecho por el Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados una cantidad superior a la que resulte de aplicar a su valor comprobado al tiempo de la adquisición el tipo medio efectivo que correspondería en el Impuesto sobre Sucesiones y Donaciones al heredero o legatario afectado por la presunción, si en la liquidación se hubiese incluido dicho valor. El tipo medio efectivo de gravamen se calculará en la forma establecida en la letra b) del artículo 46 de este Reglamento.\nSi la cantidad ingresada por el Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados fuese inferior, habrá lugar a la adición pero el sujeto pasivo tendrá derecho a que se le deduzca de la liquidación practicada por el Impuesto sobre Sucesiones y Donaciones lo satisfecho por aquél.","u":"#a2-12","c":"CAPITULO IV. La base imponible · Sección segunda: normas especiales para adquisiciones «mortis causa»"},{"n":"RISD","a":"30","t":"Presunción sobre la proporción atribuible al causante en bienes en situación de indivisión.","x":"La participación atribuible al causante en bienes que estén integrados en herencias yacentes, comunidades de bienes y demás entidades que, carentes de personalidad jurídica, constituyan una unidad económica o un patrimonio separado, se adicionará al caudal hereditario en la proporción que resulte de las normas que sean aplicables o de los pactos entre los interesados y, si éstos no constasen a la Administración en forma fehaciente, en proporción al número de interesados.","u":"#a3-3","c":"CAPITULO IV. La base imponible · Sección segunda: normas especiales para adquisiciones «mortis causa»"},{"n":"RISD","a":"31","t":"Deducción de cargas y gravámenes.","x":"1. En las adquisiciones por causa de muerte, únicamente serán deducibles las cargas o gravámenes de naturaleza perpetua, temporal o redimible que aparezcan directamente establecidas sobre los bienes y disminuyan realmente su capital y valor, como los censos y las pensiones, sin que merezcan tal consideración las que constituyan obligación personal del adquirente ni las que, como las hipotecas y las prendas, no supongan disminución del valor de lo transmitido, sin perjuicio de que las deudas que garanticen puedan ser deducidas si concurren los requisitos establecidos en el artículo siguiente.\n2. Cuando en los documentos presentados no constase expresamente la duración de las pensiones, cargas o gravámenes deducibles, se considerará ilimitada.\n3. Se entenderá como valor del censo, a efectos de su deducción, el del capital que deba entregarse para su redención según las normas del Código Civil o de las legislaciones forales.\n4. A dichos efectos, el valor de las pensiones se obtendrá capitalizándolas al interés básico del Banco de España, y tomando del capital resultante aquella parte que, según las reglas establecidas para valorar los usufructos, corresponda a la edad del pensionista, si la pensión es vitalicia, o la duración de la pensión si es temporal. En la valoración de las pensiones temporales que no se extingan al fallecimiento del pensionista, no regirá el límite fijado en la de los usufructos. En corrección del valor así obtenido, el interesado podrá solicitar la práctica de la tasación pericial contradictoria.\nAl extinguirse la pensión, el adquirente del bien vendrá obligado a satisfacer el impuesto correspondiente al capital deducido según la tarifa vigente en el momento de la constitución de aquélla.","u":"#a3-4","c":"CAPITULO IV. La base imponible · Sección segunda: normas especiales para adquisiciones «mortis causa»"},{"n":"RISD","a":"32","t":"Deducción de deudas del causante.","x":"1. En las adquisiciones por causa de muerte podrán deducirse, además de las deudas del causante reconocidas en sentencia judicial firme, las demás que dejase contraídas siempre que su existencia se acredite por documento público, o por documento privado que reúna los requisitos del artículo 1.227 del Código Civil, o se justifique de otro modo la existencia de aquéllas, salvo las que lo fueren a favor de los herederos o de los legatarios de parte alícuota y de los cónyuges, ascendientes, descendientes o hermanos de aquéllos aunque renuncien a la herencia.\nLa Administración podrá exigir que se ratifique la existencia de la deuda en documento público por los herederos con la comparecencia del acreedor.\n2. En especial, serán deducibles las cantidades que adeudare el causante por razón de tributos del Estado, de las Comunidades Autónomas, de las Corporaciones Locales, o por deudas de la Seguridad Social, y que se satisfagan por los herederos, albaceas o administradores del caudal hereditario, aunque correspondan a liquidaciones giradas después del fallecimiento.\n3. Para la deducción de las deudas del causante que se pongan de manifiesto después de ingresado el Impuesto sobre Sucesiones y Donaciones, se seguirá el procedimiento establecido en el artículo 94 de este Reglamento.","u":"#a3-5","c":"CAPITULO IV. La base imponible · Sección segunda: normas especiales para adquisiciones «mortis causa»"},{"n":"RISD","a":"33","t":"Deducción de gastos.","x":"1. Serán deducibles del caudal hereditario en las adquisiciones por causa de muerte:\na) Los gastos que, cuando la testamentaria o el abintestato adquieran carácter litigioso, se ocasionen en el litigio en interés común de todos los herederos por la representación legítima de dichas testamentarías o abintestatos, siempre que resulten debidamente probados con testimonio de los autos; y los de arbitraje, en las mismas condiciones, acreditados por testimonio de las actuaciones.\nb) Los gastos de última enfermedad satisfechos por los herederos, en cuanto se justifiquen.\nc) Los gastos de entierro y funeral en cuanto se justifiquen y hasta donde guarden la debida proporción con el caudal hereditario, conforme a los usos y costumbres de cada localidad.\n2. No serán deducibles los gastos que tengan su causa en la administración del caudal relicto.","u":"#a3-6","c":"CAPITULO IV. La base imponible · Sección segunda: normas especiales para adquisiciones «mortis causa»"},{"n":"RISD","a":"34","t":"Valoración del ajuar doméstico.","x":"1. Salvo que los interesados acreditaren fehacientemente su inexistencia, se presumirá que el ajuar doméstico forma parte de la masa hereditaria, por lo que si no estuviese incluido en el inventario de los bienes relictos del causante, lo adicionará de oficio la oficina gestora para determinar la base imponible de los causahabientes a los que deba imputarse con arreglo a las normas de este Reglamento.\n2. El ajuar doméstico se estimará en el valor declarado, siempre que sea superior al que resulte de la aplicación de la regla establecida en el Impuesto sobre el Patrimonio para su valoración. En otro caso, se estimará en el que resulte de esta regla, salvo que el inferior declarado se acredite fehacientemente.\n3. Para el cálculo del ajuar doméstico en función de porcentajes sobre el resto del caudal relicto, no se incluirá en éste el valor de los bienes adicionados en virtud de lo dispuesto en los artículos 25 a 28 de este Reglamento ni, en su caso, el de las donaciones acumuladas, así como tampoco el importe de las cantidades que procedan de seguros sobre la vida contratados por el causante si el seguro es individual o el de los seguros en que figure como asegurado si fuere colectivo.\nEl valor del ajuar doméstico así calculado se minorará en el de los bienes que, por disposición del artículo 1.321 del Código Civil o de disposiciones análogas de Derecho civil foral o especial, deben entregarse al cónyuge sobreviviente, cuyo valor se fijará en el 3 por 100 del valor catastral de la vivienda habitual del matrimonio, salvo que los interesados acrediten fehacientemente uno superior.","u":"#a3-7","c":"CAPITULO IV. La base imponible · Sección segunda: normas especiales para adquisiciones «mortis causa»"},{"n":"RISD","a":"35","t":"Principio general.","x":"En las donaciones y demás transmisiones lucrativas «ínter vivos» equiparables, constituirá la base imponible el valor neto de los bienes y derechos adquiridos, entendiéndose como tal el valor real de los bienes y derechos minorado por las cargas y deudas que fueren deducibles por reunir las condiciones establecidas en los dos artículos siguientes.","u":"#a3-8","c":"CAPITULO IV. La base imponible · Sección tercera: normas especiales para adquisiciones gratuitas «inter vivos»"},{"n":"RISD","a":"36","t":"Deducción de cargas.","x":"1. Para determinar el valor neto de los bienes o derechos adquiridos por donación o por cualquier otro negocio jurídico a título lucrativo e «ínter vivos» equiparable, únicamente serán deducibles las cargas o gravámenes que reúnan los requisitos establecidos en el artículo 31.1 de este Reglamento.\n2. En la deducción de estas cargas serán aplicables las reglas de los apartados 2, 3 y 4 del mismo artículo 31.","u":"#a3-9","c":"CAPITULO IV. La base imponible · Sección tercera: normas especiales para adquisiciones gratuitas «inter vivos»"},{"n":"RISD","a":"37","t":"Deducción de deudas del donante.","x":"1. Del valor de los bienes o derechos donados o adquiridos por otro negocio jurídico lucrativo e «ínter vivos» equiparable, sólo se deducirá el importe de las deudas que estén garantizadas con derecho real que recaiga sobre los mismos bienes o derechos adquiridos, siempre que el adquirente haya asumido fehacientemente la obligación de pagar la deuda garantizada con liberación del primitivo deudor.\n2. No obstante, cuando después de ingresado el importe del Impuesto el adquirente acreditase, fehacientemente, dentro del plazo de cinco años contados desde el día en que hubiese finalizado el plazo reglamentario para la presentación del documento, el pago de la deuda por su cuenta, tendrá derecho a la devolución de la porción de Impuesto que corresponda a la deuda pagada por él, siguiéndose para la devolución el procedimiento establecido en el artículo 95 de este Reglamento. Este plazo no admitirá interrupciones.","u":"#a3-10","c":"CAPITULO IV. La base imponible · Sección tercera: normas especiales para adquisiciones gratuitas «inter vivos»"},{"n":"RISD","a":"39","t":"Principio general.","x":"1. En la percepción de cantidades procedentes de contratos de seguro sobre la vida para caso de muerte del asegurado, constituirá la base imponible el importe de las cantidades percibidas por el beneficiario. Estas cantidades se acumularán al valor de los bienes y derechos que integren la porción hereditaria del beneficiario cuando el causante sea, a su vez, el contratante del seguro individual o el asegurado en el seguro colectivo.\n2. Cuando el seguro se hubiese contratado por cualquiera de los cónyuges con cargo a la sociedad de gananciales y el beneficiario fuese el cónyuge sobreviviente, la base imponible estará constituida por la mitad de la cantidad percibida.","u":"#a3-12","c":"CAPITULO IV. La base imponible · Sección cuarta: normas especiales en materia de seguros"},{"n":"RISD","a":"40","t":"Principios generales.","x":"1. La Administración podrá, en todo caso, comprobar el valor de los bienes y derechos transmitidos por los medios de comprobación establecidos en el artículo 52 de la Ley General Tributaria.\n2. Los interesados están obligados a consignar en sus declaraciones el valor real que atribuyen a cada uno de los bienes y derechos adquiridos. En su defecto, se les concederá un plazo de diez días para que subsanen la omisión. Si no lo hicieren incurrirán en infracción simple que se sancionará con multa de entre 6,01 y 901,52 euros.\n3. El valor declarado por los interesados prevalecerá sobre el comprobado si fuese superior.\n4. Si de la comprobación resultasen valores superiores a los declarados por los interesados, podrán impugnarlos en los plazos de reclamación de las liquidaciones que hayan tenido en cuenta los nuevos valores.\n5. En el caso de transmisiones lucrativas «ínter vivos», el resultado del expediente de comprobación de valores se notificará previamente a los transmitentes, que podrán proceder a su impugnación cuando afecte a sus derechos o intereses. Si la reclamación fuese estimada en todo o en parte, la resolución dictada beneficiará también a los sujetos pasivos del Impuesto sobre Sucesiones y Donaciones.\n6. Si el valor obtenido de la comprobación fuese superior al que resultase de la aplicación de la correspondiente regla del Impuesto sobre el Patrimonio, surtirá efecto en relación con las liquidaciones a practicar por dicho Impuesto por la anualidad corriente y las siguientes, hasta que vuelva a ser superior el valor que resulte de la regla del Impuesto sobre el Patrimonio.\n7. No se aplicará sanción como consecuencia del mayor valor obtenido de la comprobación cuando el sujeto pasivo hubiese declarado como valor de los bienes el que resulte de la aplicación de la regla correspondiente del Impuesto sobre el Patrimonio o uno superior.","u":"#a4-2","c":"CAPITULO IV. La base imponible · Sección quinta: comprobación de valores"},{"n":"RISD","a":"41","t":"Derecho de adquisición por la Administración.","x":"1. La Administración Pública tendrá derecho a adquirir para sí cualquiera de los bienes y derechos que hayan sido transmitidos siempre que su valor comprobado exceda en más del 50 por 100 del declarado y éste sea inferior al que resulte de la aplicación de la regla de valoración del Impuesto sobre el Patrimonio.\n2. El derecho de adquisición por la Administración sólo podrá ejercitarse dentro de los seis meses siguientes a la fecha en que hubiese ganado firmeza la liquidación del Impuesto y requerirá que, antes de la ocupación del bien o derecho de que se trate, se abone al interesado la cantidad que hubiese asignado como valor real al mismo en la declaración que está obligado a presentar.\nCuando la Administración ejercite el derecho de adquisición y el interesado hubiese ingresado el importe de la liquidación correspondiente al Impuesto sobre Sucesiones y Donaciones, se devolverá a aquél la porción de cuota tributaria que corresponda, según lo establecido en el presente Reglamento, con el interés de demora que proceda.","u":"#a4-3","c":"CAPITULO IV. La base imponible · Sección quinta: comprobación de valores"},{"n":"RISD","a":"42","t":"Reducciones generales.","x":"1. En las adquisiciones por causa de muerte, incluidas las de los beneficiarios de contratos de seguro sobre la vida para caso de muerte del contratante, si el seguro es individual o del asegurado, si el seguro es colectivo o está contratado por las empresas en favor de sus empleados, la base liquidable se obtendrá aplicando en la imponible la reducción que corresponda en función del Grupo en el que el causahabiente o beneficiario figure incluido de los que se enumeran a continuación:\nGrupo I. Adquisiciones por descendientes y adoptados menores de veintiún años:\nReducción de 2.271.500 pesetas, más 568.000 pesetas por cada año menos de veintiuno que tenga el causahabiente o beneficiario, sin que la reducción pueda exceder de 6.813.500 pesetas.\nGrupo II. Adquisiciones por descendientes y adoptados de veintiuno o más años, cónyuges, ascendientes y adoptantes:\nReducción de 2.271.500 pesetas.\nGrupo III. Adquisiciones por colaterales de segundo y tercer grado y ascendientes y descendientes por afinidad:\nReducción de 1.136.000 pesetas.\nGrupo IV. Adquisiciones por colaterales de cuarto grado, grados más distantes y extraños:\nNo hay lugar a reducción.\n2. En las adquisiciones por causa de muerte a que se refiere el apartado 1 anterior, cuando el sujeto pasivo resultase ser una persona con minusvalía física, psíquica o sensorial, además de la reducción que pudiera corresponderle por su inclusión en alguno de los Grupos anteriores, se aplicará otra, independientemente del parentesco, de cuantía igual a la máxima establecida por el Grupo I.\nA estos efectos se considerarán personas con minusvalía con derecho a reducción, aquellas que determinan derecho a deducción en el Impuesto sobre la Renta de las Personas Físicas, según la legislación propia de este Impuesto.\n3. Si unos mismos bienes en un período máximo de diez años fueran objeto de dos o más transmisiones «mortis causa» en favor de descendientes o adoptados, en la segunda y ulteriores se deducirá de la base imponible, además de las cantidades que procedan con arreglo a los números anteriores, el importe de lo satisfecho como cuota tributaria por las transmisiones precedentes. Esta reducción será también aplicable en el caso de que los bienes transmitidos por primera vez hayan sido sustituidos por otros del mismo valor que integren el caudal hereditario de la siguiente o ulteriores transmisiones, siempre que esta circunstancia se acredite fehacientemente.\n4. En las adquisiciones por título de donación o por cualquier otro negocio jurídico a título lucrativo e «inter vivos», la base liquidable coincidirá con la imponible.\n5. Con independencia de lo dispuesto en los números anteriores, en las adquisiciones por títulos de herencia, legado o donación de explotaciones familiares agrarias serán de aplicación, con los requisitos y condiciones en cada caso exigidos, los beneficios fiscales establecidos en la Ley 49/1981, de 24 de diciembre, del Estatuto de la Explotación Familiar Agraria y de los Jóvenes Agricultores.","u":"#a4-4","c":"TITULO I. Ordenación del Impuesto · CAPITULO V. La base liquidable"},{"n":"RISD","a":"43","t":"Tarifa.","x":"La cuota íntegra del Impuesto se obtendrá aplicando a la base liquidable, calculada según lo dispuesto en el artículo anterior, la siguiente escala:\n| Base liquidable<br>–<br>Hasta pesetas | Tipo medio<br>–<br>Porcentaje | Cuota íntegra<br>–<br>Pesetas | Resto base liquidable<br>–<br>Pesetas | Tipo marginal<br>–<br>Porcentaje |\n| ------------------------------------- | ----------------------------- | ----------------------------- | ------------------------------------- | -------------------------------- |\n| 0 | 0,00 | 0 | 1.135.575 | 7,65 |\n| 1.135.575 | 7,65 | 86.871 | 1.135.575 | 8,50 |\n| 2.271.150 | 8,08 | 183.395 | 1.135.575 | 9,35 |\n| 3.406.725 | 8,50 | 289.572 | 1.135.575 | 10,20 |\n| 4.542.300 | 8,93 | 405.400 | 1.135.575 | 11,05 |\n| 5.677.875 | 9,35 | 530.881 | 1.135.575 | 11,90 |\n| 6.813.450 | 9,78 | 666.015 | 1.135.575 | 12,75 |\n| 7.949.025 | 10,20 | 810.801 | 1.135.575 | 13,60 |\n| 9.084.600 | 10,63 | 965.239 | 1.135.575 | 14,45 |\n| 10.220.175 | 11,05 | 1.129.329 | 1.135.575 | 15,30 |\n| 11.355.750 | 11,48 | 1.303.072 | 5.677.875 | 16,15 |\n| 17.033.625 | 13,03 | 2.220.049 | 5.677.875 | 18,70 |\n| 22.711.500 | 14,45 | 3.281.812 | 11.355.750 | 21,25 |\n| 34.067.250 | 16,72 | 5.694.909 | 22.711.500 | 25,50 |\n| 56.778.750 | 20,23 | 11.486.341 | 56.778.750 | 29,75 |\n| 113.557.500 | 24,99 | 28.378.019 | Exceso | 34,00 |","u":"#a4-5","c":"TITULO I. Ordenación del Impuesto · CAPITULO VI. El tipo de gravamen"},{"n":"RISD","a":"44","t":"Aplicación de coeficientes.","x":"1. La cuota tributaria del Impuesto será el resultado de multiplicar la cuota íntegra por el coeficiente que corresponda de los que se indican a continuación, establecidos en función del patrimonio preexistente del contribuyente y del Grupo en el que, por su parentesco con el transmitente, figure incluido:\n| Patrimonio preexistente en millones de pesetas | Grupos del artículo 42 | | |\n| ---------------------------------------------- | ---------------------- | ------ | ------ |\n| | I y II | III | IV |\n| De 0 a 57 | 1,0000 | 1,5882 | 2,0000 |\n| De más de 57 a 284 | 1,0500 | 1,6676 | 2,1000 |\n| De más de 284 a 567 | 1,1000 | 1,7471 | 2,2000 |\n| De más de 567 | 1,2000 | 1,9059 | 2,4000 |\n2. Cuando la diferencia entre la cuota tributaria obtenida por aplicación del coeficiente que corresponda y la que resultaría de aplicar a la misma cuota íntegra el coeficiente inmediato inferior, sea mayor que la que exista entre el importe del patrimonio preexistente tenido en cuenta para la liquidación y el importe máximo del tramo de patrimonio preexistente que motivaría la aplicación del citado coeficiente inferior, aquélla se reducirá en el importe del exceso.\n3. En los seguros sobre la vida, para determinar la cuota tributaria del beneficiario, se aplicará el coeficiente que corresponda a su patrimonio preexistente y a su parentesco con el contratante salvo en los seguros colectivos o en los contratados por las Empresas en favor de sus empleados en los que se estará al coeficiente que corresponda al patrimonio preexistente del beneficiario y al grado de parentesco entre éste y el asegurado.\n4. Si no fuese conocido el parentesco de los causahabientes en una sucesión pero sí su número, se aplicará el mayor coeficiente de los establecidos para el Grupo IV, sin perjuicio de la devolución que proceda cuando el parentesco de aquéllos sea conocido.\nSi no fuese conocido el número de herederos se girará liquidación provisional a cargo de la representación del causante, conforme a lo dispuesto en el artículo 75 de este Reglamento.\n5. Cuando el donatario de bienes comunes de la sociedad conyugal, por su parentesco con cada uno de los cónyuges donantes, esté incluido en más de un Grupo de los que figuran en el artículo 42 de este Reglamento, la cuota tributaria se obtendrá sumando las cantidades que resulten de aplicar a la parte de cuota íntegra que corresponda al valor donado por cada cónyuge el respectivo coeficiente multiplicador.","u":"#a4-6","c":"CAPITULO VII. La deuda tributaria · Sección primera: la cuota tributaria"},{"n":"RISD","a":"45","t":"Valoración del patrimonio preexistente.","x":"Para la valoración del patrimonio preexistente del contribuyente se tendrán en cuenta las siguientes reglas:\na) La valoración del patrimonio se realizará aplicando las reglas establecidas en el Impuesto sobre el Patrimonio.\nb) En el caso de adquisiciones por causa de muerte se excluirá el valor de aquellos bienes y derechos por cuya adquisición se haya satisfecho el Impuesto como consecuencia de una donación anterior realizada por el causante.\nc) En el caso de adquisiciones por donación u otro negocio jurídico a título gratuito e «ínter vivos» equiparable, se excluirá el valor de los bienes y derechos recibidos con anterioridad del mismo donante que hubiesen sido objeto de acumulación y por cuya adquisición se hubiese satisfecho el Impuesto.\nd) En el patrimonio preexistente del cónyuge que hereda se incluirá el valor de los bienes que reciba como consecuencia de la disolución de la sociedad conyugal.\ne) En el caso de sujetos pasivos que tributen por obligación real, sólo se computará el patrimonio sujeto con el mismo carácter en el Impuesto sobre el Patrimonio, sin perjuicio de la aplicación, cuando proceda, de lo dispuesto en las letras b) y c) anteriores.\nf) La valoración del patrimonio preexistente deberá realizarse con relación al día del devengo del Impuesto.","u":"#a4-7","c":"CAPITULO VII. La deuda tributaria · Sección primera: la cuota tributaria"},{"n":"RISD","a":"46","t":"Regla general.","x":"De la cuota tributaria que resulte de la aplicación de los dos artículos anteriores, cuando la sujeción al Impuesto se produzca por obligación personal, tendrá el contribuyente derecho a deducir la menor de las dos cantidades siguientes:\na) El importe efectivo de lo satisfecho en el extranjero por razón de un Impuesto similar que afecte al incremento patrimonial sometido a gravamen en España.\nb) El resultado de aplicar el tipo medio efectivo de este Impuesto al incremento patrimonial correspondiente a bienes que radiquen o derechos que puedan ser ejercitados fuera de España, cuando hubieran sido sometidos a gravamen en el extranjero por un Impuesto similar. El tipo medio efectivo será el que resulte de dividir la cuota tributaria por la base liquidable, multiplicando el resultado por 100. El tipo medio se expresará incluyendo hasta dos decimales.","u":"#a4-8","c":"CAPITULO VII. La deuda tributaria · Sección segunda: deducción por doble imposición internacional"},{"n":"RISD","a":"47","t":"Devengo.","x":"1. En las adquisiciones por causa de muerte y en la percepción de cantidades, cualquiera que sea su modalidad, por los beneficiarios de contratos de seguro sobre la vida para caso de muerte del asegurado, el Impuesto se devengará el día del fallecimiento del causante o del asegurado, o cuando adquiera firmeza la declaración de fallecimiento del ausente conforme al artículo 196 del Código Civil.\n2. En las adquisiciones por donación o por otros negocios jurídicos lucrativos e «ínter vivos», el impuesto se devengará el día en que se cause el acto o contrato, entendiéndose por tal, cuando se trate de la adquisición de cantidades por el beneficiario de un seguro sobre la vida para caso de sobrevivencia del contratante o del asegurado, aquel en que la primera o única cantidad a percibir sea exigible por el beneficiario.\n3. Toda adquisición de bienes o derechos, cuya efectividad se halle suspendida por la concurrencia de una condición, un término, un fideicomiso o cualquiera otra limitación, se entenderá siempre realizada el día en que dichas limitaciones desaparezcan, atendiéndose a este momento para determinar el valor de los bienes y los tipos de gravamen.","u":"#a4-9","c":"CAPITULO VIII. Devengo y prescripción · Sección primera: devengo"},{"n":"RISD","a":"48","t":"Prescripción.","x":"1. Prescribirá a los cinco años el derecho de la Administración para determinar la deuda tributaria mediante la oportuna liquidación y la acción para imponer sanciones tributarias.\nEl plazo de prescripción comenzará a contarse, en el primer supuesto, desde el día en que finalice el de presentación del documento, declaración o declaración-liquidación; en el segundo, desde que se cometiere la infracción.\n2. En las adquisiciones que tengan su causa en una donación o en otros negocios jurídicos a título lucrativo e «inter vivos» incorporados a un documento privado, el plazo de prescripción comenzará a contarse a partir del momento en que, conforme al artículo 1.227 del Código Civil, la fecha del documento surta efectos frente a terceros.\n3. La presentación por los sujetos pasivos de los documentos y declaraciones a que se refiere el artículo 64 de este Reglamento interrumpirá el plazo de prescripción del derecho de la Administración, para determinar la deuda tributaria que corresponda a las adquisiciones por herencia, legado o cualquier otro título sucesorio, en relación con todos los bienes y derechos que pertenecieran al causante en el momento del fallecimiento o que, por aplicación de lo dispuesto en los artículos 25 a 28 de este Reglamento, deban adicionarse a su caudal hereditario.","u":"#a4-10","c":"CAPITULO VIII. Devengo y prescripción · Sección segunda: prescripción"},{"n":"RISD","a":"49","t":"Usufructos.","x":"Para la valoración de los derechos de usufructo y nuda propiedad se aplicarán las reglas siguientes:\na) El valor del usufructo temporal se reputará proporcional al valor total de los bienes sobre que recaiga, en razón de un 2 por 100 por cada período de un año, sin exceder del 70 por 100. No se computarán las fracciones de tiempo inferiores al año, si bien el usufructo por tiempo inferior a un año se computará en el 2 por 100 del valor de los bienes.\nb) En los usufructos vitalicios se estimará que el valor es igual al 70 por 100 del valor total de los bienes cuando el usufructuario cuente menos de veinte años, minorándose el porcentaje en la proporción de un 1 por 100 por cada año más, con el límite mínimo del 10 por 100.\nc) El valor de la nuda propiedad se computará por la diferencia entre el valor del usufructo y el valor total de los bienes. En los usufructos vitalicios que, a su vez, sean temporales, la nuda propiedad se valorará aplicando, de las reglas anteriores, aquella que le atribuya menor valor.\nd) Cuando el usufructo se hubiese constituido a favor de una persona jurídica, para determinar el valor de la nuda propiedad atribuida a una persona física, se aplicarán las reglas de la letra a) sin que, en ningún caso, pueda computarse para el usufructo un valor superior al 60 por 100 del total atribuido a los bienes. Este mismo porcentaje se tendrá en cuenta cuando la duración del usufructo sea indeterminada.","u":"#a4-11","c":"CAPITULO IX. Normas especiales · Sección primera: usufructo, uso y habitación"},{"n":"RISD","a":"50","t":"Uso y habitación.","x":"El valor de los derechos reales de uso y habitación será el que resulte de aplicar al 75 por 100 del valor de los bienes sobre los que fueren impuestos las reglas correspondientes a la valoración de los usufructos temporales o vitalicios, según los casos.","u":"#a5-2","c":"CAPITULO IX. Normas especiales · Sección primera: usufructo, uso y habitación"},{"n":"RISD","a":"51","t":"Reglas especiales.","x":"1. Al adquirirse los derechos de usufructo, uso y habitación se girará una liquidación sobre la base del valor de estos derechos, con aplicación, en su caso, de la reducción que corresponda al adquirente según lo dispuesto en el artículo 42 de este Reglamento.\n2. Al adquirente de la nuda propiedad se le girará una liquidación teniendo en cuenta el valor correspondiente a aquélla, minorando, en su caso, por el importe de la reducción a que tenga derecho el nudo propietario por su parentesco con el causante según las reglas del citado artículo 42 y con aplicación del tipo medio efectivo de gravamen correspondiente al valor íntegro de los bienes. A estos efectos, el tipo medio efectivo se calculará dividiendo la cuota tributaria correspondiente a una base liquidable teórica, para cuya determinación se haya tomado en cuenta el valor íntegro de los bienes, por esta misma base y multiplicando el cociente por 100, expresando el resultado con inclusión de hasta dos decimales.\nSin perjuicio de la liquidación anterior, al extinguirse el usufructo el primer nudo propietario viene obligado a pagar por este concepto sobre la base del valor atribuido al mismo en su constitución, minorado, en su caso, en el resto de la reducción a que se refiere el artículo 42 de este Reglamento cuando la misma no se hubiese agotado en la liquidación practicada por la adquisición de la nuda propiedad, y con aplicación del mismo tipo medio efectivo de gravamen a que se refiere el párrafo anterior.\n3. En el supuesto de que el nudo propietario transmitiese su derecho, con independencia de la liquidación que se gire al adquirente sobre la base del valor que en ese momento tenga la nuda propiedad y por el tipo de gravamen que corresponda al título de adquisición, al consolidarse el pleno dominio en la persona del nuevo nudo propietario, se girará liquidación sobre el porcentaje del valor total de los bienes por el que no se le liquidó, aplicando la escala de gravamen correspondiente al título por el que se desmembró el dominio.\n4. Si la consolidación del dominio en la persona del primero o sucesivos nudo propietarios se produjese por una causa distinta al cumplimiento del plazo previsto o a la muerte del usufructuario, el adquirente sólo pagará la mayor de las liquidaciones entre la que se encuentre pendiente por la desmembración del dominio y la correspondiente al negocio jurídico en cuya virtud se extingue el usufructo.\nSi la consolidación se opera en el usufructuario, pagará éste la liquidación correspondiente al negocio jurídico en cuya virtud adquiere la nuda propiedad.\nSi se operase en un tercero, adquirente simultáneo de los derechos de usufructo y nuda propiedad, se girará únicamente las liquidaciones correspondientes a tales adquisiciones.\n5. En los usufructos sucesivos el valor de la nuda propiedad se calculará teniendo en cuenta el usufructo de mayor porcentaje y a la extinción de este usufructo pagará el nudo propietario por el aumento de valor que la nuda propiedad experimente y así sucesivamente al extinguirse los demás usufructos. La misma norma se aplicará al usufructo constituido en favor de los dos cónyuges simultáneamente, pero sólo se practicará liquidación por consolidación del dominio cuando fallezca el último.\n6. La renuncia de un usufructo ya aceptado, aunque sea pura y simple, se considerará a efectos fiscales como donación del usufructuario al nudo propietario.\n7. Si el usufructo se constituye con condición resolutoria distinta de la vida del usufructuario se liquidará por las reglas establecidas para los usufructos vitalicios, a reserva de que, cumplida la condición, se practique nueva liquidación, conforme a las reglas establecidas para el usufructo temporal, y se hagan las rectificaciones que procedan en beneficio del Tesoro o del interesado.\n8. Al extinguirse los derechos de uso y habitación se exigirá el Impuesto al usufructuario, si lo hubiere, en razón al aumento del valor del usufructo, y si dicho usufructo no existiese se practicará al nudo propietario la liquidación correspondiente a la extinción de los mismos derechos. Si el usufructo se extinguiese antes de los derechos de uso y habitación, el nudo propietario pagará la correspondiente liquidación por la consolidación parcial operada por la extinción de dicho derecho de usufructo en cuanto al aumento que a virtud de la misma experimente el valor de la nuda propiedad.","u":"#a5-3","c":"CAPITULO IX. Normas especiales · Sección primera: usufructo, uso y habitación"},{"n":"RISD","a":"52","t":"Instituciones equiparables al derecho de usufructo o de uso.","x":"1. Siempre que como consecuencia de las disposiciones del causante o de la aplicación de las normas civiles reguladoras de la sucesión, se atribuya a una persona el derecho a disfrutar en todo o en parte de los bienes de una herencia, temporal o vitaliciamente, se entenderá a efectos fiscales la existencia de un derecho de usufructo o de uso, valorándose el respectivo derecho, cualquiera que sea su nombre, conforme a las reglas establecidas para los usufructos o derechos de uso temporales o vitalicios.\nNo obstante, si el adquirente tuviese el derecho a disponer de los bienes se le liquidará el Impuesto por el pleno dominio, sin perjuicio de la devolución que proceda de la porción de Impuesto que corresponda a la nuda propiedad si se justificara la transmisión de los mismos bienes a la persona indicada por el testador o por la normativa aplicable.\n2. Lo dispuesto en el número anterior no será aplicable a aquellas instituciones para las que este Reglamento establezca un régimen peculiar.","u":"#a5-4","c":"CAPITULO IX. Normas especiales · Sección primera: usufructo, uso y habitación"},{"n":"RISD","a":"53","t":"Sustituciones.","x":"1. En la sustitución vulgar se entenderá que el sustituto hereda al causante y, en consecuencia, se le exigirá el Impuesto cuando el heredero instituido falleciera antes o no pudiera o quisiera aceptar la herencia, teniendo en cuenta su patrimonio preexistente y atendiendo a su parentesco con el causante.\n2. En las sustituciones pupilar y ejemplar se entenderá que el sustituto hereda al sustituido y se le girará el Impuesto, cuando se realice aquélla, atendiendo al grado de parentesco con el descendiente sustituido y sin perjuicio de lo satisfecho por éste al fallecimiento del testador.\n3. En las sustituciones fideicomisarias se exigirá el Impuesto en la institución y en cada sustitución teniendo en cuenta el patrimonio preexistente del instituido o del sustituto y el grado de parentesco de cada uno con el causante, reputándose al fiduciario y a los fideicomisarios, con excepción del último, como meros usufructuarios, salvo que pudiesen disponer de los bienes por actos «ínter vivos» o «mortis causa», en cuyo caso se liquidará por el pleno dominio, haciéndose aplicación de lo dispuesto en el artículo 47.3 de este Reglamento.","u":"#a5-5","c":"CAPITULO IX. Normas especiales · Sección segunda: sustituciones"},{"n":"RISD","a":"54","t":"Fideicomisos.","x":"1. En los fideicomisos, cuando dentro de los plazos en que deba practicarse la liquidación no sea conocido el heredero fideicomisario, pagará el fiduciario el resultado de aplicar a la cuota íntegra el coeficiente más alto de los señalados en el artículo 44 para el Grupo IV, salvo que el fideicomisario tuviese que ser designado de entre un grupo determinado de personas, en cuyo caso el coeficiente máximo a aplicar por razón de parentesco será el correspondiente a la persona del Grupo de parentesco más lejano con el causante.\n2. Lo pagado con arreglo al número anterior aprovechará al fideicomisario cuando sea conocido. Si el coeficiente que le correspondiese fuese inferior al aplicado al fiduciario, quien hubiese hecho el pago superior o sus causahabientes tendrán derecho a la devolución del exceso satisfecho, con arreglo a lo dispuesto en el artículo 75.\n3. Si dentro de los plazos para practicar la liquidación se conociese el fideicomisario, éste satisfará el Impuesto con arreglo al coeficiente que corresponda a su patrimonio preexistente y a su parentesco con el causante.\n4. Si el fiduciario o persona encargada por el testador de transmitir la herencia pudiera disfrutar en todo o en parte, temporal o vitaliciamente, o tuviera la facultad de disponer de los productos o rentas de los bienes hasta su entrega al heredero fideicomisario, pagará el Impuesto en concepto de usufructuario con arreglo a su patrimonio preexistente y parentesco con el causante. En este caso, el fideicomisario satisfará también al entrar en posesión de los bienes el Impuesto correspondiente, no computándose en su favor lo pagado por el fiduciario.\n5. En los fideicomisos en que se dejen en propiedad los bienes hereditarios al heredero fiduciario, aun cuando sea con la obligación de levantar alguna carga, se liquidará el Impuesto a cargo de éste por la adquisición de la propiedad, con deducción de la carga, si fuera deducible, por la cual satisfará el Impuesto el que adquiera el beneficio consiguiente al gravamen, por el título que corresponda, si fuere conocido; y si no lo fuera pagará el heredero, pudiendo repercutir el Impuesto satisfecho por la carga al beneficiario cuando fuere conocido.\n6. El heredamiento de confianza autorizado por la legislación foral se considerará como fideicomiso a efectos del Impuesto.\n7. En los fideicomisos que admite el derecho foral de Cataluña, cuando el fideicomisario se determine por la existencia de descendientes del fiduciario o por otro supuesto de los que permite dicha legislación, se liquidará el Impuesto al fiduciario como heredero pleno propietario. En este caso, cuando tenga lugar la transmisión de los bienes al fideicomisario, éste satisfará el Impuesto correspondiente a la plena propiedad de aquéllos, con arreglo a su patrimonio preexistente y parentesco con el causante de quien provenga la institución de fideicomiso, pudiendo los derechohabientes del fiduciario solicitar la devolución del Impuesto satisfecho por su causante en la parte correspondiente a la nuda propiedad de los bienes si justifican que los mismos bienes se transmiten íntegramente al fideicomisario determinado, o en la parte que corresponda a los bienes transmitidos o restituidos si no se transmitiesen todos.\n8. (Anulado)","u":"#a5-6","c":"CAPITULO IX. Normas especiales · Sección tercera: fideicomisos"},{"n":"RISD","a":"55","t":"Reservas.","x":"1. En la herencia reservable con arreglo al artículo 811 del Código Civil satisfará el Impuesto el reservista en concepto de usufructuario; pero si por fallecimiento de todos los parientes a cuyo favor se halle establecida la reserva, o por renuncia, se extinguiera ésta, vendrá obligado el reservista a satisfacer el Impuesto correspondiente a la nuda propiedad, con aplicación, en tal caso, de lo prevenido en los artículos 47.3 y 58 de este Reglamento.\n2. En la reserva ordinaria a que se refieren los artículos 968, 969, 979 y 980 del Código Civil, se liquidará el Impuesto al reservista por el pleno dominio, sin perjuicio del derecho a la devolución de lo satisfecho por la nuda propiedad de los bienes a que afecte, cuando se acredite la transmisión de los mismos bienes o sus subrogados al reservatorio.\n3. En ambos casos, el reservatario satisfará el Impuesto teniendo en cuenta lo prevenido en el artículo 47.3 y atendido a su grado de parentesco con la persona de quien procedan los bienes, prescindiendo del que le una con el reservista, aunque éste haya hecho uso de la facultad de mejorar, reconocida en el artículo 972 del Código Civil.\n4. Lo dispuesto en los números anteriores será, en todo caso, de aplicación a las reservas reguladas en los artículos 139 de la Compilación de Aragón, 274 de la de Cataluña, 269 de la de Navarra y 36 y 38 de la de Vizcaya.","u":"#a5-7","c":"CAPITULO IX. Normas especiales · Sección cuarta: reservas"},{"n":"RISD","a":"56","t":"Principio de igualdad en la partición y excesos de adjudicación.","x":"1. En las adquisiciones por causa de muerte, cualquiera que sean las particiones y adjudicaciones que los interesados hagan, se considerará a los efectos del Impuesto como si se hubiesen hecho con estricta igualdad y con arreglo a las normas reguladoras de la sucesión, estén o no los bienes sujetos al pago del Impuesto por la condición del territorio o por cualquier otra causa y, en consecuencia, los aumentos que en la comprobación de valores resulten se prorratearán entre los distintos adquirentes o herederos.\n2. Si los bienes en cuya comprobación resultare aumento de valores o a los que deba aplicarse la exención o no sujeción fuesen atribuidos específicamente por el testador a persona determinada o adjudicados en concepto distinto del de herencia, los aumentos o disminuciones afectarán sólo al que adquiera dichos bienes.\n3. Se liquidarán excesos de adjudicación, según las normas establecidas en el Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados, cuando existan diferencias, según el valor declarado, en las adjudicaciones efectuadas a los herederos y legatarios, en relación con el título hereditario.\n4. También se liquidarán, según las mismas normas, los excesos de adjudicación que resulten cuando el valor comprobado de lo adjudicado a uno de los herederos o legatarios exceda en más del 50 por 100 del valor que le correspondería en virtud de su título, salvo en el supuesto de que los valores declarados, para cada uno de los bienes inventariados, sean iguales o superiores a los que resultarían de la aplicación de las reglas del Impuesto sobre el Patrimonio. Se entenderá a estos efectos, como valor correspondiente a cada heredero o legatario el que resulte después del prorrateo entre los mismos de los aumentos de valor obtenidos de la comprobación a que se refiere el apartado 1 anterior.","u":"#a5-8","c":"CAPITULO IX. Normas especiales · Sección quinta: partición y excesos de adjudicación"},{"n":"RISD","a":"57","t":"Pago de la legítima viudal con entrega de bienes en pleno dominio.","x":"Cuando en virtud de lo dispuesto en los artículos 839 y 840 del Código Civil se hiciese pago al cónyuge sobreviviente de su haber legitimario en forma o concepto distinto del usufructo, se girará una liquidación sobre la cantidad coincidente del valor comprobado de los bienes o derechos adjudicados y el asignado al usufructo, según las reglas del artículo 49, sin que haya lugar, en consecuencia, a practicar liquidación alguna por la nuda propiedad a los herederos ni, en su día, por extinción del usufructo. Pero cuando el valor de lo adjudicado en forma distinta del usufructo fuese menor o mayor de lo que correspondería al cónyuge viudo, el exceso o diferencia se liquidará como exceso de adjudicación a cargo del heredero o herederos favorecidos en el primer caso, o del cónyuge viudo en el segundo.","u":"#a5-9","c":"CAPITULO IX. Normas especiales · Sección quinta: partición y excesos de adjudicación"},{"n":"RISD","a":"58","t":"Repudiación y renuncia.","x":"1. En la repudiación o renuncia pura, simple y gratuita de la herencia o legado, los beneficiarios de la misma tributarán por la adquisición de la parte repudiada o renunciada aplicando siempre el coeficiente que corresponda a la cuantía de su patrimonio preexistente. En cuanto al parentesco con el causante, se tendrá en cuenta el del renunciante o el del que repudia cuando tenga señalado un coeficiente superior al que correspondería al beneficiario.\nSi el beneficiario de la renuncia recibiese directamente otros bienes del causante, sólo se aplicará lo dispuesto en el párrafo anterior cuando la suma de las liquidaciones practicadas por la adquisición separada de ambos grupos de bienes fuese superior a la girada sobre el valor de todos, con aplicación a la cuota íntegra obtenida del coeficiente que corresponda al parentesco del beneficiario con el causante.\n2. En los demás casos de renuncia en favor de persona determinada, se exigirá el Impuesto al renunciante, sin perjuicio de lo que deba liquidarse, además, por la cesión o donación de la parte renunciada.\n3. La repudiación o renuncia hecha después de prescrito el Impuesto correspondiente a la herencia o legado se reputará a efectos fiscales como donación.\n4. Para que la renuncia del cónyuge sobreviviente a los efectos y consecuencias de la sociedad de gananciales produzca el efecto de que los bienes renunciados pasen a formar parte, a los efectos de la liquidación del Impuesto, del caudal relicto del fallecido será necesario que la renuncia, además de reunir los requisitos del apartado 1, se haya realizado por escritura pública con anterioridad al fallecimiento del causante. No concurriendo estas condiciones se girará liquidación por el concepto de donación del renunciante a favor de los que resulten beneficiados por la renuncia.","u":"#a5-10","c":"CAPITULO IX. Normas especiales · Sección sexta: repudiación y renuncia"},{"n":"RISD","a":"59","t":"Donaciones onerosas y remuneratorias.","x":"1. Las donaciones con causa onerosa y las remuneratorias tributarán por tal concepto y por su total importe. Si existieran recíprocas prestaciones o se impusiere algún gravamen al donatario, tributarán por el mismo concepto solamente por la diferencia, sin perjuicio de la tributación que pudiera proceder por las prestaciones concurrentes o por el establecimiento de los gravámenes.\n2. Las cesiones de bienes a cambio de pensiones vitalicias o temporales, tributarán como donación por la parte en que el valor de los bienes exceda al de la pensión, calculados ambos en la forma establecida en el Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados.","u":"#a5-11","c":"CAPITULO IX. Normas especiales · Sección séptima: casos especiales de donación"},{"n":"RISD","a":"60","t":"Acumulación de donaciones entre sí.","x":"1. Las donaciones que se otorguen por un mismo donante a un mismo donatario dentro del plazo de tres años, a contar desde la fecha de cada una, se considerarán como una sola transmisión a los efectos de la liquidación del Impuesto, por lo que la cuota tributaria se obtendrá en función de la suma de todas las bases imponibles. Las cuotas satisfechas con anterioridad por las donaciones acumuladas serán deducibles de la liquidación que se practique como consecuencia de la acumulación.\n2. A los efectos del apartado anterior, la acumulación se practicará sumando el valor de los bienes o derechos donados en los tres años anteriores a la fecha de la donación actual.\n3. El importe a deducir por las cuotas satisfechas por las donaciones acumuladas se obtendrá aplicando al valor comprobado en su día para los bienes y derechos donados el tipo medio efectivo de gravamen que corresponda a la liquidación practicada a consecuencia de la acumulación. El tipo medio efectivo de gravamen se calculará según lo dispuesto en el artículo 46, letra b), de este Reglamento.\nLa deducción prevista en el párrafo anterior sólo procederá cuando por la donación o donaciones anteriores que se acumulan se hubiese satisfecho el Impuesto sobre Sucesiones y Donaciones.\n4. Si la donación o donaciones anteriores se hubieren realizado por ambos cónyuges de bienes comunes de la sociedad conyugal y la nueva la realizase uno solo de ellos de sus bienes privativos, la acumulación afectará sólo a la parte proporcional del valor de la donación anterior imputable al cónyuge nuevamente donante.\n5. Las donaciones acumuladas se computarán por el valor comprobado en su día para las mismas, aunque hubiese variado en el momento de la acumulación.","u":"#a6-2","c":"CAPITULO IX. Normas especiales · Sección octava: acumulación de donaciones"},{"n":"RISD","a":"61","t":"Acumulación de donaciones a la herencia del donante.","x":"1. En la sucesión que se cause por el donante a favor del donatario serán acumulables a la base imponible de la sucesión la de las donaciones realizadas en los cinco años anteriores al fallecimiento, considerándose a efectos de determinar la cuota tributaria como una sola adquisición. De la liquidación practicada por la sucesión será deducible, en su caso, el importe de lo ingresado por las donaciones acumuladas, procediéndose a la devolución de todo o parte de lo ingresado por éstas cuando la suma de sus importes sea superior al de la liquidación que se practique por la sucesión y las donaciones acumuladas.\n2. A los efectos del apartado anterior, la acumulación se efectuará sumando el valor de los bienes o derechos donados en los cinco años anteriores al día del devengo del Impuesto correspondiente a la sucesión.\n3. El importe a deducir por las cuotas satisfechas con anterioridad por las donaciones acumuladas se obtendrá aplicando al valor comprobado en su día para los bienes y derechos el tipo medio efectivo de gravamen que, calculado como dispone el artículo 46, letra b), de este Reglamento, corresponda a la sucesión. La deducción prevista en el párrafo anterior sólo procederá cuando por la donación o donaciones anteriores que se acumulan se hubiese satisfecho el Impuesto sobre Sucesiones y Donaciones.\n4. Si la donación o donaciones anteriores se hubieren realizado por ambos cónyuges de bienes comunes de la sociedad conyugal la acumulación afectará sólo a la parte proporcional de su valor imputable al causante.\n5. Las donaciones acumuladas se computarán por el valor comprobado en su día para las mismas, aunque hubiese variado en el momento de la acumulación.","u":"#a6-3","c":"CAPITULO IX. Normas especiales · Sección octava: acumulación de donaciones"},{"n":"RISD","a":"62","t":"Principio general.","x":"Las infracciones tributarias del Impuesto sobre Sucesiones y Donaciones serán calificadas y sancionadas con arreglo a lo dispuesto en la Ley General Tributaria.","u":"#a6-4","c":"TITULO I. Ordenación del Impuesto · CAPITULO X. Infracciones y sanciones"},{"n":"RISD","a":"63","t":"Competencia funcional.","x":"La titularidad de la competencia para la gestión y liquidación del Impuesto corresponderá a las Delegaciones y Administraciones de Hacienda o, en su caso, a las oficinas con análogas funciones de las Comunidades Autónomas que tengan cedida la gestión del tributo.","u":"#a6-5","c":"TITULO II. Gestión del Impuesto · CAPITULO I. Normas generales"},{"n":"RISD","a":"64","t":"Presentación de documentos y declaraciones.","x":"Los sujetos pasivos deberán presentar ante los órganos competentes de la Administración tributaria los documentos a los que se hayan incorporado los actos o contratos sujetos o, a falta de incorporación, una declaración escrita sustitutiva en la que consten las circunstancias relevantes para la liquidación, para que por aquéllos se proceda a su examen, calificación, comprobación y a la práctica de las liquidaciones que procedan, en los términos y en los plazos que se señalan en los artículos siguientes.\nLos sujetos pasivos podrán optar por presentar una declaración-liquidación, en cuyo caso deberán practicar las operaciones necesarias para determinar el importe de la deuda tributaria y acompañar el documento o declaración en el que se contenga o se constate el hecho imponible.","u":"#a6-6","c":"TITULO II. Gestión del Impuesto · CAPITULO I. Normas generales"},{"n":"RISD","a":"65","t":"Carácter del presentador del documento.","x":"1. El presentador del documento o de la declaración tributaria, para su liquidación por la Administración o para acompañar a la autoliquidación practicada por el sujeto pasivo, tendrá, por el solo hecho de la presentación, el carácter de mandatario de los obligados al pago del Impuesto y, por consiguiente, todas las notificaciones que se le hagan, así como las diligencias que suscriba, tendrán el mismo valor y producirán iguales efectos que si se hubieran entendido con los mismos interesados.\n2. En el caso de que el presentador no hubiese recibido el encargo de todos los interesados en el documento o declaración deberá hacerlo constar expresamente designando a sus mandantes.\nEn estos casos, el efecto de las notificaciones que se hagan al presentador o de las diligencias que éste suscriba, se limitarán a las personas a las que manifieste expresamente representar.\n3. En los casos del apartado anterior sólo se liquidarán los derechos que hayan de satisfacer los mandantes del presentador que deberá acompañar una copia simple literal del documento presentado que, previo cotejo, se conservará en la oficina que, una vez transcurridos los plazos de presentación, requerirá a los demás interesados para la presentación por su parte del documento o declaración en el plazo de los diez días siguientes. Presentado el documento o, en otro caso, de oficio, la oficina girará las liquidaciones que procedan a cargo de los demás interesados con imposición de las sanciones que sean aplicables.","u":"#a6-7","c":"TITULO II. Gestión del Impuesto · CAPITULO I. Normas generales"},{"n":"RISD","a":"66","t":"Contenido del documento y documentación complementaria.","x":"1. Los sujetos pasivos presentarán los documentos, acompañados de copia simple, a la Administración tributaria para la práctica de las liquidaciones que procedan en los plazos y en las oficinas competentes, con arreglo a las normas de este Reglamento.\n2. El documento, que tendrá la consideración de declaración tributaria, deberá contener, además de los datos identificativos de transmitente y adquirente y de la designación de un domicilio para la práctica de las notificaciones que procedan, una relación detallada de los bienes y derechos adquiridos que integren el incremento de patrimonio gravado, con expresión del valor real que atribuyen a cada uno, así como de las cargas, deudas y gastos cuya deducción se solicite. Tratándose de bienes inmuebles, se consignará su referencia catastral.\n3. En el caso de no existir documento, se presentará una declaración, extendida en papel común, en la que se harán constar todos los datos indicados en el número anterior.\n4. Cuando se trate de adquisiciones por causa de muerte, junto con el documento o declaración que en la relación de bienes deberá incluir, en su caso, los gananciales del matrimonio, se presentarán:\na) Certificaciones de defunción del causante y del Registro General de Actos de Última Voluntad.\nb) Copia autorizada de las disposiciones testamentarias si las hubiere y, en su defecto, testimonio de la declaración de herederos. En el caso de sucesión intestada, si no estuviere hecha la declaración judicial de herederos, se presentará una relación de los presuntos con expresión de su parentesco con el causante.\nc) Un ejemplar de los contratos de seguro concertados por el causante o certificación expedida por la Entidad aseguradora en el caso del seguro colectivo, aun cuando hubieran sido objeto, con anterioridad, de liquidación parcial.\nd) Justificación documental de las cargas, gravámenes, deudas y gastos cuya deducción se solicite, de la edad de los causahabientes menores de veintiún años, así como, en su caso, de los saldos de cuentas en entidades financieras, del valor teórico de las participaciones en el capital de entidades jurídicas cuyos títulos no coticen en Bolsa y del título de adquisición por el causante de los bienes inmuebles incluidos en la sucesión.\n5. Los sujetos pasivos acompañarán una relación de su patrimonio preexistente en la fecha del devengo del Impuesto, valorado con arreglo a las normas del Impuesto sobre el Patrimonio. Esta declaración podrá sustituirse por una copia de la correspondiente a dicho Impuesto por el ejercicio anterior al fallecimiento si éste hubiese tenido lugar una vez finalizado el plazo establecido para su presentación o, en otro caso, por la del inmediato anterior, haciendo, en ambos casos, indicación de las modificaciones que en la misma procedan para adaptarla a la situación patrimonial vigente en el momento del devengo del Impuesto sobre Sucesiones y Donaciones.\nCuando el patrimonio preexistente del sujeto pasivo esté comprendido en el primero o en el último tramo de los establecidos en el artículo 44.1 de este Reglamento, bastará con que figure su manifestación haciéndolo constar así.","u":"#a6-8","c":"CAPITULO II. Régimen de presentación de documentos · Sección primera: documentos a presentar"},{"n":"RISD","a":"67","t":"Plazos de presentación.","x":"1. Los documentos o declaraciones se presentarán en los siguientes plazos:\na) Cuando se trate de adquisiciones por causa de muerte, incluidas las de los beneficiarios de contratos de seguro de vida, en el de seis meses, contados desde el día del fallecimiento del causante o desde aquel en que adquiera firmeza la declaración de fallecimiento. El mismo plazo será aplicable a las adquisiciones del usufructo pendientes del fallecimiento del usufructuario, aunque la desmembración del dominio se hubiese realizado por acto «inter vivos».\nb) En los demás supuestos, en el de treinta días hábiles, a contar desde el siguiente a aquel en que se cause el acto o contrato.","u":"#a6-9","c":"CAPITULO II. Régimen de presentación de documentos · Sección segunda: plazos de presentación, prórroga y suspensión"},{"n":"RISD","a":"68","t":"Prórroga de los plazos de presentación.","x":"1. La oficina competente para la recepción de los documentos o declaraciones podrá otorgar prórroga para la presentación de los documentos o declaraciones relativos a adquisiciones por causa de muerte por un plazo igual al señalado para su presentación.\n2. La solicitud de prórroga se presentará por los herederos, albaceas o administradores del caudal relicto dentro de los cinco primeros meses del plazo de presentación, acompañada de certificación del acta de defunción del causante, y haciendo constar en ella el nombre y domicilio de los herederos declarados o presuntos y su grado de parentesco con el causante cuando fueren conocidos, la situación y el valor aproximado de los bienes y derechos y los motivos en que se fundamenta la solicitud.\n3. Transcurrido un mes desde la presentación de la solicitud sin que se hubiese notificado acuerdo, se entenderá concedida la prórroga.\n4. No se concederá prórroga cuando la solicitud se presente después de transcurridos los cinco primeros meses del plazo de presentación.\n5. En caso de denegación de la prórroga solicitada, el plazo de presentación se entenderá ampliado en los días transcurridos desde el siguiente al de la presentación de la solicitud hasta el de notificación del acuerdo denegatorio. Si como consecuencia de esta ampliación, la presentación tuviera lugar después de transcurridos seis meses desde el devengo del Impuesto, el sujeto pasivo deberá abonar intereses de demora por los días transcurridos desde la terminación del plazo de seis meses.\n6. La prórroga concedida comenzará a contarse desde que finalice el plazo de seis meses establecido en el artículo 67.1, a), y llevará aparejada la obligación de satisfacer el interés de demora correspondiente hasta el día en que se presente el documento o la declaración.\n7. Si finalizado el plazo de prórroga no se hubiesen presentado los documentos, se podrá girar liquidación provisional en base a los datos de que disponga la Administración, sin perjuicio de las sanciones que procedan.","u":"#a6-10","c":"CAPITULO II. Régimen de presentación de documentos · Sección segunda: plazos de presentación, prórroga y suspensión"},{"n":"RISD","a":"69","t":"Suspensión de los plazos de presentación.","x":"1. Cuando, en relación a actos o contratos relativos a hechos imponibles gravados por el Impuesto sobre Sucesiones y Donaciones, se promueva litigio o juicio voluntario de testamentaría, se interrumpirán los plazos establecidos para la presentación de los documentos y declaraciones, empezando a contarse de nuevo desde el día siguiente a aquel en que sea firme la resolución definitiva que ponga término al procedimiento judicial.\n2. Cuando se promuevan después de haberse presentado en plazo el documento o la declaración, la Administración suspenderá la liquidación hasta que sea firme la resolución definitiva.\n3. Si se promovieran con posterioridad a la expiración del plazo de presentación o del de la prórroga que se hubiese concedido sin que el documento o la declaración hubiesen sido presentados, la Administración requerirá la presentación pero podrá suspender la liquidación hasta que recaiga resolución firme, sin perjuicio de las sanciones que, en su caso, procedan.\n4. Si se promovieran después de practicada la liquidación podrá acordarse el aplazamiento de pago de conformidad con lo dispuesto en los artículos 84 y 90 de este Reglamento.\n5. No se considerarán cuestiones litigiosas, a los efectos de la suspensión de plazos a que se refieren los apartados anteriores, las diligencias judiciales que tengan por objeto la apertura de testamentos o elevación de éstos a escritura pública; la formación de inventarios para aceptar la herencia con dicho beneficio o con el de deliberar, el nombramiento de tutor, curador o defensor judicial, la prevención del abintestato o del juicio de testamentaría, la declaración de herederos cuando no se formule oposición y, en general, las actuaciones de jurisdicción voluntaria cuando no adquieran carácter contencioso. Tampoco producirán la suspensión la demanda de retracto legal o la del beneficio de justicia gratuita, ni las reclamaciones que se dirijan a hacer efectivas deudas contra la testamentaría o abintestato, mientras no se prevenga a instancia del acreedor el correspondiente juicio universal.\n6. La promoción del juicio voluntario de testamentaría interrumpirá los plazos, que empezarán a contarse de nuevo desde el día siguiente al en que quedare firme el auto aprobando las operaciones divisorias, o la sentencia que pusiere término al pleito en caso de oposición, o bien desde que todos los interesados desistieren del juicio promovido.\n7. A los efectos de este artículo se entenderá que la cuestión litigiosa comienza en la fecha de presentación de la demanda.\n8. A los mismos efectos, se asimilan a las cuestiones litigiosas los procedimientos penales que versen sobre la falsedad del testamento o del documento determinante de la transmisión.\n9. Si las partes litigantes dejaren de instar la continuación del litigio durante un plazo de seis meses, la Administración podrá exigir la presentación del documento y practicar la liquidación oportuna respecto al acto o contrato litigioso, a reserva de la devolución que proceda si al terminar aquél se declarase que no surtió efecto. Si se diere lugar a que los Tribunales declaren la caducidad de la instancia que dio origen al litigio, no se reputarán suspendidos los plazos y la Administración exigirá las sanciones e intereses de demora correspondientes a partir del día siguiente al en que hubieren expirado los plazos reglamentarios para la presentación de los documentos. La suspensión del curso de los autos, por conformidad de las partes, producirá el efecto de que, a partir de la fecha en que la soliciten, comience a correr de nuevo el plazo de presentación interrumpido.","u":"#a6-11","c":"CAPITULO II. Régimen de presentación de documentos · Sección segunda: plazos de presentación, prórroga y suspensión"},{"n":"RISD","a":"70","t":"Competencia territorial.","x":"1. Los documentos o declaraciones se presentarán en las siguientes oficinas:\na) En los supuestos de adquisición de bienes y derechos por causa de muerte, en la correspondiente al territorio donde el causante hubiese tenido su residencia habitual.\nSi el causante no hubiese tenido residencia habitual en España, en la Delegación de Hacienda de Madrid, salvo que concurriendo a la sucesión uno o varios causahabientes con residencia habitual en España, se opte por presentarlos, previo acuerdo de los interesados, en la oficina que corresponda al territorio donde cualquiera de ellos tenga su residencia habitual.\nTodos los documentos o declaraciones relativos a una misma sucesión habrán de presentarse en la oficina competente a que se refieren los dos párrafos anteriores.\nSi el mismo documento incluyese la adquisición de bienes y derechos procedentes de distintas herencias, la presentación se realizará en la oficina competente para liquidar la última ocurrida en el tiempo.\nb) En los supuestos de adquisición de bienes y derechos por donación o cualquier otro negocio jurídico a título gratuito e «inter vivos» equiparable, en la correspondiente al territorio donde radiquen los bienes inmuebles transmitidos, cuando el acto tenga por objeto exclusivo bienes de tal naturaleza. Si tuviese por objeto exclusivo bienes inmuebles situados fuera de España, la presentación se realizará en la Delegación de Hacienda de Madrid.\nSi transmitiéndose más de un bien inmueble resultase que están situados en el territorio de distintas oficinas, en la del territorio donde radiquen los inmuebles que, según las normas del Impuesto sobre el Patrimonio, tengan mayor valor. Si los inmuebles donados fuesen del mismo valor, en cualquiera de las oficinas donde esté situado alguno de ellos, previo acuerdo de los interesados, de ser varios.\nSi la donación o negocio jurídico gratuito e «inter vivos» tuviese por objeto exclusivo bienes de otra naturaleza, en la oficina del territorio donde tenga su residencia habitual el adquirente. Si existiesen varios adquirentes con distinta residencia, en la oficina del territorio donde resida el adquirente de los bienes de mayor valor, según las reglas del Impuesto sobre el Patrimonio, y si fuesen del mismo valor, en cualquiera de las oficinas correspondientes al territorio donde tengan su residencia habitual los adquirentes, previo acuerdo de éstos. Si ninguno de los adquirentes tuviese su residencia habitual en España, en la Delegación de Hacienda de Madrid.\nSi concurriesen bienes inmuebles con otros de distinta naturaleza, todos situados en España, la presentación se hará en la oficina correspondiente al territorio de situación de los inmuebles de mayor valor, cuando la suma del de todos los inmuebles sea igual o superior al de los demás bienes transmitidos. Cuando el valor de los bienes no inmuebles sea superior al de éstos, la presentación se realizará en la oficina donde el adquirente de bienes no inmuebles de mayor valor tenga su residencia habitual y si ninguno la tuviere en territorio español, en la de situación de los inmuebles cualquiera que sea su valor.\nSi concurriesen bienes inmuebles con otros de distinta naturaleza, situados todos o algunos de ellos fuera de España, la presentación se efectuará en la oficina que corresponda al lugar de situación de los inmuebles, si fuesen éstos los situados en España y, en otro caso, en la de residencia del sujeto pasivo, con la misma salvedad establecida para el caso de que no tenga residencia habitual en España.\nc) Cuando se trate exclusivamente de la percepción de cantidades por los beneficiarios de contratos de seguro sobre la vida, los interesados podrán optar por realizar la presentación en la oficina correspondiente al territorio donde la entidad aseguradora deba proceder al pago.\n2. Los documentos comprensivos de transmisiones por causa de muerte y de adquisiciones gratuitas «ínter vivos», se presentarán, precisamente, en la oficina que sea competente para liquidar la transmisión por causa de muerte.","u":"#a7-2","c":"CAPITULO II. Régimen de presentación de documentos · Sección tercera: lugar de presentación de los documentos"},{"n":"RISD","a":"71","t":"Competencia territorial y atribución de rendimientos.","x":"Cuando de la aplicación de las reglas del artículo anterior resulte atribuida la competencia territorial a una oficina integrada en la estructura administrativa de un Ente público al que no corresponda el rendimiento del tributo, según las normas establecidas en las Leyes de Cesión a las Comunidades Autónomas, se mantendrá la competencia para la gestión y liquidación del Impuesto, pero el importe ingresado se transferirá a la Caja del Ente público a que corresponda.","u":"#a7-3","c":"CAPITULO II. Régimen de presentación de documentos · Sección tercera: lugar de presentación de los documentos"},{"n":"RISD","a":"72","t":"Unidad de competencia territorial.","x":"1. En ningún caso se reconocerá la competencia territorial de más de una oficina para entender del mismo documento o declaración, aun cuando comprenda dos o más actos o contratos sujetos al Impuesto. La oficina competente conforme a las reglas del artículo 70 liquidará todos los actos y contratos a que el documento se refiera, incluso los sujetos al Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados.\n2. Cuando se practiquen diversas liquidaciones, ya sean provisionales o definitivas, las segundas y ulteriores deberán efectuarse, precisamente, en la oficina que hubiese practicado la primera.\n3. Los documentos o declaraciones relativos a extinción de usufructos, o los que tengan por objeto hacer constar el cumplimiento de condiciones, se presentarán en la misma oficina que hubiese conocido de los actos o documentos en que se constituyeron o establecieron.","u":"#a7-4","c":"CAPITULO II. Régimen de presentación de documentos · Sección tercera: lugar de presentación de los documentos"},{"n":"RISD","a":"73","t":"Órganos competentes para su resolución.","x":"1. Cuando la oficina donde se presente el documento o declaración se considere incompetente para liquidar, remitirá de oficio la documentación a la competente, notificando esta circunstancia y el acuerdo declarándose incompetente al presentador.\n2. Si se suscitaren cuestiones de competencia, positivas o negativas, serán resueltas:\na) Si se planteasen entre oficinas de una misma Comunidad Autónoma que tenga cedida la gestión del tributo, por el órgano competente de aquélla.\nb) (Derogado)\nc) Si se planteasen entre las Delegaciones de Hacienda de Madrid, Ceuta y Melilla, por la Dirección General de Gestión Tributaria del Ministerio de Economía y Hacienda.","u":"#a7-5","c":"CAPITULO II. Régimen de presentación de documentos · Sección cuarta: cuestiones de competencia"},{"n":"RISD","a":"74","t":"Tramitación de los documentos presentados.","x":"1. Presentado el documento o declaración en la oficina competente, ésta dará recibo haciendo constar la fecha de presentación y el número que le corresponda en el registro de presentación de documentos, que deberá llevarse con carácter específico.\n2. Tratándose de documentos relativos a adquisiciones «ínter vivos», su tramitación se ajustará a las siguientes reglas:\na) Cuando se hubiesen presentado todos los datos y antecedentes necesarios para la calificación de los hechos imponibles, siempre que no tenga que practicarse comprobación de valores, la oficina procederá con carácter definitivo a girar la liquidación o liquidaciones que procedan o a consignar las declaraciones de exención o no sujeción, según corresponda.\nb) Cuando sea necesaria la aportación de nuevos datos o antecedentes por los interesados, se les concederá un plazo de quince días para que puedan acompañarlos. Cuando lo hicieren, y si no fuera necesaria la comprobación de valores, se procederá como se indica en la letra anterior. Si no se aportasen y sin perjuicio de las sanciones que procedan, se podrán girar liquidaciones provisionales en base a los datos ya aportados y a los que posea la Administración.\nc) Cuando disponiendo de todos los datos y antecedentes necesarios se tuviera que practicar comprobación de valores, sobre los obtenidos se practicarán las liquidaciones definitivas que procedan, que serán debidamente notificadas al presentador.\nd) Cuando para la comprobación de valores se recurriere como medio de comprobación al dictamen de Peritos de la Administración, la oficina remitirá a los servicios técnicos correspondientes una relación de los bienes y derechos a valorar para que, por personal con título adecuado a la naturaleza de los mismos, se emita el dictamen solicitado, que deberá estar suficientemente razonado.\n3. Tratándose de documentos o declaraciones relativos a adquisiciones por causa de muerte, se procederá con arreglo a lo dispuesto en el número anterior, pero la práctica de las liquidaciones definitivas exigirá la comprobación completa del caudal hereditario del causante a efectos fiscales, debiendo procederse a la integración del declarado con las adiciones que resulten de las presunciones de los artículos 25 a 28 de este Reglamento y, en su caso, con el ajuar doméstico.\n4. Cualquiera que sea la naturaleza de la adquisición, las liquidaciones que se giren sin haber practicado la comprobación definitiva del hecho imponible y de su valoración tendrán carácter provisional.","u":"#a7-6","c":"CAPITULO II. Régimen de presentación de documentos · Sección quinta: tramitación"},{"n":"RISD","a":"75","t":"Supuesto de herederos desconocidos.","x":"En caso de adquisiciones por causa de muerte, cuando no fueren conocidos los herederos, los administradores o poseedores de los bienes hereditarios deberán presentar antes del vencimiento de los plazos señalados para ello, los documentos que se exigen para practicar liquidación, excepto la relación de herederos, y si estos presentadores no justificaren la existencia de una justa causa para suspender la liquidación, se girará liquidación provisional a cargo de la representación del causante, aplicándose sobre la cuota íntegra obtenida el coeficiente más alto de los que el artículo 44 de este Reglamento establece para el grupo IV, sin perjuicio de la devolución que proceda de lo satisfecho de más, una vez que aquéllos sean conocidos y esté justificado su parentesco con el causante y su patrimonio preexistente.","u":"#a7-7","c":"CAPITULO II. Régimen de presentación de documentos · Sección quinta: tramitación"},{"n":"RISD","a":"76","t":"Constancia del carácter de las liquidaciones.","x":"Las liquidaciones se extenderán a nombre de cada contribuyente haciendo constar en ellas su carácter de provisionales o definitivas. Del mismo modo, cuando proceda, se hará constar la naturaleza de las giradas como parciales, complementarias o caucionales.","u":"#a7-8","c":"CAPITULO II. Régimen de presentación de documentos · Sección quinta: tramitación"},{"n":"RISD","a":"77","t":"Liquidaciones complementarias.","x":"Procederá la práctica de liquidaciones complementarias cuando habiéndose girado con anterioridad liquidación provisional, la comprobación arroje aumento de valor para la base imponible tenida en cuenta en aquélla, o cuando se compruebe la existencia de errores materiales que hubiesen dado lugar a una minoración en la cuota ingresada. El mismo carácter tendrán las liquidaciones giradas a consecuencia de nuevos datos aportados por la acción investigadora de la oficina gestora que deban dar lugar a un incremento en la base de la liquidación provisional.","u":"#a7-9","c":"CAPITULO II. Régimen de presentación de documentos · Sección quinta: tramitación"},{"n":"RISD","a":"78","t":"Liquidaciones parciales a cuenta.","x":"1. Los interesados en sucesiones hereditarias podrán solicitar de la oficina competente, dentro de los plazos establecidos para la presentación de documentos o declaraciones que se practique liquidación parcial del Impuesto a los solos efectos de cobrar seguros sobre la vida, créditos del causante, haberes devengados y no percibidos por el mismo, o retirar bienes, valores, efectos o dinero que se hallasen en depósito, o bien en otros supuestos análogos en los que, con relación a bienes en distinta situación, existan razones suficientes que justifiquen la práctica de liquidación parcial.\n2. Para la práctica de las liquidaciones parciales, los interesados deberán presentar en la oficina competente un escrito, por duplicado, relacionando los bienes para los que se solicita la liquidación parcial, con expresión de su valor y de la situación en que se encuentren, del nombre de la persona o Entidad que, en su caso, deba proceder al pago o a la entrega de los bienes y del título acreditativo del derecho del solicitante o solicitantes.\n3. A la vista de la declaración presentada, la oficina girará liquidación parcial, aplicando sobre el valor de los bienes a que la solicitud se refiere, sin reducción alguna, la tarifa del Impuesto y el coeficiente multiplicador mínimo correspondiente en función del patrimonio preexistente.\n4. Ingresado el importe de la liquidación parcial, se entregará al interesado un ejemplar del escrito de solicitud presentado con la nota del ingreso. La presentación de este escrito acreditará, ante la persona que deba proceder a la entrega o al pago que, fiscalmente, queda autorizada la entrega, el pago o la retirada del dinero o de los bienes depositados.\n5. Las liquidaciones parciales que se giren con arreglo a lo dispuesto en el presente artículo tendrán el carácter de ingresos a cuenta de la liquidación definitiva que proceda por la sucesión hereditaria de que se trate.","u":"#a7-10","c":"CAPITULO II. Régimen de presentación de documentos · Sección sexta: liquidaciones parciales"},{"n":"RISD","a":"79","t":"Notificación de liquidaciones.","x":"Practicadas las liquidaciones que procedan, se notificarán al sujeto pasivo o al presentador del documento o declaración con indicación de su carácter y motivación, del lugar, plazos y forma de efectuar el ingreso, así como de los recursos que puedan ser interpuestos, con indicación de los plazos y órganos ante los que habrán de interponerse.","u":"#a7-11","c":"CAPITULO II. Régimen de presentación de documentos · Sección séptima: pago del impuesto, aplazamiento y fraccionamiento del pago"},{"n":"RISD","a":"80","t":"Plazos y forma de pago.","x":"1. El pago de las liquidaciones practicadas por la Administración deberá realizarse en los plazos establecidos en el Reglamento General de Recaudación.\n2. El pago de la deuda tributaria podrá realizarse mediante la entrega de bienes integrantes del Patrimonio Histórico Español que estén inscritos en el Inventario General de Bienes Muebles o en el Registro General de Bienes de Interés Cultural.\n3. La oficina gestora que hubiese practicado las liquidaciones podrá autorizar, a solicitud de los interesados, deducida dentro de los ocho días siguientes al de su notificación, a las Entidades financieras para enajenar valores depositados en las mismas a nombre del causante y, con cargo a su importe, o al saldo a favor de aquél en cuentas de cualquier tipo, librar los correspondientes talones a nombre del Tesoro Público por el exacto importe de las citadas liquidaciones.","u":"#a8-2","c":"CAPITULO II. Régimen de presentación de documentos · Sección séptima: pago del impuesto, aplazamiento y fraccionamiento del pago"},{"n":"RISD","a":"81","t":"Supuestos generales de aplazamiento y fraccionamiento.","x":"Sin perjuicio de los supuestos especiales de aplazamiento y fraccionamiento de pago, a que se refieren los artículos siguientes de esta Sección, en el Impuesto sobre Sucesiones y Donaciones serán aplicables las normas sobre aplazamiento y fraccionamiento de pago del Reglamento General de Recaudación.","u":"#a8-3","c":"CAPITULO II. Régimen de presentación de documentos · Sección séptima: pago del impuesto, aplazamiento y fraccionamiento del pago"},{"n":"RISD","a":"82","t":"Aplazamiento por término de hasta un año.","x":"Los órganos competentes para la gestión y liquidación del Impuesto podrán acordar el aplazamiento de las liquidaciones giradas por adquisiciones «mortis causa», por término de hasta un año, cuando concurran las condiciones siguientes:\na) Que se solicite antes de expirar el plazo reglamentario de pago.\nb) Que no exista inventariado entre los bienes del causante efectivo o bienes de fácil realización suficientes para el abono de las cuotas liquidadas.\nLa concesión del aplazamiento implicará la obligación de pagar el interés de demora vigente el día que comience su devengo.","u":"#a8-4","c":"CAPITULO II. Régimen de presentación de documentos · Sección séptima: pago del impuesto, aplazamiento y fraccionamiento del pago"},{"n":"RISD","a":"83","t":"Fraccionamiento hasta por cinco anualidades.","x":"Los órganos competentes para la gestión y liquidación del Impuesto podrán acordar el fraccionamiento de las liquidaciones giradas por adquisiciones «mortis causa», en cinco anualidades como máximo, siempre que concurran las siguientes condiciones:\na) Que se solicite antes de expirar el plazo reglamentario de pago.\nb) Que no exista inventariado entre los bienes del causante efectivo o bienes de fácil realización suficientes para el abono de las cuotas liquidadas.\nc) Que se acompañe compromiso de constituir garantía suficiente que cubra el importe de la deuda principal e intereses de demora, más un 25 por 100 de la suma de ambas partidas. La concesión definitiva del fraccionamiento quedará subordinada a la constitución de la garantía.\nLa concesión del fraccionamiento implicará la obligación de pagar el interés de demora vigente el día en que comience su devengo.","u":"#a8-5","c":"CAPITULO II. Régimen de presentación de documentos · Sección séptima: pago del impuesto, aplazamiento y fraccionamiento del pago"},{"n":"RISD","a":"84","t":"Aplazamiento en caso de causahabientes desconocidos.","x":"A solicitud de los administradores o poseedores de los bienes hereditarios, los órganos competentes para la gestión y liquidación del Impuesto podrán conceder el aplazamiento de las liquidaciones giradas por adquisiciones «mortis causa», hasta que fueren conocidos los causahabientes en una sucesión, siempre que concurran las condiciones siguientes:\na) Que se solicite antes de expirar el plazo reglamentario de pago.\nb) Que no exista inventariado entre los bienes del causante efectivo o bienes de fácil realización suficientes para el abono de las cuotas liquidadas.\nc) Que se acompañe compromiso de constituir garantía suficiente que cubra el importe de la deuda principal e intereses de demora, más un 25 por 100 de la suma de ambas partidas. La concesión definitiva del aplazamiento quedará subordinada a la constitución de la garantía.\nLa concesión del aplazamiento implicará obligación de abonar el interés de demora vigente el día en que comience su devengo.","u":"#a8-6","c":"CAPITULO II. Régimen de presentación de documentos · Sección séptima: pago del impuesto, aplazamiento y fraccionamiento del pago"},{"n":"RISD","a":"85","t":"Aplazamiento en caso de transmisión de empresas individuales y de la vivienda habitual.","x":"1. Los órganos competentes para conceder los aplazamientos y fraccionamientos de pago a que se refiere el Reglamento General de Recaudación, y con sujeción al procedimiento y a las condiciones que en él se establecen, en cuanto no sean incompatibles con lo que en este artículo se dispone, podrán aplazar por tres años, a petición del sujeto pasivo, el pago de las liquidaciones giradas como consecuencia de la transmisión por herencia, legado o donación de una empresa individual que ejerza una actividad industrial, comercial, artesanal, agrícola o profesional.\nLa solicitud deberá presentarse antes de expirar el plazo reglamentario de ingreso, acompañada del compromiso de constituir garantía suficiente que cubra la deuda principal e interés legal, más un 25 por 100 de la suma de ambas partidas.\n2. Vencido el aplazamiento a que se refiere el apartado anterior, podrán acordar con las mismas condiciones y el cumplimiento de idénticos requisitos, el fraccionamiento de pago en siete plazos semestrales sucesivos, a partir de la notificación de la concesión del fraccionamiento.\nLa falta de pago de alguno de los pagos fraccionados producirá los efectos establecidos en el Reglamento General de Recaudación para dicho supuesto.\n3. Lo dispuesto en los números anteriores sobre aplazamiento y fraccionamiento de pago será aplicable a las liquidaciones giradas a consecuencia de la transmisión hereditaria de la vivienda habitual de una persona, siempre que el adquirente de la misma sea el cónyuge, ascendiente, o descendiente de aquél, o bien pariente colateral, mayor de sesenta y cinco años, que hubiese convivido con el causante durante los dos años anteriores a su fallecimiento.\n4. Los aplazamientos y fraccionamientos a que se refieren los números anteriores afectarán a la parte proporcional de la deuda tributaria que corresponda al valor comprobado de la Empresa o de la vivienda transmitidas en relación con el total caudal hereditario de cada uno de los causahabientes.","u":"#a8-7","c":"CAPITULO II. Régimen de presentación de documentos · Sección séptima: pago del impuesto, aplazamiento y fraccionamiento del pago"},{"n":"RISD","a":"85 bis","t":"Fraccionamiento de la cuota derivada de las cantidades percibidas en forma de renta por contratos de seguro sobre la vida.","x":"1. En los seguros sobre la vida en los que el causante sea, a su vez, el contratante del seguro individual o el asegurado en el seguro colectivo y cuyo importe se perciba por los beneficiarios en forma de renta, vitalicia o temporal, éstos deberán integrar en la base imponible el valor actual de dicha renta.\n2. El valor actual de dicha renta se acumulará al resto de bienes y derechos que integran la porción hereditaria del beneficiario.\n3. El beneficiario podrá solicitar, durante el plazo previsto en el artículo 67.1.a) de este Reglamento, el fraccionamiento de la parte de la cuota resultante de aplicar sobre el valor actual de la renta, vitalicia o temporal, deducida en su caso la cantidad prevista en el artículo 20.2.b) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, el tipo medio de gravamen.\nSe entenderá por tipo medio de gravamen el derivado de multiplicar por 100 el cociente resultante de dividir la cuota tributaria total a ingresar por el contribuyente por el valor total de los bienes y derechos que integran su base liquidable. Dicho tipo medio de gravamen se expresará con dos decimales.\n4. La Administración competente para la exacción del impuesto acordará el fraccionamiento en el número de años en que se perciba la renta, si fuera temporal, o en quince años si fuera vitalicia, no exigiéndose la constitución de ningún tipo de caución ni devengándose intereses de demora.\nLa Administración competente notificará al contribuyente la resolución de la solicitud en el plazo de tres meses, si transcurrido dicho plazo no se ha notificado resolución expresa, la solicitud se considerará estimada. Sólo podrá desestimarse la solicitud si ésta está incompleta o no cumple con los requisitos fijados en la norma.\n5. El importe del ingreso anual correspondiente al pago fraccionado resultará de dividir la cuota que se fracciona entre el número de años en que se perciba la renta si fuera temporal, o entre quince si fuera vitalicia.\nEl pago anual fraccionado se ingresará en los plazos que figuren en la resolución de concesión del fraccionamiento, dentro del mes de enero siguiente a la percepción íntegra de cada anualidad de renta.\n6. En el supuesto en que se ejercite el derecho de rescate, la totalidad de los pagos fraccionados pendientes deberán ingresarse durante los treinta días siguientes a tal ejercicio.\n7. En el supuesto en que se produzca la extinción de la renta, sólo resultará exigible el pago fraccionado pendiente que corresponda a la anualidad de renta efectivamente percibida y pendiente de ingreso.\n8. La responsabilidad subsidiaria de las entidades de seguros se extingue en relación con el primer pago fraccionado cuando el beneficiario acredite la obtención, en forma expresa o por silencio, del fraccionamiento regulado en el presente precepto.\nEl mantenimiento de la extinción de la responsabilidad exige la acreditación por el contribuyente ante la entidad de seguros del ingreso del pago fraccionado correspondiente a cada anualidad de renta.\nEn el supuesto del ejercicio del derecho de rescate, las entidades de seguros podrán exigir la presentación de certificación expedida por la Administración tributaria sobre el importe del impuesto pendiente de pago, a los efectos de conocer la cuantía de su responsabilidad subsidiaria y, en su caso, poder entregar a los beneficiarios cheque bancario expedido a nombre de la Administración acreedora del impuesto, de acuerdo con lo previsto en el artículo 8.1.b) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones.\nTexto añadido, publicado el 12/03/2002, en vigor a partir del 13/03/2002.","u":"#a8-8","c":"CAPITULO II. Régimen de presentación de documentos · Sección séptima: pago del impuesto, aplazamiento y fraccionamiento del pago"},{"n":"RISD","a":"86","t":"Régimen de autoliquidación: Requisitos.","x":"1. La opción de los sujetos pasivos por el régimen de autoliquidación exigirá que en las declaraciones-liquidaciones se incluya el valor de la totalidad de los bienes y derechos transmitidos y que, tratándose de adquisiciones por causa de muerte, incluidas las realizadas por los beneficiarios de contratos de seguro de vida para caso de muerte del asegurado, todos los adquirentes interesados en la sucesión o el seguro estén incluidos en el mismo documento o declaración y exista la conformidad de todos.\nEl importe ingresado por una autoliquidación que no reúna los requisitos exigidos en el párrafo anterior tendrá el carácter de mero ingreso a cuenta, pero no dará lugar a que la oficina gestora dé cumplimiento a lo establecido en el artículo 87, apartados 3 y 4 de este Reglamento.\n2. No obstante lo dispuesto en el apartado anterior, se admitirá la autoliquidación parcial referida a una parte de los bienes y derechos en aquellos supuestos en los que, según el artículo 78 de este Reglamento, se admite la práctica de liquidación parcial a cuenta.","u":"#a8-9","c":"CAPITULO III. Autoliquidación · Sección primera: requisitos y presentación"},{"n":"RISD","a":"87","t":"Presentación e ingreso de autoliquidaciones.","x":"1. Los sujetos pasivos que opten por determinar el importe de sus deudas tributarias mediante autoliquidación deberán presentarla en el modelo de impreso de declaración-liquidación especialmente habilitado al efecto, procediendo a ingresar su importe dentro de los plazos establecidos en el artículo 67 de este Reglamento para la presentación de documentos o declaraciones o en el de prórroga del artículo 68, en la entidad de depósito que presta el servicio de caja en la Administración tributaria competente o en alguna de sus entidades colaboradoras.\n2. Ingresado el importe de las autoliquidaciones, los sujetos pasivos deberán presentar en la oficina gestora, en un sobre único para cada sucesión o donación, el original y copia simple del documento notarial, judicial o administrativo o privado en el que conste o se relacione el acto o contrato que origine el tributo, con un ejemplar de cada autoliquidación practicada.\n3. La oficina devolverá al presentador el documento original, con nota estampada en el mismo acreditativa del ingreso efectuado y de la presentación de la copia. La misma nota de ingreso se hará constar también en la copia, que se conservará en la oficina para el examen y calificación del hecho imponible y, si procede, para la rectificación, comprobación y práctica de la liquidación o liquidaciones complementarias.\n4. En los supuestos en los que de la autoliquidación no resulte cuota tributaria a ingresar, su presentación, junto con los documentos, se realizará directamente en la oficina competente, que sellará la autoliquidación y extenderá nota en el documento original haciendo constar la calificación que proceda, según los interesados, devolviéndolo al presentador y conservando la copia simple en la oficina a los efectos señalados en el número anterior.\n5. Las actuaciones a que se refiere este artículo deberán realizarse en la oficina que resulte territorialmente competente según las reglas del artículo 70 de este Reglamento.","u":"#a8-10","c":"CAPITULO III. Autoliquidación · Sección primera: requisitos y presentación"},{"n":"RISD","a":"87 bis","t":"Regulación de los medios de acreditación de la presentación y pago, en su caso, del impuesto, ante la oficina gestora competente, para los contribuyentes que deban tributar a la Administración Tributaria del Estado.","x":"A los efectos de lo dispuesto en la normativa reguladora de este impuesto, la presentación ante la oficina gestora competente de la autoliquidación junto con los documentos que contengan actos o contratos sujetos al Impuesto sobre Sucesiones y Donaciones, así como, en su caso, el pago de dicho impuesto, o la no sujeción o los beneficios fiscales aplicables, se podrán acreditar, además de por los medios previstos en la normativa reguladora del mismo, por cualquiera de los siguientes:\na) Certificación expedida a tal efecto por la oficina gestora competente de la Agencia Estatal de Administración Tributaria que contenga todas las menciones y requisitos necesarios para identificar el documento notarial, judicial, administrativo o privado que contenga o en el que se relacione el acto o contrato que origine el impuesto, acompañada, en su caso, de la carta de pago o del correspondiente ejemplar de la autoliquidación.\nb) Cualquier otro medio determinado reglamentariamente por el Ministro de Hacienda y Función Pública.\nTexto añadido, publicado el 30/12/2017, en vigor a partir del 30/12/2017.","u":"#a8-11","c":"CAPITULO III. Autoliquidación · Sección primera: requisitos y presentación"},{"n":"RISD","a":"88","t":"Tramitación de autoliquidaciones.","x":"1. La tramitación de los documentos y de las declaraciones-liquidaciones presentadas por los sujetos pasivos en las oficinas gestoras se acomodará a lo dispuesto para el régimen de presentación de documentos en el artículo 74 de este Reglamento, sin otras especialidades que las que sean consecuencia de las autoliquidaciones practicadas y, en su caso, ingresadas por los interesados. En consecuencia, se procederá por la oficina gestora al examen y calificación de los hechos imponibles consignados en los documentos para girar las liquidaciones complementarias que procedan, entre otros casos, como consecuencia de errores materiales o de calificación o por la existencia de hechos imponibles no autoliquidados por los interesados, así como las que tengan su origen en la comprobación de valores, en la adición de bienes o del ajuar doméstico o en el descubrimiento de nuevos bienes del causante.\nCuando sea necesaria la aportación de nuevos datos o antecedentes, se concederá un plazo de quince días a los interesados para presentarlos en la oficina.\n2. Cuando se proceda a la comprobación de valores, se cumplirá lo dispuesto en el número 2, letras c) y d), del artículo 74 de este Reglamento.\n3. Las liquidaciones giradas por la oficina competente como consecuencia de lo establecido en el presente artículo, se notificarán a los sujetos pasivos o al presentador del documento con indicación de su carácter y motivación, del lugar, plazos y forma de efectuar el ingreso, así como de los recursos que puedan ser interpuestos, con indicación de los plazos y órganos ante los que habrán de interponerse.","u":"#a8-12","c":"CAPITULO III. Autoliquidación · Sección segunda: tramitación"},{"n":"RISD","a":"89","t":"Autoliquidaciones parciales a cuenta.","x":"1. De conformidad con lo dispuesto en el artículo 86.2 de este Reglamento, tratándose de adquisiciones por causa de muerte, los sujetos pasivos, previa conformidad de todos en caso de ser más de uno, podrán proceder a la práctica de una autoliquidación parcial del Impuesto a los solos efectos de cobrar seguros sobre la vida, créditos del causante, haberes devengados y no percibidos por el mismo o retirar bienes, valores, efectos o dinero que se encuentren en depósito, o bien en otros supuestos análogos en los que con relación a otros bienes en distinta situación, existan razones suficientes que justifiquen la práctica de autoliquidación parcial.\nLos sujetos pasivos que presenten la autoliquidación parcial deberán proceder posteriormente a presentar la autoliquidación por la totalidad de los bienes y derechos que hayan adquirido, en la forma prevista en los artículos 86 y 87 anteriores.\n2. La autoliquidación deberá practicarse aplicando sobre el valor de los bienes a que se refiera, sin reducción alguna, la tarifa del Impuesto y los coeficientes multiplicadores mínimos correspondientes en función del patrimonio preexistente.\n3. Ingresado el importe de la autoliquidación parcial en la forma establecida en el artículo 87 de este Reglamento, se presentará en la oficina competente un ejemplar del impreso de autoliquidación donde conste el ingreso, acompañado de una relación por duplicado en la que se describan los bienes a que se refiera, su valor y la situación en que se encuentren, así como el nombre de la persona o Entidad que deba proceder al pago o a la entrega de los bienes, y del título acreditativo del derecho del solicitante o solicitantes, devolviéndose por la oficina uno de los ejemplares de la relación con la nota del ingreso.\n4. El ingreso efectuado en virtud de autoliquidación parcial tendrá el carácter de ingreso a cuenta de la liquidación definitiva que proceda por la sucesión hereditaria de que se trate.","u":"#a8-13","c":"CAPITULO III. Autoliquidación · Sección tercera: autoliquidaciones parciales"},{"n":"RISD","a":"90","t":"Aplazamiento y fraccionamiento de autoliquidaciones.","x":"1. Serán aplicables las normas del Reglamento General de Recaudación para la concesión de aplazamientos y fraccionamientos del pago de autoliquidaciones que los interesados deban satisfacer por el Impuesto sobre Sucesiones y Donaciones.\n2. No obstante, si en el régimen de presentación de documentos correspondiese a las oficinas gestoras la competencia para acordar el aplazamiento y el fraccionamiento de pago y concurren los requisitos establecidos en los artículos 82, 83 y 84 de este Reglamento, los interesados podrán solicitar de la oficina competente para admitir la autoliquidación, dentro de los cinco primeros meses del plazo establecido, la concesión del beneficio. Si la petición fuese denegada, el plazo para el ingreso se entenderá prorrogado en los días transcurridos desde el de la presentación de la solicitud hasta el de notificación del acuerdo denegatorio, sin perjuicio del abono de los intereses de demora que procedan.","u":"#a9-2","c":"CAPITULO III. Autoliquidación · Sección cuarta: aplazamientos y fraccionamientos"},{"n":"RISD","a":"91","t":"Normas generales.","x":"1. Los órganos judiciales remitirán a los Organismos de la Administración Tributaria de su respectiva jurisdicción relación mensual de los fallos ejecutoriados o que tengan el carácter de sentencia firme de los que se desprenda la existencia de incrementos de patrimonio gravados por el Impuesto sobre Sucesiones y Donaciones.\n2. Los encargados del Registro Civil remitirán a los mismos Organismos, dentro de la primera quincena de cada mes, relación nominal de los fallecidos en el mes anterior y de su domicilio.\n3. Los Notarios están obligados a facilitar los datos que les reclamen los Organismos de la Administración Tributaria acerca de los actos en que hayan intervenido en el ejercicio de sus funciones, y a expedir gratuitamente, en el plazo de quince días, las copias que aquéllos les pidan de los documentos que autoricen o tengan en su protocolo, salvo cuando se trate de los instrumentos públicos a que se refieren los artículos 34 y 35 de la Ley Orgánica del Notariado de 28 de mayo de 1862, y los relativos a cuestiones matrimoniales, con excepción de los referentes al régimen económico de la sociedad conyugal.\nAsimismo, estarán obligados a remitir, dentro de la primera quincena de cada trimestre, relación o índice comprensivo de todos los documentos autorizados en el trimestre anterior que se refieran a actos o contratos que pudieran dar lugar a los incrementos patrimoniales que constituyen el hecho imponible del Impuesto. También están obligados a remitir, dentro del mismo plazo, relación de los documentos privados con el contenido indicado que les hayan sido presentados para su conocimiento o legitimación de firmas.\nLos Cónsules cumplimentarán la obligación impuesta en este apartado remitiendo los índices o relaciones a la Dirección General de Gestión Tributaria del Ministerio de Economía y Hacienda.\n4. Los órganos judiciales, intermediarios financieros, asociaciones, fundaciones, sociedades, funcionarios y particulares o cualesquiera otras Entidades públicas o privadas, no acordarán entregas de bienes a personas distintas de su titular sin que se acredite previamente el pago del Impuesto o su exención, a menos que la Administración lo autorice.\n5. Las entidades de seguros no podrán efectuar la liquidación y pago de los concertados sobre la vida de una persona, a menos que se justifique haber presentado a liquidación la documentación correspondiente o, en su caso, el ingreso de la autoliquidación practicada.\n6. El incumplimiento de las obligaciones establecidas en los números anteriores se sancionará de acuerdo con lo dispuesto en la Ley General Tributaria.\nNo obstante, cuando se trate de órganos jurisdiccionales, la autoridad competente del Ministerio de Economía y Hacienda pondrá los hechos en conocimiento del Consejo General del Poder Judicial, por conducto del Ministerio Fiscal, a los efectos pertinentes.","u":"#a9-3","c":"TITULO II. Gestión del Impuesto · CAPITULO IV. Obligaciones formales"},{"n":"RISD","a":"92","t":"Procedimiento.","x":"Cuando la Administración tenga conocimiento de alguno de los hechos a que se refiere el artículo 15 de este Reglamento, en los que se fundamentan las presunciones sobre la posible existencia de incrementos de patrimonio sujetos al Impuesto, sin haber sido objeto de declaración en los plazos establecidos para la presentación de documentos, lo pondrá en conocimiento de los interesados por medio de la oficina que fuese la competente para practicar la liquidación, para que aquéllos manifiesten su conformidad o disconformidad con la existencia del hecho imponible, formulando cuantas alegaciones tengan por conveniente en plazo de quince días, con aportación de las pruebas o documentos pertinentes.\nTranscurrido dicho plazo, la oficina, a la vista del expediente, dictará la resolución que proceda, girando, en su caso, las liquidaciones que correspondan a los hechos imponibles que estime producidos.","u":"#a9-4","c":"TITULO III. Procedimientos especiales · CAPITULO I. Procedimiento sobre presunciones de hechos imponibles"},{"n":"RISD","a":"93","t":"Procedimiento.","x":"Cuando la oficina competente ante la que se hubiese presentado un documento, declaración o declaración-liquidación comprensivo de una adquisición por causa de muerte, comprobase la omisión en el inventario de bienes del causante de los que se encuentren en alguna de las situaciones a que se refieren los artículos 25 a 28 y 30 de este Reglamento, lo pondrá en conocimiento de los interesados, concediéndoles un plazo de quince días para que puedan dar su conformidad a su adición al caudal relicto del causante.\nSi la adición fuese admitida por los interesados, las liquidaciones que se practiquen incluirán en la base imponible el valor de los bienes adicionables, o se procederá a rectificar las autoliquidaciones ingresadas por los interesados practicando las complementarias a que hubiere lugar, cuando se haya optado por ese procedimiento de declaración.\nEn el caso de que los interesados, en el plazo concedido, rechazasen la propuesta de adición o dejaren transcurrir el mismo sin contestar, sin perjuicio de continuar las actuaciones establecidas en este Reglamento para la liquidación del documento o para la comprobación de las autoliquidaciones, la oficina procederá a instruir un expediente a efectos de decidir en definitiva sobre la adición, concediendo a los interesados un plazo de quince días para formular alegaciones y aportar los documentos o pruebas que estimen convenientes a su derecho. Transcurrido este plazo se dictará acuerdo sobre la procedencia o no de la adición.\nEl acuerdo favorable a la adición será recurrible en reposición o en vía económico-administrativa.\nUltimada la vía administrativa en sentido favorable a la adición, la Administración podrá proceder a la rectificación de las liquidaciones provisionales o a practicar las complementarias que procedan.\nDurante la tramitación del expediente y hasta su ultimación definitiva quedará interrumpido el plazo de prescripción de la acción de la Administración para practicar las liquidaciones que procedan.","u":"#a9-5","c":"TITULO III. Procedimientos especiales · CAPITULO II. Procedimiento para la adición de bienes a la masa hereditaria"},{"n":"RISD","a":"94","t":"Procedimiento.","x":"El procedimiento para la deducción de las deudas del causante que se pongan de manifiesto con posterioridad al ingreso de las liquidaciones giradas por la Administración o de las autoliquidaciones practicadas por los interesados, se ajustará a las siguientes reglas:\n1.ª La deducción se hará efectiva mediante la devolución, sin intereses de demora, de la porción de Impuesto que corresponda al importe de la deuda no deducida, entendiéndose por tal la diferencia que exista entre la cantidad ingresada y la que se hubiese ingresado si al practicar la liquidación o la autoliquidación se hubiese deducido el importe de la deuda.\n2.ª Los interesados presentarán un escrito ante la oficina que hubiese practicado la liquidación o tramitado la autoliquidación, solicitando la rectificación correspondiente, acompañado de los documentos acreditativos de la existencia de la deuda o del pago de la misma realizado con posterioridad al ingreso.\n3.ª Si la oficina estimase acreditada fehacientemente la existencia o el pago de la deuda, propondrá al órgano competente la adopción de acuerdo reconociendo el derecho a la devolución de la porción de impuesto a que se refiere la regla primera. En caso contrario, propondrá acuerdo denegatorio que se notificará a los interesados con expresión de los recursos procedentes contra el mismo.\n4.ª Lo dispuesto en este artículo no será aplicable cuando hubiesen transcurrido cinco años desde la fecha de expiración del plazo de presentación a liquidación del documento, declaración o declaración-liquidación o cuando se trate de liquidaciones administrativas firmes de carácter definitivo.","u":"#a9-6","c":"TITULO III. Procedimientos especiales · CAPITULO III. Procedimiento para la deducción de deudas del causante puestas de manifiesto con posterioridad al ingreso del impuesto"},{"n":"RISD","a":"95","t":"Procedimiento.","x":"El procedimiento para la devolución de la porción de Impuesto que corresponda a una deuda del donante, garantizada con derecho real que recaiga sobre los bienes que hubiesen sido donados por el mismo, cuando haya sido pagada por el donatario después de ingresado el Impuesto correspondiente a la donación, se ajustará a las reglas siguientes:\n1.ª Se entenderá como porción de Impuesto correspondiente a la deuda pagada y no deducida en la base imponible de la donación, la diferencia entre la cantidad ingresada y la que se hubiese ingresado si al practicar la liquidación o autoliquidación se hubiese deducido el importe de la deuda.\n2.ª El interesado deberá solicitar la rectificación mediante escrito presentado dentro del plazo de cinco años, contado desde el día en que hubiese finalizado el plazo reglamentario para presentar el correspondiente documento, declaración o declaración-liquidación, en la oficina que hubiese practicado la liquidación o tramitado la autoliquidación, acompañando los documentos que acrediten el pago de la deuda por su cuenta.\n3.ª Si la oficina estimase acreditado fehacientemente el pago de la deuda por el donatario, propondrá al órgano competente la adopción de acuerdo reconociendo el derecho a la devolución, que no incluirá intereses de demora. En otro caso, la propuesta será denegatoria de la devolución y el correspondiente acuerdo se notificará al interesado con expresión de los recursos procedentes contra el mismo.","u":"#a9-7","c":"TITULO III. Procedimientos especiales · CAPITULO IV. Procedimiento para la deducción de deudas del donante satisfechas por el donatario"},{"n":"RISD","a":"96","t":"Procedimiento.","x":"El procedimiento para que la Administración pública pueda ejercitar el derecho de adquisición reconocido en el artículo 19 de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, y en el artículo 41 de este Reglamento, se ajustará a las reglas siguientes:\n1.ª El órgano u oficina que haya practicado liquidaciones definitivas por el Impuesto sobre Sucesiones y Donaciones, remitirá al Delegado de Hacienda o al órgano correspondiente de las Comunidades Autónomas, dentro del mes siguiente a la fecha en que hubiesen ganado firmeza, relación por duplicado de los documentos o declaraciones presentados en los que se incluyan bienes o derechos que reúnan las condiciones establecidas en el párrafo segundo del artículo 41.1 de este Reglamento para el ejercicio del derecho de adquisición por la Administración, con indicación de los bienes concretos susceptibles de ser adquiridos y del nombre, domicilio y demás circunstancias personales de los adquirentes.\n2.ª Dentro del mes siguiente a la recepción de estas relaciones, el Delegado de Hacienda o el órgano correspondiente en la Comunidad Autónoma, previo informe del Servicio Jurídico, propondrá al Centro directivo encargado de la gestión del impuesto los bienes sobre los que proceda ejercitar el derecho de adquisición, relacionados por orden de importancia según su valor comprobado.\n3.ª Recibida la propuesta en el Centro directivo, éste recabará informe sobre las disponibilidades presupuestarias para atender a los gastos de la adquisición y, a la vista de este informe, comunicará al órgano proponente los bienes sobre los que debe ejercitarse el derecho de adquisición. Estas actuaciones deberán estar ultimadas de tal modo que la comunicación a los Delegados de Hacienda o a los órganos respectivos de las Comunidades Autónomas sea realizada dentro del tercer mes siguiente a la fecha en que las liquidaciones a que se refiere la regla primera hubiesen quedado firmes.\n4.ª Recibida la comunicación por el Delegado de Hacienda u órgano correspondiente de la Comunidad Autónoma, lo comunicará a los interesados, concediéndoles el plazo de un mes para formular las alegaciones que estimen convenientes a su derecho. Al mismo tiempo, dará traslado a los Registros de la Propiedad, Mercantil o de la Propiedad Industrial para que hagan constar, mediante nota, que el bien o derecho se encuentra sometido al ejercicio del derecho de adquisición por la Administración. Ultimado el expediente, se elevará de nuevo al Centro directivo que, a la vista de las actuaciones practicadas, propondrá al Ministerio de Economía y Hacienda, o al órgano correspondiente de la Comunidad Autónoma, la resolución que deba dictarse.\nLa nota de afección a que se refiere el párrafo anterior caducará a los dos años de su fecha.\n5.ª La Orden del Ministerio de Economía y Hacienda, o la resolución del órgano equivalente de la Comunidad Autónoma, se notificará a los interesados y será susceptible de impugnación en la vía contencioso-administrativa, previa interposición del recurso de reposición a que se refiere la Ley Reguladora de la Jurisdicción Contencioso-Administrativa.","u":"#a9-8","c":"TITULO III. Procedimientos especiales · CAPITULO V. Procedimiento para el ejercicio del derecho de adquisición por la Administración"},{"n":"RISD","a":"97","t":"Procedimiento.","x":"El procedimiento para la devolución de la porción de Impuesto que corresponda a bienes o derechos sobre los que la Administración hubiese ejercitado el derecho de adquisición establecido en el artículo 41 de este Reglamento, se ajustará a las reglas siguientes:\n1.ª Se entenderá como porción de Impuesto a devolver la diferencia entre la cantidad ingresada y la que se hubiese ingresado si en la base tenida en cuenta para la liquidación se hubiese computado para el bien adquirido el valor declarado por el interesado en lugar del comprobado.\n2.ª El expediente se tramitará de oficio por la Administración una vez que hubiese adquirido firmeza el acuerdo sobre el ejercicio del derecho de adquisición, siendo competente la oficina que hubiese girado la liquidación. La tramitación del expediente se comunicará a los interesados a efectos de que puedan personarse en el mismo y formular las alegaciones y aportar los documentos que estimen convenientes a su derecho.","u":"#a9-9","c":"TITULO III. Procedimientos especiales · CAPITULO VI. Procedimiento para la devolución del Impuesto correspondiente a bienes sobre los que la Administración haya ejercitado el derecho de adquisición"},{"n":"RISD","a":"98","t":"Tasación pericial contradictoria.","x":"En corrección del resultado obtenido en la comprobación de valores los interesados podrán promover la práctica de la tasación pericial contradictoria con arreglo a las siguientes reglas:\n1.ª La solicitud de tasación pericial contradictoria deberá presentarse dentro del plazo de la primera reclamación que proceda contra la liquidación efectuada sobre la base de los valores comprobados administrativamente. La presentación determinará la suspensión del ingreso de la liquidación practicada y de los plazos de reclamación contra la misma.\n2.ª En el caso de que no figurase ya en el expediente la valoración motivada de un Perito de la Administración, por haberse utilizado para la comprobación del valor un medio distinto al «dictamen de Peritos de la Administración» previsto en el artículo 52.1.d), de la Ley General Tributaria, la oficina gestora remitirá a los servicios técnicos correspondientes una relación de los bienes y derechos a valorar para que, por personal con título adecuado a la naturaleza de los mismos, se proceda a la formulación, en el plazo de quince días, de la correspondiente hoja de aprecio por duplicado en la que deberá constar no sólo el resultado de la valoración realizada sino también los fundamentos tenidos en cuenta para el avalúo.\n3.ª Recibida por la oficina competente la valoración del Perito de la Administración, o la que ya figure en el expediente por haber utilizado la oficina gestora como medio de comprobación el de «dictamen de Peritos de la Administración», se trasladará a los interesados, concediéndoles un plazo de quince días para que puedan proceder al nombramiento de un Perito, que deberá tener título adecuado a la naturaleza de los bienes y derechos a valorar. Designado el Perito por el contribuyente se le entregará la relación de bienes y derechos concediéndole un nuevo plazo de quince días para formular la hoja de aprecio, que deberá estar fundamentada.\n4.ª Transcurrido el plazo de quince días sin hacer la designación de Perito se entenderá la conformidad del interesado con el valor comprobado sobre el que se hubiese girado la liquidación, dándose por terminado el expediente y procediéndose, en consecuencia, a la confirmación de la liquidación inicialmente practicada. En este caso, el sujeto pasivo deberá ingresar el importe del Impuesto en el resto del plazo que quedase por transcurrir al tiempo de solicitar la tasación, liquidándose los correspondientes intereses de demora.\n5.ª Si la tasación del Perito de la Administración no excede en más del 10 por 100 y no es superior en 20.000.000 de pesetas a la realizada por el del interesado, servirá de base el valor resultante de ésta, si fuese mayor que el valor declarado, o este valor en caso contrario, procediéndose a la rectificación de la liquidación inicialmente practicada. La nueva liquidación, con los correspondientes intereses de demora, se notificará al sujeto pasivo para su ingreso en los plazos establecidos en el Reglamento General de Recaudación.\n6.ª Si la tasación del Perito de la Administración excede de los límites indicados en la regla anterior, se procederá por el Delegado de Hacienda o por el órgano correspondiente de la Comunidad Autónoma, a designar por sorteo público un Perito tercero de entre los colegiados o asociados que figuren en las listas remitidas por los Colegios, Asociaciones y Corporaciones Profesionales en cumplimiento de lo dispuesto en el artículo 52.2 de la Ley General Tributaria o, en su caso, se interesará del Banco de España la designación de una sociedad de tasación inscrita en el correspondiente registro oficial. Realizada la designación se remitirá a la persona o entidad designada la relación de bienes y derechos a valorar y copia de las hojas de aprecio de los Peritos anteriores, para que en el plazo de quince días proceda a confirmar alguna de ellas o realice una nueva valoración que será definitiva.\n7.ª En ningún caso podrá servir de base para la liquidación el resultado de la tasación pericial si fuese menor que el valor declarado por los interesados.\n8.ª A la vista del resultado obtenido de la tasación pericial contradictoria, la oficina confirmará o rectificará la liquidación inicial, sin perjuicio de su posible impugnación en reposición o en vía económico-administrativa.\nEn ambos casos se liquidarán los correspondientes intereses de demora.\n9.ª Los honorarios del Perito del sujeto pasivo serán satisfechos por éste. Cuando la tasación practicada por el tercer Perito fuese superior en un 20 por 100 al valor declarado, todos los gastos de la pericia serán abonados por el sujeto pasivo y, por el contrario, caso de ser inferior, serán de cuenta de la Administración y, en este caso, el sujeto pasivo tendrá derecho a ser reintegrado de los gastos ocasionados por el depósito a que se refiere el párrafo siguiente.\nEl Perito tercero podrá exigir que, previamente al desempeño de su cometido, se haga provisión del importe de sus honorarios, lo que se realizará mediante depósito en el Banco de España, en el plazo de diez días. La falta de depósito por cualquiera de las partes supondrá la aceptación de la valoración realizada por el Perito de la otra, cualquiera que fuera la diferencia entre ambas valoraciones.\nEntregada en la Delegación de Hacienda u órgano equivalente de la Comunidad Autónoma la valoración por el tercer Perito, se comunicará al interesado y, al mismo tiempo, se le concederá un plazo de quince días para justificar el pago de los honorarios a su cargo. En su caso, se autorizará la disposición de la provisión de honorarios depositados en el Banco de España.","u":"#a9-10","c":"Reglamento del Impuesto sobre Sucesiones y Donaciones · TITULO IV. Tasación pericial contradictoria"},{"n":"RISD","a":"99","t":"Principio general sobre admisión de documentos.","x":"1. Los documentos que contengan actos o contratos de los que resulte la existencia de un incremento de patrimonio adquirido a título lucrativo, no se admitirán ni surtirán efecto en oficinas o registros públicos sin que conste en ellos la nota de presentación en la oficina competente para practicar la liquidación o la del ingreso de la correspondiente autoliquidación o la de declaración de exención o no sujeción consignada en ellos por la oficina gestora a la vista de la declaración-liquidación presentada, salvo lo previsto en la legislación hipotecaria o autorización expresa de la Administración.\n2. Los Juzgados y Tribunales que hubiesen admitido los documentos a que se refiere el número anterior sin las notas que en él se indican, remitirán a los órganos de la Administración tributaria de su jurisdicción copia autorizada de los mismos, en el plazo de los quince días siguientes al de su admisión.","u":"#a9-11","c":"Reglamento del Impuesto sobre Sucesiones y Donaciones · TITULO V. Cierre registral"},{"n":"RISD","a":"100","t":"Cierre registral.","x":"1. Los Registros de la Propiedad, Mercantiles, y de la Propiedad Industrial, no admitirán para su inscripción o anotación ningún documento que contenga acto o contrato del que resulte la adquisición de un incremento de patrimonio o título lucrativo, sin que se justifique el pago de la liquidación correspondiente por el Impuesto sobre Sucesiones y Donaciones o, en su caso, la declaración de exención o no sujeción, o la presentación de aquél ante los órganos competentes para su liquidación.\n2. A los efectos prevenidos en el número anterior se considerará acreditado el pago del Impuesto siempre que el documento lleve la nota justificativa del mismo y se presente acompañado de la carta de pago o del correspondiente ejemplar de la autoliquidación debidamente sellada por la oficina competente y constando en ella el pago del tributo o la alegación de no sujeción o de los beneficios fiscales aplicables.\n3. Cuando se encontrare pendiente de liquidación, provisional o definitiva, el documento o la declaración presentada en la oficina competente y en los casos de autoliquidación, el Registrador hará constar, mediante nota al margen de la inscripción, que el bien o derecho transmitido queda afecto al pago de la liquidación o liquidaciones que proceda practicar. Cuando exista liquidación provisional o se haya realizado algún ingreso por la autoliquidación se expresará el importe satisfecho.\n4. La nota se extenderá de oficio, quedando sin efecto y debiendo ser cancelada cuando se presente la carta de pago de las liquidaciones cuyo pago garantizaba o se justifique fehacientemente de cualquier otra manera el ingreso de las mismas y, en todo caso, transcurridos cinco años desde su fecha.","u":"#a1-13","c":"Reglamento del Impuesto sobre Sucesiones y Donaciones · TITULO V. Cierre registral"},{"n":"TRLRHL","a":"104","t":"Naturaleza y hecho imponible. Supuestos de no sujeción.","x":"1. El Impuesto sobre el Incremento de Valor de los Terrenos de Naturaleza Urbana es un tributo directo que grava el incremento de valor que experimenten dichos terrenos y se ponga de manifiesto a consecuencia de la transmisión de la propiedad de los terrenos por cualquier título o de la constitución o transmisión de cualquier derecho real de goce, limitativo del dominio, sobre los referidos terrenos.\n2. No está sujeto a este impuesto el incremento de valor que experimenten los terrenos que tengan la consideración de rústicos a efectos del Impuesto sobre Bienes Inmuebles. En consecuencia con ello, está sujeto el incremento de valor que experimenten los terrenos que deban tener la consideración de urbanos, a efectos de dicho Impuesto sobre Bienes Inmuebles, con independencia de que estén o no contemplados como tales en el Catastro o en el padrón de aquél. A los efectos de este impuesto, estará asimismo sujeto a éste el incremento de valor que experimenten los terrenos integrados en los bienes inmuebles clasificados como de características especiales a efectos del Impuesto sobre Bienes Inmuebles.\n3. No se producirá la sujeción al impuesto en los supuestos de aportaciones de bienes y derechos realizadas por los cónyuges a la sociedad conyugal, adjudicaciones que a su favor y en pago de ellas se verifiquen y transmisiones que se hagan a los cónyuges en pago de sus haberes comunes.\nTampoco se producirá la sujeción al impuesto en los supuestos de transmisiones de bienes inmuebles entre cónyuges o a favor de los hijos, como consecuencia del cumplimiento de sentencias en los casos de nulidad, separación o divorcio matrimonial, sea cual sea el régimen económico matrimonial. Asimismo, no se producirá la sujeción al impuesto en los supuestos de transmisiones de bienes inmuebles a título lucrativo en beneficio de las hijas, hijos, menores o personas con discapacidad sujetas a patria potestad, tutela o con medidas de apoyo para el adecuado ejercicio de su capacidad jurídica, cuyo ejercicio se llevará a cabo por las mujeres fallecidas como consecuencia de violencia contra la mujer, en los términos en que se defina por la ley o por los instrumentos internacionales ratificados por España, cuando estas transmisiones lucrativas traigan causa del referido fallecimiento.\n4. No se devengará el impuesto con ocasión de las aportaciones o transmisiones de bienes inmuebles efectuadas a la Sociedad de Gestión de Activos Procedentes de la Reestructuración Bancaria, S.A. regulada en la disposición adicional séptima de la Ley 9/2012, de 14 de noviembre, de reestructuración y resolución de entidades de crédito, que se le hayan transferido, de acuerdo con lo establecido en el artículo 48 del Real Decreto 1559/2012, de 15 de noviembre, por el que se establece el régimen jurídico de las sociedades de gestión de activos.\nNo se producirá el devengo del impuesto con ocasión de las aportaciones o transmisiones realizadas por la Sociedad de Gestión de Activos Procedentes de la Reestructuración Bancaria, S.A., a entidades participadas directa o indirectamente por dicha Sociedad en al menos el 50 por ciento del capital, fondos propios, resultados o derechos de voto de la entidad participada en el momento inmediatamente anterior a la transmisión, o como consecuencia de la misma.\nNo se devengará el impuesto con ocasión de las aportaciones o transmisiones realizadas por la Sociedad de Gestión de Activos Procedentes de la Reestructuración Bancaria, S.A., o por las entidades constituidas por esta para cumplir con su objeto social, a los fondos de activos bancarios, a que se refiere la disposición adicional décima de la Ley 9/2012, de 14 de noviembre.\nNo se devengará el impuesto por las aportaciones o transmisiones que se produzcan entre los citados Fondos durante el período de tiempo de mantenimiento de la exposición del Fondo de Reestructuración Ordenada Bancaria a los Fondos, previsto en el apartado 10 de dicha disposición adicional décima.\nEn la posterior transmisión de los inmuebles se entenderá que el número de años a lo largo de los cuales se ha puesto de manifiesto el incremento de valor de los terrenos no se ha interrumpido por causa de la transmisión derivada de las operaciones previstas en este apartado.\n5. No se producirá la sujeción al impuesto en las transmisiones de terrenos respecto de los cuales se constate la inexistencia de incremento de valor por diferencia entre los valores de dichos terrenos en las fechas de transmisión y adquisición.\nPara ello, el interesado en acreditar la inexistencia de incremento de valor deberá declarar la transmisión, así como aportar los títulos que documenten la transmisión y la adquisición, entendiéndose por interesados, a estos efectos, las personas o entidades a que se refiere el artículo 106.\nPara constatar la inexistencia de incremento de valor, como valor de transmisión o de adquisición del terreno se tomará en cada caso el mayor de los siguientes valores, sin que a estos efectos puedan computarse los gastos o tributos que graven dichas operaciones: el que conste en el título que documente la operación o el comprobado, en su caso, por la Administración tributaria.\nCuando se trate de la transmisión de un inmueble en el que haya suelo y construcción, se tomará como valor del suelo a estos efectos el que resulte de aplicar la proporción que represente en la fecha de devengo del impuesto el valor catastral del terreno respecto del valor catastral total y esta proporción se aplicará tanto al valor de transmisión como, en su caso, al de adquisición.\nSi la adquisición o la transmisión hubiera sido a título lucrativo se aplicarán las reglas de los párrafos anteriores tomando, en su caso, por el primero de los dos valores a comparar señalados anteriormente, el declarado en el Impuesto sobre Sucesiones y Donaciones.\nEn la posterior transmisión de los inmuebles a los que se refiere este apartado, para el cómputo del número de años a lo largo de los cuales se ha puesto de manifiesto el incremento de valor de los terrenos, no se tendrá en cuenta el periodo anterior a su adquisición. Lo dispuesto en este párrafo no será de aplicación en los supuestos de aportaciones o transmisiones de bienes inmuebles que resulten no sujetas en virtud de lo dispuesto en el apartado 3 de este artículo o en la disposición adicional segunda de la Ley 27/2014, de 27 de noviembre, del Impuesto sobre Sociedades.","u":"#a104","c":"Sección 3.ª Impuestos · Subsección 6.ª Impuesto sobre el Incremento de Valor de los Terrenos de Naturaleza Urbana"},{"n":"TRLRHL","a":"105","t":"Exenciones.","x":"1. Estarán exentos de este impuesto los incrementos de valor que se manifiesten como consecuencia de los siguientes actos:\na) La constitución y transmisión de derechos de servidumbre.\nb) Las transmisiones de bienes que se encuentren dentro del perímetro delimitado como Conjunto Histórico-Artístico, o hayan sido declarados individualmente de interés cultural, según lo establecido en la Ley 16/1985, de 25 de junio, del Patrimonio Histórico Español, cuando sus propietarios o titulares de derechos reales acrediten que han realizado a su cargo obras de conservación, mejora o rehabilitación en dichos inmuebles. A estos efectos, la ordenanza fiscal establecerá los aspectos sustantivos y formales de la exención.\nc) Las transmisiones realizadas por personas físicas con ocasión de la dación en pago de la vivienda habitual del deudor hipotecario o garante del mismo, para la cancelación de deudas garantizadas con hipoteca que recaiga sobre la misma, contraídas con entidades de crédito o cualquier otra entidad que, de manera profesional, realice la actividad de concesión de préstamos o créditos hipotecarios.\nAsimismo, estarán exentas las transmisiones de la vivienda en que concurran los requisitos anteriores, realizadas en ejecuciones hipotecarias judiciales o notariales.\nPara tener derecho a la exención se requiere que el deudor o garante transmitente o cualquier otro miembro de su unidad familiar no disponga, en el momento de poder evitar la enajenación de la vivienda, de otros bienes o derechos en cuantía suficiente para satisfacer la totalidad de la deuda hipotecaria. Se presumirá el cumplimiento de este requisito. No obstante, si con posterioridad se comprobara lo contrario, se procederá a girar la liquidación tributaria correspondiente.\nA estos efectos, se considerará vivienda habitual aquella en la que haya figurado empadronado el contribuyente de forma ininterrumpida durante, al menos, los dos años anteriores a la transmisión o desde el momento de la adquisición si dicho plazo fuese inferior a los dos años.\nRespecto al concepto de unidad familiar, se estará a lo dispuesto en la Ley 35/2006, de 28 de noviembre, del Impuesto sobre la Renta de las Personas Físicas y de modificación parcial de las leyes de los Impuestos sobre Sociedades, sobre la Renta de no Residentes y sobre el Patrimonio. A estos efectos, se equiparará el matrimonio con la pareja de hecho legalmente inscrita.\nRespecto de esta exención, no resultará de aplicación lo dispuesto en el artículo 9.2 de esta Ley.\n2. Asimismo, estarán exentos de este impuesto los correspondientes incrementos de valor cuando la obligación de satisfacer aquél recaiga sobre las siguientes personas o entidades:\na) El Estado, las comunidades autónomas y las entidades locales, a las que pertenezca el municipio, así como los organismos autónomos del Estado y las entidades de derecho público de análogo carácter de las comunidades autónomas y de dichas entidades locales.\nb) El municipio de la imposición y demás entidades locales integradas o en las que se integre dicho municipio, así como sus respectivas entidades de derecho público de análogo carácter a los organismos autónomos del Estado.\nc) Las instituciones que tengan la calificación de benéficas o de benéfico-docentes.\nd) Las entidades gestoras de la Seguridad Social y las mutualidades de previsión social reguladas en la Ley 30/1995, de 8 de noviembre, de ordenación y supervisión de los seguros privados.\ne) Los titulares de concesiones administrativas revertibles respecto a los terrenos afectos a éstas.\nf) La Cruz Roja Española.\ng) Las personas o entidades a cuyo favor se haya reconocido la exención en tratados o convenios internacionales.","u":"#a105","c":"Sección 3.ª Impuestos · Subsección 6.ª Impuesto sobre el Incremento de Valor de los Terrenos de Naturaleza Urbana"},{"n":"TRLRHL","a":"106","t":"Sujetos pasivos.","x":"1. Es sujeto pasivo del impuesto a título de contribuyente:\na) En las transmisiones de terrenos o en la constitución o transmisión de derechos reales de goce limitativos del dominio a título lucrativo, la persona física o jurídica, o la entidad a que se refiere el artículo 35.4 de la Ley 58/2003, de 17 de diciembre, General Tributaria, que adquiera el terreno o a cuyo favor se constituya o transmita el derecho real de que se trate.\nb) En las transmisiones de terrenos o en la constitución o transmisión de derechos reales de goce limitativos del dominio a título oneroso, la persona física o jurídica, o la entidad a que se refiere el artículo 35.4 de la Ley 58/2003, de 17 de diciembre, General Tributaria, que transmita el terreno, o que constituya o transmita el derecho real de que se trate.\n2. En los supuestos a que se refiere el párrafo b) del apartado anterior, tendrá la consideración de sujeto pasivo sustituto del contribuyente, la persona física o jurídica, o la entidad a que se refiere el artículo 35.4 de la Ley 58/2003, de 17 de diciembre, General Tributaria, que adquiera el terreno o a cuyo favor se constituya o transmita el derecho real de que se trate, cuando el contribuyente sea una persona física no residente en España.","u":"#a106","c":"Sección 3.ª Impuestos · Subsección 6.ª Impuesto sobre el Incremento de Valor de los Terrenos de Naturaleza Urbana"},{"n":"TRLRHL","a":"107","t":"Base imponible.","x":"1. La base imponible de este impuesto está constituida por el incremento del valor de los terrenos puesto de manifiesto en el momento del devengo y experimentado a lo largo de un periodo máximo de veinte años, y se determinará, sin perjuicio de lo dispuesto en el apartado 5 de este artículo, multiplicando el valor del terreno en el momento del devengo calculado conforme a lo establecido en sus apartados 2 y 3, por el coeficiente que corresponda al periodo de generación conforme a lo previsto en su apartado 4.\n2. El valor del terreno en el momento del devengo resultará de lo establecido en las siguientes reglas:\na) En las transmisiones de terrenos, el valor de estos en el momento del devengo será el que tengan determinado en dicho momento a efectos del Impuesto sobre Bienes Inmuebles.\nNo obstante, cuando dicho valor sea consecuencia de una ponencia de valores que no refleje modificaciones de planeamiento aprobadas con posterioridad a la aprobación de la citada ponencia, se podrá liquidar provisionalmente este impuesto con arreglo a aquel. En estos casos, en la liquidación definitiva se aplicará el valor de los terrenos una vez se haya obtenido conforme a los procedimientos de valoración colectiva que se instruyan, referido a la fecha del devengo. Cuando esta fecha no coincida con la de efectividad de los nuevos valores catastrales, estos se corregirán aplicando los coeficientes de actualización que correspondan, establecidos al efecto en las leyes de presupuestos generales del Estado.\nCuando el terreno, aun siendo de naturaleza urbana o integrado en un bien inmueble de características especiales, en el momento del devengo del impuesto, no tenga determinado valor catastral en dicho momento, el ayuntamiento podrá practicar la liquidación cuando el referido valor catastral sea determinado, refiriendo dicho valor al momento del devengo.\nLos ayuntamientos podrán establecer en la ordenanza fiscal un coeficiente reductor sobre el valor señalado en los párrafos anteriores que pondere su grado de actualización, con el máximo del 15 por ciento.\nb) En la constitución y transmisión de derechos reales de goce limitativos del dominio, los porcentajes anuales contenidos en el apartado 4 de este artículo se aplicarán sobre la parte del valor definido en el párrafo a) anterior que represente, respecto de aquel, el valor de los referidos derechos calculado mediante la aplicación de las normas fijadas a efectos del Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados.\nc) En la constitución o transmisión del derecho a elevar una o más plantas sobre un edificio o terreno, o del derecho de realizar la construcción bajo suelo sin implicar la existencia de un derecho real de superficie, los porcentajes anuales contenidos en el apartado 4 de este artículo se aplicarán sobre la parte del valor definido en el párrafo a) que represente, respecto de aquel, el módulo de proporcionalidad fijado en la escritura de transmisión o, en su defecto, el que resulte de establecer la proporción entre la superficie o volumen de las plantas a construir en vuelo o subsuelo y la total superficie o volumen edificados una vez construidas aquellas.\nd) En los supuestos de expropiaciones forzosas, los porcentajes anuales contenidos en el apartado 4 de este artículo se aplicarán sobre la parte del justiprecio que corresponda al valor del terreno, salvo que el valor definido en el párrafo a) del apartado 2 anterior fuese inferior, en cuyo caso prevalecerá este último sobre el justiprecio.\n3. Los ayuntamientos podrán establecer una reducción cuando se modifiquen los valores catastrales como consecuencia de un procedimiento de valoración colectiva de carácter general. En ese caso, se tomará como valor del terreno, o de la parte de este que corresponda según las reglas contenidas en el apartado anterior, el importe que resulte de aplicar a los nuevos valores catastrales dicha reducción durante el período de tiempo y porcentajes máximos siguientes:\na) La reducción, en su caso, se aplicará, como máximo, respecto de cada uno de los cinco primeros años de efectividad de los nuevos valores catastrales.\nb) La reducción tendrá como porcentaje máximo el 60 por ciento. Los ayuntamientos podrán fijar un tipo de reducción distinto para cada año de aplicación de la reducción.\nLa reducción prevista en este apartado no será de aplicación a los supuestos en los que los valores catastrales resultantes del procedimiento de valoración colectiva a que aquel se refiere sean inferiores a los hasta entonces vigentes.\nEl valor catastral reducido en ningún caso podrá ser inferior al valor catastral del terreno antes del procedimiento de valoración colectiva.\nLa regulación de los restantes aspectos sustantivos y formales de la reducción se establecerá en la ordenanza fiscal.\n4. El periodo de generación del incremento de valor será el número de años a lo largo de los cuales se haya puesto de manifiesto dicho incremento.\nEn los supuestos de no sujeción, salvo que por ley se indique otra cosa, para el cálculo del periodo de generación del incremento de valor puesto de manifiesto en una posterior transmisión del terreno, se tomará como fecha de adquisición, a los efectos de lo dispuesto en el párrafo anterior, aquella en la que se produjo el anterior devengo del impuesto.\nEn el cómputo del número de años transcurridos se tomarán años completos, es decir, sin tener en cuenta las fracciones de año. En el caso de que el periodo de generación sea inferior a un año, se prorrateará el coeficiente anual teniendo en cuenta el número de meses completos, es decir, sin tener en cuenta las fracciones de mes.\nEl coeficiente a aplicar sobre el valor del terreno en el momento del devengo, calculado conforme a lo dispuesto en los apartados anteriores, será el que corresponda de los aprobados por el ayuntamiento según el periodo de generación del incremento de valor, sin que pueda exceder de los límites siguientes:\n| Periodo de generación | Coeficiente |\n| --------------------------- | ----------- |\n| Inferior a 1 año. | 0,17 |\n| 1 año. | 0,16 |\n| 2 años. | 0,16 |\n| 3 años. | 0,17 |\n| 4 años. | 0,17 |\n| 5 años. | 0,19 |\n| 6 años. | 0,21 |\n| 7 años. | 0,23 |\n| 8 años. | 0,24 |\n| 9 años. | 0,25 |\n| 10 años. | 0,22 |\n| 11 años. | 0,18 |\n| 12 años. | 0,14 |\n| 13 años. | 0,12 |\n| 14 años. | 0,11 |\n| 15 años. | 0,11 |\n| 16 años. | 0,11 |\n| 17 años. | 0,11 |\n| 18 años. | 0,13 |\n| 19 años. | 0,20 |\n| Igual o superior a 20 años. | 0,30 |\nEstos coeficientes máximos serán actualizados anualmente mediante norma con rango legal, pudiendo llevarse a cabo dicha actualización mediante las leyes de presupuestos generales del Estado.\nSi, como consecuencia de la actualización referida en el párrafo anterior, alguno de los coeficientes aprobados por la vigente ordenanza fiscal resultara ser superior al correspondiente nuevo máximo legal, se aplicará este directamente hasta que entre en vigor la nueva ordenanza fiscal que corrija dicho exceso.\n5. Cuando, a instancia del sujeto pasivo, conforme al procedimiento establecido en el artículo 104.5, se constate que el importe del incremento de valor es inferior al importe de la base imponible determinada con arreglo a lo dispuesto en los apartados anteriores de este artículo, se tomará como base imponible el importe de dicho incremento de valor.","u":"#a107","c":"Sección 3.ª Impuestos · Subsección 6.ª Impuesto sobre el Incremento de Valor de los Terrenos de Naturaleza Urbana"},{"n":"TRLRHL","a":"108","t":"Tipo de gravamen. Cuota íntegra y cuota líquida.","x":"1. El tipo de gravamen del impuesto será el fijado por cada ayuntamiento, sin que dicho tipo pueda exceder del 30 por ciento.\nDentro del límite señalado en el párrafo anterior, los ayuntamientos podrán fijar un solo tipo de gravamen o uno para cada uno de los períodos de generación del incremento de valor indicados en el apartado 4 del artículo anterior.\n2. La cuota íntegra del impuesto será el resultado de aplicar a la base imponible el tipo de gravamen.\n3. La cuota líquida del impuesto será el resultado de aplicar sobre la cuota íntegra, en su caso, las bonificaciones a que se refieren los apartados siguientes.\n4. Las ordenanzas fiscales podrán regular una bonificación de hasta el 95 por ciento de la cuota íntegra del impuesto, en las transmisiones de terrenos, y en la transmisión o constitución de derechos reales de goce limitativos del dominio, realizadas a título lucrativo por causa de muerte a favor de los descendientes y adoptados, los cónyuges y los ascendientes y adoptantes.\n5. Las ordenanzas fiscales podrán regular una bonificación de hasta el 95 por ciento de la cuota íntegra del impuesto, en las transmisiones de terrenos, y en la transmisión o constitución de derechos reales de goce limitativos del dominio de terrenos, sobre los que se desarrollen actividades económicas que sean declaradas de especial interés o utilidad municipal por concurrir circunstancias sociales, culturales, histórico artísticas o de fomento del empleo que justifiquen tal declaración. Corresponderá dicha declaración al Pleno de la Corporación y se acordará, previa solicitud del sujeto pasivo, por voto favorable de la mayoría simple de sus miembros.\n6. La regulación de los restantes aspectos sustantivos y formales de las bonificaciones a que se refieren los apartados anteriores se establecerá en la ordenanza fiscal.","u":"#a108","c":"Sección 3.ª Impuestos · Subsección 6.ª Impuesto sobre el Incremento de Valor de los Terrenos de Naturaleza Urbana"},{"n":"TRLRHL","a":"109","t":"Devengo.","x":"1. El impuesto se devenga:\na) Cuando se transmita la propiedad del terreno, ya sea a título oneroso o gratuito, entre vivos o por causa de muerte, en la fecha de la transmisión.\nb) Cuando se constituya o transmita cualquier derecho real de goce limitativo del dominio, en la fecha en que tenga lugar la constitución o transmisión.\n2. Cuando se declare o reconozca judicial o administrativamente por resolución firme haber tenido lugar la nulidad, rescisión o resolución del acto o contrato determinante de la transmisión del terreno o de la constitución o transmisión del derecho real de goce sobre aquel, el sujeto pasivo tendrá derecho a la devolución del impuesto satisfecho, siempre que dicho acto o contrato no le hubiere producido efectos lucrativos y que reclame la devolución en el plazo de cinco años desde que la resolución quedó firme, entendiéndose que existe efecto lucrativo cuando no se justifique que los interesados deban efectuar las recíprocas devoluciones a que se refiere el artículo 1.295 del Código Civil. Aunque el acto o contrato no haya producido efectos lucrativos, si la rescisión o resolución se declarase por incumplimiento de las obligaciones del sujeto pasivo del impuesto, no habrá lugar a devolución alguna.\n3. Si el contrato queda sin efecto por mutuo acuerdo de las partes contratantes, no procederá la devolución del impuesto satisfecho y se considerará como un acto nuevo sujeto a tributación. Como tal mutuo acuerdo se estimará la avenencia en acto de conciliación y el simple allanamiento a la demanda.\n4. En los actos o contratos en que medie alguna condición, su calificación se hará con arreglo a las prescripciones contenidas en el Código Civil. Si fuese suspensiva no se liquidará el impuesto hasta que ésta se cumpla. Si la condición fuese resolutoria, se exigirá el impuesto desde luego, a reserva, cuando la condición se cumpla, de hacer la oportuna devolución según la regla del apartado anterior.","u":"#a109","c":"Sección 3.ª Impuestos · Subsección 6.ª Impuesto sobre el Incremento de Valor de los Terrenos de Naturaleza Urbana"},{"n":"TRLRHL","a":"110","t":"Gestión tributaria del impuesto.","x":"1. Los sujetos pasivos vendrán obligados a presentar ante el ayuntamiento correspondiente la declaración que determine la ordenanza respectiva, conteniendo los elementos de la relación tributaria imprescindibles para practicar la liquidación procedente.\n2. Dicha declaración deberá ser presentada en los siguientes plazos, a contar desde la fecha en que se produzca el devengo del impuesto:\na) Cuando se trate de actos ínter vivos, el plazo será de treinta días hábiles.\nb) Cuando se trate de actos por causa de muerte, el plazo será de seis meses prorrogables hasta un año a solicitud del sujeto pasivo.\n3. A la declaración se acompañará el documento en el que consten los actos o contratos que originan la imposición.\n4. Los ayuntamientos quedan facultados para establecer el sistema de autoliquidación por el sujeto pasivo, que llevará consigo el ingreso de la cuota resultante de aquella dentro de los plazos previstos en el apartado 2 de este artículo. Respecto de dichas autoliquidaciones, sin perjuicio de las facultades de comprobación de los valores declarados por el interesado o el sujeto pasivo a los efectos de lo dispuesto en los artículos 104.5 y 107.5, respectivamente, el ayuntamiento correspondiente solo podrá comprobar que se han efectuado mediante la aplicación correcta de las normas reguladoras del impuesto, sin que puedan atribuirse valores, bases o cuotas diferentes de las resultantes de tales normas.\nEn ningún caso podrá exigirse el impuesto en régimen de autoliquidación cuando se trate del supuesto a que se refiere el artículo 107.2.a), párrafo tercero.\n5. Cuando los ayuntamientos no establezcan el sistema de autoliquidación, las liquidaciones del impuesto se notificaran íntegramente a los sujetos pasivos con indicación del plazo de ingreso y expresión de los recursos procedentes.\n6. Con independencia de lo dispuesto en el apartado 1 de este artículo, están igualmente obligados a comunicar al ayuntamiento la realización del hecho imponible en los mismos plazos que los sujetos pasivos:\na) En los supuestos contemplados en el párrafo a) del artículo 106 de esta ley, siempre que se hayan producido por negocio jurídico entre vivos, el donante o la persona que constituya o transmita el derecho real de que se trate.\nb) En los supuestos contemplados en el párrafo b) de dicho artículo, el adquirente o la persona a cuyo favor se constituya o transmita el derecho real de que se trate.\n7. Asimismo, los notarios estarán obligados a remitir al ayuntamiento respectivo, dentro de la primera quincena de cada trimestre, relación o índice comprensivo de todos los documentos por ellos autorizados en el trimestre anterior, en los que se contengan hechos, actos o negocios jurídicos que pongan de manifiesto la realización del hecho imponible de este impuesto, con excepción de los actos de última voluntad. También estarán obligados a remitir, dentro del mismo plazo, relación de los documentos privados comprensivos de los mismos hechos, actos o negocios jurídicos, que les hayan sido presentados para conocimiento o legitimación de firmas. Lo prevenido en este apartado se entiende sin perjuicio del deber general de colaboración establecido en la Ley General Tributaria.\nEn la relación o índice que remitan los notarios al ayuntamiento, éstos deberán hacer constar la referencia catastral de los bienes inmuebles cuando dicha referencia se corresponda con los que sean objeto de transmisión. Esta obligación será exigible a partir de 1 de abril de 2002.\nLos notarios advertirán expresamente a los comparecientes en los documentos que autoricen sobre el plazo dentro del cual están obligados los interesados a presentar declaración por el impuesto y, asimismo, sobre las responsabilidades en que incurran por la falta de presentación de declaraciones.\n8. Con arreglo a lo dispuesto en el artículo 8, las Administraciones tributarias de las comunidades autónomas y de las entidades locales colaborarán para la aplicación del impuesto y, en particular, para dar cumplimiento a lo establecido en los artículos 104.5 y 107.5, pudiendo suscribirse para ello los correspondientes convenios de intercambio de información tributaria y de colaboración.","u":"#a110","c":"Sección 3.ª Impuestos · Subsección 6.ª Impuesto sobre el Incremento de Valor de los Terrenos de Naturaleza Urbana"},{"n":"LGT","a":"26","t":"Interés de demora.","x":"1. El interés de demora es una prestación accesoria que se exigirá a los obligados tributarios y a los sujetos infractores como consecuencia de la realización de un pago fuera de plazo o de la presentación de una autoliquidación o declaración de la que resulte una cantidad a ingresar una vez finalizado el plazo establecido al efecto en la normativa tributaria, del cobro de una devolución improcedente o en el resto de casos previstos en la normativa tributaria.\nLa exigencia del interés de demora tributario no requiere la previa intimación de la Administración ni la concurrencia de un retraso culpable en el obligado.\n2. El interés de demora se exigirá, entre otros, en los siguientes supuestos:\na) Cuando finalice el plazo establecido para el pago en período voluntario de una deuda resultante de una liquidación practicada por la Administración o del importe de una sanción, sin que el ingreso se hubiera efectuado.\nb) Cuando finalice el plazo establecido para la presentación de una autoliquidación o declaración sin que hubiera sido presentada o hubiera sido presentada incorrectamente, salvo lo dispuesto en el apartado 2 del artículo 27 de esta ley relativo a la presentación de declaraciones extemporáneas sin requerimiento previo.\nc) Cuando se suspenda la ejecución del acto, salvo en el supuesto de recursos y reclamaciones contra sanciones durante el tiempo que transcurra hasta la finalización del plazo de pago en período voluntario abierto por la notificación de la resolución que ponga fin a la vía administrativa.\nd) Cuando se inicie el período ejecutivo, salvo lo dispuesto en el apartado 5 del artículo 28 de esta ley respecto a los intereses de demora cuando sea exigible el recargo ejecutivo o el recargo de apremio reducido.\ne) Cuando se reciba una petición de cobro de deudas de titularidad de otros Estados o de entidades internacionales o supranacionales conforme a la normativa sobre asistencia mutua, salvo que dicha normativa establezca otra cosa.\nf) Cuando el obligado tributario haya obtenido una devolución improcedente, salvo que voluntariamente regularice su situación tributaria sin perjuicio de lo dispuesto en el apartado 2 del artículo 27 de esta Ley relativo a la presentación de declaraciones extemporáneas sin requerimiento previo.\n3. El interés de demora se calculará sobre el importe no ingresado en plazo o sobre la cuantía de la devolución cobrada improcedentemente, y resultará exigible durante el tiempo al que se extienda el retraso del obligado, salvo lo dispuesto en el apartado siguiente.\n4. No se exigirán intereses de demora desde el momento en que la Administración tributaria incumpla por causa imputable a la misma alguno de los plazos fijados en esta ley para resolver hasta que se dicte dicha resolución o se interponga recurso contra la resolución presunta. Entre otros supuestos, no se exigirán intereses de demora a partir del momento en que se incumplan los plazos máximos para notificar la resolución de las solicitudes de compensación, el acto de liquidación o la resolución de los recursos administrativos, siempre que, en este último caso, se haya acordado la suspensión del acto recurrido.\nLo dispuesto en este apartado no se aplicará al incumplimiento del plazo para resolver las solicitudes de aplazamiento o fraccionamiento del pago.\n5. En los casos en que resulte necesaria la práctica de una nueva liquidación como consecuencia de haber sido anulada otra liquidación por una resolución administrativa o judicial, se conservarán íntegramente los actos y trámites no afectados por la causa de anulación, con mantenimiento íntegro de su contenido, y exigencia del interés de demora sobre el importe de la nueva liquidación. En estos casos, la fecha de inicio del cómputo del interés de demora será la misma que, de acuerdo con lo establecido en el apartado 2 de este artículo, hubiera correspondido a la liquidación anulada y el interés se devengará hasta el momento en que se haya dictado la nueva liquidación, sin que el final del cómputo pueda ser posterior al plazo máximo para ejecutar la resolución.\n6. El interés de demora será el interés legal del dinero vigente a lo largo del período en el que aquél resulte exigible, incrementado en un 25 por ciento, salvo que la Ley de Presupuestos Generales del Estado establezca otro diferente.\nNo obstante, en los supuestos de aplazamiento, fraccionamiento o suspensión de deudas garantizadas en su totalidad mediante aval solidario de entidad de crédito o sociedad de garantía recíproca o mediante certificado de seguro de caución, el interés de demora exigible será el interés legal.","u":"#a26","c":"Sección 2.ª Las obligaciones tributarias · Subsección 4.ª Las obligaciones tributarias accesorias"},{"n":"LGT","a":"27","t":"Recargos por declaración extemporánea sin requerimiento previo.","x":"1. Los recargos por declaración extemporánea son prestaciones accesorias que deben satisfacer los obligados tributarios como consecuencia de la presentación de autoliquidaciones o declaraciones fuera de plazo sin requerimiento previo de la Administración tributaria.\nA los efectos de este artículo, se considera requerimiento previo cualquier actuación administrativa realizada con conocimiento formal del obligado tributario conducente al reconocimiento, regularización, comprobación, inspección, aseguramiento o liquidación de la deuda tributaria.\n2. El recargo será un porcentaje igual al 1 por ciento más otro 1 por ciento adicional por cada mes completo de retraso con que se presente la autoliquidación o declaración respecto al término del plazo establecido para la presentación e ingreso.\nDicho recargo se calculará sobre el importe a ingresar resultante de las autoliquidaciones o sobre el importe de la liquidación derivado de las declaraciones extemporáneas y excluirá las sanciones que hubieran podido exigirse y los intereses de demora devengados hasta la presentación de la autoliquidación o declaración.\nSi la presentación de la autoliquidación o declaración se efectúa una vez transcurridos 12 meses desde el término del plazo establecido para la presentación, el recargo será del 15 por ciento y excluirá las sanciones que hubieran podido exigirse. En estos casos, se exigirán los intereses de demora por el período transcurrido desde el día siguiente al término de los 12 meses posteriores a la finalización del plazo establecido para la presentación hasta el momento en que la autoliquidación o declaración se haya presentado.\nEn las liquidaciones derivadas de declaraciones presentadas fuera de plazo sin requerimiento previo no se exigirán intereses de demora por el tiempo transcurrido desde la presentación de la declaración hasta la finalización del plazo de pago en período voluntario correspondiente a la liquidación que se practique, sin perjuicio de los recargos e intereses que corresponda exigir por la presentación extemporánea.\nNo obstante lo anterior, no se exigirán los recargos de este apartado si el obligado tributario regulariza, mediante la presentación de una declaración o autoliquidación correspondiente a otros períodos del mismo concepto impositivo, unos hechos o circunstancias idénticos a los regularizados por la Administración, y concurren las siguientes circunstancias:\na) Que la declaración o autoliquidación se presente en el plazo de seis meses a contar desde el día siguiente a aquél en que la liquidación se notifique o se entienda notificada.\nb) Que se produzca el completo reconocimiento y pago de las cantidades resultantes de la declaración o autoliquidación en los términos previstos en el apartado 5 de este artículo.\nc) Que no se presente solicitud de rectificación de la declaración o autoliquidación, ni se interponga recurso o reclamación contra la liquidación dictada por la Administración.\nd) Que de la regularización efectuada por la Administración no derive la imposición de una sanción.\nEl incumplimiento de cualquiera de estas circunstancias determinará la exigencia del recargo correspondiente sin más requisito que la notificación al interesado.\nLo dispuesto en los párrafos anteriores no impedirá el inicio de un procedimiento de comprobación o investigación en relación con las obligaciones tributarias regularizadas mediante las declaraciones o autoliquidaciones a que los mismos se refieren.\n3. Cuando los obligados tributarios no efectúen el ingreso ni presenten solicitud de aplazamiento, fraccionamiento o compensación al tiempo de la presentación de la autoliquidación extemporánea, la liquidación administrativa que proceda por recargos e intereses de demora derivada de la presentación extemporánea según lo dispuesto en el apartado anterior no impedirá la exigencia de los recargos e intereses del período ejecutivo que correspondan sobre el importe de la autoliquidación.\n4. Para que pueda ser aplicable lo dispuesto en este artículo, las autoliquidaciones extemporáneas deberán identificar expresamente el período impositivo de liquidación al que se refieren y deberán contener únicamente los datos relativos a dicho período.\n5. El importe de los recargos a que se refiere el apartado 2 anterior se reducirá en el 25 por ciento siempre que se realice el ingreso total del importe restante del recargo en el plazo del apartado 2 del artículo 62 de esta Ley abierto con la notificación de la liquidación de dicho recargo y siempre que se realice el ingreso total del importe de la deuda resultante de la autoliquidación extemporánea o de la liquidación practicada por la Administración derivada de la declaración extemporánea, al tiempo de su presentación o en el plazo del apartado 2 del artículo 62 de esta Ley, respectivamente, o siempre que se realice el ingreso en el plazo o plazos fijados en el acuerdo de aplazamiento o fraccionamiento de dicha deuda que la Administración tributaria hubiera concedido con garantía de aval o certificado de seguro de caución y que el obligado al pago hubiera solicitado al tiempo de presentar la autoliquidación extemporánea o con anterioridad a la finalización del plazo del apartado 2 del artículo 62 de esta Ley abierto con la notificación de la liquidación resultante de la declaración extemporánea.\nEl importe de la reducción practicada de acuerdo con lo dispuesto en este apartado se exigirá sin más requisito que la notificación al interesado, cuando no se hayan realizado los ingresos a que se refiere el párrafo anterior en los plazos previstos incluidos los correspondientes al acuerdo de aplazamiento o fraccionamiento.","u":"#a27","c":"Sección 2.ª Las obligaciones tributarias · Subsección 4.ª Las obligaciones tributarias accesorias"},{"n":"LGT","a":"62","t":"Plazos para el pago.","x":"1. Las deudas tributarias resultantes de una autoliquidación deberán pagarse en los plazos que establezca la normativa de cada tributo.\n2. En el caso de deudas tributarias resultantes de liquidaciones practicadas por la Administración, el pago en período voluntario deberá hacerse en los siguientes plazos:\na) Si la notificación de la liquidación se realiza entre los días uno y 15 de cada mes, desde la fecha de recepción de la notificación hasta el día 20 del mes posterior o, si éste no fuera hábil, hasta el inmediato hábil siguiente.\nb) Si la notificación de la liquidación se realiza entre los días 16 y último de cada mes, desde la fecha de recepción de la notificación hasta el día cinco del segundo mes posterior o, si éste no fuera hábil, hasta el inmediato hábil siguiente.\n3. El pago en período voluntario de las deudas de notificación colectiva y periódica que no tengan establecido otro plazo en sus normas reguladoras deberá efectuarse en el período comprendido entre el día uno de septiembre y el 20 de noviembre o, si éste no fuera hábil, hasta el inmediato hábil siguiente.\nLa Administración tributaria competente podrá modificar el plazo señalado en el párrafo anterior siempre que dicho plazo no sea inferior a dos meses.\n4. Las deudas que deban abonarse mediante efectos timbrados se pagarán en el momento de la realización del hecho imponible, si no se dispone otro plazo en su normativa específica.\n5. Una vez iniciado el período ejecutivo y notificada la providencia de apremio, el pago de la deuda tributaria deberá efectuarse en los siguientes plazos:\na) Si la notificación de la providencia se realiza entre los días uno y 15 de cada mes, desde la fecha de recepción de la notificación hasta el día 20 de dicho mes o, si éste no fuera hábil, hasta el inmediato hábil siguiente.\nb) Si la notificación de la providencia se realiza entre los días 16 y último de cada mes, desde la fecha de recepción de la notificación hasta el día cinco del mes siguiente o, si éste no fuera hábil, hasta el inmediato hábil siguiente.\n6. El pago de las deudas de titularidad de otros Estados o entidades internacionales o supranacionales cuya actuación recaudatoria se realice en el marco de la asistencia mutua será requerido al obligado tributario, que deberá efectuarlo en los siguientes plazos:\na) Si la notificación del instrumento de ejecución se realiza entre los días uno y 15 de cada mes, desde la fecha de recepción de la notificación hasta el día 20 de dicho mes o, si éste no fuera hábil, hasta el inmediato hábil siguiente.\nb) Si la notificación del instrumento de ejecución se realiza entre los días 16 y último de cada mes, desde la fecha de recepción de la notificación hasta el día cinco del mes siguiente o, si éste no fuera hábil, hasta el inmediato hábil siguiente.\nNo obstante lo anterior, cuando la norma reguladora de la asistencia mutua lo permita, la Administración tributaria podrá desarrollar actuaciones recaudatorias desde la recepción de la solicitud de cobro del Estado o entidad internacional o supranacional requirente, sin necesidad de que haya concluido el plazo al que se refiere este apartado.\n7. Las deudas tributarias aduaneras y fiscales derivadas de operaciones de comercio exterior deberán pagarse en el plazo establecido por su propia normativa.\n8. En los supuestos en los que la ley de cada tributo lo establezca, el ingreso de la deuda de un obligado tributario podrá suspenderse total o parcialmente, sin aportación de garantía y a solicitud de éste, si otro obligado presenta una declaración o autoliquidación de la que resulte una cantidad a devolver o una comunicación de datos, con indicación de que el importe de la devolución que pueda ser reconocido se destine a la cancelación de la deuda cuya suspensión se pretende.\nEl importe de la deuda suspendida no podrá ser superior a la devolución solicitada.\nLa deuda suspendida quedará total o parcialmente extinguida en el importe que proceda de la devolución reconocida, sin que sean exigibles intereses de demora sobre la deuda cancelada con cargo a la devolución.\n9. El ingreso de la deuda de un obligado tributario se suspenderá total o parcialmente, sin aportación de garantías, cuando se compruebe que por la misma operación se ha satisfecho a la misma u otra Administración una deuda tributaria o se ha soportado la repercusión de otro impuesto, siempre que el pago realizado o la repercusión soportada fuera incompatible con la deuda exigida y, además, en este último caso, el sujeto pasivo no tenga derecho a la completa deducción del importe soportado indebidamente.\nReglamentariamente se regulará el procedimiento para la extinción de las deudas tributarias a las que se refiere el párrafo anterior y, en los casos en que se hallen implicadas dos Administraciones tributarias, los mecanismos de compensación entre éstas.","u":"#a62","c":"CAPÍTULO IV. La deuda tributaria · Sección 2.ª El pago"},{"n":"LH","a":"14","t":"","x":"El título de la sucesión hereditaria, a los efectos del Registro, es el testamento, el contrato sucesorio, el acta de notoriedad para la declaración de herederos abintestato y la declaración administrativa de heredero abintestato a favor del Estado, así como, en su caso, el certificado sucesorio europeo al que se refiere el capítulo VI del Reglamento (UE) n.º 650/2012.\nPara inscribir bienes y adjudicaciones concretas deberán determinarse en escritura pública o por sentencia firme los bienes, o parte indivisa de los mismos que correspondan o se adjudiquen a cada titular o heredero, con la sola excepción de lo ordenado en el párrafo siguiente.\nCuando se tratare de heredero único, y no exista ningún interesado con derecho a legítima, ni tampoco Comisario o persona autorizada para adjudicar la herencia, el título de la sucesión, acompañado de los documentos a que se refiere el artículo dieciséis de esta Ley, bastará para inscribir directamente a favor del heredero los bienes y derechos de que en el Registro era titular el causante.","u":"#a14","c":"LEY HIPOTECARIA · TÍTULO II. De la forma y efectos de la inscripción"},{"n":"RH","a":"76","t":"","x":"En la inscripción de bienes adquiridos por herencia testada se harán constar las disposiciones testamentarias pertinentes, la fecha del fallecimiento del causante, tomada de la certificación respectiva, y el contenido del certificado del Registro General de Actos de Ultima Voluntad.\nEn la inscripción de bienes adquiridos por herencia intestada se consignarán los particulares de la declaración judicial de herederos.","u":"#a76","c":"REGLAMENTO PARA LA EJECUCIÓN DE LA LEY HIPOTECARIA · Inscripciones de capitulaciones matrimoniales, de herencia y de contrato sucesorio"},{"n":"RH","a":"77","t":"","x":"1. En la inscripción de bienes adquiridos o que hayan de adquirirse en el futuro en virtud de contrato sucesorio se consignarán, además de la denominación que en su caso tenga la institución en la respectiva legislación que la regule o admita, las estipulaciones pertinentes de la escritura pública la fecha del matrimonio, si se tratase de capitulaciones matrimoniales y, en su caso la fecha del fallecimiento de la persona o personas que motiven la transmisión. El contenido de la certificación del Registro General de Actos de Ultima Voluntad, cuando fuere necesaria su presentación, y las particularidades de la escritura, testamento o resolución judicial en que aparezca la designación del heredero.\n2. Si se tratase de adquisiciones bajo supuesto de futuro matrimonio y éste no se hubiese contraído, se suspenderá la inscripción y podrá tomarse anotación preventiva de suspensión, que se convertirá en inscripción cuando se acredite la celebración de aquél, o, si fuese aplicable el artículo 1.334 del Código civil, se estará a lo dispuesto en el apartado segundo del artículo 75.\n3. Cuando, por implicar el contrato sucesorio, heredamiento o institución de que se trate, la transmisión de presente de bienes inmuebles, se hubiera practicado la inscripción de éstos antes del fallecimiento del causante o instituyente, se hará constar en su día tal fallecimiento por medio de nota al margen de la inscripción practicada, si bien habrá de extenderse el correspondiente asiento principal para la cancelación de las facultades o derechos reservados por el fallecido, en su caso.","u":"#a77","c":"REGLAMENTO PARA LA EJECUCIÓN DE LA LEY HIPOTECARIA · Inscripciones de capitulaciones matrimoniales, de herencia y de contrato sucesorio"},{"n":"RH","a":"78","t":"","x":"En los casos de los dos artículos anteriores se considerará defecto que impida la inscripción el no presentar los certificados que se indican en los mismos, o no relacionarse en el título o resultar contradictorios con éste. No se considerará contradictorio el certificado del Registro General de Actos de Ultima Voluntad cuando fuere negativo u omitiere el título sucesorio en que se base el documento presentado, si este título fuera de fecha posterior a los consignados en el certificado.","u":"#a78","c":"REGLAMENTO PARA LA EJECUCIÓN DE LA LEY HIPOTECARIA · Inscripciones de capitulaciones matrimoniales, de herencia y de contrato sucesorio"},{"n":"RH","a":"79","t":"","x":"Podrán inscribirse a favor del heredero único y a su instancia, mediante la presentación de los documentos referidos en el artículo 76, los bienes y derechos que estuvieren inscritos a nombre del causante, cuando no exista legitimario ni persona autorizada, según el título sucesorio para adjudicar la herencia, salvo que en este segundo supuesto la única persona interesada en la herencia resultare ser dicho heredero.","u":"#a79","c":"REGLAMENTO PARA LA EJECUCIÓN DE LA LEY HIPOTECARIA · Inscripciones de capitulaciones matrimoniales, de herencia y de contrato sucesorio"},{"n":"RH","a":"80","t":"","x":"1. Para obtener la inscripción de adjudicación de bienes hereditarios o cuotas indivisas de los mismos se deberán presentar, según los casos:\na) Escritura de partición, escritura o, en su caso, acta de protocolización de operaciones particionales formalizadas con arreglo a las Leyes, o resolución judicial firme en la que se determinen las adjudicaciones a cada interesado, cuando fuesen varios los herederos.\nb) Escritura de manifestación de herencia, cuando en caso de heredero único sea necesario con arreglo al artículo anterior.\nc) Escritura pública, a la cual hayan prestado su consentimiento todos los interesados, si se adjudicare solamente una parte del caudal y éste fuera de su libre disposición.\n2. La inscripción de las adjudicaciones de bienes hereditarios a alguno o algunos de los hijos o descendientes con obligación de pago en metálico de la porción hereditaria de los demás legitimarios, expresará que las adjudicaciones se verifican con arreglo al artículo 844 del Código civil, y se llevarán a cabo:\na) Si se trata de adjudicación practicada por el testador, en virtud del testamento de éste si la contuviere, y, en otro caso, se acompañará, además, la escritura pública en que se contenga.\nb) Si se trata de adjudicación practicada por contador-partidor, en virtud del testamento del causante, de la escritura pública otorgada por aquél en que se contenga la adjudicación con fijación de la cuantía de los haberes de los legitimarios y en su caso, del documento público acreditativo de haberse conferido al contador dativo tal facultad.\nEn ambos supuestos deberá acompañarse el documento en que conste la aceptación del adjudicatario o adjudicatarios y el que acredite la confirmación de los demás hijos o descendientes o la aprobación judicial.\nEl pago de la porción hereditaria de los legitimarios se hará constar por nota marginal mediante el documento público que lo acredite.","u":"#a80","c":"REGLAMENTO PARA LA EJECUCIÓN DE LA LEY HIPOTECARIA · Inscripciones de capitulaciones matrimoniales, de herencia y de contrato sucesorio"},{"n":"AND","a":"26","t":"Mejora de las reducciones de la base imponible, coeficientes multiplicadores y bonificaciones de la cuota mediante equiparaciones.","x":"1. A los efectos establecidos en el apartado 2 de este artículo, se establecen las siguientes equiparaciones:\na) Las parejas o uniones de hecho inscritas en el Registro de Parejas de Hecho de la Comunidad Autónoma de Andalucía o en registros análogos de otras administraciones públicas se equipararán a los cónyuges.\nb) Las personas objeto de un acogimiento familiar permanente y guarda con fines de adopción se equipararán a los adoptados.\nc) Las personas que realicen un acogimiento familiar permanente y guarda con fines de adopción se equipararán a los adoptantes.\nSe entiende por acogimiento familiar permanente y guarda con fines de adopción los constituidos con arreglo a la Ley 1/1998, de 20 de abril, de los Derechos y la Atención al Menor o norma que la sustituya y las disposiciones del Código Civil.\n2. Las equiparaciones previstas en el presente artículo se aplicarán a:\na) Las reducciones en la base imponible, coeficientes multiplicadores y bonificaciones en la cuota previstas en el Capítulo III del Título I de la presente Ley.\nb) Las reducciones en la base imponible previstas en el artículo 20 de la Ley 29/1987, de 18 de diciembre, del impuesto sobre sucesiones y donaciones.","u":"#a2-8","c":"CAPÍTULO III. Impuesto sobre sucesiones y donaciones · Sección 1.ª Equiparaciones"},{"n":"AND","a":"27","t":"Mejora de la reducción estatal de la base imponible por la adquisición «mortis causa» de la vivienda habitual.","x":"1. El porcentaje de reducción previsto en el artículo 20.2 c) de la Ley 29/1987, de 18 de diciembre, del impuesto sobre sucesiones y donaciones en el supuesto de adquisición mortis causa de la vivienda habitual del causante será del 99%.\n2. Esta reducción será de aplicación con los siguientes requisitos:\na) Que los causahabientes sean el cónyuge, ascendientes o descendientes del causante o las personas equiparadas a éstos de acuerdo con lo establecido en el artículo 26, o bien pariente colateral mayor de 65 años que hubiese convivido con el mismo durante los dos años anteriores al fallecimiento.\nb) Que la adquisición se mantenga durante los tres años siguientes a la fecha del fallecimiento del causante, salvo que el adquirente falleciera dentro de ese plazo.","u":"#a2-9","c":"Sección 2.ª Reducciones de la base imponible · Subsección 1.ª Por adquisiciones mortis causa"},{"n":"AND","a":"28","t":"Mejora de la reducción estatal de la base imponible por la adquisición «mortis causa» por personas con parentesco.","x":"1. El importe de reducción previsto en el artículo 20.2 a) de la Ley 29/1987, de 18 de diciembre, del impuesto sobre sucesiones y donaciones en el supuesto de adquisiciones mortis causa, incluidas las de los beneficiarios de pólizas de seguros de vida, será el siguiente:\na) Grupo I: adquisiciones por descendientes y adoptados menores de 21 años, 1.000.000 de euros.\nb) Grupo II: adquisiciones por descendientes y adoptados de 21 o más años, cónyuges, ascendientes y adoptantes, 1.000.000 euros.\nc) Grupo III: adquisiciones por colaterales de segundo y tercer grado, ascendientes y descendientes por afinidad, 10.000 euros.\n2. Esta reducción también se aplicará en los supuestos de equiparaciones recogidos en el artículo 26.","u":"#a2-10","c":"Sección 2.ª Reducciones de la base imponible · Subsección 1.ª Por adquisiciones mortis causa"},{"n":"AND","a":"29","t":"Mejora de la reducción estatal de la base imponible para contribuyentes con discapacidad por adquisiciones «mortis causa».","x":"1. El importe de la reducción previsto en el artículo 20.2 a) de la Ley 29/1987, de 18 de diciembre, del impuesto sobre sucesiones y donaciones, en el supuesto de adquisiciones mortis causa, incluidas las de los beneficiarios de pólizas de seguros de vida, cuando el contribuyente tenga la consideración de persona con discapacidad, será el siguiente:\na) 250.000 euros, si el grado de discapacidad fuera igual o superior al 33% e inferior al 65%.\nb) 500.000 euros, si el grado de discapacidad fuera igual o superior al 65%.\n2. Esta reducción será compatible con la mejora de la reducción estatal de la base imponible por la adquisición mortis causa por personas con parentesco prevista en el artículo 28.","u":"#a2-11","c":"Sección 2.ª Reducciones de la base imponible · Subsección 1.ª Por adquisiciones mortis causa"},{"n":"AND","a":"30","t":"Mejora de la reducción estatal de la base imponible por la adquisición «mortis causa» de empresas individuales o negocios profesionales.","x":"1. En los casos en los que en la base imponible de una adquisición mortis causa estuviese incluido el valor de una empresa individual o de un negocio profesional o el valor de derechos de usufructo sobre los mismos, o de derechos económicos derivados de la extinción de dicho usufructo, siempre que con motivo del fallecimiento se consolidara el pleno dominio, o se percibieran los derechos debidos a la finalización del usufructo en forma de participaciones en la empresa o negocio afectado, se aplicará en la base imponible una reducción del 99% del mencionado valor, siempre que se cumplan los siguientes requisitos:\na) Que el adquirente esté comprendido en los Grupos I, II y III previstos en el artículo 20.2 a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, o en los supuestos de equiparaciones recogidos en el artículo 26.\nb) Que el causante haya ejercido la actividad empresarial o profesional de forma habitual, personal y directa a la fecha del fallecimiento y percibiera rendimientos por dicha actividad.\nNo obstante, en el caso de que el causante se encontrara jubilado de la misma o en situación de incapacidad permanente en grado de absoluta o gran invalidez reconocida a la fecha del fallecimiento, dicha actividad empresarial o profesional deberá estar ejerciéndose de forma habitual, personal y directa por cualquiera de las personas contempladas en el párrafo a) de este apartado 1, ya sea mediante contrato laboral remunerado con el titular de la empresa o negocio, o mediante la explotación directa de éstos, en caso de que le sea cedida la empresa o el negocio profesional por cualquier negocio jurídico, percibiendo rendimientos por dicha actividad.\nTambién se aplicará la reducción a los bienes y derechos comunes a ambos miembros del matrimonio o pareja de hecho equiparada, cuando se utilicen en el desarrollo de la actividad empresarial o profesional de cualquiera de los cónyuges, siempre que se cumplan los requisitos anteriores.\nc) Que durante los tres años siguientes a la fecha de fallecimiento del causante el adquirente mantenga en su patrimonio los bienes y derechos adquiridos, salvo que falleciera dentro de este plazo.\n2. La reducción se aplicará sobre el valor neto de los bienes y derechos de las personas físicas necesarios para el desarrollo de su actividad, calculado conforme al artículo 11 de la Ley 19/1991, de 6 de junio, del impuesto sobre el patrimonio.\nEsta reducción se aplica tanto en caso de adquisición de la plena propiedad o de la nuda propiedad como en caso de adquisición de cualquier otra participación o derecho sobre los citados bienes y derechos.\n3. La reducción prevista en este artículo, con los mismos requisitos de los apartados anteriores, será aplicable a aquellos adquirentes que estén comprendidos en el Grupo IV del artículo 20. 2.a) de la Ley 29/1987, de 18 de diciembre, y que cumplan, además, los siguientes requisitos:\na) Tener un contrato laboral o de prestación de servicios dentro de la empresa o negocio profesional del causante que esté vigente a la fecha del fallecimiento de éste y acreditar una antigüedad mínima de cinco años en la empresa o negocio profesional.\nb) Tener encomendadas tareas de responsabilidad en la gestión o dirección de la empresa o negocio a la fecha del fallecimiento del causante y con una antigüedad mínima de tres años ininterrumpidos en el ejercicio de éstas, inmediatamente anteriores a la fecha del fallecimiento.\nSe entenderá que tienen encomendadas estas tareas si acreditan la categoría laboral correspondiente a los grupos 1 y 2 de cotización del Régimen General de la Seguridad Social o si el causante les hubiera otorgado un apoderamiento especial para llevar a cabo las actuaciones habituales de gestión de la empresa.","u":"#a3-2","c":"Sección 2.ª Reducciones de la base imponible · Subsección 1.ª Por adquisiciones mortis causa"},{"n":"AND","a":"31","t":"Mejora de la reducción estatal de la base imponible por la adquisición «mortis causa» de participaciones en entidades.","x":"1. En los casos en los que en la base imponible de una adquisición mortis causa estuviese incluido el valor de participaciones en entidades, o el valor de derechos de usufructo sobre las mismas, o de derechos económicos derivados de la extinción de dicho usufructo, siempre que con motivo del fallecimiento se consolidara el pleno dominio, o se percibieran los derechos debidos a la finalización del usufructo en forma de participaciones en la entidad afectada, se aplicará en la base imponible una reducción del 99% del valor de los citados derechos, siempre que se cumplan los siguientes requisitos:\na) Que el adquirente esté comprendido en los Grupos I, II y III previstos en el artículo 20.2 a) de la Ley 29/1987, de 18 de diciembre, o en los supuestos de equiparaciones recogidos en el artículo 26.\nb) Que la participación del causante en el capital de la entidad sea al menos del 5% computado de forma individual, o del 20% del grupo de parentesco formado conjuntamente con su cónyuge, ascendientes, descendientes o colaterales hasta el sexto grado, ya tenga su origen el parentesco en la consanguinidad, en la afinidad o en la adopción, así como en los supuestos de equiparación del artículo 26.\nc) Que el causante o alguna de las personas del grupo de parentesco conforme a lo establecido en la letra anterior, tengan o no participación en la entidad, ejerza efectivamente funciones de dirección en la entidad, percibiendo por ello remuneración.\nd) Que la entidad, sea o no societaria, no tenga por actividad principal la gestión de un patrimonio mobiliario o inmobiliario, de conformidad con lo establecido en el artículo 4.Ocho.Dos.a) de la Ley 19/1991, de 6 de junio, del Impuesto sobre el Patrimonio.\ne) Que el adquirente mantenga en su patrimonio las participaciones en la entidad durante los tres años siguientes a la fecha de fallecimiento del causante, salvo que falleciera dentro de este plazo.\n2. El importe de la reducción solo alcanzará al valor de las participaciones, en la parte que corresponda a la proporción existente entre los activos necesarios para el ejercicio de la actividad empresarial o profesional, minorados en el importe de las deudas derivadas de la misma, y el valor del patrimonio neto de la entidad, aplicándose estas mismas reglas en la valoración de las participaciones de entidades participadas para determinar el valor de las de su entidad tenedora.\nNo obstante, también será aplicable la reducción a la tesorería, los activos representativos de la participación en fondos propios de una entidad y de la cesión de capitales a terceros cuyo precio de adquisición no supere el importe de los beneficios no distribuidos obtenidos por la entidad, siempre que dichos beneficios provengan de la realización de actividades económicas, con el límite del importe de los beneficios obtenidos tanto en el propio ejercicio como en los diez ejercicios anteriores. A estos efectos, se asimilan a los beneficios procedentes de actividades económicas los dividendos que procedan de los valores de entidades participadas cuando los ingresos obtenidos por estas procedan, al menos en el 90%, de la realización de actividades económicas.\n3. La reducción prevista en este artículo, con los mismos requisitos de los apartados anteriores, será aplicable a aquellos adquirentes que estén comprendidos en el Grupo IV del artículo 20.2. a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones y que cumplan, además, los siguientes requisitos:\na) Tener un contrato laboral o de prestación de servicios dentro de la empresa o negocio profesional del causante que esté vigente a la fecha del fallecimiento de este y acreditar una antigüedad mínima de cinco años en la empresa o negocio.\nb) Tener encomendadas tareas de responsabilidad en la gestión o dirección de la empresa o negocio a la fecha del fallecimiento del causante y con una antigüedad mínima de tres años ininterrumpidos en el ejercicio de éstas inmediatamente anteriores a la fecha del fallecimiento.\nSe entenderá que tienen encomendadas estas tareas si acreditan la categoría laboral correspondiente a los grupos 1 y 2 de cotización del Régimen General de la Seguridad Social o si el causante les hubiera otorgado un apoderamiento especial para llevar a cabo las actuaciones habituales de gestión de la empresa.","u":"#a3-3","c":"Sección 2.ª Reducciones de la base imponible · Subsección 1.ª Por adquisiciones mortis causa"},{"n":"AND","a":"32","t":"Reducción propia por la donación de dinero a descendientes para la adquisición de la vivienda habitual.","x":"1. Los donatarios que perciban dinero de sus ascendientes, o de las personas equiparadas a éstas de acuerdo con lo establecido en el artículo 26, para la adquisición de su vivienda habitual, podrán aplicar una reducción propia del 99% del importe de la base imponible del impuesto, siempre que concurran los siguientes requisitos:\na) Que el donatario cumpla alguna de las siguientes condiciones:\n1.ª Ser menor de 35 años.\n2.ª Tener la consideración de persona con discapacidad.\n3.ª Tener la consideración de víctima de violencia doméstica.\n4.ª Tener la consideración de víctima del terrorismo o persona afectada.\nb) Que el patrimonio preexistente del donatario esté comprendido en el primer tramo de la escala establecida por el artículo 22 de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones.\nc) Que el importe íntegro de la donación se destine a la compra de la vivienda habitual.\nd) La vivienda deberá estar situada en el territorio de la Comunidad Autónoma de Andalucía.\ne) El donatario ha de mantener la vivienda habitual durante los tres años siguientes a la fecha de su adquisición.\nf) La adquisición de la vivienda deberá efectuarse dentro del período de autoliquidación del impuesto correspondiente a la donación, debiendo aportar la escritura pública en que se formalice la compraventa. En este documento público deberá hacerse constar la donación recibida y su aplicación al pago del precio de la vivienda habitual.\n2. La base máxima de la reducción será 150.000 euros, con carácter general. No obstante, cuando el donatario tenga la consideración de persona con discapacidad, la base de la reducción no podrá exceder de 250.000 euros.\nEn el caso de dos o más donaciones, provenientes del mismo o de diferentes ascendientes o personas equiparadas a éstas, la base de la reducción será el resultado de sumar el importe de todas ellas, sin que pueda exceder de los límites anteriormente señalados.","u":"#a3-4","c":"Sección 2.ª Reducciones de la base imponible · Subsección 2.ª Por adquisiciones «inter vivos»"},{"n":"AND","a":"33","t":"Reducción propia por la donación de vivienda habitual a descendientes.","x":"1. Los donatarios que reciban el pleno dominio de un inmueble de sus ascendientes, o de las personas equiparadas a éstos de acuerdo con lo establecido en el artículo 26, podrán aplicar una reducción propia del 99% del importe de la base imponible del impuesto, siempre que concurran los siguientes requisitos:\na) Que el donatario cumpla alguna de las siguientes condiciones:\n1.ª Ser menor de 35 años.\n2.ª Tener la consideración de persona con discapacidad.\n3.ª Tener la consideración de víctima de violencia doméstica.\n4.ª Tener la consideración de víctima del terrorismo o persona afectada.\nb) Que el patrimonio preexistente del donatario esté comprendido en el primer tramo de la escala establecida por el artículo 22 de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones.\nc) Que el inmueble adquirido se destine a vivienda habitual del donatario.\nd) El donatario ha de mantener la vivienda habitual durante los 3 años siguientes a la fecha de su adquisición.\ne) Que se haga constar en la escritura pública en la que se formalice la donación que el inmueble se destine a constituir la vivienda habitual para el donatario y el compromiso de mantenimiento a que se refiere la letra anterior.\n2. La base máxima de la reducción será 150.000 euros, con carácter general. No obstante, cuando el donatario tenga la consideración de persona con discapacidad, la base de la reducción no podrá exceder de 250.000 euros.\nEn el caso de dos o más donaciones provenientes del mismo o de diferentes donantes cotitulares de la vivienda donada, la base de la reducción no podrá exceder del límite anteriormente señalado.","u":"#a3-5","c":"Sección 2.ª Reducciones de la base imponible · Subsección 2.ª Por adquisiciones «inter vivos»"},{"n":"AND","a":"34","t":"Reducción propia por donación de dinero a parientes para la constitución o ampliación de una empresa individual o negocio profesional.","x":"1. Los donatarios que perciban dinero para la constitución o ampliación de una empresa individual o de un negocio profesional se podrán aplicar una reducción propia del 99% del importe de la base imponible del impuesto, siempre que concurran los siguientes requisitos:\na) Que el donante esté comprendido en los Grupos I, II y III previstos en el artículo 20.2.a) de la Ley 29/1987, de 18 de diciembre, o en los supuestos de equiparaciones recogidos en el artículo 26.\nb) Que el importe íntegro de la donación se destine a la constitución o ampliación de una empresa individual o de un negocio profesional.\nc) Que la empresa individual o negocio profesional tenga centralizada la gestión administrativa y la dirección de las actividades desarrolladas en el territorio de la Comunidad Autónoma de Andalucía, y que la citada gestión y dirección se mantengan en dicho territorio durante los tres años siguientes a la fecha de la donación, salvo que el donatario falleciera dentro de ese plazo.\nd) Que la constitución o ampliación de la empresa individual o del negocio profesional se produzca en el plazo máximo de seis meses desde la fecha de formalización de la donación.\ne) Que la donación se formalice en documento público y se haga constar de manera expresa que el dinero donado se destina por parte del donatario exclusivamente a la constitución o ampliación de una empresa individual o negocio profesional que cumpla los requisitos que se prevén en este artículo.\nf) Que la empresa individual o negocio profesional no tengan por actividad principal la gestión de un patrimonio mobiliario o inmobiliario, de acuerdo con lo establecido en el artículo 4. Ocho.Dos.a) de la Ley 19/1991, de 6 de junio, del Impuesto sobre el Patrimonio.\n2. El importe de la reducción no podrá exceder de 1.000.000 de euros.\nEn el caso de dos o más donaciones, provenientes del mismo o de diferentes donantes relacionados en el apartado 1 de este artículo, la base de la reducción será el resultado de sumar el importe de todas ellas, sin que pueda exceder del límite anteriormente señalado.","u":"#a3-6","c":"Sección 2.ª Reducciones de la base imponible · Subsección 2.ª Por adquisiciones «inter vivos»"},{"n":"AND","a":"35","t":"Mejora de la reducción estatal de la base imponible por la adquisición «inter vivos» de empresas individuales o negocios profesionales.","x":"1. En el supuesto de adquisición inter vivos de una empresa individual o negocio profesional, se establece una mejora de la reducción estatal en la base imponible del 99% del valor neto de los citados bienes y derechos, siempre que se cumplan los siguientes requisitos:\na) Que el donante esté comprendido en los Grupos I, II y III previstos en el artículo 20.2 a) de la Ley 29/1987, del Impuesto sobre Sucesiones y Donaciones, de 18 de diciembre, o en los supuestos de equiparaciones recogidos en el artículo 26.\nb) Que el donante haya ejercido la actividad empresarial o profesional de forma habitual, personal y directa a la fecha de la donación y percibiera rendimientos por dicha actividad.\nNo obstante, en el caso de que el donante se encontrara jubilado de la misma o en situación de incapacidad permanente en grado de absoluta o gran invalidez reconocida a la fecha de la donación, dicha actividad empresarial o profesional deberá estar ejerciéndose de forma habitual, personal y directa por cualquiera de las personas contempladas en el párrafo a) de este apartado 1 ya sea mediante contrato laboral remunerado con el titular de la empresa o negocio, o mediante la explotación directa de estos, en caso de que le sean cedidas la empresa o negocio por cualquier negocio jurídico, percibiendo rendimientos por dicha actividad.\nTambién se aplicará la reducción a los bienes y derechos comunes a ambos miembros del matrimonio o pareja de hecho equiparada, cuando se utilicen en el desarrollo de la actividad empresarial o profesional de cualquiera de los cónyuges, siempre que se cumplan los requisitos anteriores.\nc) Que el donatario mantenga en su patrimonio los bienes y derechos adquiridos durante los tres años siguientes a la fecha de la donación, salvo que falleciera dentro de este plazo.\n2. La reducción se aplicará sobre el valor neto de los bienes y derechos de las personas físicas necesarios para el desarrollo de su actividad, calculado conforme al artículo 11 de la Ley 19/1991, de 6 de junio, del Impuesto sobre el Patrimonio.\nEsta reducción se aplica tanto en caso de adquisición de la plena propiedad o de la nuda propiedad como en caso de adquisición de cualquier otra participación o derecho sobre los citados bienes y derechos.\n3. La reducción prevista en este artículo, con los mismos requisitos de los apartados anteriores, será aplicable a aquellos adquirentes que estén comprendidos en el Grupo IV del artículo 20.2.a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, y que cumplan, además, los siguientes requisitos:\na) Tener un contrato laboral o de prestación de servicios dentro de la empresa o negocio profesional del donante que esté vigente a la fecha de la donación y acreditar una antigüedad mínima de cinco años en la empresa o negocio.\nb) Tener encomendadas tareas de responsabilidad en la gestión o dirección de la empresa o negocio a la fecha de la donación y con una antigüedad mínima de tres años ininterrumpidos en el ejercicio de estas inmediatamente anteriores a la fecha de la donación. Se entenderá que tienen encomendadas estas tareas si acreditan la categoría laboral correspondiente a los grupos 1 y 2 de cotización del Régimen General de la Seguridad Social o si el donante les hubiera otorgado un apoderamiento especial para llevar a cabo las actuaciones habituales de gestión de la empresa.","u":"#a3-7","c":"Sección 2.ª Reducciones de la base imponible · Subsección 2.ª Por adquisiciones «inter vivos»"},{"n":"AND","a":"36","t":"Mejora de la reducción estatal de la base imponible por la adquisición «inter vivos» de participaciones en entidades.","x":"1. En el supuesto de adquisición inter vivos de participaciones en una entidad se establece una mejora de la reducción en la base imponible del 99% del valor neto de los citados bienes y derechos, siempre que se cumplan los siguientes requisitos:\na) Que el donatario esté comprendido en los Grupos I, II y III previstos en el artículo 20.2 a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, o en los supuestos de equiparaciones recogidos en el artículo 26.\nb) Que la participación del donante en el capital de la entidad sea al menos del 5% computado de forma individual, o del 20% del grupo de parentesco formado conjuntamente con su cónyuge, ascendientes, descendientes o colaterales hasta de sexto grado, ya tenga su origen el parentesco en la consanguinidad, en la afinidad o en la adopción, así como en los supuestos de equiparación del artículo 26.\nc) Que el donante o alguna de las personas del grupo de parentesco conforme a lo establecido en el párrafo anterior, tengan o no participación en la entidad, ejerza efectivamente funciones de dirección en la entidad, percibiendo por ello remuneración.\nd) Que la entidad, sea o no societaria, no tenga por actividad principal la gestión de un patrimonio mobiliario o inmobiliario, de conformidad con lo establecido en el artículo 4.Ocho. Dos. a) de la Ley 19/1991, del Impuesto sobre el Patrimonio.\ne) Que el donatario mantenga en su patrimonio las participaciones en la entidad durante los tres años siguientes a la fecha de la donación, salvo que falleciera dentro de este plazo.\n2. El importe de la reducción solo alcanzará al valor de las participaciones, en la parte que corresponda a la proporción existente entre los activos necesarios para el ejercicio de la actividad empresarial o profesional, minorados en el importe de las deudas derivadas de la misma, y el valor del patrimonio neto de la entidad, aplicándose estas mismas reglas en la valoración de las participaciones de entidades participadas para determinar el valor de las de su entidad tenedora.\nNo obstante, también será aplicable la reducción a la tesorería, los activos representativos de la participación en fondos propios de una entidad y de la cesión de capitales a terceros cuyo precio de adquisición no supere el importe de los beneficios no distribuidos obtenidos por la entidad, siempre que dichos beneficios provengan de la realización de actividades económicas, con el límite del importe de los beneficios obtenidos tanto en el propio ejercicio como en los diez ejercicios anteriores. A estos efectos, se asimilan a los beneficios procedentes de actividades económicas los dividendos que procedan de los valores de entidades participadas cuando los ingresos obtenidos por estas procedan, al menos en el 90%, de la realización de actividades económicas.\n3. La reducción prevista en este artículo, con los mismos requisitos de los apartados anteriores, será aplicable a aquellos donatarios que estén comprendidos en el Grupo IV del artículo 20.2. a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, y que cumplan, además, los siguientes requisitos:\na) Tener un contrato laboral o de prestación de servicios dentro de la empresa o negocio profesional del donante que esté vigente a la fecha de la donación y acreditar una antigüedad mínima de cinco años en la empresa o negocio.\nb) Tener encomendadas tareas de responsabilidad en la gestión o dirección de la empresa o negocio a la fecha de la donación y con una antigüedad mínima de tres años ininterrumpidos en el ejercicio de estas inmediatamente anteriores a la fecha de la donación. Se entenderá que tienen encomendadas estas tareas si acreditan la categoría laboral correspondiente a los grupos 1 y 2 de cotización del Régimen General de la Seguridad Social o si el donante les hubiera otorgado un apoderamiento especial para llevar a cabo las actuaciones habituales de gestión de la empresa.","u":"#a3-8","c":"Sección 2.ª Reducciones de la base imponible · Subsección 2.ª Por adquisiciones «inter vivos»"},{"n":"AND","a":"37","t":"Tarifa.","x":"La cuota íntegra del impuesto regulada en el artículo 21.1 de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, se obtendrá aplicando sobre la base liquidable los tipos de gravamen que se indican en la siguiente escala:\n| Base liquidable<br>–<br>Hasta euros | Cuota íntegra<br>–<br>Euros | Resto base liquidable<br>–<br>Hasta euros | Tipo aplicable<br>–<br>Porcentaje |\n| ----------------------------------- | --------------------------- | ----------------------------------------- | --------------------------------- |\n| 0 | 0 | 8.000 | 7 |\n| 8.000 | 560 | 7.000 | 8 |\n| 15.000 | 1.120 | 15.000 | 10 |\n| 30.000 | 2.620 | 20.000 | 12 |\n| 50.000 | 5.020 | 20.000 | 14 |\n| 70.000 | 7.820 | 30.000 | 16 |\n| 100.000 | 12.620 | 50.000 | 18 |\n| 150.000 | 21.620 | 50.000 | 20 |\n| 200.000 | 31.620 | 200.000 | 22 |\n| 400.000 | 75.620 | 400.000 | 24 |\n| 800.000 | 171.620 | En adelante | 26 |","u":"#a3-9","c":"CAPÍTULO III. Impuesto sobre sucesiones y donaciones · Sección 3.ª Tarifa"},{"n":"AND","a":"38","t":"Cuota tributaria.","x":"1. La cuota tributaria prevista en el artículo 22.1 de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, se obtendrá aplicando a la cuota íntegra el coeficiente multiplicador que corresponda según los siguientes grupos de parentesco:\n| Grupos I y II | Grupo III | Grupo IV |\n| ------------- | --------- | -------- |\n| 1,0 | 1,5 | 1,9 |\n2. Estos coeficientes multiplicadores también se aplicarán en los supuestos de equiparaciones recogidos en el artículo 26.","u":"#a3-10","c":"CAPÍTULO III. Impuesto sobre sucesiones y donaciones · Sección 4.ª Cuota tributaria"},{"n":"AND","a":"39","t":"Bonificación en adquisiciones «mortis causa».","x":"Los contribuyentes incluidos en los Grupos I y II de los previstos en el artículo 20.2.a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, o en los supuestos de equiparaciones establecidos en el artículo 26, aplicarán una bonificación del 99% en la cuota tributaria derivada de adquisiciones mortis causa, incluidas las de los beneficiarios de pólizas de seguro de vida.","u":"#a3-11","c":"Sección 5.ª Bonificaciones de la cuota · Subsección 1.ª Por adquisiciones mortis causa"},{"n":"AND","a":"40","t":"Bonificación en adquisiciones inter vivos.","x":"1. Los contribuyentes incluidos en los Grupos I y II de los previstos en el artículo 20.2.a) de la Ley 29/1987, de 18 de diciembre, del impuesto sobre sucesiones y donaciones, o en los supuestos de equiparaciones establecidos en el artículo 26, aplicarán una bonificación del 99% en la cuota tributaria derivada de adquisiciones inter vivos.\n2. La bonificación a que se refiere el apartado anterior será aplicable, exclusivamente, sobre la parte de la cuota que proporcionalmente corresponda a los bienes y derechos declarados por el sujeto pasivo de forma espontánea, sin requerimiento previo de la Administración tributaria, y quedará sujeta a los siguientes requisitos:\na) En relación con aquellos elementos patrimoniales cuyas transmisiones no requieran para su eficacia el otorgamiento de documento público, el negocio jurídico a título gratuito e inter vivos deberá formalizarse en documento público, con la entrega simultánea del bien, cuando la base imponible del impuesto sea superior a 5.000 euros o su contravalor en moneda extranjera.\nA estos efectos, se computarán todos los negocios jurídicos gratuitos e inter vivos efectuados por el mismo donante al mismo donatario en los tres años anteriores al momento del devengo, quedando excluidas de este cómputo las transmisiones de aquellos elementos patrimoniales que requieran el otorgamiento de documento público para su eficacia.\nb) Cuando el objeto de la donación o de cualquier otro negocio jurídico a título gratuito e inter vivos sea en metálico o cualquiera de los bienes o derechos contemplados en el artículo 12 de la Ley 19/1991, de 6 de junio, del impuesto sobre el patrimonio y la base imponible del impuesto sea superior a 5.000 euros o su contravalor en moneda extranjera, el documento público deberá formalizarse en el plazo máximo de un mes desde que se produjo la entrega y la bonificación solo resultará aplicable cuando el origen de los fondos esté debidamente justificado, y se manifieste el origen de dichos fondos en el propio documento público en que se formalice la transmisión.\nEn los supuestos de donaciones en metálico por una cuantía total determinada con entregas a plazos diferidas en el tiempo, la donación deberá formalizarse en una única escritura pública que contenga la totalidad de las entregas previstas. En estos casos, se entenderá cumplido el requisito de la entrega simultánea del bien, exigido en el párrafo a) de este apartado, cuando la primera entrega se produzca con la firma de la escritura o, en su defecto, cuando esta se otorgue en el plazo máximo de un mes desde que se efectuó dicha primera entrega.","u":"#a4-2","c":"Sección 5.ª Bonificaciones de la cuota · Subsección 2.ª Por adquisiciones «inter vivos»"},{"n":"AND","a":"61","t":"Comprobación de valores.","x":"1. Para efectuar la comprobación de valores a efectos de los impuestos sobre sucesiones y donaciones y sobre transmisiones patrimoniales y actos jurídicos documentados, la Agencia Tributaria de Andalucía podrá utilizar, indistintamente, cualquiera de los medios previstos en el artículo 57 de la Ley 58/2003, de 17 de diciembre, General Tributaria, conforme a lo dispuesto en los siguientes apartados, salvo que, en el caso de bienes inmuebles, la base imponible sea el valor de referencia previsto en la normativa reguladora del catastro inmobiliario o el valor declarado, precio o contraprestación pactada por ser superior, de acuerdo con lo dispuesto en los artículos 9.3 y 18 de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, para el caso del impuesto sobre sucesiones y donaciones, y en los artículos 10.2 y 46 del texto refundido de la Ley del Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados, aprobado por Real Decreto Legislativo 1/1993, de 24 de septiembre, para el caso del impuesto sobre transmisiones patrimoniales y actos jurídicos documentados.\n2. La Consejería competente en materia de Hacienda podrá desarrollar reglamentariamente los procedimientos para la obtención de los precios medios de mercado de los bienes inmuebles de naturaleza rústica y urbana a que se refiere el artículo 57.1.c) de la Ley 58/2003, de 17 de diciembre, General Tributaria, mediante el establecimiento de una metodología a seguir para la determinación del valor unitario por metro cuadrado. Asimismo, determinará los datos y parámetros objetivos que se tendrán en cuenta para la obtención del valor.\n3. El dictamen de peritos de la Administración previsto en el artículo 57.1.e) de la Ley 58/2003, de 17 de diciembre, General Tributaria, habrá de contener los datos objetivos utilizados para la identificación del bien o derecho cuyo valor se comprueba, obtenidos de documentación suficiente que permita su individualización.\nSe entenderá que la documentación empleada permite la individualización del bien:\na) Tratándose de bienes inmuebles de naturaleza urbana, cuando aquella documentación posibilite la descripción de las características físicas, económicas y jurídicas del bien que, según la normativa técnica vigente, haya que considerar para la obtención del valor catastral del bien.\nb) Tratándose de bienes inmuebles de naturaleza rústica, cuando la documentación proceda de sistemas de información geográfica gestionados por entidades dependientes de las administraciones públicas, siempre que posibiliten la ubicación en el territorio del inmueble y se disponga de los datos catastrales de cultivos del mismo.","u":"#a6-3","c":"CAPÍTULO III. Impuestos sobre sucesiones y donaciones y sobre transmisiones patrimoniales y actos jurídicos documentados · Sección 1.ª Normas comunes"},{"n":"AND","a":"62","t":"Información sobre valores.","x":"1. De acuerdo con lo establecido en el artículo 90 de la Ley 58/2003, de 17 de diciembre, General Tributaria, la Agencia Tributaria de Andalucía informará, a solicitud de la persona interesada, sobre el valor de los bienes inmuebles radicados en el territorio de la Comunidad Autónoma de Andalucía.\n2. La información referida en el apartado anterior habrá de ser solicitada por escrito por el titular del inmueble o por cualquier persona, siempre que cuente con su autorización. En este último caso, la autorización se acompañará a la solicitud.\n3. La valoración realizada por la Agencia Tributaria de Andalucía se emitirá por escrito dentro del plazo de tres meses, con indicación de su carácter vinculante, del supuesto de hecho a que se refiere y del impuesto al que se aplica. No quedará vinculada la Administración por su valoración cuando el interesado declare un valor superior de acuerdo con lo previsto en el artículo 46.3 del Texto Refundido de la Ley del Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados, aprobado por Real Decreto Legislativo 1/1993, de 24 de septiembre, y en el artículo 18.2 de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones.\nA los efectos previstos en el párrafo anterior, el contribuyente unirá a la autoliquidación por el correspondiente impuesto el escrito de valoración notificado por la Administración.\n4. Los solicitantes no podrán interponer recurso alguno contra los informes previos de valoración, sin perjuicio de que puedan hacerlo contra las liquidaciones administrativas que pudieran dictarse ulteriormente.","u":"#a6-4","c":"CAPÍTULO III. Impuestos sobre sucesiones y donaciones y sobre transmisiones patrimoniales y actos jurídicos documentados · Sección 1.ª Normas comunes"},{"n":"AND","a":"63","t":"Suministro de información a efectos tributarios.","x":"1. El cumplimiento de las obligaciones formales de los notarios y las notarias que contemplan los artículos 32.3 de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, y 52 del Texto Refundido de la Ley del Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados, aprobado por Real Decreto Legislativo 1/1993, de 24 de septiembre, se realizará en el formato, condiciones y diseño que apruebe la Consejería competente en materia de Hacienda.\n2. Sin perjuicio de lo dispuesto en el apartado 1, los notarios y notarias remitirán por vía telemática a la Agencia Tributaria de Andalucía, con la colaboración del Consejo General del Notariado, la información relativa a las escrituras por ellos autorizadas con trascendencia en el ámbito de la Comunidad Autónoma de Andalucía en los impuestos sobre sucesiones y donaciones y sobre transmisiones patrimoniales y actos jurídicos documentados. A estos efectos, se remitirán, en el plazo máximo de 15 días desde el otorgamiento de cada escritura, tanto la copia autorizada electrónica como una ficha con todos los elementos y datos de la misma. Mediante Resolución de la Dirección de la Agencia Tributaria de Andalucía se determinará la forma de remisión y estructura en las que debe ser suministrada la ficha.","u":"#a6-5","c":"CAPÍTULO III. Impuestos sobre sucesiones y donaciones y sobre transmisiones patrimoniales y actos jurídicos documentados · Sección 1.ª Normas comunes"},{"n":"AND","a":"64","t":"Simplificación de obligaciones formales.","x":"1. En el caso de hechos, actos o contratos sujetos al impuesto sobre sucesiones y donaciones o al impuesto sobre transmisiones patrimoniales y actos jurídicos documentados que se documenten o formalicen en escritura pública, no será obligatoria para el contribuyente la presentación junto a la autoliquidación de dicha escritura, a los efectos de lo dispuesto en la normativa reguladora de estos tributos.\n2. La justificación de la presentación a los efectos de lo dispuesto en el artículo 33 de la Ley 29/1987, de 18 de diciembre, y en el artículo 54 del Texto Refundido de la Ley del Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados, en relación con su admisión en las oficinas o registros públicos, se realizará mediante diligencia emitida al efecto a partir del momento en el que conste en el sistema la información suministrada por el notario correspondiente a la autoliquidación presentada.\n3. La diligencia a la que se refiere el apartado anterior se obtendrá necesariamente en formato electrónico por los registros públicos en los que deba surtir efecto. Mediante resolución de la Dirección de la Agencia Tributaria de Andalucía se determinará la forma de obtención y descarga de la diligencia.","u":"#a6-6","c":"CAPÍTULO III. Impuestos sobre sucesiones y donaciones y sobre transmisiones patrimoniales y actos jurídicos documentados · Sección 1.ª Normas comunes"},{"n":"AND","a":"65","t":"Suministro de información por los registradores de la propiedad y mercantiles.","x":"1. Los registradores de la propiedad y mercantiles con destino en el ámbito territorial de la Comunidad Autónoma de Andalucía deberán remitir a la Agencia Tributaria de Andalucía, en la primera quincena de cada trimestre, una declaración comprensiva de la relación de los documentos relativos a actos o contratos sujetos al impuesto sobre sucesiones y donaciones o al impuesto sobre transmisiones patrimoniales y actos jurídicos documentados que se presenten a inscripción en los citados registros. Dicha declaración irá referida al trimestre anterior.\n2. Mediante orden de la Consejería competente en materia de Hacienda podrá establecerse el formato, condiciones, diseño y demás extremos necesarios para el cumplimiento de las obligaciones formales a que se refiere el apartado anterior, que podrá consistir en soporte directamente legible por ordenador o mediante transmisión por vía telemática.","u":"#a6-7","c":"CAPÍTULO III. Impuestos sobre sucesiones y donaciones y sobre transmisiones patrimoniales y actos jurídicos documentados · Sección 1.ª Normas comunes"},{"n":"AND","a":"66","t":"Presentación de autoliquidación complementaria en caso de pérdida del derecho a aplicar un beneficio fiscal.","x":"1. El incumplimiento de los requisitos exigidos en la regulación de los beneficios fiscales aprobados por la Comunidad Autónoma en relación con los impuestos a los que se refiere el presente Capítulo determinará la obligación de regularizar la situación tributaria mediante la presentación de una declaración donde se exprese tal circunstancia, dentro del plazo de un mes desde que se produzca el hecho determinante del incumplimiento.\n2. A dicha declaración se acompañará el ingreso mediante autoliquidación complementaria de la parte del impuesto que se hubiera dejado de ingresar como consecuencia de la aplicación del beneficio fiscal, más los intereses de demora correspondientes.\n3. La obligación de declarar se extenderá a cualquier beneficio fiscal cuya efectividad dependa de condiciones futuras.\n4. En particular, cuando se hayan aplicado beneficios fiscales de la Comunidad Autónoma en la adquisición de la vivienda habitual, el incumplimiento de los requisitos regulados en el artículo 2 relativos a que se habite de forma efectiva y permanente y por plazo continuado determinará la obligación de presentar la declaración y autoliquidación en la forma establecida en los apartados anteriores.\n5. A los efectos del presente artículo se considerará beneficio fiscal aquel que establezca exenciones, reducciones a la base imponible, deducciones en cuota y cualquier otro incentivo fiscal.","u":"#a6-8","c":"CAPÍTULO III. Impuestos sobre sucesiones y donaciones y sobre transmisiones patrimoniales y actos jurídicos documentados · Sección 1.ª Normas comunes"},{"n":"AND","a":"67","t":"Tasación pericial contradictoria y suspensión de las liquidaciones en supuestos especiales.","x":"1. En corrección del resultado obtenido en la comprobación de valores del impuesto sobre sucesiones y donaciones, las personas interesadas podrán promover la práctica de la tasación pericial contradictoria mediante solicitud presentada dentro del plazo del primer recurso o reclamación que proceda contra la liquidación efectuada sobre la base de los valores comprobados administrativamente, o contra el acto de comprobación de valores debidamente notificado.\nSi la persona interesada estimase que la notificación no contiene expresión suficiente de los datos y motivos tenidos en cuenta para elevar los valores declarados y pusiere de manifiesto la omisión a través de un recurso de reposición o de una reclamación económico-administrativa, reservándose el derecho a promover tasación pericial contradictoria, el plazo a que se refiere el párrafo anterior se contará desde la fecha de firmeza en vía administrativa de la resolución del recurso o de la reclamación interpuesta.\n2. La presentación de la solicitud de tasación pericial contradictoria, o la reserva del derecho a promoverla a que se refiere el apartado 1 de este artículo, determinará la suspensión de la ejecución de las liquidaciones practicadas y de los plazos de recurso y reclamación contra las mismas.","u":"#a6-9","c":"CAPÍTULO III. Impuestos sobre sucesiones y donaciones y sobre transmisiones patrimoniales y actos jurídicos documentados · Sección 2.ª Impuesto sobre sucesiones y donaciones"},{"n":"AND","a":"68","t":"Plazo de presentación de la autoliquidación.","x":"1. Con carácter general, para los hechos imponibles sujetos a la modalidad de donaciones del impuesto sobre sucesiones y donaciones, el plazo de presentación de la autoliquidación e ingreso, en su caso, de la deuda tributaria, junto con la documentación exigida en la normativa aplicable, será de dos meses a contar desde el día siguiente a la fecha del devengo.\n2. En los casos de consolidación del pleno dominio como consecuencia de la extinción del usufructo previamente constituido mediante una operación sujeta a la modalidad donaciones del impuesto sobre sucesiones y donaciones, cuando dicha extinción se produzca por el fallecimiento del usufructuario, el plazo de presentación de la autoliquidación e ingreso de la deuda tributaria será de seis meses a contar desde el día siguiente a la fecha del fallecimiento del usufructuario.","u":"#a6-10","c":"CAPÍTULO III. Impuestos sobre sucesiones y donaciones y sobre transmisiones patrimoniales y actos jurídicos documentados · Sección 2.ª Impuesto sobre sucesiones y donaciones"},{"n":"MAD","a":"21","t":"Reducciones en la base imponible.","x":"Uno. Mejora de las reducciones establecidas por la normativa estatal.\nEn las adquisiciones mortis causa, incluidas las de los beneficiarios de pólizas de seguros sobre la vida, la base liquidable se obtendrá aplicando a la base imponible las reducciones siguientes, que sustituyen a las análogas del Estado reguladas en el artículo 20.2 de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones:\n1. La que corresponda de las incluidas en los grupos siguientes:\nGrupo I: Adquisiciones por descendientes y adoptados menores de veintiún años, 16.000 euros, más 4.000 euros por cada año menos de veintiuno que tenga el causahabiente, sin que la reducción pueda exceder de 48.000 euros.\nGrupo II: Adquisiciones por descendientes y adoptados de veintiuno o más años, cónyuges, ascendientes y adoptantes, 16.000 euros.\nGrupo III: Adquisiciones por colaterales de segundo y tercer grado, ascendientes y descendientes por afinidad, 8.000 euros.\nGrupo IV: En las adquisiciones por colaterales de cuarto grado, grados más distantes y extraños, no habrá lugar a reducción.\n2. Se aplicará, además de las que pudieran corresponder en función del grado de parentesco con el causante, una reducción de 55.000 euros a las personas con un grado de discapacidad igual o superior al 33 por 100. La reducción será de 153.000 euros para aquellas personas que acrediten un grado de discapacidad igual o superior al 65 por 100. A tales efectos, los grados de discapacidad son los que se establezcan de acuerdo con el baremo al que se refiere la normativa estatal que establece el procedimiento para el reconocimiento, declaración y calificación del grado de discapacidad.\nEn particular, se considerará acreditado un grado de discapacidad igual o superior al 33 por 100 en el caso de los pensionistas de la Seguridad Social que tengan reconocida una pensión de incapacidad permanente total, absoluta o gran invalidez y en el caso de los pensionistas de clases pasivas que tengan reconocida una pensión de jubilación o retiro por incapacidad permanente para el servicio o inutilidad.\nEn el caso de personas cuya incapacidad hubiera sido declarada judicialmente, así como aquellas personas para las que, como medida de apoyo a su capacidad jurídica y mediante resolución judicial, se haya nombrado un curador con facultades de representación plenas para todos los actos jurídicos, se considerará acreditado un grado de discapacidad igual o superior al 65 % aunque no alcance dicho grado.\n3. Con independencia de las reducciones anteriores, se aplicará una reducción del 100 por 100, con un límite de 9.200 euros, a las cantidades percibidas por los beneficiarios de contratos de seguros sobre la vida cuando su parentesco con el contratante fallecido sea el de cónyuge, ascendiente, descendiente, adoptante o adoptado.\nEn los seguros colectivos o contratados por las empresas en favor de sus empleados se estará al grado de parentesco entre el asegurado fallecido y el beneficiario.\nLa reducción será única por sujeto pasivo, cualquiera que fuese el número de contratos de seguros de vida de los que sea beneficiario. En el caso de que tenga derecho al régimen de bonificaciones y reducciones que establece la disposición transitoria cuarta de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, el sujeto pasivo puede optar entre aplicar dicho régimen o la reducción que se establece en este número.\nCuando se trate de seguros de vida que traigan causa en actos de terrorismo, así como en servicios prestados en misiones internacionales humanitarias o de paz de carácter público, será de aplicación lo previsto en el artículo 20.2. b) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones.\n4. En los casos en los que en la base imponible de una adquisición mortis causa que corresponda a los cónyuges, ascendientes o adoptantes, descendientes o adoptados de la persona fallecida, o bien pariente colateral mayor de sesenta y cinco años que hubiese convivido con el causante durante los dos años anteriores al fallecimiento, estuviese incluida la vivienda habitual de la persona fallecida para obtener la base liquidable se aplicará en la base imponible, una reducción del 95 por 100 con el límite de 123.000 euros para cada sujeto, siempre que la adquisición se mantenga, durante los cinco años siguientes al fallecimiento del causante, salvo que falleciese el adquirente dentro de este plazo.\n5. Cuando en la base imponible correspondiente a una adquisición mortis causa del cónyuge, descendientes o adoptados de la persona fallecida se incluyeran bienes comprendidos en el artículo 4, apartados 1, 2 y 3, de la Ley 19/1991, de 6 de junio, del Impuesto sobre el Patrimonio, en cuanto integrantes del Patrimonio Histórico Español o Cultural de las Comunidades Autónomas, se aplicará, asimismo, una reducción del 95 por 100 de su valor con el mismo requisito de permanencia señalado en el apartado 4.\nEn el caso de no cumplirse el requisito de permanencia al que se refieren los anteriores apartados 4 y 5 el adquirente beneficiario de esta reducción deberá declarar tal circunstancia a la Administración Tributaria de la Comunidad de Madrid y pagar la parte del impuesto que se hubiese dejado de ingresar como consecuencia de la reducción practicada junto con los correspondientes intereses de demora dentro del plazo de treinta días hábiles desde que se produzca el hecho determinante del incumplimiento.\nDos. Reducciones propias por determinadas prestaciones.\n1. Cuando en la base imponible del impuesto se integren indemnizaciones satisfechas por las Administraciones Públicas a los herederos de los afectados por el síndrome tóxico, se practicará una reducción propia del 99 por 100 sobre los importes percibidos, cualquiera que sea la fecha de devengo del impuesto.\n2. Se aplicará el mismo porcentaje de reducción y con el mismo carácter en las prestaciones públicas extraordinarias por actos de terrorismo percibidas por los herederos.\n3. No será de aplicación la reducción cuando las indemnizaciones percibidas estén sujetas al Impuesto sobre la Renta de las Personas Físicas.","u":"#a21","c":"CAPÍTULO III. Impuesto sobre Sucesiones y Donaciones · Sección 1ª. Reducciones de la base imponible"},{"n":"MAD","a":"22","t":"Reducción propia por la adquisición de bienes y derechos afectos a una actividad económica y de participaciones en entidades.","x":"Uno. Reducción por la adquisición “mortis causa” de empresa individual o negocio profesional.\n1. En los casos en los que en la base imponible de una adquisición mortis causa estuviese incluido el valor de una empresa individual o de un negocio profesional o el valor de derechos de usufructo sobre los mismos, o de derechos económicos derivados de la extinción de dicho usufructo, siempre que con motivo del fallecimiento se consolidara el pleno dominio, o se percibieran los derechos debidos a la finalización del usufructo en forma de participaciones en la empresa o negocio afectado, se aplicará en la base imponible una reducción del 99 % del mencionado valor, siempre que se cumplan los siguientes requisitos:\na) Que el adquirente esté comprendido en los Grupos I, II y III previstos en el artículo 20.2 a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones o sea colateral de cuarto grado por consanguinidad o afinidad del causante.\nb) Que el causante haya ejercido la actividad empresarial o profesional de forma habitual, personal y directa a la fecha del fallecimiento y haya percibido rendimientos netos de la actividad que supongan más del 50 por 100 de los rendimientos del trabajo y de actividades económicas en el impuesto sobre la renta de las personas físicas. Este requisito podrá cumplirse tanto en el período que abarque desde 1 de enero hasta el día del fallecimiento como en el año natural anterior.\nA efectos del cálculo anterior, no se computarán entre los rendimientos del trabajo y de actividades económicas los rendimientos derivados de las funciones de dirección a que se refiere el número dos de este artículo.\nNo obstante, en el caso de que el causante se encontrara en situación de incapacidad permanente absoluta o gran invalidez reconocida a la fecha del fallecimiento, los requisitos previstos en el párrafo b) habrán de cumplirse por cualquiera de las personas contempladas en el párrafo a).\nTambién se aplicará la reducción a los bienes y derechos comunes a ambos miembros del matrimonio o de la unión de hecho equiparada, cuando se utilicen en el desarrollo de la actividad empresarial o profesional de cualquiera de los cónyuges, siempre que se cumplan los requisitos anteriores.\nc) Que durante los cinco años siguientes a la fecha de fallecimiento del causante el adquirente mantenga en su patrimonio los bienes y derechos adquiridos, salvo que falleciera dentro de este plazo, manteniendo su afectación a una actividad económica durante el referido plazo.\n2. La reducción prevista en este apartado, con los mismos requisitos establecidos, será aplicable a aquellos adquirentes que estén comprendidos en el Grupo IV del artículo 20.2 a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones distintos de los colaterales de cuarto grado por consanguinidad y afinidad, y que cumplan, además, los siguientes requisitos:\na) Tener un contrato laboral o de prestación de servicios dentro de la empresa o negocio profesional del causante que esté vigente a la fecha del fallecimiento de este y acreditar una antigüedad mínima de diez años en la empresa o negocio.\nb) Ejercer funciones de dirección en la empresa o negocio a la fecha del fallecimiento del causante y con una antigüedad mínima de cuatro años ininterrumpidos en el ejercicio de éstas inmediatamente anteriores a la fecha del fallecimiento.\n3. La reducción se aplicará sobre el valor neto de los bienes y derechos de las personas físicas necesarios para el desarrollo de su actividad, calculado conforme al artículo 11 de la Ley 19/1991, de 6 de junio, del impuesto sobre el patrimonio.\n4. Esta reducción es incompatible con la contemplada en el artículo 20.2 c) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones. La opción por la reducción propia prevista en este apartado deberá efectuarse dentro del plazo de presentación de la autoliquidación correspondiente al fallecimiento del causante.\nDos. Reducción por la adquisición “mortis causa” de participaciones en entidades.\n1. En los casos en los que en la base imponible de una adquisición mortis causa estuviese incluido el valor de participaciones en entidades, o el valor de derechos de usufructo sobre las mismas, o de derechos económicos derivados de la extinción de dicho usufructo, siempre que con motivo del fallecimiento se consolidara el pleno dominio, o se percibieran los derechos debidos a la finalización del usufructo en forma de participaciones en la entidad afectada, se aplicará en la base imponible una reducción del 99 % del valor de los citados derechos, siempre que se cumplan los siguientes requisitos:\na) Que el adquirente esté comprendido en los Grupos I, II y III previstos en el artículo 20.2 a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, o sea colateral de cuarto grado por consanguinidad o afinidad del causante.\nb) Que la participación del causante en el capital de la entidad sea al menos del 5 % computado de forma individual, o del 20 % del grupo de parentesco formado conjuntamente con su cónyuge, ascendientes, descendientes o colaterales hasta el cuarto grado, ya tenga su origen el parentesco en la consanguinidad, en la afinidad o en la adopción.\nc) Que el causante o alguna de las personas del grupo de parentesco conforme a lo establecido en la letra anterior, tengan o no participación en la entidad, ejerza efectivamente funciones de dirección en la entidad, percibiendo por ello remuneración que represente más del 50 por 100 de los rendimientos del trabajo y de actividades económicas en el impuesto sobre la renta de las personas físicas, que podrá cumplirse tanto en el período que abarque desde 1 de enero hasta el día del fallecimiento como en el año natural anterior. A efectos del cálculo anterior, no se computarán entre los rendimientos del trabajo y de actividades económicas, los rendimientos de la actividad económica a que se refiere el número uno de este artículo.\nd) Que la entidad no tenga por actividad principal la gestión de un patrimonio mobiliario o inmobiliario, de conformidad con lo establecido en el artículo 4.Ocho.Dos.a) de la Ley 19/1991, de 6 de junio, del Impuesto sobre el Patrimonio.\ne) Que el adquirente mantenga en su patrimonio las participaciones en la entidad durante los cinco años siguientes a la fecha de fallecimiento del causante, salvo que falleciera dentro de este plazo, debiendo conservarse el carácter económico de la actividad de la entidad en los términos señalados en la letra a) del punto Dos, apartado Ocho, del artículo 4 de la Ley 19/1991, del Impuesto sobre el Patrimonio, en el referido plazo.\nAsimismo, no podrán realizarse actos de disposición y operaciones societarias que, directa o indirectamente, puedan dar lugar a una minoración sustancial del valor de la adquisición.\n2. La reducción prevista en este apartado, con los mismos requisitos establecidos, será aplicable a aquellos adquirentes que estén comprendidos en el Grupo IV del artículo 20.2 a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones distintos de los colaterales de cuarto grado por consanguinidad y afinidad, y que cumplan, además, los siguientes requisitos:\na) Tener un contrato laboral o de prestación de servicios dentro de la entidad que esté vigente a la fecha del fallecimiento de este y acreditar una antigüedad mínima de diez años en la entidad.\nb) Ejercer funciones de dirección en la entidad a la fecha del fallecimiento del causante y con una antigüedad mínima de cuatro años ininterrumpidos en el ejercicio de éstas inmediatamente anteriores a la fecha del fallecimiento.\n3. El importe de la reducción solo alcanzará al valor de las participaciones, en la parte que corresponda a la proporción existente entre los activos necesarios para el ejercicio de la actividad empresarial o profesional, minorados en el importe de las deudas derivadas de la misma, y el valor del patrimonio neto de la entidad, aplicándose estas mismas reglas en la valoración de las participaciones de entidades participadas para determinar el valor de las de su entidad tenedora.\nNo obstante, también será aplicable la reducción a la tesorería, los activos representativos de la participación en fondos propios de una entidad y de la cesión de capitales a terceros cuyo precio de adquisición no supere el importe de los beneficios no distribuidos obtenidos por la entidad, siempre que dichos beneficios provengan de la realización de actividades económicas, con el límite del importe de los beneficios obtenidos tanto en el propio ejercicio como en los diez ejercicios anteriores. A estos efectos, se asimilan a los beneficios procedentes de actividades económicas los dividendos y plusvalías que procedan de los valores de entidades participadas cuando los ingresos obtenidos por estas procedan, al menos en el 80 %, de la realización de actividades económicas.\n4. Esta reducción es incompatible con la contemplada en el artículo 20.2 c) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones. La opción por la reducción propia prevista en este apartado deberá efectuarse dentro del plazo de presentación de la autoliquidación correspondiente al fallecimiento del causante.\nTres. Reducción por la adquisición gratuita “inter vivos” de empresa individual o negocio profesional.\n1. En el supuesto de adquisición inter vivos de una empresa individual o negocio profesional se aplicará en la base imponible una reducción del 99 % del valor neto de los citados bienes y derechos, siempre que se cumplan los siguientes requisitos:\na) Que el donatario esté comprendido en los Grupos I, II y III previstos en el artículo 20.2 a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, o sea colateral de cuarto grado por consanguinidad o afinidad del donante.\nb) Que el donante haya ejercido la actividad empresarial o profesional de forma habitual, personal y directa a la fecha de la donación y percibiera rendimientos por dicha actividad, que representen más del 50 por 100 de los rendimientos del trabajo y de actividades económicas en el impuesto sobre la renta de las personas físicas, que podrá cumplirse tanto en el período que abarque desde 1 de enero hasta el día de la transmisión, como en el año natural anterior. A efectos del cálculo anterior, no se computarán entre los rendimientos del trabajo y de actividades económicas, los rendimientos derivados de las funciones de dirección a que se refiere el número cuatro de este artículo.\nNo obstante, en el caso de que el donante se encontrará en situación de incapacidad permanente en grado de absoluta o gran invalidez reconocida a la fecha del devengo del impuesto, los requisitos previstos en el párrafo b) habrán de cumplirse por cualquiera de las personas contempladas en el párrafo a).\nTambién se aplicará la reducción a los bienes y derechos comunes a ambos miembros del matrimonio o unión de hecho equiparada, cuando se utilicen en el desarrollo de la actividad empresarial o profesional de cualquiera de los cónyuges, siempre que se cumplan los requisitos anteriores.\nc) Que el donatario mantenga en su patrimonio los bienes y derechos adquiridos durante los cinco años siguientes a la fecha de la donación, salvo que falleciera dentro de este plazo, manteniendo su afectación a una actividad económica durante el referido plazo.\n2. La reducción prevista en este apartado, con los mismos requisitos establecidos, será aplicable a aquellos adquirentes que estén comprendidos en el Grupo IV del artículo 20.2 a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones distintos de los colaterales de cuarto grado por consanguinidad y afinidad, y que cumplan, además, los siguientes requisitos:\na) Tener un contrato laboral o de prestación de servicios dentro de la empresa o negocio profesional del donante que esté vigente a la fecha de la donación y acreditar una antigüedad mínima de diez años en la empresa o negocio.\nb) Ejercer funciones de dirección en la empresa o negocio a la fecha de la donación y con una antigüedad mínima de cuatro años ininterrumpidos en el ejercicio de éstas inmediatamente anteriores a la fecha de la donación.\n3. La reducción se aplicará sobre el valor neto de los bienes y derechos de las personas físicas necesarios para el desarrollo de su actividad, calculado conforme al artículo 11 de la Ley 19/1991, de 6 de junio, del Impuesto sobre el Patrimonio.\n4. Esta reducción es incompatible con la contemplada en el artículo 20.6 de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones. La opción por la reducción propia prevista en este apartado deberá efectuarse dentro del plazo de presentación de la autoliquidación correspondiente a la donación.\nCuatro. Reducción por la adquisición gratuita “inter vivos” de participaciones en entidades.\n1. En el supuesto de adquisición inter vivos de participaciones en una entidad se aplicará una reducción en la base imponible del 99 % del valor neto de los citados bienes y derechos, siempre que se cumplan los siguientes requisitos:\na) Que el donatario esté comprendido en los Grupos I, II y III previstos en el artículo 20.2 a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones o sea colateral de cuarto grado por consanguinidad o afinidad del donante.\nb) Que la participación del donante en el capital de la entidad sea al menos del 5 % computado de forma individual, o del 20 % del grupo de parentesco formado conjuntamente con su cónyuge, ascendientes, descendientes o colaterales hasta de cuarto grado, ya tenga su origen el parentesco en la consanguinidad, en la afinidad o en la adopción.\nc) Que el donante o alguna de las personas del grupo de parentesco conforme a lo establecido en la letra anterior, tengan o no participación en la entidad, ejerza efectivamente funciones de dirección en la entidad, percibiendo por ello retribuciones que representen más del 50 por 100 de los rendimientos del trabajo y de actividades económicas en el impuesto sobre la renta de las personas físicas, que podrá cumplirse tanto en el período que abarque desde 1 de enero hasta el día de la transmisión, como en el año natural anterior. A efectos del cálculo anterior, no se computarán entre los rendimientos del trabajo y de actividades económicas, los rendimientos de actividades económicas a que se refiere el número tres de este artículo.\nd) Que la entidad no tenga por actividad principal la gestión de un patrimonio mobiliario o inmobiliario, de conformidad con lo establecido en el artículo 4.Ocho. Dos.a) de la Ley 19/1991, del Impuesto sobre el Patrimonio.\ne) Que el donatario mantenga en su patrimonio las participaciones en la entidad durante los cinco años siguientes a la fecha de la donación, salvo que falleciera dentro de este plazo, debiendo conservarse el carácter económico de la actividad de la entidad en los términos señalados en la letra a) del punto Dos, apartado Ocho, del artículo 4 de la Ley 19/1991, del Impuesto sobre el Patrimonio, en el referido plazo.\nAsimismo, no podrán realizarse actos de disposición y operaciones societarias que, directa o indirectamente, puedan dar lugar a una minoración sustancial del valor de la adquisición.\n2. La reducción prevista en este apartado, con los mismos requisitos establecidos, será aplicable a aquellos adquirentes que estén comprendidos en el Grupo IV del artículo 20.2 a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones distintos de los colaterales de cuarto grado por consanguinidad y afinidad, y que cumplan, además, los siguientes requisitos:\na) Tener un contrato laboral o de prestación de servicios dentro de la entidad que esté vigente a la fecha de la donación y acreditar una antigüedad mínima de diez años en la entidad.\nb) Ejercer funciones de dirección en la entidad a la fecha de la donación y con una antigüedad mínima de cuatro años ininterrumpidos en el ejercicio de éstas inmediatamente anteriores a la fecha de la donación.\n3. El importe de la reducción solo alcanzará al valor de las participaciones, en la parte que corresponda a la proporción existente entre los activos necesarios para el ejercicio de la actividad empresarial o profesional, minorados en el importe de las deudas derivadas de la misma, y el valor del patrimonio neto de la entidad, aplicándose estas mismas reglas en la valoración de las participaciones de entidades participadas para determinar el valor de las de su entidad tenedora.\nNo obstante, también será aplicable la reducción a la tesorería, los activos representativos de la participación en fondos propios de una entidad y de la cesión de capitales a terceros cuyo precio de adquisición no supere el importe de los beneficios no distribuidos obtenidos por la entidad, siempre que dichos beneficios provengan de la realización de actividades económicas, con el límite del importe de los beneficios obtenidos tanto en el propio ejercicio como en los diez ejercicios anteriores. A estos efectos, se asimilan a los beneficios procedentes de actividades económicas los dividendos y plusvalías que procedan de los valores de entidades participadas cuando los ingresos obtenidos por estas procedan, al menos en el 80 %, de la realización de actividades económicas.\n4. Esta reducción es incompatible con la contemplada en el artículo 20.6 de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones. La opción por la reducción propia prevista en este apartado deberá efectuarse dentro del plazo de presentación de la autoliquidación correspondiente a la donación.\nCinco. En el caso de no cumplirse el requisito de permanencia en el patrimonio del adquirente al que se refieren los anteriores apartados del artículo, el adquirente beneficiario de esta reducción deberá declarar tal circunstancia a la Administración Tributaria de la Comunidad de Madrid y pagar la parte del impuesto que se hubiese dejado de ingresar como consecuencia de la reducción practicada junto con los correspondientes intereses de demora dentro del plazo de treinta días hábiles desde que se produzca el hecho determinante del incumplimiento.","u":"#a22","c":"CAPÍTULO III. Impuesto sobre Sucesiones y Donaciones · Sección 1ª. Reducciones de la base imponible"},{"n":"MAD","a":"22 bis","t":"Reducción propia por determinadas donaciones en metálico.","x":"1. En las donaciones en metálico que cumplan los requisitos establecidos en el presente apartado y en los dos siguientes, en las que el donatario esté incluido en los grupos I o II de parentesco de los previstos en el artículo 20.2.a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, o sea un colateral de segundo grado por consanguinidad del donante, se podrá aplicar una reducción del 100 por cien de la donación recibida, con el límite máximo de 250.000 euros.\nA efectos de la aplicación del límite indicado en el párrafo anterior, se computarán todas las donaciones efectuadas por el mismo donante al mismo donatario en los tres años anteriores al momento del devengo, siempre que se destinen a los fines indicados en el apartado 2, de forma que no podrá superarse el límite de reducción establecido por el conjunto de todas las donaciones computables.\n2. La reducción prevista en el apartado anterior se aplicará sobre las donaciones en metálico en las que el importe donado se destine por el donatario, en el plazo de un año desde la donación, a uno de los siguientes fines:\na) La adquisición de una vivienda que tenga la consideración de habitual.\nA tal efecto, se considerará vivienda habitual la que se ajusta a la definición y requisitos establecidos en la disposición adicional vigésima tercera de la Ley 35/2006, de 28 de noviembre, del Impuesto sobre la Renta de las Personas Físicas, y en su normativa de desarrollo, en su redacción vigente desde el 1 de enero de 2013.\nb) La adquisición de acciones y participaciones sociales como consecuencia de acuerdos de constitución o de ampliación de capital de entidades que revistan la forma de Sociedad Anónima, Sociedad Anónima Laboral, Sociedad de Responsabilidad Limitada, Sociedad de Responsabilidad Limitada Laboral y Sociedad Cooperativa, en las condiciones a que se refiere el artículo 15 de esta ley.\nc) La adquisición bienes, servicios y derechos que se afecten al desarrollo de una empresa individual o de un negocio profesional del donatario.\n3. En el documento en que se formalice la donación deberá manifestarse el destino de las cantidades donadas.\nSerá requisito necesario para la aplicación de esta reducción que la donación se formalice en documento público cuando su base imponible sea superior a 10.000 euros o su contravalor en moneda extranjera. A estos efectos, se computarán todas las donaciones efectuadas por el mismo donante al mismo donatario en los tres años anteriores al momento del devengo.\nEn los supuestos de elevación a público de documentos privados que documenten la donación no será aplicable la reducción cuando la formalización en documento público se realice con posterioridad a la finalización del correspondiente periodo voluntario de declaración.\n4. En el caso en que las cantidades donadas no llegasen a destinarse a los fines indicados en el plazo establecido, el donatario deberá presentar, en el plazo de un mes desde que se produzca el incumplimiento, una autoliquidación complementaria sin aplicación de la reducción contenida en este artículo e incluyendo los correspondientes intereses de demora.\nLa misma obligación tendrá quien recibe la donación para la adquisición de vivienda habitual en el caso de que la vivienda adquirida no llegue a habitarse efectivamente en el plazo de 12 meses desde su adquisición o construcción o no se habite efectivamente durante un plazo mínimo continuado de tres años, salvo que concurran las circunstancias indicadas en la disposición adicional vigésima tercera de la Ley 35/2006, de 28 de noviembre, del Impuesto sobre la Renta de las Personas Físicas, y en su normativa de desarrollo, en su redacción vigente desde el 1 de enero de 2013.\nLa reducción será aplicable, exclusivamente, sobre la parte que proporcionalmente corresponda a los bienes y derechos declarados por el sujeto pasivo, considerándose como tales a los que se encuentren incluidos de forma completa en una autoliquidación o declaración presentada dentro del plazo voluntario o fuera de este sin que se haya efectuado un requerimiento previo de la Administración tributaria.\nTexto añadido, publicado el 28/12/2018, en vigor a partir del 01/01/2019.","u":"#a2-2","c":"CAPÍTULO III. Impuesto sobre Sucesiones y Donaciones · Sección 1ª. Reducciones de la base imponible"},{"n":"MAD","a":"23","t":"Tarifa del Impuesto.","x":"La tarifa prevista en el artículo 21.1 de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, será la siguiente:\n| Base liquidable<br>(hasta euros) | Cuota íntegra<br>(euros) | Resto base liquidable<br>(hasta euros) | Tipo aplicable<br>(porcentaje) |\n| -------------------------------- | ------------------------ | -------------------------------------- | ------------------------------ |\n| 0,00 | 0,00 | 8.313,20 | 7,65 |\n| 8.313,20 | 635,96 | 7.688,15 | 8,50 |\n| 16.001,35 | 1.289,45 | 8.000,66 | 9,35 |\n| 24.002,01 | 2.037,51 | 8.000,69 | 10,20 |\n| 32.002,70 | 2.853,58 | 8.000,66 | 11,05 |\n| 40.003,36 | 3.737,66 | 8.000,68 | 11,90 |\n| 48.004,04 | 4.689,74 | 8.000,67 | 12,75 |\n| 56.004,71 | 5.709,82 | 8.000,68 | 13,60 |\n| 64.005,39 | 6.797,92 | 8.000,66 | 14,45 |\n| 72.006,05 | 7.954,01 | 8.000,68 | 15,30 |\n| 80.006,73 | 9.178,12 | 39.940,85 | 16,15 |\n| 119.947,58 | 15.628,56 | 39.940,87 | 18,70 |\n| 159.888,45 | 23.097,51 | 79.881,71 | 21,25 |\n| 239.770,16 | 40.072,37 | 159.638,43 | 25,50 |\n| 399.408,59 | 80.780,17 | 399.408,61 | 29,75 |\n| 798.817,20 | 199.604,23 | En adelante | 34,00 |","u":"#a23","c":"CAPÍTULO III. Impuesto sobre Sucesiones y Donaciones · Sección 2ª. Tarifa y cuota tributaria"},{"n":"MAD","a":"24","t":"Cuota tributaria.","x":"1. La cuota tributaria prevista en el artículo 22.1 de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, se obtendrá aplicando a la cuota íntegra el coeficiente multiplicador en función de la cuantía del patrimonio preexistente y de los grupos de parentesco siguientes:\n| Patrimonio Preexistente en euros | Grupos del artículo 20 | | |\n| -------------------------------- | ---------------------- | ------ | ---- |\n| | I y II | III | IV |\n| De 0 a 403.000 | 1,00 | 1,5882 | 2,00 |\n| De más de 403.000 a 2.008.000 | 1,05 | 1,6676 | 2,1 |\n| De más de 2.008.000 a 4.021.000 | 1,10 | 1,7471 | 2,2 |\n| De más de 4.021.000 | 1,20 | 1,9059 | 2,4 |\n2. Cuando la diferencia entre la cuota tributaria obtenida por aplicación del coeficiente multiplicador que corresponda y la que resultaría de aplicar a la misma cuota íntegra el coeficiente multiplicador inmediato inferior sea mayor que la que exista entre el importe del patrimonio preexistente tenido en cuenta para la liquidación y el importe máximo del tramo del patrimonio preexistente que motivaría la aplicación del citado coeficiente multiplicador inferior, aquella se reducirá en el importe del exceso.\n3. En los casos de seguros sobre la vida se aplicará el coeficiente que corresponda al patrimonio preexistente del beneficiario y al grupo en que por su parentesco con el contratante estuviese encuadrado. En los seguros colectivos o contratados por las empresas en favor de sus empleados se estará al coeficiente que corresponda al patrimonio preexistente del beneficiario y al grado de parentesco entre este y el asegurado.\n4. Si no fuesen conocidos los causahabientes en una sucesión, se aplicará el coeficiente establecido para los colaterales de cuarto grado y extraños cuando el patrimonio preexistente exceda de 4.021.000 euros, sin perjuicio de la devolución que proceda una vez que aquéllos fuesen conocidos.","u":"#a24","c":"CAPÍTULO III. Impuesto sobre Sucesiones y Donaciones · Sección 2ª. Tarifa y cuota tributaria"},{"n":"MAD","a":"25","t":"Bonificaciones de la cuota.","x":"Serán aplicables las siguientes bonificaciones:\n1. Bonificación en adquisiciones mortis causa.\nLos sujetos pasivos incluidos en los grupos I y II de los previstos en el artículo 20.2.a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, aplicarán una bonificación del 99 por ciento en la cuota tributaria derivada de adquisiciones mortis causa y de cantidades percibidas por beneficiarios de seguros sobre la vida que se acumulen al resto de bienes y derechos que integren la porción hereditaria del beneficiario.\nLos sujetos pasivos incluidos en el grupo III de los previstos en el artículo 20.2.a) indicado en el párrafo anterior, aplicarán una bonificación del 50 por ciento, de la cuota tributaria derivada de las mismas adquisiciones a que se refiere el párrafo anterior. La bonificación a que se refiere este párrafo será aplicable, exclusivamente, sobre la parte de la cuota que proporcionalmente corresponda a los bienes y derechos declarados por el sujeto pasivo, considerándose como tales a los que se encuentren incluidos de forma completa en una autoliquidación o declaración presentada dentro del plazo voluntario o fuera de este sin que se haya efectuado un requerimiento previo de la Administración tributaria.\n2. Bonificaciones en adquisiciones inter vivos:\na) Los sujetos pasivos que realicen adquisiciones lucrativas inter vivos procedentes de personas físicas cuya base imponible no supere los 1.000 euros aplicarán una bonificación del 100 por cien de la cuota tributaria derivada de las mismas.\nA efectos de la aplicación del límite indicado en el párrafo anterior, se computarán todos los negocios lucrativos inter vivos efectuados por el mismo donante al mismo donatario en los tres años anteriores al momento del devengo, de forma que no podrá aplicarse la bonificación una vez superado el límite establecido por el conjunto de todas las adquisiciones lucrativas inter vivos computables.\nLos contribuyentes que apliquen esta bonificación no estarán obligados a presentar autoliquidación por el impuesto. No obstante, mantendrán la obligación de presentar la autoliquidación los adquirentes de bienes que deban ser objeto de inscripción en cualquier registro público.\nb) En las adquisiciones inter vivos, los sujetos pasivos incluidos en los grupos I y II de parentesco de los previstos en el artículo 20.2.a) de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, aplicarán una bonificación del 99 por ciento en la cuota tributaria derivada de las mismas.\nLos sujetos pasivos incluidos en el grupo III de los previstos en el artículo 20.2.a) indicado en el párrafo anterior aplicarán una bonificación del 50 por ciento en la cuota tributaria derivada de las mismas adquisiciones a que se refiere el párrafo anterior.\nLas bonificaciones a que se refiere este apartado 2.b) del presente artículo serán aplicables, exclusivamente, sobre la parte de la cuota que proporcionalmente corresponda a los bienes y derechos declarados por el sujeto pasivo, considerándose como tales a los que se encuentren incluidos de forma completa en una autoliquidación o declaración presentada dentro del plazo voluntario o fuera de este sin que se haya efectuado un requerimiento previo de la Administración tributaria. Cuando el negocio jurídico gratuito e inter vivos sea en metálico o en cualquiera de los bienes o derechos contemplados en el artículo 12 de la Ley 19/1991, de 6 de junio, del Impuesto sobre el Patrimonio, la bonificación solo resultará aplicable cuando el origen de los fondos donados esté debidamente justificado, siempre que, además, se haya manifestado en el propio documento en que se formalice la transmisión el origen de dichos fondos.\nSerá requisito necesario para la aplicación de estas bonificaciones previstas en el apartado 2.b), en relación a los elementos patrimoniales cuyas transmisiones a título gratuito no requieren para su eficacia el otorgamiento de documento público, que el negocio jurídico gratuito e inter vivos se formalice en documento público cuando su base imponible sea superior a 10.000 euros o su contravalor en moneda extranjera. A estos efectos, se computarán todos los negocios jurídicos gratuitos e inter vivos efectuados por el mismo donante al mismo donatario en los tres años anteriores al momento del devengo.\nEn los supuestos de elevación a público de documentos privados que documenten la adquisición, no serán aplicables las bonificaciones previstas en este apartado 2.b) cuando la formalización en documento público se realice con posterioridad a la finalización del correspondiente periodo voluntario de declaración»","u":"#a25","c":"CAPÍTULO III. Impuesto sobre Sucesiones y Donaciones · Sección 3ª. Bonificaciones de la cuota"},{"n":"MAD","a":"26","t":"Uniones de hecho y menores acogidos y tutelados.","x":"1. Uniones de hecho y menores acogidos y tutelados.\n1. A efectos de la aplicación de lo dispuesto en este capítulo, se asimilarán a cónyuges los miembros de uniones de hecho que cumplan los requisitos establecidos en la Ley 11/2001, de 19 de diciembre, de Uniones de Hecho de la Comunidad de Madrid y se encuentren inscritas en el Registro de Uniones de Hecho de la Comunidad de Madrid o en registros análogos existentes en otras Administraciones públicas, dentro o fuera del ámbito español.\n2. Asimismo, se asimilan a descendientes y adoptados a los menores vinculados al transmitente por razón de tutela o acogimiento familiar en los términos previstos en la legislación civil aplicable.","u":"#a26","c":"CAPÍTULO III. Impuesto sobre Sucesiones y Donaciones · Sección 4ª. Normas comunes"},{"n":"MAD","a":"48","t":"Obligaciones formales de Notarios.","x":"1. El cumplimiento de las obligaciones formales de los Notarios, recogidas en los artículos 32.3 de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, y en el artículo 52 del Texto Refundido del Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados, aprobado por Real Decreto Legislativo 1/1993, de 24 de septiembre, se realizará en la forma, condiciones y plazos que se determinen por la Consejería competente en materia de Hacienda. La remisión de dicha información podrá exigirse en soporte directamente legible por ordenador y por vía telemática.\n2. 1.º Los Notarios con destino en la Comunidad de Madrid remitirán por vía telemática a la Dirección General de Tributos de la Consejería competente en materia de Hacienda un documento informativo de los elementos básicos de las escrituras por ellos autorizadas, así como la copia electrónica de las mismas de conformidad con lo dispuesto en la legislación notarial.\nEste documento informativo deberá remitirse respecto de los hechos imponibles que determine la Consejería competente en materia de Hacienda, quien, además, establecerá los procedimientos, estructura y plazos en los que debe ser remitida esta información, dentro de los límites establecidos en el apartado 4 del artículo 93 de la Ley 58/2003, de 17 de diciembre, General Tributaria.\n2.º El justificante de la recepción por parte de la Administración de la copia electrónica de la escritura, en los términos que determine la Consejería competente en materia de Hacienda, junto con el ejemplar para el interesado de la autoliquidación en la que conste el pago del tributo o la no sujeción o exención, debidamente validada, en la forma determinada por la Consejería competente en materia de Hacienda, serán requisitos suficientes para justificar el pago de la liquidación correspondiente, su exención o no sujeción, a efectos de los dispuesto en el artículo 122 del Real Decreto 828/1995, de 29 de mayo, por el que se aprueba el Reglamento del Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados y en el artículo 100 del Real Decreto 1629/1991, de 8 de noviembre, por el que se aprueba el Reglamento del Impuesto sobre Sucesiones y Donaciones.\nEn todo caso, el justificante de presentación o pago telemático regulado por la Consejería competente en materia de Hacienda servirá, a todos los efectos, de justificante de presentación y pago de la autoliquidación.\n3.º La Consejería competente en materia de Hacienda habilitará un sistema de confirmación permanente e inmediata que posibilite a las oficinas y registros públicos, juzgados y tribunales verificar la concordancia del justificante de presentación o pago telemático con los datos que constan en la Administración Tributaria.","u":"#a48","c":"TÍTULO II. Obligaciones formales · CAPÍTULO I. Impuestos sobre Sucesiones y Donaciones y sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados"},{"n":"MAD","a":"49","t":"Obligaciones formales de los Registradores de la Propiedad y Mercantiles.","x":"1. Los Registradores de la Propiedad y Mercantiles con destino en el ámbito territorial de la Comunidad de Madrid deberán remitir a la Consejería competente en materia de Hacienda, en la primera quincena de cada trimestre, una declaración con la relación de los documentos relativos a actos o contratos sujetos al Impuesto sobre Sucesiones y Donaciones o al Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados que se presenten a inscripción, cuando el pago o la presentación de la declaración se haya realizado en otra Comunidad Autónoma a la que no corresponda el rendimiento de los impuestos. Dicha declaración irá referida al trimestre anterior.\n2. Mediante convenio entre la Comunidad de Madrid y el Colegio de Registradores de la Propiedad y Mercantiles de Madrid o, en su defecto, por Orden de la Consejería competente en materia de Hacienda, podrá establecerse el formato, condiciones, diseño y demás extremos necesarios para el cumplimiento de las obligaciones formales a que se refiere el apartado anterior, que podrá consistir en soporte legible por ordenador o mediante transmisión por vía telemática.","u":"#a49","c":"TÍTULO II. Obligaciones formales · CAPÍTULO I. Impuestos sobre Sucesiones y Donaciones y sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados"},{"n":"MAD","a":"50","t":"Autoliquidación mensual del Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados, de los empresarios dedicados a la compraventa de objetos fabricados con metales preciosos.","x":"1. Los adquirentes de objetos fabricados con metales preciosos que estén obligados a la llevanza del libro-registro a que hace referencia el artículo 91 del Real Decreto 197/1988, de 22 de febrero, por el que se aprueba el Reglamento de la Ley de objetos fabricados con metales preciosos, declararán conjuntamente todas las operaciones sujetas a la modalidad de «Transmisiones Patrimoniales Onerosas» del Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados devengadas en cada mes natural. A tal efecto, presentarán una única autoliquidación comprensiva de la totalidad de las operaciones realizadas en cada mes natural.\n2. El plazo de presentación e ingreso de la autoliquidación será treinta días hábiles a contar desde el último día del mes al que se refieran las operaciones declaradas.\n3. La autoliquidación se presentará sin documentación adicional, sin perjuicio de que pueda requerirse por la Administración el detalle de las operaciones objeto de declaración, en cuyo caso deberá ponerse a su disposición copia de las páginas del libro-registro indicado en el apartado 1 anterior, en caso de cumplimentarse éste en papel, o una relación, firmada por el declarante, de las operaciones incluidas en dicho libro-registro, en caso de cumplimentarse por otros medios, que contengan la información relativa a tales operaciones.\nPor orden del Consejero competente en materia de Hacienda podrá regularse la documentación complementaria que debe acompañarse a la autoliquidación y, en su caso, la obligatoriedad de su presentación telemática.","u":"#a50","c":"TÍTULO II. Obligaciones formales · CAPÍTULO I. Impuestos sobre Sucesiones y Donaciones y sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados"},{"n":"MAD","a":"50 bis","t":"Exclusión de la obligación de presentación de autoliquidación del Impuesto sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados por adquisición de bienes muebles y semovientes de escaso valor.","x":"Los sujetos pasivos que realicen las adquisiciones de bienes a las que resulte de aplicación la bonificación contenida en el artículo 30 ter de esta ley no estarán obligados a presentar autoliquidación por el impuesto.\nNo obstante lo anterior, mantendrán la obligación de presentar la autoliquidación los adquirentes de bienes que deban ser objeto de inscripción en cualquier registro público.\nTexto añadido, publicado el 28/12/2018, en vigor a partir del 01/01/2019.","u":"#a5-2","c":"TÍTULO II. Obligaciones formales · CAPÍTULO I. Impuestos sobre Sucesiones y Donaciones y sobre Transmisiones Patrimoniales y Actos Jurídicos Documentados"},{"n":"VAL","a":"10","t":"Reducciones en transmisiones mortis causa.","x":"Para el cálculo de la base liquidable del Impuesto sobre Sucesiones y Donaciones, en las transmisiones mortis causa resultarán aplicables las siguientes reducciones:\n1. Con el carácter de reducciones análogas a las aprobadas por el Estado con la misma finalidad:\na) La que corresponda de las incluidas en los grupos siguientes:\n– Grupo I: adquisiciones por descendientes y adoptados menores de 21 años, 100.000 euros, más 8.000 euros por cada año menos de 21 que tenga el causahabiente, sin que la reducción pueda exceder de 156.000 euros.\n– Grupo II: adquisiciones por descendientes y adoptados de 21 o más años, cónyuges, ascendientes y adoptantes, 100.000 euros.\nb) En las adquisiciones por personas con un grado de discapacidad igual o superior al 33 por 100, se aplicará una reducción de 120.000 euros, además de la que pudiera corresponder en función del grado de parentesco con el causante. En las adquisiciones por personas con un grado de discapacidad igual o superior al 65 por 100, o un grado de discapacidad intelectual o mental reconocido de manera permanente igual o superior al 33 por 100, la reducción antes citada será de 240.000 euros.\nc) En las adquisiciones de la vivienda habitual del causante, se aplicará, con el límite de 150.000 euros para cada sujeto pasivo, una reducción del 95 por 100 del valor de dicha vivienda, siempre que los causahabientes sean el cónyuge, ascendientes o descendientes de aquel, o bien pariente colateral mayor de sesenta y cinco años de edad que hubiese convivido con el causante durante los dos años anteriores al fallecimiento, y que la adquisición se mantenga durante los cinco años siguientes al fallecimiento del causante, salvo que falleciera el adquirente dentro de ese plazo.\nd) En los casos en los que en la base imponible de una adquisición mortis causa a favor del cónyuge, descendientes o adoptados, ascendientes o adoptantes, o parientes colaterales hasta el cuarto grado del causante estuviese incluido el valor de una empresa individual o de un negocio profesional o el valor de derechos de usufructo sobre los mismos, o de derechos económicos derivados de la extinción de dicho usufructo, siempre que con motivo del fallecimiento se consolidara el pleno dominio, o se percibieran los derechos debidos a la finalización del usufructo en forma de participaciones en la empresa o negocio afectado, se aplicará en la base imponible una reducción del 99 por 100 del valor neto de los elementos patrimoniales afectos a la empresa o al negocio, siempre que se cumplan los siguientes requisitos:\n1.º) Que la actividad se ejerza por el causante de forma habitual, personal y directa.\n2.º) Que dicha actividad constituya la mayor fuente de renta del causante, entendiendo por tal la que proporcione un importe superior de los rendimientos del trabajo o de las actividades económicas.\nA tal efecto, no se tendrán en cuenta, siempre que se cumplan las condiciones en cada caso establecidas, todas aquellas remuneraciones que traigan causa de las participaciones del causante que disfruten de reducción en el impuesto.\nCuando un mismo causante ejerza dos o más actividades de forma habitual, personal y directa, la reducción alcanzará a todos los bienes y derechos afectos a las mismas, considerándose que su mayor fuente de renta a estos efectos viene determinada por el conjunto de los rendimientos de todas ellas.\n3.º) Que durante los cinco años siguientes a la fecha del fallecimiento del causante el adquirente mantenga la adquisición, salvo que falleciera dentro de este plazo. Asimismo, el causahabiente no podrá realizar actos de disposición u operaciones societarias que, directa o indirectamente, puedan dar lugar a una minoración sustancial del valor de la adquisición.\nEn el caso de no cumplirse el citado plazo, deberá abonarse la parte del impuesto que se hubiese dejado de ingresar como consecuencia de la reducción practicada y los intereses de demora.\nEn el caso de que el causante se encontrara jubilado de la actividad de la empresa o negocio o en situación de incapacidad permanente absoluta o gran invalidez reconocida en el momento del fallecimiento, los requisitos anteriores se habrán de cumplir por alguno de los adquirentes incluidos en el primer párrafo de la presente letra. Si, en el momento de la jubilación, el causante hubiera cumplido los 65 años, la reducción aplicable será la general del 99 por 100, siendo del 90 por 100 si, en aquel momento, el causante tuviera entre 60 y 64 años cumplidos.\nTambién se aplicará la mencionada reducción respecto del valor neto de los bienes del causante afectos al desarrollo de la actividad empresarial o profesional del cónyuge sobreviviente, por la parte en que resulte adjudicatario de aquellos, con sujeción a lo dispuesto en el artículo 27 de la Ley 29/1987, de 18 de diciembre, del impuesto sobre sucesiones y donaciones. En tal caso, los requisitos a los que hacen referencia los ordinales anteriores se habrán de cumplir en el cónyuge adjudicatario. En el caso de no cumplirse, deberá abonarse la parte del impuesto que se hubiese dejado de ingresar como consecuencia de la reducción practicada y los intereses de demora.\ne) En los casos en los que en la base imponible de una adquisición mortis causa a favor del cónyuge, descendientes o adoptados, ascendientes o adoptantes, o parientes colaterales hasta el cuarto grado del causante estuviese incluido el valor de participaciones en entidades, o el valor de derechos de usufructo sobre las mismas, o de derechos económicos derivados de la extinción de dicho usufructo, siempre que con motivo del fallecimiento se consolidara el pleno dominio, o se percibieran los derechos debidos a la finalización del usufructo en forma de participaciones en la entidad afectada, se aplicará en la base imponible una reducción del 99 por 100 del valor de las participaciones, siempre que se cumplan los siguientes requisitos:\n1.º) Que la entidad, sea o no societaria, no tenga por actividad principal la gestión de un patrimonio mobiliario o inmobiliario, de conformidad con lo establecido en el artículo 4. Ocho.Dos.a de la Ley 19/1991, del Impuesto sobre el Patrimonio.\n2.º) Que la participación del causante en el capital de la entidad sea al menos del 5 por 100 computado de forma individual, o del 20 por 100 conjuntamente con su cónyuge, ascendientes o adoptantes, descendientes o adoptados, o colaterales hasta el cuarto grado, ya tenga su origen el parentesco en la consanguinidad, en la afinidad o en la adopción.\n3.º) Que el causante o, en el caso de participación conjunta, alguna de las personas del grupo familiar a que se refiere el ordinal anterior ejerzan efectivamente funciones de dirección en la entidad.\n4.º) Que la retribución que se perciba por las funciones de dirección suponga la mayor fuente de renta, entendiendo por tal la que proporcione un importe superior de los rendimientos del trabajo o de las actividades económicas.\nA tales efectos, no se tendrán en cuenta los rendimientos de las actividades económicas cuyos bienes y derechos afectos disfruten de reducción en el impuesto. Cuando un mismo causante sea directamente titular de participaciones en varias entidades, y en ellas concurran los requisitos 1.º, 2.º y 3.º, el cálculo de su mayor fuente de renta se efectuará de forma separada para cada una de dichas entidades, no incluyéndose los rendimientos derivados de las funciones de dirección en las otras entidades.\n5.º) Que el adquirente mantenga la adquisición durante los cinco años siguientes a la fecha del fallecimiento del causante, salvo que falleciera dentro de este plazo. Asimismo, el adquirente no podrá realizar actos de disposición u operaciones societarias que, directa o indirectamente, puedan dar lugar a una minoración sustancial del valor de la adquisición.\nEn el caso de no cumplirse el requisito de permanencia patrimonial de las participaciones, deberá abonarse la parte del impuesto que se hubiese dejado de ingresar como consecuencia de la reducción practicada, así como los intereses de demora.\nEn el caso de participación individual, si el causante se encontrara jubilado o en situación de incapacidad permanente absoluta o gran invalidez reconocida en el momento del fallecimiento, los requisitos anteriores se habrán de cumplir por alguno de los adquirentes incluidos en el primer párrafo de la presente letra. Si, en el momento de la jubilación, el causante hubiera cumplido los 65 años, la reducción aplicable será la general del 99 por 100, siendo del 90 por 100 si, en aquel momento, el causante tuviera entre 60 y 64 años cumplidos.\nEl importe de la reducción solo alcanzará al valor de las participaciones en la parte que corresponda a la proporción existente entre los activos necesarios para el ejercicio de la actividad empresarial o profesional, minorados en el importe de las deudas derivadas de la misma, y el valor del patrimonio neto de la entidad, aplicándose estas mismas reglas en la valoración de las participaciones de entidades participadas para determinar el valor de las de su entidad tenedora.\n2. Por circunstancias propias de la Comunitat Valenciana, y sin perjuicio de la aplicación de las reducciones previstas en el artículo 20.2 de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones, y de las demás reducciones reguladas en las leyes especiales:\na) En el supuesto de transmisión de una empresa individual agrícola a favor del cónyuge, descendientes o adoptados, ascendientes o adoptantes, o parientes colaterales hasta el cuarto grado del causante, la base imponible del impuesto se reducirá en el 99 por 100 del valor neto de los elementos patrimoniales afectos a la empresa transmitida, siempre que se cumplan, simultáneamente, los siguientes requisitos:\n1.º) Que la actividad no constituya la principal fuente de renta del causante;\n2.º) Que el causante haya ejercido dicha actividad de forma habitual, personal y directa;\n3.º) Que la empresa, por esta vía adquirida, se mantenga en el patrimonio del adquirente durante los cinco años siguientes al fallecimiento del causante, salvo que aquel fallezca, a su vez, dentro de dicho plazo. En caso de no cumplirse este requisito, deberá pagarse la parte del impuesto que se hubiera dejado de ingresar como consecuencia de la reducción practicada, así como sus intereses de demora.\nEn el caso de que el causante se encontrara jubilado de la actividad empresarial agrícola o en situación de incapacidad permanente absoluta o gran invalidez reconocida en el momento del fallecimiento, dicha actividad deberá haberse ejercido de forma habitual, personal y directa por alguno de los adquirentes de la empresa incluidos en el primer párrafo de la presente letra. Si, en el momento de la jubilación, el causante hubiera cumplido los 65 años, la reducción aplicable será la general del 99 por 100, siendo del 90 por 100 si, en aquel momento, el causante tuviera entre 60 y 64 años cumplidos.\nTambién se aplicará la mencionada reducción respecto del valor neto de los bienes del causante afectos al desarrollo de la actividad empresarial agrícola del cónyuge sobreviviente, por la parte en que resulte adjudicatario de aquellos con sujeción a lo dispuesto en el artículo 27 de la Ley 29/1987, de 18 de diciembre, del impuesto sobre sucesiones y donaciones. En tal caso, los requisitos a los que hacen referencia los ordinales 1.º a 3.º se habrán de cumplir por el cónyuge adjudicatario.\nb) En los supuestos de transmisiones de bienes del patrimonio cultural valenciano resultará aplicable una reducción para aquéllos inscritos en el Registro general de bienes de interés cultural, en el Inventario general del patrimonio cultural valenciano, o que antes de finalizar el plazo para presentar la declaración por este impuesto se inscriban en cualquiera de estos registros, siempre que sean cedidos para su exposición en las siguientes condiciones:\n1.º) Que la cesión se efectúe a favor de la Generalitat y las entidades locales de la Comunitat Valenciana; los entes del sector público de la Generalitat y de las entidades locales; las universidades públicas, los centros superiores de enseñanzas artísticas públicos y los centros de investigación de la Comunitat Valenciana, y las entidades sin fines lucrativos reguladas en los apartados a y b del artículo 2 de la Ley 49/2002, de 23 de diciembre, de régimen fiscal de las entidades sin fines lucrativos y de los incentivos fiscales al mecenazgo, siempre que persigan fines de naturaleza exclusivamente cultural y se hallen inscritas en los correspondientes registros de la Comunitat Valenciana.\n2.º) Que la cesión se efectúe gratuitamente.\n3.º) Que el bien se destine a los fines culturales propios de la entidad donataria.\nLa reducción será, en función del periodo de cesión del bien, del siguiente porcentaje del valor del mismo:\n– Del 95 por 100, para cesiones de más de 20 años.\n– Del 75 por 100, para cesiones de más de 10 años.\n– Del 50 por 100, para cesiones de más de 5 años.","u":"#a10","c":"TÍTULO II. Otros tributos cedidos · CAPÍTULO II. Impuesto sobre Sucesiones y Donaciones"},{"n":"VAL","a":"10 bis","t":"Reducciones en transmisiones inter vivos.","x":"Para el cálculo de la base liquidable del Impuesto sobre Sucesiones y Donaciones, en las transmisiones inter vivos resultarán aplicables las siguientes reducciones:\n1. Con el carácter de reducciones análogas a las aprobadas por el Estado con la misma finalidad:\na) En los casos de transmisiones de una empresa individual o de un negocio profesional a favor del cónyuge, descendientes o adoptados o, cuando no existan descendientes o adoptados, a favor del cónyuge, ascendientes, adoptantes, o parientes colaterales hasta el cuarto grado del donante, se aplicará a la base imponible una reducción del 99 por 100 del valor neto de los elementos patrimoniales afectos a la empresa o al negocio, siempre que se cumplan los siguientes requisitos:\n1.º) Que la actividad se ejerza por el donante de forma habitual, personal y directa.\n2.º) Que dicha actividad constituya la mayor fuente de renta del donante, entendiendo por tal la que proporcione un importe superior de los rendimientos del trabajo o de las actividades económicas.\nA tal efecto, no se tendrán en cuenta, siempre que se cumplan las condiciones en cada caso establecidas, todas aquellas remuneraciones que traigan causa de las participaciones del donante que disfruten de reducción en el impuesto.\nCuando un mismo donante ejerza dos o más actividades de forma habitual, personal y directa, la reducción alcanzará a todos los bienes y derechos afectos a las mismas, considerándose que su mayor fuente de renta a estos efectos viene determinada por el conjunto de los rendimientos de todas ellas.\n3.º) Que durante los cinco años siguientes a la fecha de la donación, el donatario mantenga en actividad los elementos patrimoniales afectos a la empresa o al negocio adquiridos, salvo que falleciera dentro de este plazo. Asimismo, el donatario no podrá realizar actos de disposición u operaciones societarias que, directa o indirectamente, puedan dar lugar a una minoración sustancial del valor de la adquisición.\nEn el caso de no cumplirse el citado plazo, deberá abonarse la parte del impuesto que se hubiese dejado de ingresar como consecuencia de la reducción practicada y los intereses de demora.\nEn el caso de que el donante se encontrara jubilado de la actividad de la empresa o negocio o en situación de incapacidad permanente absoluta o gran invalidez reconocida en el momento de la donación, los requisitos anteriores se habrán de cumplir por alguno de los donatarios incluidos en el primer párrafo de la presente letra. Si, en el momento de la jubilación, el donante hubiera cumplido los 65 años, la reducción aplicable será la general del 99 por 100, siendo del 90 por 100 si, en aquel momento, el donante tuviera entre 60 y 64 años cumplidos.\nb) En los casos de transmisiones de participaciones en entidades a favor del cónyuge, descendientes o adoptados o, cuando no existan descendientes o adoptados, a favor del cónyuge, ascendientes, adoptantes, o parientes colaterales hasta el cuarto grado del donante, se aplicará a la base imponible una reducción del 99 por 100 del valor de las participaciones, siempre que se cumplan los siguientes requisitos:\n1.º) Que la entidad, sea o no societaria, no tenga por actividad principal la gestión de un patrimonio mobiliario o inmobiliario, de conformidad con lo establecido en el artículo 4.Ocho.Dos.a de la Ley 19/1991, del Impuesto sobre el Patrimonio.\n2.º) Que la participación del donante en el capital de la entidad sea al menos del 5 por 100 computado de forma individual, o del 20 por 100 conjuntamente con su cónyuge, ascendientes o adoptantes, descendientes o adoptados, o colaterales hasta el cuarto grado, ya tenga su origen el parentesco en la consanguinidad, en la afinidad o en la adopción.\n3.º) Que el donante o, en el caso de participación conjunta, alguna de las personas del grupo familiar a que se refiere el ordinal anterior, ejerzan efectivamente funciones de dirección en la entidad.\n4.º) Que la retribución que perciba por ello suponga la mayor fuente de renta, entendiendo por tal la que proporcione un importe superior de los rendimientos del trabajo o de las actividades económicas.\nA tales efectos, no se tendrán en cuenta los rendimientos de las actividades económicas cuyos bienes y derechos afectos disfruten de reducción en el impuesto, y, cuando un mismo donante sea directamente titular de participaciones en varias entidades, y en ellas concurran los requisitos 1.º, 2.º y 3.º, el cálculo de la mayor fuente de renta del mismo se efectuará de forma separada para cada una de dichas entidades, no incluyéndose los rendimientos derivados de las funciones de dirección en las otras entidades.\n5.º) Que el donatario mantenga las participaciones durante los cinco años siguientes a la fecha de la donación, salvo que falleciera dentro de este plazo. Asimismo, el donatario no podrá realizar actos de disposición u operaciones societarias que, directa o indirectamente, puedan dar lugar a una minoración sustancial del valor de la adquisición.\nEn el caso de no cumplirse el requisito de permanencia patrimonial de las participaciones, deberá abonarse la parte del impuesto que se hubiese dejado de ingresar como consecuencia de la reducción practicada, así como los intereses de demora.\nEn el caso de participación individual, si el donante se encontrara jubilado o en situación de incapacidad permanente absoluta o gran invalidez reconocida en el momento de la donación, los requisitos anteriores se habrán de cumplir por alguno de los donatarios incluidos en el primer párrafo de la presente letra. Si, en el momento de la jubilación, el donante hubiera cumplido los 65 años, la reducción aplicable será la general del 99 por 100, siendo del 90 por 100 si, en aquel momento, el donante tuviera entre 60 y 64 años cumplidos.\nEl importe de la reducción solo alcanzará al valor de las participaciones, en la parte que corresponda a la proporción existente entre los activos necesarios para el ejercicio de la actividad empresarial o profesional, minorados en el importe de las deudas derivadas de la misma, y el valor del patrimonio neto de la entidad, aplicándose estas mismas reglas en la valoración de las participaciones de entidades participadas para determinar el valor de las de su entidad tenedora.\n2. Por circunstancias propias de la Comunitat Valenciana, y sin perjuicio de la aplicación de la reducción prevista en el apartado 7 del artículo 20 de la Ley 29/1987, de 18 de diciembre, del impuesto sobre sucesiones y donaciones, y de las demás reducciones reguladas en las leyes especiales:\na) La que corresponda de las siguientes:\n– Adquisiciones por hijos o adoptados menores de 21 años: 100.000 euros, más 8.000 euros por cada año menos de 21 que tenga el donatario, sin que la reducción pueda exceder de 156.000 euros.\n– Adquisiciones por hijos o adoptados de 21 o más años, por el cónyuge, padres o adoptantes: 100.000 euros.\n– Adquisiciones por nietos menores de 21 años: 100.000 euros, más 8.000 euros por cada año menos de 21 que tenga el nieto, sin que, en este último caso, la reducción pueda exceder de 156.000 euros.\n– Adquisiciones por nietos de 21 o más años: 100.000 euros.\n– Adquisiciones por abuelos: 100.000 euros.\nA los efectos de los citados límites de reducción, se tendrá en cuenta la totalidad de las adquisiciones lucrativas inter vivos provenientes del mismo donante efectuadas en los cinco años inmediatamente anteriores al momento del devengo.\nb) En las adquisiciones por personas con un grado de discapacidad igual o superior al 65 por 100; o un grado de discapacidad intelectual o mental reconocido de manera permanente igual o superior al 33 por 100, se aplicará una reducción a la base imponible de 240.000 euros.\nCuando la adquisición se efectúe por personas con un grado de discapacidad igual o superior al 33 por 100, que sean el cónyuge, padres, adoptantes, hijos o adoptados, nietos y abuelos del donante, se aplicará una reducción de 120.000 euros.\nA los efectos de los citados límites de reducción, se tendrá en cuenta la totalidad de las transmisiones lucrativas inter vivos realizadas en favor del mismo donatario en los últimos cinco años inmediatamente anteriores a la fecha del devengo.\nEn ambos casos, la aplicación de estas reducciones resultará compatible con la de las que pudieran corresponder en virtud de lo dispuesto en la letra a de este apartado.\nPara la aplicación de las reducciones contenidas en las letras a y b de este apartado se exigirá, además, que la adquisición se efectúe en documento público, o que se formalice de este modo dentro del plazo de declaración del impuesto.\nNo obstante, en las donaciones dinerarias o de medios de transporte inscritos o matriculados en el Registro Nacional de Vehículos de la Dirección General de Tráfico, destinados exclusivamente a uso particular, cuando el valor de lo donado, en la misma o distintas entregas entre el mismo donante y donatario realizadas dentro de los tres años anteriores a la fecha de devengo, no exceda de 4.000 euros o su valor en divisas equivalente, y siempre que la validez o eficacia del negocio jurídico no exija lo contrario, podrá suplirse el instrumento público mediante la aportación de documentos firmados digitalmente a través de un servicio de confianza cualificado de los previstos en el Reglamento (UE) 910/2014, del Parlamento Europeo y del Consejo, de 23 de julio de 2014, relativo a la identificación electrónica y los servicios de confianza para las transacciones electrónicas en el mercado interior.\nEn todo caso, cuando los bienes donados consistan en metálico o en cualquiera de los contemplados en el artículo 12 de la Ley 19/1991, de 6 de junio, del impuesto sobre el patrimonio, la reducción solo resultará aplicable cuando el origen de los fondos esté debidamente justificado, siempre que, además, en el documento en el que se formalice la operación se haya manifestado el origen de dichos fondos y se identifiquen los medios efectivos en virtud de los cuales se produzca la entrega de lo donado.\nc) En el supuesto de transmisión de una empresa individual agrícola a favor del cónyuge, descendientes o adoptados o, cuando no existan descendientes o adoptados, a favor del cónyuge, ascendientes, adoptantes, o parientes colaterales hasta el cuarto grado del donante, la base imponible del impuesto se reducirá en el 99 por 100 del valor neto de los elementos patrimoniales afectos a la empresa transmitida, siempre que se cumplan, simultáneamente, los siguientes requisitos:\n1.º) Que la actividad no constituya la principal fuente de renta del donante;\n2.º) Que el donante haya ejercido dicha actividad de forma habitual, personal y directa;\n3.º) Que la empresa, por esta vía adquirida, se mantenga en el patrimonio del adquirente durante los cinco años siguientes a la donación, salvo que aquel fallezca dentro de dicho plazo. En caso de no cumplirse este requisito, deberá pagarse la parte del impuesto que se hubiera dejado de ingresar como consecuencia de la reducción practicada, así como sus intereses de demora.\nEn el caso de que el donante se encontrara jubilado de la actividad empresarial agrícola o en situación de incapacidad permanente absoluta o gran invalidez reconocida en el momento de la donación, dicha actividad deberá haberse ejercido de forma habitual, personal y directa por cualquiera de los donatarios incluidos en el primer párrafo de la presente letra. Si, en el momento de la jubilación, el donante hubiera cumplido los 65 años, la reducción aplicable será la general del 99 por 100, siendo del 90 por 100 si, en aquel momento, el donante tuviera entre 60 y 64 años cumplidos.\nd) En las transmisiones de importes dinerarios destinadas al desarrollo de una actividad empresarial o profesional, con fondos propios inferiores a 300.000 euros, en el ámbito de la cinematografía, las artes escénicas, la música, la pintura y otras artes visuales o audiovisuales, la edición, la investigación o en el ámbito social, la base imponible del impuesto tendrá una reducción de hasta 1.000 euros. A los efectos del citado límite de reducción, se tendrá en cuenta la totalidad de las adquisiciones dinerarias lucrativas provenientes del mismo donante efectuadas en los tres años inmediatamente anteriores al momento del devengo.\nLa aplicación de esta reducción es compatible con la de las previstas en los apartados 1 y 2 de este artículo.\ne) En el supuesto de donaciones de dinero realizadas a favor de mujeres víctimas de violencia de género con la finalidad de adquirir una vivienda habitual situada en la Comunitat Valenciana se aplicará una reducción sobre el importe donado del 95 por 100 siempre que se cumplan los siguientes requisitos:\n– La base máxima de la reducción no podrá superar los 60.000 euros por contribuyente, sea en una donación o en donaciones sucesivas.\n– Deberá adquirirse la vivienda en los 12 meses siguientes a la donación. En caso de haber varias donaciones, el plazo se computará desde la fecha de la primera donación. La reducción no se aplicará a donaciones de dinero posteriores a la compra de la vivienda, salvo en los supuestos de adquisición con precio aplazado o financiación ajena, siempre que se acredite que el importe del dinero donado se ha destinado en el mismo plazo de un año al pago del precio pendiente o a la cancelación total o parcial del crédito.\n– La donataria no podrá ser titular de otra vivienda, salvo que sea la que compartía con la persona agresora.\n– La donación deberá formalizarse en escritura pública en la que se exprese la voluntad de que el dinero donado se destine a la adquisición de la vivienda o, en su caso, al pago del precio pendiente o a la cancelación total o parcial del crédito.\nNo obstante, cuando el valor de lo donado, en la misma o distintas entregas entre el mismo donante y donatario realizadas dentro de los tres años anteriores a la fecha de devengo, no exceda de 4.000 euros o su valor en divisas equivalente, y siempre que la validez o eficacia del negocio jurídico no exija lo contrario, podrá suplirse el instrumento público mediante la aportación de documentos firmados digitalmente a través de un servicio de confianza cualificado de los previstos en el Reglamento (UE) 910/2014, del Parlamento Europeo y del Consejo, de 23 de julio de 2014, relativo a la identificación electrónica y los servicios de confianza para las transacciones electrónicas en el mercado interior.\nLa reducción solo resultará aplicable cuando el origen de los fondos esté debidamente justificado, siempre que, además, en el documento en el que se formalice la operación se haya manifestado su origen y se identifiquen los medios efectivos en virtud de los cuales se produzca la entrega de lo donado.\nLa acreditación de la situación de violencia de género se hará según lo dispuesto en la Ley 7/2012, de 23 de noviembre, de la Generalitat, Integral contra la violencia sobre la mujer en el ámbito de la Comunitat Valenciana.\nTexto añadido, publicado el 31/12/2002, en vigor a partir del 01/01/2003.","u":"#a10bis","c":"TÍTULO II. Otros tributos cedidos · CAPÍTULO II. Impuesto sobre Sucesiones y Donaciones"},{"n":"VAL","a":"11","t":"Tarifa.","x":"La cuota íntegra se obtendrá aplicando a la base liquidable la siguiente escala:\n| Base liquidable hasta<br>–<br>Euros | Cuota integra<br>–<br>Euros | Resto base liquidable<br>–<br>Euros | Tipo aplicable<br>–<br>Porcentaje |\n| ----------------------------------- | --------------------------- | ----------------------------------- | --------------------------------- |\n| - | - | 7.993,46 | 7,65 |\n| 7.993,46 | 611,50 | 7.668,91 | 8,50 |\n| 15.662,38 | 1.263,36 | 7.831,19 | 9,35 |\n| 23.493,56 | 1.995,58 | 7.831,19 | 10,20 |\n| 31.324,75 | 2.794,36 | 7.831,19 | 11,05 |\n| 39.155,94 | 3.659,70 | 7.831,19 | 11,90 |\n| 46.987,13 | 4.591,61 | 7.831,19 | 12,75 |\n| 54.818,31 | 5.590,09 | 7.831,19 | 13,60 |\n| 62.649,50 | 6.655,13 | 7.831,19 | 14,45 |\n| 70.480,69 | 7.786,74 | 7.831,19 | 15,30 |\n| 78.311,88 | 8.984,91 | 39.095,84 | 16,15 |\n| 117.407,71 | 15.298,89 | 39.095,84 | 18,70 |\n| 156.503,55 | 22.609,81 | 78.191,67 | 21,25 |\n| 234.695,23 | 39.225,54 | 156.263,15 | 25,50 |\n| 390.958,37 | 79.072,64 | 390.958,37 | 29,75 |\n| 781.916,75 | 195.382,76 | En adelante | 34,00 |","u":"#a11","c":"TÍTULO II. Otros tributos cedidos · CAPÍTULO II. Impuesto sobre Sucesiones y Donaciones"},{"n":"VAL","a":"12","t":"Cuota tributaria.","x":"La cuota tributaria se obtendrá aplicando a la cuota íntegra el coeficiente multiplicador que corresponda de entre los que se indican a continuación, establecidos en función del patrimonio preexistente del contribuyente y del grupo, según el grado de parentesco, señalado en el artículo 20, de la Ley 29/1987, de 18 de diciembre, del Impuesto sobre Sucesiones y Donaciones:\n| Patrimonio preexistente<br>–<br>Euros | Grupos del artículo 20 | | |\n| ------------------------------------- | ---------------------- | ------ | ------ |\n| | I y II | III | IV |\n| De 0 a 390.657,87. | 1,0000 | 1,5882 | 2,0000 |\n| De 390.657,87 a 1.965.309,58. | 1,0500 | 1,6676 | 2,1000 |\n| De 1.965.309,58 a 3.936.629,28. | 1,1000 | 1,7471 | 2,2000 |\n| De más de 3.936.629,28. | 1,2000 | 1,9059 | 2,4000 |","u":"#a12","c":"TÍTULO II. Otros tributos cedidos · CAPÍTULO II. Impuesto sobre Sucesiones y Donaciones"},{"n":"VAL","a":"12 bis","t":"Bonificaciones en la cuota.","x":"1. Gozarán de una bonificación del 99 por 100 sobre la parte de la cuota tributaria del impuesto sobre sucesiones y donaciones que proporcionalmente corresponda a los bienes y derechos declarados por el sujeto pasivo:\na) Las adquisiciones mortis causa efectuadas por parientes del causante pertenecientes a los grupos I y II del artículo 20.2.a de la Ley 29/1987, de 18 de diciembre, del impuesto sobre sucesiones y donaciones.\nb) Las adquisiciones inter vivos efectuadas por el cónyuge, padres, adoptantes, hijos o adoptados del donante. Igual bonificación resultará aplicable a los nietos y a los abuelos.\nc) Las adquisiciones mortis causa e inter vivos realizadas por personas con un grado de discapacidad igual o superior al 65 por 100, o un grado de discapacidad intelectual o mental reconocido de manera permanente igual o superior al 33 por 100.\nLa aplicación de esta bonificación excluirá las de las letras a y b.\n2. Gozarán de una bonificación del 25 por 100 sobre la parte de la cuota tributaria del Impuesto sobre Sucesiones y Donaciones que proporcionalmente corresponda a los bienes y derechos declarados por el sujeto pasivo:\na) Las adquisiciones mortis causa efectuadas por parientes colaterales de segundo o tercer grado por consanguinidad del causante pertenecientes al grupo III del artículo 20.2.a de la Ley 29/1987, de 18 de diciembre, del impuesto sobre sucesiones y donaciones.\nb) Las adquisiciones inter vivos efectuadas por los parientes colaterales consanguíneos de segundo y tercer grado del donante pertenecientes al grupo III del artículo 20.2.a de la Ley 29/1987, de 18 de diciembre, del impuesto sobre sucesiones y donaciones.\n3. A los efectos de lo dispuesto en los apartados 1 y 2, se entenderá como bienes y derechos declarados por el sujeto pasivo los que se encuentren incluidos de forma completa en una autoliquidación presentada dentro del plazo voluntario o fuera de este sin que se haya efectuado un requerimiento previo de la administración tributaria en los términos a los que se refiere el apartado 1 del artículo 27 de la Ley 58/2003, de 17 de diciembre, general tributaria.\nPara determinar la proporción de la cuota tributaria que corresponde a los bienes declarados por el sujeto pasivo se tendrá en cuenta la relación entre aquella base liquidable que correspondería a los bienes y derechos declarados por el sujeto pasivo y la base liquidable que corresponda a la totalidad de los adquiridos.\n4. En las adquisiciones inter vivos, para la aplicación de las anteriores bonificaciones se exigirá, además, que la adquisición se efectúe en documento público, o que se formalice de este modo dentro del plazo de declaración del impuesto.\nNo obstante, en las donaciones dinerarias o de medios de transporte inscritos o matriculados en el Registro Nacional de Vehículos de la Dirección General de Tráfico, destinados exclusivamente a uso particular, cuando el valor de lo donado, en la misma o distintas entregas entre el mismo donante y donatario realizadas dentro de los tres años anteriores a la fecha de devengo, no exceda de 4.000 euros o su valor en divisas equivalente, y siempre que la validez o eficacia del negocio jurídico no exija lo contrario, podrá suplirse el instrumento público mediante la aportación de documentos firmados digitalmente a través de un servicio de confianza cualificado de los previstos en el Reglamento (UE) 910/2014, del Parlamento Europeo y del Consejo, de 23 de julio de 2014, relativo a la identificación electrónica y los servicios de confianza para las transacciones electrónicas en el mercado interior.\nEn todo caso, cuando los bienes donados consistan en metálico o en cualquiera de los contemplados en el artículo 12 de la Ley 19/1991, de 6 de junio, del Impuesto sobre el Patrimonio, la bonificación solo resultará aplicable cuando el origen de los fondos esté debidamente justificado, siempre que, además, en el documento en el que se formalice la operación se haya manifestado el origen de dichos fondos y se identifiquen los medios efectivos en virtud de los cuales se produzca la entrega de lo donado.\nTexto añadido, publicado el 19/12/2003, en vigor a partir del 01/01/2004.","u":"#a12bis","c":"TÍTULO II. Otros tributos cedidos · CAPÍTULO II. Impuesto sobre Sucesiones y Donaciones"},{"n":"VAL","a":"12 quáter","t":"Asimilación a cónyuges de las parejas de hecho en el Impuesto sobre Sucesiones y Donaciones.","x":"Se asimilan a cónyuges los miembros de parejas de hecho cuya unión cumpla los requisitos establecidos en la Ley 5/2012, de 15 de octubre, de la Generalitat, de uniones de hecho formalizadas de la Comunitat Valenciana, y se encuentren inscritas en el Registro de Uniones de Hecho Formalizadas de la Comunitat Valenciana o registros análogos establecidos por otras administraciones públicas del Estado español, de países pertenecientes a la Unión Europea o el Espacio Económico Europeo, o de terceros países.\nTexto añadido, publicado el 31/12/2016, en vigor a partir del 01/01/2017.","u":"#a12quater","c":"TÍTULO II. Otros tributos cedidos · CAPÍTULO II. Impuesto sobre Sucesiones y Donaciones"},{"n":"VAL","a":"12 ter","t":"Plazos de presentación.","x":"Uno. Los documentos o declaraciones se presentarán en los siguientes plazos:\na) Cuando se trate de adquisiciones por causa de muerte, incluidas las de los beneficiarios de contratos de seguro de vida, en el de seis meses, contados desde el día del fallecimiento del causante o desde aquel en que adquiera firmeza la declaración de su fallecimiento.\nEl mismo plazo, a contar desde el día del fallecimiento del usufructuario o desde aquel en que adquiera firmeza la declaración de fallecimiento, será aplicable a las consolidaciones del dominio en el nudo propietario por fallecimiento del usufructuario, aunque la desmembración del dominio se hubiese realizado por acto inter vivos.\nb) En los demás supuestos, en el de un mes, contado desde el día en que se cause el acto o contrato.\nDos. Salvo que específicamente se establezca otra cosa, cuando con posterioridad a la aplicación de un beneficio fiscal se produzca la pérdida del derecho a su aplicación por incumplimiento de los requisitos a que estuviese condicionado, se deberá presentar la autoliquidación correspondiente en el plazo de un mes contado desde el día en que se hubiera producido el incumplimiento. La regularización que se practique incluirá la parte del impuesto que se hubiere dejado de ingresar como consecuencia de la aplicación del beneficio fiscal, así como los intereses de demora.\nTexto añadido, publicado el 06/08/2013, en vigor a partir del 06/08/2013.","u":"#a12ter","c":"TÍTULO II. Otros tributos cedidos · CAPÍTULO II. Impuesto sobre Sucesiones y Donaciones"},{"n":"CAT","a":"631-1","t":"Base liquidable.","x":"1. En las adquisiciones por causa de muerte, incluidas las que correspondan a las personas beneficiarias de pólizas de seguros de vida y las de bienes del causante adquiridos con pacto de supervivencia, la base liquidable se obtiene como resultado de aplicar a la base imponible las reducciones que establece esta sección, que sustituyen a las reducciones análogas aprobadas por la normativa estatal.\n2. Las reducciones establecidas en los preceptos enumerados seguidamente mejoran las reducciones análogas del Estado:\n– Subsección primera: reducción por parentesco y reducción por discapacidad.\n– Subsección segunda: reducción por seguros.\n– Subsección tercera: reducción por la adquisición de bienes y derechos afectos a una actividad económica.\n– Subsección cuarta: reducción por la adquisición de participaciones en entidades.\n– Subsección sexta: reducción por la adquisición de la vivienda habitual del causante.\n– Subsección séptima: reducción por la adquisición de determinadas fincas rústicas de dedicación forestal.\n– Subsección novena: reducción por la adquisición de bienes del patrimonio cultural.\n– Subsección undécima: reducción por sobreimposición decenal.\n3. Las reducciones establecidas en los preceptos enumerados a continuación son reducciones propias:\n– Subsección primera: reducción para personas mayores.\n– Subsección quinta: reducción por adquisición de participaciones por personas con vínculos laborales.\n– Subsección octava: reducción por bienes utilizados en la explotación agraria del causahabiente.\n– Subsección décima: reducción por bienes del patrimonio natural.\n4. No puede aplicarse en ningún caso sobre un mismo bien, o sobre la misma porción de un bien más de una de las reducciones que establece esta sección, ni pueden añadirse a la reducción que se aplique otros beneficios fiscales que hayan establecido la normativa catalana o la normativa estatal precisamente en consideración a la naturaleza del bien bonificado.","u":"#a6-18","c":"Sección I. Reducciones de la base imponible · Subsección preliminar. Régimen general"},{"n":"CAT","a":"631-2","t":"Reducción por parentesco.","x":"En las adquisiciones por causa de muerte, se aplica la reducción que corresponda, entre las siguientes, por razón del grado de parentesco entre el adquirente y el causante:\na) Grupo I (adquisiciones por descendientes menores de veintiún años): 100.000, más 12.000 euros por cada año de menos de veintiuno que tenga el causahabiente, hasta un límite de 196.000 euros.\nb) Grupo II (adquisiciones por descendientes de veintiún años o más, cónyuges y ascendientes):\n– Cónyuge: 100.000 euros.\n– Hijo o hija: 100.000 euros.\n– Resto de descendientes: 50.000 euros.\n– Ascendientes: 30.000 euros.\nc) Grupo III (adquisiciones por colaterales de segundo y tercer grado y por ascendientes y descendientes por afinidad): 8.000 euros.\nd) Grupo IV (adquisiciones por colaterales de cuarto grado o de grados más distantes y por extraños): no se aplica ninguna reducción por razón de parentesco.","u":"#a6-19","c":"Sección I. Reducciones de la base imponible · Subsección primera. Reducciones por circunstancias personales"},{"n":"CAT","a":"631-3","t":"Reducción por discapacidad.","x":"Junto con las reducciones que puedan corresponder en función del grado de parentesco entre el adquirente y el causante, en las adquisiciones por causa de muerte por parte de personas con discapacidad física, psíquica o sensorial con un grado de discapacidad igual o superior al 33 % se aplica una reducción de 275.000 euros. Si el grado de discapacidad es igual o superior al 65 %, la reducción es de 650.000 euros. A tales efectos, los grados de discapacidad son los que se establezcan de acuerdo con el baremo a que se refiere la normativa estatal que establece el procedimiento para el reconocimiento, declaración y calificación del grado de discapacidad.","u":"#a6-20","c":"Sección I. Reducciones de la base imponible · Subsección primera. Reducciones por circunstancias personales"},{"n":"CAT","a":"631-4","t":"Reducción para personas mayores.","x":"1. En les adquisiciones por causa de muerte por personas del grupo II de setenta y cinco años o más se aplica una reducción de 275.000 euros.\n2. Esta reducción es incompatible con la reducción por discapacidad que establece el artículo 631-3.","u":"#a6-21","c":"Sección I. Reducciones de la base imponible · Subsección primera. Reducciones por circunstancias personales"},{"n":"CAT","a":"631-5","t":"Reducciones por seguros de vida.","x":"1. En las adquisiciones por causa de muerte, se aplica una reducción del 100 %, con un límite de 25.000 euros, de las cantidades percibidas por las personas beneficiarias de contratos de seguros de vida, si su parentesco con el contratante muerto es el de cónyuge, de descendiente o de ascendiente. En el caso de seguros colectivos o contratados por las empresas a favor de sus trabajadores, debe tenerse en cuenta el grado de parentesco entre la persona asegurada y la beneficiaria.\n2. La reducción por seguros de vida es única por sujeto pasivo, independientemente del número de contratos de seguros de vida de los que sea beneficiario. En caso de que tenga derecho al régimen de bonificaciones y reducciones que establece la disposición transitoria cuarta de la Ley 29/1987, de 18 de diciembre, del impuesto sobre sucesiones y donaciones, el sujeto pasivo puede optar entre aplicar este régimen o aplicar la reducción establecida en este artículo.","u":"#a6-22","c":"Sección I. Reducciones de la base imponible · Subsección segunda. Reducciones por seguros de vida"},{"n":"CAT","a":"631-6","t":"Supuestos de aplicación.","x":"1. En las adquisiciones por causa de muerte que correspondan al cónyuge, a los descendientes, a los ascendientes o a los colaterales hasta el tercer grado del causante, tanto por consanguinidad o adopción como por afinidad, puede aplicarse a la base imponible una reducción del 95 % del valor neto de los elementos patrimoniales afectos a una actividad empresarial o profesional del causante.\n2. La reducción que establece el apartado 1 también se aplica respecto a los bienes del causante utilizados en el desarrollo de la actividad empresarial o profesional ejercida por el cónyuge superviviente, cuando este sea el adjudicatario de los bienes en la partición hereditaria o el causante se los haya atribuido.\n3. También pueden disfrutar de la reducción establecida en el apartado 1 las personas que, sin tener la relación de parentesco que se especifica, y sin perjuicio de que deban cumplir los demás requisitos y condiciones que determina esta subsección, cumplan en la fecha de la muerte del causante los siguientes requisitos:\na) Tener una vinculación laboral o de prestación de servicios con la empresa o el negocio profesional del causante con una antigüedad mínima acreditada de diez años.\nb) Tener encargadas tareas de responsabilidad en la gestión o dirección de la empresa o el negocio profesional del causante, con una antigüedad mínima de cinco años en el ejercicio de estas tareas. Se entiende que tiene encomendadas estas tareas si acredita la categoría laboral correspondiente a los grupos 1 y 2 de cotización del régimen general de la Seguridad Social o si el causante le había otorgado un apoderamiento especial para llevar a cabo las actuaciones habituales de gestión de la empresa.","u":"#a6-23","c":"Sección I. Reducciones de la base imponible · Subsección tercera. Reducción por la adquisición de bienes y derechos afectos a una actividad económica"},{"n":"CAT","a":"631-7","t":"Concepto de actividad empresarial o profesional.","x":"1. A efectos de la aplicación de la reducción que establece esta subsección, tiene la consideración de actividad empresarial o profesional la actividad que, a través del trabajo personal o de la participación en el capital, o de ambos factores conjuntamente, supone la ordenación, por cuenta propia, de medios de producción o de recursos humanos, o de unos y otros a la vez, con la finalidad de intervenir en la producción o la distribución de bienes y de servicios. En particular, tienen tal consideración las actividades extractivas, de fabricación, de comercio o de prestación de servicios, incluidas las de artesanía, agrícolas, forestales, ganaderas, pesqueras, de construcción o mineras, y el ejercicio de profesiones liberales, artísticas y deportivas.\n2. Se determinan por reglamento las condiciones y los requisitos de acreditación de una actividad empresarial o profesional a efectos de lo establecido en el apartado 1.\n3. Sin perjuicio de lo dispuesto en el apartado anterior, se entiende que el arrendamiento de inmuebles se realiza como actividad empresarial cuando para la ordenación de la actividad se tiene empleada como mínimo una persona con contrato laboral y a jornada completa.","u":"#a6-24","c":"Sección I. Reducciones de la base imponible · Subsección tercera. Reducción por la adquisición de bienes y derechos afectos a una actividad económica"},{"n":"CAT","a":"631-8","t":"Bienes afectos.","x":"1. A efectos de la aplicación de la reducción que establece esta subsección, tienen la consideración de elementos patrimoniales afectos a una actividad económica:\na) Los bienes inmuebles en los que se realiza la actividad.\nb) Los bienes destinados a la oferta de servicios económicos y socioculturales para el personal al servicio de la actividad, salvo aquellos bienes destinados al ocio o el tiempo libre o, en general, los bienes de uso particular del titular de la actividad económica.\nc) Los demás elementos patrimoniales que sean necesarios para obtener los rendimientos de la actividad; en ningún caso tienen esta consideración los activos representativos de la participación en fondos propios de una entidad ni los activos representativos de la cesión de capital a terceros.\n2. Si los elementos patrimoniales a que se refiere el apartado 1 sirven tan solo parcialmente al objeto de la actividad económica, se entiende que la afectación se limita a la parte de estos elementos que realmente se utilice en la actividad de que se trate; en ningún caso son susceptibles de afectación parcial los elementos patrimoniales indivisibles.\n3. Se determinan por reglamento, con carácter exhaustivo, las condiciones y los requisitos que deben cumplir los elementos patrimoniales para ser considerados afectos a la actividad económica a efectos de la reducción establecida en esta subsección.","u":"#a6-25","c":"Sección I. Reducciones de la base imponible · Subsección tercera. Reducción por la adquisición de bienes y derechos afectos a una actividad económica"},{"n":"CAT","a":"631-9","t":"Regla de mantenimiento.","x":"El disfrute definitivo de la reducción establecida en esta subsección queda condicionado al mantenimiento del ejercicio de la actividad empresarial o profesional durante los cinco años siguientes a la muerte del causante, salvo que el adquirente fallezca en este plazo, así como al mantenimiento en el patrimonio del adquirente, durante el mismo plazo y con la misma excepción, de los mismos bienes y derechos, o de bienes y derechos subrogados de valor equivalente, y de su afectación a la actividad.","u":"#a6-26","c":"Sección I. Reducciones de la base imponible · Subsección tercera. Reducción por la adquisición de bienes y derechos afectos a una actividad económica"},{"n":"CAT","a":"631-10","t":"Supuesto de aplicación.","x":"1. En las adquisiciones por causa de muerte que correspondan al cónyuge, a los descendientes, a los ascendientes o a los colaterales hasta el tercer grado del causante, tanto por consanguinidad o adopción como por afinidad, puede aplicarse en la base imponible una reducción del 95 % del valor de las participaciones en entidades, con cotización o sin cotización en mercados organizados, por la parte que corresponda por razón de la proporción existente entre los activos necesarios para el ejercicio de la actividad empresarial o profesional, minorados en el importe de las deudas derivadas de la misma, y el valor del patrimonio neto de cada entidad. Estas mismas reglas se aplican en la valoración de la participación en entidades participadas para determinar el valor de las participaciones de la entidad tenedora.\n2. En caso de adquisición de participaciones en sociedades laborales, la reducción establecida en el apartado 1 es del 97 %.\n3. La reducción establecida en esta subsección no se aplica en ningún caso a las participaciones en instituciones de inversión colectiva.","u":"#a6-27","c":"Sección I. Reducciones de la base imponible · Subsección cuarta. Reducción por la adquisición de participaciones en entidades"},{"n":"CAT","a":"631-11","t":"Requisitos.","x":"1. Para poder disfrutar de la reducción establecida en esta subsección, deben cumplirse los siguientes requisitos:\na) Que la entidad no tenga como actividad principal, en los términos que establece el artículo 631-12, la gestión de un patrimonio mobiliario o inmobiliario.\nb) Que la participación del causante en el capital de la entidad constituya al menos el 5 %, computado individualmente, o el 20 %, computado conjuntamente con el cónyuge, los descendientes, los ascendientes o los colaterales hasta el tercero grado del causante, tanto por consanguinidad o adopción como por afinidad.\nc) Que el causante haya ejercido efectivamente funciones de dirección en la entidad y haya percibido por esta tarea una remuneración que constituya al menos el 50 % de la totalidad de los rendimientos de actividades económicas y del trabajo personal, en los términos establecidos en el apartado 2.\nSi la participación en la entidad era conjunta con alguna o algunas de las personas a las que se refiere la letra b), al menos una de las personas de este grupo de parentesco debe cumplir los requisitos relativos a las funciones de dirección y a las remuneraciones que deriven de ellas.\n2. A efectos de lo establecido en la letra c del apartado 1, no deben computarse entre los rendimientos de actividades económicas y del trabajo personal los rendimientos de la actividad económica a que se refiere el artículo 631-7. Si el causante era titular de participaciones en varias entidades y donde desarrollaba tareas directivas retribuidas, y siempre y cuando se cumplan los requisitos que establecen las letras a) y b) del apartado 1, en el cálculo del porcentaje que representa la remuneración por las funciones de dirección ejercidas en cada entidad respecto a la totalidad de los rendimientos del trabajo y de actividades económicas no deben computarse los rendimientos derivados del ejercicio de las funciones de dirección en las demás entidades.\n3. Se determinan por reglamento los requisitos establecidos en el apartado 1.","u":"#a6-28","c":"Sección I. Reducciones de la base imponible · Subsección cuarta. Reducción por la adquisición de participaciones en entidades"},{"n":"CAT","a":"631-12","t":"Concepto de entidad que gestiona un patrimonio mobiliario o inmobiliario.","x":"1. A efectos de la aplicación de la reducción establecida en esta subsección, tiene la consideración de entidad que gestiona un patrimonio mobiliario o inmobiliario aquella entidad en la que, durante más de noventa días del año natural inmediatamente anterior a la fecha de la muerte del causante, más de la mitad del activo estuviera constituido por valores o más de la mitad del activo no estuviera afecto a actividades económicas.\n2. Únicamente a efectos de determinar si se dan los requisitos para considerar que una entidad gestiona un patrimonio mobiliario o inmobiliario, el valor del activo y el valor de los elementos patrimoniales no afectos a actividades económicas son los que se deducen de la contabilidad, siempre y cuando esta refleje fielmente la verdadera situación patrimonial de la entidad.\n3. Para determinar, a efectos de lo establecido en el apartado 2, la parte del activo que está constituida por valores o elementos patrimoniales no afectos:\na) No se computan los siguientes valores:\n– Los valores que se poseen en cumplimiento de obligaciones legales y reglamentarias.\n– Los valores que incorporan derechos de crédito nacidos de relaciones contractuales establecidas como consecuencia del desarrollo de actividades económicas.\n– Los valores poseídos por sociedades de valores como consecuencia del ejercicio de la actividad constitutiva de su objeto.\n– Los valores que otorguen al menos el 5 % de los derechos de voto y se posean con la finalidad de dirigir y gestionar la participación, siempre y cuando se disponga a tales efectos de la correspondiente organización de medios materiales y personales y la entidad participada no tenga la consideración, de acuerdo con el apartado 1, de entidad que gestiona un patrimonio mobiliario o inmobiliario.\nb) No se computan como valores ni como elementos no afectos a actividades económicas los valores o los elementos cuyo precio de adquisición no supere el importe de los beneficios no distribuidos obtenidos por la entidad, siempre y cuando provengan de la realización de sus actividades económicas, con el límite del importe de los beneficios obtenidos tanto durante el año en curso como durante los diez años anteriores. A tales efectos, se asimilan a los beneficios procedentes de actividades económicas los dividendos que procedan de los valores a que se refiere el último inciso de la letra a, si al menos el 90 % de los ingresos obtenidos por la entidad participada proceden de la realización de actividades económicas.","u":"#a6-29","c":"Sección I. Reducciones de la base imponible · Subsección cuarta. Reducción por la adquisición de participaciones en entidades"},{"n":"CAT","a":"631-13","t":"Actividad económica y bienes afectos.","x":"Para determinar, al efecto de la reducción establecida en esta subsección, si se desarrolla una actividad económica, o si esta actividad tiene elementos patrimoniales afectos, es preciso atenerse, respectivamente, a las reglas que determinan los artículos 631-7 y 631-8, excepto con relación a los activos a que se refiere el último inciso de la letra c del artículo 631-8.1, los que pueden estar afectos a la actividad económica.","u":"#a6-30","c":"Sección I. Reducciones de la base imponible · Subsección cuarta. Reducción por la adquisición de participaciones en entidades"},{"n":"CAT","a":"631-14","t":"Regla de mantenimiento.","x":"El disfrute definitivo de la reducción establecida en esta subsección queda condicionado al mantenimiento de los elementos adquiridos en el patrimonio del adquirente durante los cinco años siguientes a la muerte del causante, salvo que el adquirente fallezca en este plazo.","u":"#a6-31","c":"Sección I. Reducciones de la base imponible · Subsección cuarta. Reducción por la adquisición de participaciones en entidades"},{"n":"CAT","a":"631-15","t":"Supuesto de aplicación.","x":"1. En las adquisiciones por causa de muerte, los causahabientes que, sin tener la relación de parentesco que determina el artículo 631-10, adquieren participaciones en entidades, con cotización o sin cotización en mercados organizados, pueden disfrutar de la reducción del 95 % del valor de las participaciones adquiridas por la parte que corresponda a razón de la proporción existente entre los activos necesarios para el ejercicio de la actividad empresarial o profesional, minorados en el importe de las deudas derivadas de esa actividad, y el valor del patrimonio neto de cada entidad. Dichas reglas se aplican asimismo en la valoración de las participaciones de entidades participadas para determinar el valor de las participaciones de la entidad tenedora.\n2. La reducción establecida en esta subsección no se aplica en ningún caso a las participaciones en instituciones de inversión colectiva.","u":"#a6-32","c":"Sección I. Reducciones de la base imponible · Subsección quinta. Reducción por la adquisición de participaciones en entidades por parte de personas con vínculos laborales o profesionales"},{"n":"CAT","a":"631-16","t":"Requisitos.","x":"1. Para poder disfrutar de la reducción establecida en esta subsección, es preciso que se cumplan los siguientes requisitos:\na) Los establecidos en el artículo 631-11.1.\nb) El causahabiente debe tener en la fecha de la muerte del causante una vinculación laboral o de prestación de servicios con la entidad cuyas participaciones son objeto de adquisición gratuita, con una antigüedad mínima de diez años, y debe haber ejercido funciones de dirección como mínimo los cinco años anteriores a dicha fecha.\nc) La participación del causahabiente en el capital de la entidad resultante de la adquisición por causa de muerte debe ser de más del 50 %; si se trata de sociedades laborales, la participación debe ser de más del 25 %.\n2. Los requisitos y las condiciones que determinen los artículos 631-12, 631-13 y 631-14 se aplican también a la reducción establecida en esta subsección.","u":"#a6-33","c":"Sección I. Reducciones de la base imponible · Subsección quinta. Reducción por la adquisición de participaciones en entidades por parte de personas con vínculos laborales o profesionales"},{"n":"CAT","a":"631-17","t":"Supuesto de aplicación.","x":"En las adquisiciones por causa de muerte que correspondan al cónyuge, a los descendientes, a los ascendientes o a los colaterales del causante, puede aplicarse en la base imponible una reducción del 95 % del valor de la vivienda habitual del causante, con un límite de 500.000 euros por el valor conjunto de la vivienda, que debe prorratearse entre los sujetos pasivos en proporción a su participación; en todo caso, el límite individual resultante del prorrateo entre los sujetos pasivos no puede ser menor de 180.000 euros.","u":"#a6-34","c":"Sección I. Reducciones de la base imponible · Subsección sexta. Reducción por la adquisición de la vivienda habitual del causante"},{"n":"CAT","a":"631-18","t":"Requisitos.","x":"1. A efectos de la aplicación de la reducción establecida en esta subsección, tiene la consideración de vivienda habitual la vivienda que cumple los requisitos y se ajusta a la definición establecidos en la normativa reguladora del impuesto sobre la renta de las personas físicas, sin perjuicio de que puedan considerarse como vivienda habitual, conjuntamente con esta vivienda, un trastero y hasta dos plazas de aparcamiento, pese a no haber sido adquiridos simultáneamente en unidad de acto, si están ubicados en el mismo edificio o complejo urbanístico y si en la fecha de la muerte del causante se hallaban a su disposición, sin haberse cedido a terceras personas.\n2. Los parientes colaterales del causante, para poder disfrutar de la reducción establecida en el apartado 1, deben ser mayores de sesenta y cinco años y deben haber convivido con el causante como mínimo los dos años anteriores a su muerte.\n3. Si el causante, en la fecha de su muerte, tenía la residencia efectiva en un domicilio del que no era titular, tiene la consideración de vivienda habitual, en los términos establecidos en el apartado 1, la vivienda que tenía esta consideración hasta cualquier día de los diez años anteriores a la fecha de la muerte, no aplicándose dicha limitación de diez años si el causante ha tenido el último domicilio en un centro residencial o sociosanitario. En el supuesto que regula el presente apartado, no rige la prohibición de cesión a terceras personas establecida en el apartado 1.","u":"#a6-35","c":"Sección I. Reducciones de la base imponible · Subsección sexta. Reducción por la adquisición de la vivienda habitual del causante"},{"n":"CAT","a":"631-19","t":"Regla de mantenimiento.","x":"1. El disfrute definitivo de la reducción establecida en esta subsección queda condicionado al mantenimiento de la vivienda, o de la vivienda subrogada de valor equivalente que pase a ser vivienda habitual del causahabiente, en el patrimonio del adquirente durante los cinco años siguientes a la muerte del causante, salvo que el adquirente fallezca en este plazo.\n2. El supuesto de subrogación a que se refiere el apartado 1 se aplica tanto si el importe resultante de la transmisión de la vivienda habitual del causante se ha destinado a adquirir la vivienda habitual del causahabiente como si se ha destinado a amortizar el préstamo o crédito hipotecario concedido al causahabiente para la adquisición de su vivienda habitual. La subrogación debe producirse, en ambos casos, en el plazo de seis meses desde la fecha de transmisión de la vivienda habitual del causante.","u":"#a6-36","c":"Sección I. Reducciones de la base imponible · Subsección sexta. Reducción por la adquisición de la vivienda habitual del causante"},{"n":"CAT","a":"631-20","t":"Supuesto de aplicación.","x":"1. En las adquisiciones por causa de muerte que correspondan al cónyuge, a los descendientes, a los ascendientes o a los colaterales hasta el tercer grado del causante, puede aplicarse a la base imponible una reducción del 95 % del valor de las fincas rústicas de dedicación forestal, si cumplen alguno de los siguientes requisitos:\na) Disponer de un instrumento de ordenación forestal que haya sido aprobado por el departamento competente o que se apruebe en el plazo voluntario de presentación de la autoliquidación.\nb) Ser gestionadas en el marco de un convenio, acuerdo o contrato de gestión forestal formalizado con la Administración forestal.\nc) Estar ubicadas en terrenos que han sufrido incendios forestales en los veinticinco años anteriores a la fecha de la muerte del causante o que, de conformidad con la normativa forestal, han sido declarados zona de actuación urgente por razón de los incendios que han sufrido.\n2. La base sobre la que se aplica esta reducción comprende tanto el valor del terreno como, si procede, el de las construcciones ubicadas en la finca forestal y que sean para utilidad exclusiva de la misma.","u":"#a6-37","c":"Sección I. Reducciones de la base imponible · Subsección séptima. Reducción por la adquisición de determinadas fincas rústicas de dedicación forestal"},{"n":"CAT","a":"631-21","t":"Regla de mantenimiento.","x":"El disfrute definitivo de la reducción establecida en esta subsección queda condicionado al mantenimiento de la finca rústica de dedicación forestal en el patrimonio del adquirente durante los diez años siguientes a la fecha de la muerte del causante, salvo que el adquirente fallezca en este plazo.","u":"#a6-38","c":"Sección I. Reducciones de la base imponible · Subsección séptima. Reducción por la adquisición de determinadas fincas rústicas de dedicación forestal"},{"n":"CAT","a":"631-22","t":"Supuesto de aplicación.","x":"1. En las adquisiciones por causa de muerte, se puede aplicar en la base imponible una reducción del 95% del valor de los elementos patrimoniales de los que es propietario el causante, afectos a una explotación agraria. La reducción es del 99% si el adquirente tiene la condición de joven agricultor, en los términos establecidos por el apartado 1 del artículo 631-23.\nPara que esta reducción sea aplicable en caso de que la titularidad de la explotación agraria vaya a cargo de una persona jurídica, es necesario que concurran los dos requisitos siguientes:\n– Debe tener por objeto exclusivo la actividad agraria y, si procede, también debe desarrollar actividades complementarias establecidas por el primer párrafo de la letra a del apartado 1 del artículo 631-23.\n– Debe pertenecer en más del 50% del capital social a personas físicas que tengan la condición de agricultor profesional, entre las cuales el adquirente de los bienes.\n2. La misma reducción se aplica en el caso de transmisión de participaciones en la entidad que efectúe la explotación agraria, con cotización o sin cotización en mercados organizados, por la parte que corresponda por razón de la proporción existente entre los activos necesarios para el ejercicio de la actividad, minorados en el importe de las deudas que deriven de la misma, y el valor del patrimonio neto de la entidad.\n3. A efectos de esta reducción:\na) Se entiende por explotación agraria el conjunto de bienes y derechos organizados empresarialmente por su titular en el ejercicio de la actividad agraria, primordialmente con fines de mercado, que constituyan una unidad de gestión técnico-económica.\nb) Es titular de la explotación quien ejerce la actividad organizando los bienes y derechos integrantes de la explotación con criterios empresariales y asumiendo los riesgos y las responsabilidades civil, social, fiscal, sanitaria y de bienestar de los animales que se puedan derivar de la gestión de la explotación.\nc) Se considera actividad agraria el conjunto de trabajos que se requieren para la obtención de productos agrícolas, ganaderos y forestales. Asimismo, se considera actividad agraria la venta directa por parte del agricultor de la producción propia sin transformación, o la primera transformación de esta producción, siempre y cuando el producto final esté incluido en el anexo I del artículo 38 del Tratado de funcionamiento de la Unión Europea, dentro de los elementos que integren la explotación, en mercados municipales o en lugares que no sean establecimientos comerciales permanentes. También se considera actividad agraria la que implica la gestión o la dirección y gerencia de la explotación.\nd) Se considera joven agricultor la persona física que cumple los siguientes requisitos:\n– Tener 40 años o menos, y ser responsable de explotación.\n– Acreditar la formación o la capacitación adecuadas en el ámbito agrario, para cuya determinación se deberán conjugar criterios de formación lectiva y capacitación profesional, con un mínimo de 150 horas lectivas. Este requisito puede acreditarse en el plazo de dos años a contar desde la muerte del causante.","u":"#a6-39","c":"Sección I. Reducciones de la base imponible · Subsección octava. Reducción por adquisición de explotación agraria"},{"n":"CAT","a":"631-23","t":"Requisitos.","x":"1. El causahabiente debe tener la condición de agricultor profesional o estar en condición de obtenerla en el plazo de dos años a contar desde la muerte del causante. En caso de desmembración del dominio, puede cumplir la condición de agricultor profesional tanto el nudo propietario como el usufructuario.\nTiene la condición de agricultor profesional la persona física que sea titular de una explotación agraria; obtenga al menos el 50% de la renta total de actividades agrarias u otras actividades complementarias, siempre y cuando la parte de renta procedente directamente de la actividad agraria de su explotación no sea inferior al 25% de su renta total, y dedique a actividades agrarias o complementarias un volumen de ocupación igual o superior a la mitad de una unidad de trabajo agrario.\nA estos efectos:\na) Se consideran actividades complementarias las actividades de transformación de los productos de la explotación agraria y la venta directa de los productos transformados de su explotación; las actividades relacionadas con la conservación del espacio natural y la protección del medio ambiente, y las actividades cinegéticas y artesanales realizadas en su explotación.\nTambién se consideran actividades complementarias la participación y presencia del titular, como consecuencia de elección pública, en instituciones de carácter representativo, así como en órganos de representación de carácter sindical, cooperativo o profesional, siempre y cuando estos estén vinculados al sector agrario.\nb) Se considera unidad de trabajo agrario el trabajo que una persona a tiempo completo dedica a la actividad agraria durante un año. La aportación del trabajo agrario se acredita sobre la base de la cotización a la Seguridad Social.\nc) Para el cómputo del 25% de la renta total, se excluyen los rendimientos obtenidos del ejercicio de la actividad de turismo rural o agroturismo.\n2. Para determinar si se desarrolla la actividad económica es necesario ajustarse a lo que dispone el artículo 631-13.\n3. En el caso de transmisión de participaciones, es necesario que la participación del causante en el capital de la entidad constituya al menos el 5%, computado individualmente, o el 20%, computado junto con el cónyuge, los descendientes, los ascendientes o los colaterales hasta el tercer grado del causante, por consanguinidad, adopción o afinidad.\n4. Esta reducción es incompatible con las reducciones establecidas por los artículos 631-6 y 631-10.","u":"#a6-40","c":"Sección I. Reducciones de la base imponible · Subsección octava. Reducción por adquisición de explotación agraria"},{"n":"CAT","a":"631-24","t":"Regla de mantenimiento.","x":"1. En el caso de adquisición de bienes afectos a la actividad, el disfrute definitivo de la reducción queda condicionado al mantenimiento del ejercicio de la actividad agraria durante los cinco años siguientes a la muerte del causante, salvo que el adquirente muera dentro de este plazo, y también queda condicionado al mantenimiento en el patrimonio del adquirente, durante el mismo plazo y con la misma excepción, de los mismos bienes y derechos, o de bienes y derechos subrogados de valor equivalente, y de su afectación a la actividad.\n2. En el caso de adquisición de participaciones, el disfrute definitivo de la reducción que establece esta subsección queda condicionado al mantenimiento de los elementos adquiridos en el patrimonio del adquirente durante los cinco años siguientes a la muerte del causante, salvo que el adquirente muera dentro de este plazo.\n3. El adquirente que tenga la condición de agricultor profesional, de acuerdo con lo que dispone el apartado 1 del artículo 631-23, en los supuestos 1 y 2 anteriores, debe mantener esta condición en el mismo plazo señalado de cinco años.","u":"#a6-41","c":"Sección I. Reducciones de la base imponible · Subsección octava. Reducción por adquisición de explotación agraria"},{"n":"CAT","a":"631-29","t":"Supuestos y régimen de aplicación.","x":"1. Si unos mismos bienes o derechos son objeto, en un período máximo de diez años, de dos o más transmisiones por causa de muerte a favor del cónyuge, de los descendientes o de los ascendientes, en la segunda y ulteriores transmisiones debe practicarse en la base imponible, con carácter alternativo, la reducción que resulte más favorable entre las dos reducciones siguientes:\na) Una reducción de cuantía equivalente al importe de las cuotas del impuesto sobre sucesiones y donaciones satisfechas por razón de las precedentes transmisiones por causa de muerte.\nb) La reducción que resulte de la aplicación de la siguiente escala:\nPrimero. Una reducción del 50 % del valor real de los bienes y derechos, si la transmisión se produce en el año natural siguiente a la fecha de la anterior transmisión.\nSegundo. Una reducción del 30 % del valor real de los bienes y derechos, si la transmisión se produce tras transcurrir un año natural y antes de transcurrir cinco años naturales desde la fecha de la anterior transmisión.\nTercero. Una reducción del 10 % del valor real de los bienes y derechos, si la transmisión se produce tras transcurrir cinco años naturales desde la fecha de la anterior transmisión.\n2. En caso de que las reducciones a que se refiere el apartado 1.b recaigan sobre bienes y derechos a los que les sea de aplicación alguna de les otras reducciones establecidas en esta sección, el porcentaje de reducción solo se aplica al remanente del valor del bien o derecho que no es objeto de las reducciones.\n3. La aplicación de las reducciones de este artículo queda condicionada al hecho de que, por razón de la primera adquisición por causa de muerte o la anterior, se haya producido una tributación efectiva en concepto del impuesto sobre sucesiones y donaciones, y se entiende sin perjuicio de las reducciones que procedan. En cualquier caso, se admite la subrogación de bienes o derechos siempre y cuando se acredite de modo fehaciente.","u":"#a6-46","c":"Sección I. Reducciones de la base imponible · Subsección undécima. Reducción por sobreimposición decenal"},{"n":"CAT","a":"631-30","t":"Ámbito de aplicación.","x":"Las reducciones establecidas en las subsecciones de tercera a décima se aplican tanto en caso de adquisición de la plena propiedad o de la nuda propiedad como en caso de adquisición de cualquier otro derecho sobre los bienes afectados.","u":"#a6-47","c":"Sección I. Reducciones de la base imponible · Subsección duodécima. Disposiciones comunes para las reducciones establecidas en las subsecciones de la tercera a la décima."},{"n":"CAT","a":"631-31","t":"Base de las reducciones.","x":"Los porcentajes de reducción que establecen las subsecciones de tercera a décima se aplican sobre el importe resultante de haber deducido del valor de los bienes o derechos que son objeto de la reducción el importe de las cargas y gravámenes que establece el artículo 12 de la Ley 29/1987. El valor así determinado, sin prorrateo del importe de las deudas y gastos generales legalmente deducibles, constituye la base de cálculo de la reducción. La aplicación de la regla de cálculo establecida en el párrafo precedente no puede determinar en ningún caso bases liquidables negativas.","u":"#a6-48","c":"Sección I. Reducciones de la base imponible · Subsección duodécima. Disposiciones comunes para las reducciones establecidas en las subsecciones de la tercera a la décima."},{"n":"CAT","a":"631-32","t":"Bienes comunes de los cónyuges.","x":"Las reducciones establecidas en las subsecciones de tercera a décima, si los bienes o derechos que son objeto de la reducción han formado parte de la sociedad de gananciales regulada en el artículo 1344 del Código civil o de otros regímenes económicos matrimoniales análogos, y con independencia de las adjudicaciones concretas que resulten de la liquidación del régimen económico matrimonial, solo pueden afectar a la mitad del valor de cada bien o derecho adquirido, o a la parte que corresponda por razón de la participación del causante en la comunidad matrimonial.","u":"#a6-49","c":"Sección I. Reducciones de la base imponible · Subsección duodécima. Disposiciones comunes para las reducciones establecidas en las subsecciones de la tercera a la décima."},{"n":"CAT","a":"631-33","t":"Regla de mantenimiento de los bienes o derechos adquiridos.","x":"1. En las adquisiciones por causa de muerte, el causahabiente no puede hacer actos de disposición ni operaciones societarias que, directamente o indirectamente, puedan dar lugar a una minoración sustancial del valor de los bienes o derechos adquiridos o, en caso de subrogación, de los bienes o derechos subrogados.\n2. En caso de incumplimiento de lo dispuesto en el apartado 1 o de las reglas de mantenimiento fijadas por los artículos 631-9, 631-14, 631-19, 631-21, 631-24, 631-26 y 631-28, el sujeto pasivo debe pagar, dentro del plazo voluntario de presentación de la autoliquidación correspondiente a los actos de transmisión entre vivos, la parte del impuesto que había dejado de ingresar como consecuencia de la reducción aplicada, junto a los intereses de demora que se hayan devengado.\n3. Se entiende que el incumplimiento a que se refiere el apartado 2 no se produce si el bien ha sido objeto de expropiación forzosa, se ha perdido en virtud de resolución judicial o de disposición legal o se ha perdido o ha sido destruido por causa de fuerza mayor.","u":"#a6-50","c":"Sección I. Reducciones de la base imponible · Subsección duodécima. Disposiciones comunes para las reducciones establecidas en las subsecciones de la tercera a la décima."},{"n":"CAT","a":"631-34","t":"Relaciones de convivencia de ayuda mutua.","x":"1. En las adquisiciones por causa de muerte entre miembros de una relación de convivencia de ayuda mutua, los adquirentes quedan asimilados al resto de descendientes del grupo II que define el artículo 2, al efecto de la aplicación de las reducciones que establecen las subsecciones primera y sexta y al efecto de la aplicación del coeficiente multiplicador para la determinación de la cuota tributaria.\n2. Para poder disfrutar de la reducción establecida en el apartado 1, el conviviente o convivientes supervivientes deben acreditar la existencia de la relación de convivencia de ayuda mutua mediante la escritura pública de formalización de la relación, otorgada como mínimo dos años antes de la muerte del causante, o bien mediante un acta de notoriedad que demuestre un período mínimo de dos años de convivencia.","u":"#a6-51","c":"CAPÍTULO I. Adquisiciones por causa de muerte · Sección II. Otras normas en relación con las adquisiciones por causa de muerte"},{"n":"CAT","a":"632-1","t":"Base liquidable.","x":"1. En las adquisiciones lucrativas entre vivos, la base liquidable se obtiene como resultado de aplicar a la base imponible las reducciones establecidas en esta sección única.\n2. Las reducciones establecidas en las subsecciones enumeradas seguidamente mejoran las reducciones análogas del Estado:\n– Subsección primera: reducción por donación del negocio empresarial o profesional.\n– Subsección segunda: reducción por donación de participaciones en entidades.\n– Subsección quinta: reducción por donación de bienes del patrimonio cultural.\n3. Las reducciones establecidas en las subsecciones enumeradas a continuación son reducciones propias:\n– Subsección tercera: reducción por la donación de participaciones en entidades a personas con vínculos laborales o profesionales.\n– Subsección cuarta: reducción por la donación de dinero para constituir o adquirir una empresa individual o un negocio profesional o para adquirir participaciones en entidades.\n– Subsección sexta: reducción por la donación de determinadas fincas rústicas de dedicación forestal.\n– Subsección octava: reducción por la donación de una vivienda que ha de constituir la primera vivienda habitual o por la donación de dinero destinado a la adquisición de dicha primera vivienda habitual.\n– Subsección novena: reducción por aportaciones a patrimonios protegidos de personas con discapacidad.\n– Subsección décima: reducción por donaciones hechas por entidades sin finalidad de lucro.\n4. Las reducciones establecidas en esta sección son aplicables a las donaciones por causa de muerte que regula el capítulo II del título III de la Ley 10/2008, de 10 de julio, del libro cuarto del Código civil de Cataluña, relativo a las sucesiones, en las que se pacte la transmisión inmediata de la propiedad de la cosa dada sujeta a condición resolutoria de revocación o premoriencia del donatario. Las reducciones que establece la sección I del capítulo I no pueden aplicarse a las donaciones mencionadas por causa de muerte, que se asimilan a tal efecto a las adquisiciones lucrativas entre vivos.","u":"#a6-52","c":"Sección única. Reducciones de la base imponible · Subsección preliminar. Régimen general"},{"n":"CAT","a":"632-2","t":"Supuestos de aplicación.","x":"1. En las donaciones o cualquier otro negocio jurídico gratuito equiparable entre vivos a favor del cónyuge, de los descendientes, de los ascendientes o de los colaterales hasta el tercer grado del donante, tanto por consanguinidad o adopción como por afinidad, puede aplicarse a la base imponible una reducción del 95 % del valor neto de la totalidad de los elementos afectos a una actividad empresarial o profesional del donante.\n2. También pueden disfrutar de la reducción establecida en el apartado 1 las personas que, sin tener la relación de parentesco que se especifica, y sin perjuicio de que deban cumplir los demás requisitos y condiciones determinados en esta subsección, cumplan en la fecha de la donación los siguientes requisitos:\na) Tener una vinculación laboral o de prestación de servicios con la empresa o el negocio profesional del donante, con una antigüedad mínima de diez años.\nb) Tener encargadas tareas de responsabilidad en la gestión o dirección de la empresa o negocio profesional del donante, con una antigüedad mínima de cinco años en el ejercicio de dichas tareas. Se entiende que tiene encargadas dichas tareas, si acredita la categoría laboral correspondiente a los grupos 1 y 2 de cotización del régimen general de la Seguridad Social o si el donante le ha otorgado un apoderamiento especial para realizar las actuaciones habituales de gestión de la empresa.","u":"#a6-53","c":"Sección única. Reducciones de la base imponible · Subsección primera. Reducción por donación de un negocio empresarial o profesional"},{"n":"CAT","a":"632-3","t":"Requisitos.","x":"1. Para poder disfrutar de la reducción establecida en esta subsección, es preciso que se cumplan los siguientes requisitos:\na) Que la actividad sea ejercida por el donante de forma habitual, personal y directa, en los términos establecidos en el apartado 2.\nb) Que el donante haya cumplido sesenta y cinco años, cese anticipadamente en una actividad agraria en los términos establecidos en el Reglamento (UE) 1305/2013 del Parlamento Europeo y del Consejo, o se encuentre en situación de incapacidad permanente absoluta o de gran invalidez.\nc) Que los rendimientos derivados del ejercicio de la actividad empresarial o profesional cuyos elementos patrimoniales afectos son objeto de donación constituyen al menos el 50 % de la totalidad de los rendimientos del trabajo personal, del capital mobiliario e inmobiliario y de las actividades económicas a los efectos del impuesto sobre la renta de las personas físicas del donante, en los términos establecidos en el apartado 3.\nd) Que en la fecha de la donación el donante cese en la actividad empresarial o profesional y deje de percibir rendimientos de esa actividad.\n2. A efectos de la aplicación de la reducción establecida en esta subsección:\n– Se entiende que el donante ha ejercido la actividad de forma habitual, si lo ha hecho con vocación de perdurabilidad y continuidad personal en el tiempo.\n– Se entiende que el donante ha ejercido la actividad de forma personal, si la ha desarrollado por sí mismo.\n– Se entiende que el donante ha ejercido la actividad de manera directa si él mismo ha ejercido el control de la actividad sin intermediarios y ha tenido a su cargo las funciones y facultades de gestión y organización de la actividad.\n3. A efectos de lo establecido en la letra c) del apartado 1:\n– No deben computarse como rendimientos del trabajo personal las remuneraciones por la participación del donante en las entidades que son objeto de la reducción establecida en la subsección segunda.\n– No deben computarse como rendimientos de actividades económicas los rendimientos derivados del ejercicio de otras actividades empresariales o profesionales del donante, siempre que la suma de la totalidad de los rendimientos de actividades económicas constituya al menos el 50 % de la totalidad de los rendimientos del trabajo personal, del capital mobiliario e inmobiliario y de actividades económicas, ni tampoco los rendimientos derivados de la participación del donante en las entidades que son objeto de la reducción que establece la subsección segunda.\n4. Para determinar, a efectos de la reducción establecida en esta subsección, si se desarrolla una actividad empresarial o profesional, o si tal actividad tiene bienes afectos, es preciso atenerse a las reglas determinadas en la subsección tercera de la sección I, capítulo I.\n5. Se determinan por reglamento las condiciones y los requisitos de acreditación de una actividad empresarial o profesional a efectos de lo establecido en el apartado 1.","u":"#a6-54","c":"Sección única. Reducciones de la base imponible · Subsección primera. Reducción por donación de un negocio empresarial o profesional"},{"n":"CAT","a":"632-4","t":"Regla de mantenimiento.","x":"El disfrute definitivo de la reducción establecida en esta subsección queda condicionado al mantenimiento del ejercicio de la actividad empresarial o profesional durante los cinco años siguientes a la donación, o al negocio jurídico equiparable, salvo que el donatario fallezca en este plazo, así como al mantenimiento en el patrimonio del donatario, durante el mismo plazo y con la misma excepción, de los elementos que han sido objeto de la donación, o de los elementos subrogados, y de su afectación a la actividad empresarial o profesional.","u":"#a6-55","c":"Sección única. Reducciones de la base imponible · Subsección primera. Reducción por donación de un negocio empresarial o profesional"},{"n":"CAT","a":"632-5","t":"Supuesto de aplicación.","x":"1. En las donaciones o cualquier otro negocio jurídico gratuito equiparable entre vivos a favor del cónyuge, de los descendientes, de los ascendientes o de los colaterales hasta el tercer grado del donante, tanto por consanguinidad o adopción como por afinidad, puede aplicarse a la base imponible una reducción del 95 % del valor de las participaciones en entidades, con cotización o sin cotización en mercados organizados, por la parte que corresponda por razón de la proporción existente entre los activos necesarios para el ejercicio de la actividad empresarial o profesional, minorados en el importe de las deudas derivadas de la actividad, y el valor del patrimonio neto de cada entidad. Dichas reglas se aplican asimismo en la valoración de las participaciones de entidades participadas para determinar el valor de las participaciones de la entidad tenedora.\n2. En caso de donación de participaciones en sociedades laborales, la reducción establecida en el apartado 1 es del 97 %.\n3. La reducción establecida en esta subsección no se aplica en ningún caso a las participaciones en instituciones de inversión colectiva.","u":"#a6-56","c":"Sección única. Reducciones de la base imponible · Subsección segunda. Reducción por donación de participaciones en entidades"},{"n":"CAT","a":"632-6","t":"Requisitos.","x":"1. Para poder disfrutar de la reducción establecida en esta subsección, deben cumplirse los siguientes requisitos:\na) Que el donante haya cumplido sesenta y cinco años, o se halle en situación de incapacidad permanente absoluta o de gran invalidez.\nb) Que la entidad no tenga como actividad principal, en los términos establecidos en el artículo 631-12, la gestión de un patrimonio mobiliario o inmobiliario.\nc) Que la participación del donante en el capital de la entidad sea al menos del 5 %, computado individualmente, o del 20 %, computado conjuntamente con el cónyuge, los descendientes, los ascendientes o los colaterales hasta el tercer grado del donante, tanto por consanguinidad o adopción como por afinidad.\nd) Que el donante haya ejercido efectivamente funciones de dirección en la entidad y haya percibido por esta tarea una remuneración que constituya al menos el 50 % de la totalidad de los rendimientos de actividades económicas y del trabajo personal, en los términos establecidos en el apartado 2.\nSi la participación en la entidad es conjunta con alguna o algunas de las personas a las que se refiere la letra c de este apartado, al menos una de las personas de este grupo de parentesco debe cumplir los requisitos relativos a las funciones de dirección y a las remuneraciones derivadas de estas funciones.\ne) Que el donante, en la fecha de la donación, si ejerce funciones de dirección en la entidad, deje de ejercerlas y deje de percibir las remuneraciones correspondientes.\n2. A efectos de lo establecido en la letra d) del apartado 1:\na) No deben computarse como rendimientos del trabajo personal los rendimientos derivados del ejercicio de funciones de dirección en otras entidades, siempre y cuando se cumplan los requisitos establecidos en las letras b) y c) del apartado 1.\nb) No deben computarse como rendimientos de actividades económicas los rendimientos derivados del ejercicio de otras actividades empresariales o profesionales del donante, siempre y cuando la suma de la totalidad de los rendimientos de actividades económicas constituya al menos el 50 % de la totalidad de los rendimientos del trabajo personal, del capital mobiliario e inmobiliario y de actividades económicas, con la misma excepción que establece la letra a en cuanto a los rendimientos derivados del ejercicio de funciones de dirección.\n3. Se determinan por reglamento los requisitos que establece el apartado 1.","u":"#a6-57","c":"Sección única. Reducciones de la base imponible · Subsección segunda. Reducción por donación de participaciones en entidades"},{"n":"CAT","a":"632-7","t":"Regla de mantenimiento.","x":"El disfrute definitivo de la reducción establecida en esta subsección queda condicionado al mantenimiento en el patrimonio del donatario, durante los cinco años siguientes a la donación, o al negocio jurídico equiparable, y salvo que el donatario fallezca dentro de este plazo, de los elementos que han sido objeto de la donación, así como al cumplimiento, durante el mismo plazo y con la misma excepción, de los requisitos que establecen para la entidad participada y para el donante las letras b), c) y d) del artículo 632-6.1.","u":"#a6-58","c":"Sección única. Reducciones de la base imponible · Subsección segunda. Reducción por donación de participaciones en entidades"},{"n":"CAT","a":"632-8","t":"Supuesto de aplicación.","x":"1. En las donaciones o cualquier otro negocio jurídico gratuito equiparable entre vivos a favor de personas que, sin tener la relación de parentesco que especifica el artículo 632-5, adquieren participaciones en entidades, con cotización o sin cotización en mercados organizados, puede aplicarse a la base imponible una reducción del 95 % del valor de las participaciones adquiridas, por la parte que corresponda por razón de la proporción existente entre los activos necesarios para el ejercicio de la actividad empresarial o profesional, minorados en el importe de las deudas derivadas de las mismas y el valor del patrimonio neto de cada entidad. Dichas reglas se aplican en la valoración de las participaciones de entidades participadas para determinar el valor de las participaciones de la entidad tenedora.\n2. La reducción establecida en esta subsección no se aplica en ningún caso a las participaciones en instituciones de inversión colectiva.","u":"#a6-59","c":"Sección única. Reducciones de la base imponible · Subsección tercera. Reducción por la donación de participaciones en entidades a personas con vínculos laborales o profesionales"},{"n":"CAT","a":"632-9","t":"Requisitos.","x":"Para poder disfrutar de la reducción establecida en esta subsección, es preciso que se cumplan los siguientes requisitos:\na) Los establecidos en el artículo 632-6.1.\nb) Que el donatario tenga una vinculación laboral o de prestación de servicios con la entidad cuyas participaciones son objeto de adquisición gratuita, con una antigüedad mínima de diez años, y que haya ejercido funciones de dirección como mínimo los cinco años anteriores a esta fecha.\nc) Que la participación del donatario en el capital de la entidad resultante de la donación sea de más del 50 %.","u":"#a6-60","c":"Sección única. Reducciones de la base imponible · Subsección tercera. Reducción por la donación de participaciones en entidades a personas con vínculos laborales o profesionales"},{"n":"CAT","a":"632-10","t":"Regla de mantenimiento.","x":"El disfrute definitivo de la reducción establecida en esta subsección queda condicionado a los siguientes requisitos:\na) El donatario debe mantener en su patrimonio, durante los cinco años siguientes a la donación, o al negocio jurídico equiparable, y salvo que fallezca en este plazo, los elementos que han sido objeto de la donación, y debe continuar ejerciendo en la entidad, durante el mismo plazo y con la misma excepción, funciones de dirección.\nb) La entidad no puede tener como actividad principal, en los términos establecidos en el artículo 631-12, la gestión de un patrimonio mobiliario o inmobiliario.","u":"#a6-61","c":"Sección única. Reducciones de la base imponible · Subsección tercera. Reducción por la donación de participaciones en entidades a personas con vínculos laborales o profesionales"},{"n":"CAT","a":"632-11","t":"Supuesto de aplicación.","x":"1. En las donaciones de dinero a favor de descendientes para constituir o adquirir un negocio profesional o una empresa o para adquirir participaciones, siempre y cuando la empresa, el negocio o la entidad tengan el domicilio social y fiscal en Cataluña, puede aplicarse en la base imponible una reducción del 95 % del importe donado, con una reducción máxima de 200.000 euros, límite que se fija en 400.000 euros para los donatarios que tengan un grado de discapacidad igual o superior al 33 %.\n2. Los importes máximos que fija el apartado 1 se aplican tanto en caso de una única donación de dinero como en caso de donaciones sucesivas o simultáneas, que a tal efecto son acumulables, tanto si provienen del mismo ascendiente como si provienen de diferentes ascendientes. En caso de donaciones sucesivas, solo puede aplicarse la reducción, con los mencionados límites, a las que se hayan realizado en los seis meses anteriores a la constitución o la adquisición de la empresa o negocio o dentro de los seis meses anteriores a la adquisición de las participaciones, de acuerdo con lo establecido por la letra b) del artículo 632-12.","u":"#a6-62","c":"Sección única. Reducciones de la base imponible · Subsección cuarta. Reducción por la donación de dinero para constituir o adquirir una empresa o un negocio profesional o para adquirir participaciones en entidades"},{"n":"CAT","a":"632-12","t":"Requisitos.","x":"Para poder disfrutar de la reducción establecida en esta subsección, es preciso que se cumplan los siguientes requisitos:\na) La donación debe formalizarse en escritura pública, otorgada en el plazo de un mes, a contar desde la fecha de entrega del dinero. Debe hacerse constar de forma expresa en la escritura que el donatario destina el dinero donado exclusivamente a la constitución o la adquisición de su primera empresa o de su primer negocio profesional o a la adquisición de sus primeras participaciones en entidades que cumplen los requisitos que determina este artículo.\nb) La constitución o la adquisición de la empresa o el negocio profesional o la adquisición de las participaciones debe producirse en el plazo de seis meses, a contar desde la fecha de formalización de la donación.\nc) El patrimonio neto del donatario en la fecha de formalización de la donación no puede ser superior a 500.000 euros.\nd) La empresa, el negocio o la entidad no pueden tener como actividad principal, en los términos establecidos en el artículo 631-12, la gestión de un patrimonio mobiliario o inmobiliario.\ne) En caso de adquisición de una empresa o un negocio o de adquisición de participaciones en entidades, no puede haber ninguna vinculación entre la empresa, el negocio o la entidad y el donatario, en los términos establecidos por el artículo 18 de la Ley 27/2014, de 27 de noviembre, del impuesto sobre sociedades.\nf) En el caso de adquisición de una empresa o un negocio, el importe del volumen de negocios neto del último ejercicio cerrado antes de la fecha de adquisición no puede superar los siguientes límites:\n– Tres millones de euros, en caso de adquisición de una empresa.\n– Un millón de euros, en caso de adquisición de un negocio profesional.\ng) En caso de adquisición de participaciones en una entidad, exceptuando las empresas de economía social, las cooperativas de trabajo asociado y las sociedades laborales, además de los límites del importe del volumen de negocio neto que establece la letra f), es preciso cumplir los siguientes requisitos:\n– Las participaciones adquiridas por el donatario deben constituir al menos el 50 % del capital social de la entidad.\n– El donatario debe ejercer efectivamente funciones de dirección en la entidad.","u":"#a6-63","c":"Sección única. Reducciones de la base imponible · Subsección cuarta. Reducción por la donación de dinero para constituir o adquirir una empresa o un negocio profesional o para adquirir participaciones en entidades"},{"n":"CAT","a":"632-13","t":"Regla de mantenimiento.","x":"El disfrute definitivo de la reducción establecida en esta subsección queda condicionado al hecho de que el donatario continúe ejerciendo funciones de dirección en la entidad durante los cinco años siguientes a la donación, o al negocio jurídico equiparable, salvo que el donatario fallezca en este plazo, así como al mantenimiento en el patrimonio del donatario, durante el mismo plazo y con la misma excepción, de los bienes resultantes de la donación, o de bienes subrogados de valor equivalente.","u":"#a6-64","c":"Sección única. Reducciones de la base imponible · Subsección cuarta. Reducción por la donación de dinero para constituir o adquirir una empresa o un negocio profesional o para adquirir participaciones en entidades"},{"n":"CAT","a":"632-16","t":"Supuesto de aplicación.","x":"1. En las donaciones o cualquier otro negocio jurídico gratuito equiparable entre vivos a favor del cónyuge, los descendientes, los ascendientes o los colaterales hasta el tercer grado del donante, puede aplicarse a la base imponible una reducción del 95 % del valor de las fincas rústicas de dedicación forestal, si cumplen alguno de los siguientes requisitos:\na) Disponer de un instrumento de ordenación forestal que haya sido aprobado por el departamento competente o que se apruebe en el plazo voluntario de presentación de la autoliquidación.\nb) Ser gestionadas en el marco de un convenio, acuerdo o contrato de gestión forestal formalizado con la Administración forestal.\nc) Estar ubicadas en terrenos que han sufrido incendios forestales en los veinticinco años anteriores a la fecha de la donación o que, de conformidad con la normativa forestal, han sido declarados zona de actuación urgente debido a los incendios que han sufrido.\n2. La base sobre la que se aplica esta bonificación comprende tanto el valor del terreno como, si procede, el de las construcciones ubicadas en la finca forestal y que sean para utilidad exclusiva de la finca.","u":"#a6-67","c":"Sección única. Reducciones de la base imponible · Subsección sexta. Reducción por la donación de determinadas fincas rústicas de dedicación forestal"},{"n":"CAT","a":"632-17","t":"Regla de mantenimiento.","x":"El disfrute definitivo de la reducción que establece esta subsección queda condicionado al mantenimiento de la finca rústica de dedicación forestal en el patrimonio del adquirente durante los diez años siguientes a la fecha de la donación o cualquier otro negocio jurídico gratuito equiparable entre vivos, salvo que el adquirente fallezca dentro de este plazo.","u":"#a6-68","c":"Sección única. Reducciones de la base imponible · Subsección sexta. Reducción por la donación de determinadas fincas rústicas de dedicación forestal"},{"n":"CAT","a":"632-18","t":"Ámbito de aplicación.","x":"Las reducciones que establecen las subsecciones de primera a sexta se aplican tanto en caso de adquisición de la plena propiedad o de la nuda propiedad como en caso de adquisición de cualquier otro derecho sobre los bienes afectados.","u":"#a6-69","c":"Sección única. Reducciones de la base imponible · Subsección séptima. Disposiciones comunes para las reducciones que establecen las subsecciones de primera a sexta."},{"n":"CAT","a":"632-19","t":"Regla de mantenimiento de los bienes o derechos objeto de la donación.","x":"1. En las adquisiciones lucrativas entre vivos, el donatario no puede hacer actos de disposición ni operaciones societarias que, directamente o indirectamente, puedan dar lugar a una minoración sustancial del valor de los bienes o derechos objeto de la donación.\n2. En caso de incumplimiento de lo dispuesto en el apartado 1 o de las reglas de mantenimiento fijadas por los artículos 632-4, 632-7, 632-10, 632-13, 632-15 y 632-17, el sujeto pasivo debe pagar, dentro del plazo voluntario de presentación de la autoliquidación correspondiente a los actos de transmisión entre vivos, la parte del impuesto que haya dejado de ingresar como consecuencia de la reducción aplicada, junto con los intereses de demora que se hayan devengado.\n3. Se entiende que el incumplimiento a que se refiere el apartado 2 no se produce si los bienes y derechos han sido objeto de expropiación forzosa, se han perdido en virtud de resolución judicial o de disposición legal o se han perdido o han sido destruidos por causa de fuerza mayor.","u":"#a6-70","c":"Sección única. Reducciones de la base imponible · Subsección séptima. Disposiciones comunes para las reducciones que establecen las subsecciones de primera a sexta."},{"n":"CAT","a":"632-20","t":"Supuesto de aplicación.","x":"1. En las donaciones a descendientes de una vivienda que debe constituir su primera vivienda habitual o de dinero destinado a la adquisición de dicha primera vivienda habitual, puede aplicarse una reducción del 95 % del valor de la vivienda o el importe donado, con una reducción máxima de 60.000 euros, límite que se fija en 120.000 euros para los donatarios que tengan un grado de discapacidad igual o superior al 65 %. También se aplica la reducción en caso de que la donación sea de un terreno o de dinero para adquirirlo para que, en ambos casos, el descendiente construya su primera vivienda habitual.\n2. Los importes máximos que fija el apartado 1 se aplican tanto en el caso de una única donación como en el caso de donaciones sucesivas o simultáneas, que a tal efecto son acumulables, tanto si son exclusivamente dinerarias como si combinan donación de vivienda o terreno y donación de dinero, y tanto si provienen del mismo ascendiente como si provienen de diferentes ascendientes. En las donaciones de dinero, la reducción solo puede aplicarse, con los límites mencionados, a las que se han hecho dentro de los seis meses anteriores a la adquisición de la vivienda o terreno, de acuerdo con lo establecido por la letra d del artículo 632-21.1.","u":"#a6-71","c":"Sección única. Reducciones de la base imponible · Subsección octava. Reducción por la donación de una vivienda que debe constituir la primera vivienda habitual o por la donación de dinero destinado a la adquisición de dicha primera vivienda habitual"},{"n":"CAT","a":"632-21","t":"Requisitos.","x":"1. Para poder disfrutar de la reducción que establece esta subsección, es necesario que se cumplan los siguientes requisitos:\na) La donación debe formalizarse en escritura pública, en la que debe hacerse constar de manera expresa la finalidad, en cada caso, de la donación:\n– Que la vivienda constituirá la primera vivienda habitual del donatario.\n– Que el terreno se destinará a la construcción de esta primera vivienda habitual.\n– Que el dinero recibido se destinará a la adquisición del terreno o de la primera vivienda habitual del donatario. En caso de donación dineraria, la escritura pública debe otorgarse en el plazo de un mes, a contar desde la entrega del dinero.\nb) El donatario no puede tener más de treinta y seis años, salvo que tenga un grado de discapacidad igual o superior al 65 %.\nc) La suma de las bases imponibles general y del ahorro de la última declaración del impuesto sobre la renta de las personas físicas presentada por el donatario no puede ser superior, restando los mínimos personal y familiar, a 36.000 euros.\nd) En caso de donaciones de dinero, el donatario debe adquirir la vivienda en el plazo de seis meses, a contar de la fecha de la donación o, si hay donaciones sucesivas, a contar de la fecha de la primera donación.\n2. A efectos de la aplicación de la reducción establecida en esta subsección:\na) Se considera vivienda habitual tanto la vivienda como un trastero y hasta dos plazas de aparcamiento que hayan sido adquiridos simultáneamente en unidad de acto o estén situados en el mismo edificio o complejo urbanístico, y siempre que, en ambos casos, en el momento de la transmisión se encuentren a disposición del donante, sin haber sido cedidos a terceras personas.\nb) Para considerar que la vivienda constituye la vivienda habitual del contribuyente debe haber sido habitada de forma efectiva y permanente por el contribuyente en el plazo de doce meses, contados a partir de la fecha de adquisición de la vivienda o de finalización de las obras de construcción. En este último caso, las obras deben finalizar dentro de un plazo de tres años, a contar desde la donación.\nc) Se considera vivienda habitual la vivienda en la que el contribuyente resida durante un plazo continuado de tres años. Se entiende que la vivienda tiene también este carácter cuando, a pesar de no haber transcurrido el plazo de tres años, concurran circunstancias que necesariamente exijan el cambio de vivienda, como la celebración de matrimonio, separación matrimonial, constitución de pareja estable, extinción de pareja estable, traslado laboral, obtención de primer empleo o de empleo más ventajoso u otras análogas.\nd) Si la vivienda ha sido habitada de forma efectiva y permanente por el contribuyente en el plazo de doce meses, contados a partir de la fecha de adquisición o de finalización de las obras, el plazo de tres años al que se refiere la letra c se computa desde esta última fecha.\ne) Se considera adquisición de la primera vivienda habitual la adquisición en plena propiedad de la totalidad de la vivienda o, en caso de cónyuges o futuros contrayentes, de una parte indivisa de la vivienda.\n3. Esta reducción se entiende concedida con carácter provisional y está condicionada al cumplimiento de los requisitos temporales establecidos en las letras b), c) y d) del apartado 2.\n4. En caso de incumplimiento de los requisitos a que está condicionada la aplicación de esta reducción, el sujeto pasivo debe presentar e ingresar, en el plazo de un mes, a contar des del día siguiente al de la fecha en que se produjo el incumplimiento, la autoliquidación correspondiente por la parte del impuesto que haya dejado de ingresar como consecuencia de la reducción aplicada, junto con los intereses de demora que se hayan devengado.","u":"#a6-72","c":"Sección única. Reducciones de la base imponible · Subsección octava. Reducción por la donación de una vivienda que debe constituir la primera vivienda habitual o por la donación de dinero destinado a la adquisición de dicha primera vivienda habitual"},{"n":"CAT","a":"632-22","t":"Supuesto de aplicación.","x":"1. En la parte de las aportaciones a patrimonios protegidos de personas con discapacidad que, en tanto que exceda el importe máximo fijado por ley para tener la consideración de rendimientos del trabajo de la persona con discapacidad, quede gravada por el impuesto sobre sucesiones y donaciones como transmisión lucrativa entre vivos, puede aplicarse en la base imponible una reducción del 90 % del importe excedente, siempre que las aportaciones cumplan los requisitos y las formalidades que determina la Ley 41/2003, de 18 de noviembre, de protección patrimonial de las personas con discapacidad y de modificación del Código civil, de la Ley de enjuiciamiento civil y de la normativa tributaria con esta finalidad.\n2. La misma reducción es aplicable, en los términos establecidos en el apartado 1, en el caso de que las aportaciones se realicen a favor de patrimonios protegidos constituidos al amparo de la Ley 25/2010, de 29 de julio, del libro segundo del Código civil de Cataluña, relativo a la persona y la familia.","u":"#a6-73","c":"Sección única. Reducciones de la base imponible · Subsección novena. Reducción por aportaciones a patrimonios protegidos"},{"n":"CAT","a":"632-23","t":"Supuesto de aplicación.","x":"1. En las donaciones, y en el resto de transmisiones lucrativas entre vivos que sean equiparables, recibidas de fundaciones y asociaciones que cumplen finalidades de interés general, hayan sido o no declaradas de utilidad pública, inscritas en los registros de fundaciones y de asociaciones adscritos a la dirección general correspondiente del Departamento de Justicia, o en registros análogos de otras administraciones públicas, el contribuyente puede aplicar a la base imponible una reducción del 95 %. A efectos de esta reducción, se consideran asociaciones que cumplen finalidades de interés general las que han sido declaradas de utilidad pública y todas las que promueven actividades cuyo beneficio no esté restringido exclusivamente a sus asociados.\n2. Quedan excluidas de la aplicación de la reducción a la que se refiere el apartado 1:\na) Las donaciones recibidas de las entidades inscritas en el censo de asociaciones y fundaciones vinculadas a partidos políticos vinculados al registro mencionado en el apartado 1 y de entidades análoga inscritas en otras administraciones públicas.\nb) Las donaciones recibidas de partidos políticos, de asociaciones religiosas o deportivas y de las organizaciones empresariales y sindicales inscritas en registros específicos de la Generalitat o de otras administraciones públicas.\nc) Las donaciones recibidas de asociaciones que queden excluidas de la concesión de ayudas públicas en virtud de lo establecido en el artículo 4 de la Ley orgánica reguladora del derecho de asociación.\nd) Las donaciones de bienes inmuebles.","u":"#a6-74","c":"Sección única. Reducciones de la base imponible · Subsección décima. Reducción por donaciones realizadas por entidades sin ánimo de lucro"},{"n":"CAT","a":"632-24","t":"Requisitos.","x":"1. Para poder disfrutar de la reducción establecida por esta subsección, es necesario que se cumplan los siguientes requisitos:\na) La entidad donante debe estar inscrita en el registro correspondiente con una antelación mínima de dos años a la realización de la donación y estar operativa desde que se constituyó. Además, las fundaciones y las asociaciones declaradas de utilidad pública deben estar al corriente de la presentación de las cuentas anuales en los registros correspondientes.\nb) La donación debe realizarse dentro del marco de los fines propios de la entidad donante y debe formalizarse en documento público o privado, otorgado por el donante y el donatario, en el plazo de un mes, a contar desde la entrega de la cosa o cantidad. Este documento debe contener, como mínimo, la siguiente información:\n1.º La identificación de la entidad donante (denominación, NIF, domicilio social y número en el correspondiente registro de entidades).\n2.º La identificación del donatario (nombre y apellidos, NIF o NIE y domicilio fiscal).\n3.º El ámbito de actuación o fines de la entidad, de acuerdo con sus estatutos.\n4.º La cosa o cantidad objeto de la donación.\n5.º El motivo de la donación y los fines o usos a los que el donatario debe aplicar la cosa o cantidad.\n6.º La previsión expresa, si procede, de la reversión parcial del exceso no aplicado por el donatario al fin o uso mencionados en el punto 5.º\nc) Si se trata de una donación de dinero, la entrega debe realizarse por una de las dos siguientes vías:\n1.º Por transferencia bancaria a una cuenta nominativa del donatario, que debe destinar la totalidad de la donación a los fines establecidos en el documento al que se refiere la letra b) en el plazo de seis meses, a contar desde la fecha de este documento, ampliable a seis meses más por causa justificada y debidamente acreditada.\n2.º Por transferencia directa de la entidad donante a la cuenta bancaria del acreedor del donatario por la prestación de servicios o entrega de bienes de los que este haya sido beneficiario que queden amparados en el documento de la donación a la que se refiere la letra b).\n2. Salvo en el supuesto establecido por el párrafo siguiente, el incumplimiento por parte del donatario de la aplicación de la cosa o cantidad recibida a los fines o usos recogidos en el documento al que se refiere la letra b) conlleva la pérdida total de la reducción, con aplicación de los intereses de demora correspondientes y sin perjuicio de los recargos y las sanciones que puedan resultar aplicables de acuerdo con la normativa tributaria general.\nSi una vez efectuada la donación resulta que es excesiva, en términos cuantitativos o temporales, y el donatario devuelve este exceso a la entidad donante porque así lo establece expresamente el documento de donación al que se refiere el punto 6.º de la letra b), el contribuyente puede solicitar la rectificación de la autoliquidación con devolución, si procede, de la parte de la cuota que representa este exceso, con la acreditación previa del retorno a la entidad de este exceso por cualquier medio de prueba admitido en derecho.\n3. El plazo para presentar e ingresar la autoliquidación del impuesto es de un mes, a contar desde la fecha de entrega de la cosa o cantidad.","u":"#a6-75","c":"Sección única. Reducciones de la base imponible · Subsección décima. Reducción por donaciones realizadas por entidades sin ánimo de lucro"},{"n":"CAT","a":"632-25","t":"Supuesto de aplicación.","x":"1. En las donaciones a ascendientes, descendentes y colaterales de segundo grado, que tengan la condición de víctimas de violencia machista de acuerdo con la Ley 5/2008, de 24 de abril, del derecho de las mujeres a erradicar la violencia machista, de una vivienda que tiene que constituir su vivienda habitual o de dinero destinado a la adquisición de esta vivienda habitual, se puede aplicar una reducción del 95 % del valor de la vivienda o el importe donado, con una reducción máxima de 100.000 euros, límite que se fija en 200.000 euros para las donatarias que tengan un grado de discapacidad igual o superior al 65 % o con algún hijo o hija menor a cargo. También se aplica la reducción en el caso que la donación sea de un terreno o de dinero para adquirirlo para que, en ambos casos, la descendiente construya su primera vivienda habitual.\n2. Los importes máximos que fija el apartado 1 se aplican tanto en el caso de una única donación como en el caso de donaciones sucesivas o simultáneas que, a tal efecto, son acumulables, tanto si son exclusivamente dinerarias como si combinan donación de vivienda o terreno y donación de dinero, y tanto si provienen del mismo ascendiente como si provienen de diferentes ascendientes. En las donaciones de dinero, la reducción solo se puede aplicar, con los límites mencionados, a las que se han hecho dentro de los seis meses anteriores a la adquisición de la vivienda o terreno, de acuerdo con lo establecido por la letra d del apartado 1 del artículo 632-21.\nTexto añadido, publicado el 26/03/2025, en vigor a partir del 27/06/2025.","u":"#a6-136","c":"Sección única. Reducciones de la base imponible · Subsección undécima. Reducción por donación de una vivienda que debe constituir la vivienda habitual o por donación de dinero destinado a la adquisición de esta vivienda habitual a favor de víctimas de violencia machista"},{"n":"CAT","a":"632-26","t":"Requisitos.","x":"1. Para poder disfrutar de la reducción que establece esta subsección, hace falta que se cumplan los siguientes requisitos:\na) La condición de víctima de violencia machista en el ámbito de la pareja se acredita por alguno de los medios de prueba establecidos en la Ley 5/2008, de 24 de abril, del derecho de las mujeres a erradicar la violencia machista.\nb) La adquisición de la vivienda debe obedecer a la necesidad de cambio de domicilio de la persona víctima de violencia machista y producirse como consecuencia de esta circunstancia.\nc) La donación se debe formalizar en escritura pública, en la que se debe hacer constar de manera expresa la finalidad, en cada caso, de la donación:\n– Que la vivienda constituirá la vivienda habitual del donatario.\n– Que el terreno se destinará a la construcción de esta vivienda habitual.\n– Que el dinero recibido se destinará a la adquisición del terreno o de la vivienda habitual del donatario. En el caso de donación dineraria, la escritura pública debe otorgarse en el plazo de un mes, a contar desde la entrega del dinero.\nd) La suma general de las bases imponibles y del ahorro de la última declaración del impuesto sobre la renta de las personas físicas presentada por la donataria no puede ser superior, restando los mínimos personal y familiar, a 36.000 euros.\ne) En el caso de donaciones de dinero, la donataria debe adquirir la vivienda en el plazo de seis meses, a contar de la fecha de la donación o, si hay sucesivas, a contar de la fecha de la primera donación.\n2. Al efecto de la aplicación de la reducción se debe estar a lo establecido en las letras a), b), c) y d) del apartado 2 del artículo 632-21.\n3. Esta reducción se entiende concedida con carácter provisional y queda condicionada al cumplimiento de los requisitos temporales establecidos en el apartado 2 de este artículo.\n4. En el caso de incumplimiento de los requisitos a que está condicionada la aplicación de esta reducción, el sujeto pasivo debe presentar e ingresar, en el plazo de un mes, a contar des del día siguiente al de la fecha en que se produjo el incumplimiento, la autoliquidación correspondiente por la parte del impuesto que haya dejado de ingresar como consecuencia de la reducción aplicada, junto con los intereses de demora que se hayan devengado.\nTexto añadido, publicado el 26/03/2025, en vigor a partir del 27/06/2025.","u":"#a6-137","c":"Sección única. Reducciones de la base imponible · Subsección undécima. Reducción por donación de una vivienda que debe constituir la vivienda habitual o por donación de dinero destinado a la adquisición de esta vivienda habitual a favor de víctimas de violencia machista"},{"n":"CAT","a":"632-27","t":"Supuesto de aplicación.","x":"1. En las donaciones o en cualquier otro negocio jurídico gratuito se puede aplicar en la base imponible una reducción del 95% del valor de los elementos patrimoniales de los que es propietario el donante, afectos a una explotación agraria. La reducción es del 99% si el adquirente tiene la condición de joven agricultor, en los términos establecidos por el apartado 1 del artículo 632-28.\nPara que esta reducción sea aplicable en el caso de que la titularidad de la explotación agraria vaya a cargo de una persona jurídica, es necesario que concurran los dos requisitos siguientes:\n– Debe tener por objeto exclusivo la actividad agraria y, si procede, también debe desarrollar actividades complementarias establecidas por el primer párrafo de la letra a del apartado 1 del artículo 632-28.\n– Debe pertenecer en más del 50% del capital social a personas físicas que tengan la condición de agricultor profesional, entre las cuales el adquirente de los bienes.\n2. La misma reducción se aplica en el caso de donación de participaciones en la entidad que efectúe la explotación agraria, con cotización o sin cotización en mercados organizados, por la parte que corresponda por razón de la proporción existente entre los activos necesarios para el ejercicio de la actividad, minorados en el importe de las deudas que derivan de la misma, y el valor del patrimonio neto de la entidad.\n3. A efectos de esta reducción:\na) Se entiende por explotación agraria el conjunto de bienes y derechos organizados empresarialmente por su titular en el ejercicio de la actividad agraria, primordialmente con fines de mercado, que constituyan una unidad de gestión técnico-económica.\nb) Es titular de la explotación quien ejerce la actividad agraria y, por lo tanto, también quien toma las decisiones, asume el riesgo empresarial y obtiene los beneficios.\nc) Se considera actividad agraria el conjunto de trabajos que se requieren para la obtención de productos agrícolas, ganaderos y forestales. Asimismo, se considera actividad agraria la venta directa por parte del agricultor de la producción propia sin transformación, o la primera transformación de esta producción, siempre y cuando el producto final esté incluido en el anexo I del artículo 38 del Tratado de funcionamiento de la Unión Europea, dentro de los elementos que integren la explotación, en mercados municipales o en lugares que no sean establecimientos comerciales permanentes.\nTambién se considera actividad agraria la que implica la gestión o la dirección y gerencia de la explotación.\nd) Se considera joven agricultor la persona física que cumple los siguientes requisitos:\n– Tener 40 años o menos, y ser responsable de explotación.\n– Acreditar la formación o la capacitación adecuadas en el ámbito agrario, para cuya determinación se deberán conjugar criterios de formación lectiva y capacitación profesional, con un mínimo de 150 horas lectivas. Este requisito puede acreditarse en el plazo de dos años a contar desde la donación.","u":"#A62","c":"Sección única. Reducciones de la base imponible · Subsección duodécima. Reducción por donación de explotación agraria"},{"n":"CAT","a":"632-28","t":"Requisitos.","x":"1. El donatario debe tener la condición de agricultor profesional o debe estar en condición de obtenerla en el plazo de dos años a contar desde la donación. En caso de desmembración del dominio, puede cumplir la condición de agricultor profesional tanto el nudo propietario como el usufructuario.\nTiene la condición de agricultor profesional la persona física que es titular de una explotación agraria; obtiene al menos el 50% de su renta total de actividades agrarias u otras actividades complementarias, siempre y cuando la parte de renta procedente directamente de la actividad agraria de su explotación no sea inferior al 25% de su renta total, y dedica a actividades agrarias o complementarias un volumen de ocupación igual o superior a la mitad de una unidad de trabajo agrario.\nA estos efectos:\na) Se consideran actividades complementarias las actividades de transformación de los productos de la explotación agraria y la venta directa de los productos transformados de su explotación; las actividades relacionadas con la conservación del espacio natural y la protección del medio ambiente, y las actividades cinegéticas y artesanales realizadas en su explotación.\nTambién se consideran actividades complementarias la participación y presencia del titular, como consecuencia de elección pública, en instituciones de carácter representativo, así como en órganos de representación de carácter sindical, cooperativo o profesional, siempre y cuando estos estén vinculados al sector agrario.\nb) Se considera unidad de trabajo agrario el trabajo que una persona a tiempo completo dedica a la actividad agraria durante un año. La aportación del trabajo agrario se acredita sobre la base de la cotización a la Seguridad Social.\nc) Para el cómputo del 25% de la renta total, se excluyen los rendimientos obtenidos del ejercicio de la actividad de turismo rural o agroturismo.\n2. Para determinar si se desarrolla la actividad económica es necesario ajustarse a lo que dispone el artículo 631-13.\n3. En el caso de donación de participaciones, es necesario que la participación del donante en el capital de la entidad constituya al menos el 5%, computado individualmente, o el 20%, computado junto con el cónyuge, los descendientes, los ascendientes o los colaterales hasta el tercer grado del causante, por consanguinidad, adopción o afinidad.\n4. Esta reducción es incompatible con las reducciones establecidas por los artículos 632-2 y 632-5.\nTexto añadido, publicado el 16/10/2025, en vigor a partir del 01/12/2025.","u":"#A62","c":"Sección única. Reducciones de la base imponible · Subsección duodécima. Reducción por donación de explotación agraria"},{"n":"CAT","a":"632-29","t":"Regla de mantenimiento.","x":"1. En el caso de adquisición de bienes afectos a la actividad, el disfrute definitivo de la reducción queda condicionado al mantenimiento del ejercicio de la actividad agraria durante los cinco años siguientes a la donación, salvo que el adquirente muera dentro de este plazo. También queda condicionado al mantenimiento en el patrimonio del adquirente, durante el mismo plazo y con igual excepción, de los mismos bienes y derechos, o de bienes y derechos subrogados de valor equivalente, y de su afectación a la actividad.\n2. En el caso de adquisición de participaciones, el disfrute definitivo de la reducción que establece esta subsección queda condicionado al mantenimiento de los elementos adquiridos en el patrimonio del adquirente durante los cinco años siguientes a la muerte del causante, salvo que el adquirente muera dentro de este plazo.\n3. El adquirente que tenga la condición de agricultor profesional, de acuerdo con lo que dispone el apartado 1 del artículo 631-28, en los supuestos 1 y 2 anteriores, debe mantener esta condición en el mismo plazo señalado de cinco años.\n4. En el caso de incumplimiento de los requisitos a los que está condicionada la aplicación de esta reducción, el sujeto pasivo debe presentar e ingresar, en el plazo de un mes a contar desde el día siguiente a la fecha en la que se haya producido el incumplimiento, la autoliquidación correspondiente por la parte del impuesto que haya dejado de ingresar como consecuencia de la reducción aplicada, con los intereses de demora que se hayan devengado.\nTexto añadido, publicado el 16/10/2025, en vigor a partir del 01/12/2025.","u":"#a6-147","c":"Sección única. Reducciones de la base imponible · Subsección duodécima. Reducción por donación de explotación agraria"},{"n":"CAT","a":"633-1","t":"Tarifa general.","x":"La cuota íntegra del impuesto sobre sucesiones y donaciones se obtiene como resultado de aplicar a la base liquidable la siguiente escala:\n| Base liquidable<br>Hasta (euros) | Cuota íntegra (euros) | Resto base liquidable<br>Hasta (euros) | Tipo aplicable<br>(%) |\n| -------------------------------- | --------------------- | -------------------------------------- | --------------------- |\n| 0,00 | 0,00 | 50.000,00 | 7 |\n| 50.000,00 | 3.500,00 | 150.000,00 | 11 |\n| 150.000,00 | 14.500,00 | 400.000,00 | 17 |\n| 400.000,00 | 57.000,00 | 800.000,00 | 24 |\n| 800.000,00 | 153.000,00 | En adelante | 32 |","u":"#a6-76","c":"TÍTULO III. Impuesto sobre sucesiones y donaciones (artículo 631-1 - artículo 634-5) · CAPÍTULO III. Deuda tributaria"},{"n":"CAT","a":"633-2","t":"Tarifa reducida.","x":"1. La cuota íntegra del impuesto sobre sucesiones y donaciones en las transmisiones lucrativas entre vivos a favor de contribuyentes de los grupos I y II que define el artículo 631-2 se obtiene como resultado de aplicar a la base liquidable la siguiente escala:\n| Base liquidable<br>Hasta (euros) | Cuota íntegra (euros) | Resto base liquidable<br>Hasta (euros) | Tipo aplicable (%) |\n| -------------------------------- | --------------------- | -------------------------------------- | ------------------ |\n| 0,00 | 0,00 | 200.000,00 | 5 |\n| 200.000,00 | 10.000,00 | 600.000,00 | 7 |\n| 600.000,00 | 38.000,00 | En adelante | 9 |\n2. Para poder aplicar la tarifa que establece el apartado 1, la donación entre vivos, o el negocio jurídico equiparable, debe haberse formalizado en escritura pública o sentencia judicial. Si la escritura no es requisito de validez, es necesario que el otorgante u otorgantes la eleven a pública:\na) En el plazo de un mes, a contar desde la fecha de entrega del bien.\nb) En el caso del negocio jurídico equiparable, en el plazo de un mes, a contar desde la celebración del negocio.\nLa tarifa establecida por el apartado 1 no es aplicable a los negocios jurídicos a los que se refiere la letra e del artículo 12 del Real decreto 1629/1991, de 8 de noviembre, por el que se aprueba el Reglamento del impuesto sobre sucesiones y donaciones.","u":"#a6-77","c":"TÍTULO III. Impuesto sobre sucesiones y donaciones (artículo 631-1 - artículo 634-5) · CAPÍTULO III. Deuda tributaria"},{"n":"CAT","a":"633-3","t":"Cuota tributaria.","x":"La cuota tributaria por el impuesto sobre sucesiones y donaciones se obtiene aplicando a la cuota íntegra el coeficiente multiplicador que corresponda de los que se indican a continuación, establecidos en función del patrimonio preexistente del contribuyente y del grupo, según el grado de parentesco señalado en el artículo 631-2:\n| Patrimonio preexistente (euros) | Grupos de parentesco | | |\n| ------------------------------- | -------------------- | ------ | ------ |\n| | I y II | III | IV |\n| De 0 a 500.000. | 1,0000 | 1,5882 | 2,0000 |\n| De 500.000,01 a 2.000.000,00. | 1,1000 | 1,5882 | 2,0000 |\n| De 2.000.000,01 a 4.000.000,00. | 1,1500 | 1,5882 | 2,0000 |\n| Más de 4.000.000,00. | 1,2000 | 1,5882 | 2,0000 |","u":"#a6-78","c":"TÍTULO III. Impuesto sobre sucesiones y donaciones (artículo 631-1 - artículo 634-5) · CAPÍTULO III. Deuda tributaria"},{"n":"CAT","a":"633-4","t":"Bonificación de la cuota tributaria.","x":"1. Los cónyuges pueden aplicar una bonificación del 99 % de la cuota tributaria del impuesto sobre sucesiones en las adquisiciones por causa de muerte, incluidas las cantidades percibidas por las personas beneficiarias de seguros de vida que se acumulan al resto de bienes y derechos que integran su porción hereditaria.\n1 bis. Los descendientes y los ascendientes consanguíneos pueden aplicar una bonificación del 99 % de la cuota tributaria del impuesto sobre sucesiones en las adquisiciones por causa de muerte, de una causante víctima de violencia machista, que haya muerto como consecuencia de actos derivados de esta violencia, incluidas las cantidades derivadas de seguros de vida que se acumulan a la porción hereditaria.\nLa condición de víctima de violencia machista se acredita por alguno de los medios de prueba establecidos en la Ley 5/2008, de 24 de abril, del derecho de las mujeres a erradicar la violencia machista.\n2. El resto de contribuyentes de los grupos I y II pueden aplicar la bonificación en el porcentaje medio ponderado que resulte de la aplicación para cada tramo de base imponible de los siguientes porcentajes:\na) Para los contribuyentes del grupo I:\n| Base imponible<br>Hasta (euros) | Bonificación<br>(%) | Resto base imponible<br>Hasta (euros) | Bonificación marginal<br>(%) |\n| ------------------------------- | ------------------- | ------------------------------------- | ---------------------------- |\n| 0,00 | 0,00 | 100.000,00 | 99,00 |\n| 100.000,00 | 99,00 | 100.000,00 | 97,00 |\n| 200.000,00 | 98,00 | 100.000,00 | 95,00 |\n| 300.000,00 | 97,00 | 200.000,00 | 90,00 |\n| 500.000,00 | 94,20 | 250.000,00 | 80,00 |\n| 750.000,00 | 89,47 | 250.000,00 | 70,00 |\n| 1.000.000,00 | 84,60 | 500.000,00 | 60,00 |\n| 1.500.000,00 | 76,40 | 500.000,00 | 50,00 |\n| 2.000.000,00 | 69,80 | 500.000,00 | 40,00 |\n| 2.500.000,00 | 63,84 | 500.000,00 | 25,00 |\n| 3.000.000,00 | 57,37 | En adelante | 20,00 |\nb) Para el resto de contribuyentes del grupo II:\n| Base imponible<br>Hasta (euros) | Bonificación(%) | Resto base imponible<br>Hasta (euros) | Bonificación marginal (%) |\n| ------------------------------- | --------------- | ------------------------------------- | ------------------------- |\n| 0,00 | 0,00 | 100.000,00 | 60,00 |\n| 100.000,00 | 60,00 | 100.000,00 | 55,00 |\n| 200.000,00 | 57,50 | 100.000,00 | 50,00 |\n| 300.000,00 | 55,00 | 200.000,00 | 45,00 |\n| 500.000,00 | 51,00 | 250.000,00 | 40,00 |\n| 750.000,00 | 47,33 | 250.000,00 | 35,00 |\n| 1.000.000,00 | 44,25 | 500.000,00 | 30,00 |\n| 1.500.000,00 | 39,50 | 500.000,00 | 25,00 |\n| 2.000.000,00 | 35,88 | 500.000,00 | 20,00 |\n| 2.500.000,00 | 32,70 | 500.000,00 | 10,00 |\n| 3.000.000,00 | 28,92 | En adelante | 0,00 |\n3. En caso de desmembramiento del dominio, la base imponible a la que se refiere el apartado 2 es la base imponible teórica.\n4. Los contribuyentes de los grupos I y II a los que se refiere el apartado 2 no tienen derecho a la bonificación en caso de que opten por aplicar cualquiera de las siguientes reducciones y exenciones:\na) Las reducciones establecidas por las subsecciones de tercera a décima, salvo la reducción por vivienda habitual establecida por la subsección sexta, que es aplicable en todos los casos.\nb) Las exenciones y reducciones reguladas por la Ley 19/1995, de 4 de julio, de modernización de las explotaciones agrarias.\nc) Cualquier otra reducción de la base imponible o exención que requiera que el contribuyente la solicite y que dependa de la concurrencia de determinados requisitos cuyo cumplimiento corresponda exclusivamente a la voluntad del contribuyente.\n5. El porcentaje medio ponderado resultante debe tener solo dos decimales, de modo que se aproximan las milésimas a la centésima más próxima: si la milésima es igual o inferior a 5, se mantiene la centésima; si es superior a 5, se aproxima a la centésima superior.\n6. La opción a la que se refiere el apartado 4 se entiende ejercida con la presentación de la autoliquidación. Si durante el plazo voluntario de presentación de la autoliquidación el contribuyente manifiesta opciones distintas, se entiende que vale la opción manifestada en último lugar.\nEl derecho de opción no se rehabilita si, como resultado de la comprobación administrativa, se constata que no se pueden aplicar una o más de una de las reducciones o exenciones que especifica el apartado 4. Tampoco se rehabilita si se incumplen las reglas de mantenimiento a las que queda condicionado el disfrute definitivo de las reducciones o exenciones mencionadas.","u":"#a6-79","c":"TÍTULO III. Impuesto sobre sucesiones y donaciones (artículo 631-1 - artículo 634-5) · CAPÍTULO III. Deuda tributaria"},{"n":"CAT","a":"634-1","t":"Tratamiento fiscal de las parejas estables.","x":"1. Los miembros de las parejas estables quedan asimilados a los cónyuges, a efectos del impuesto sobre sucesiones y donaciones.\n2. Para poder disfrutar de la asimilación que establece el apartado 1, el sujeto pasivo ha de acreditar la convivencia en pareja estable, de acuerdo con los requisitos que se establezcan a tal efecto por la normativa reguladora de dichas uniones.","u":"#a6-80","c":"TÍTULO III. Impuesto sobre sucesiones y donaciones (artículo 631-1 - artículo 634-5) · CAPÍTULO IV. Disposiciones comunes aplicables a las adquisiciones por causa de muerte y a las adquisiciones lucrativas entre vivos"},{"n":"CAT","a":"634-2","t":"Relaciones entre un cónyuge o un conviviente en pareja estable y los hijos de su cónyuge o del otro miembro de la pareja.","x":"Las relaciones entre un cónyuge o un conviviente en pareja estable y los hijos de su cónyuge o del otro miembro de la pareja quedan asimiladas, a efectos del impuesto sobre sucesiones y donaciones, a las relaciones entre ascendientes e hijos.","u":"#a6-81","c":"TÍTULO III. Impuesto sobre sucesiones y donaciones (artículo 631-1 - artículo 634-5) · CAPÍTULO IV. Disposiciones comunes aplicables a las adquisiciones por causa de muerte y a las adquisiciones lucrativas entre vivos"},{"n":"CAT","a":"634-3","t":"Acogimiento.","x":"1. Las relaciones entre una persona que esté o haya estado en acogimiento y la persona o personas acogedoras, quedan asimiladas a las relaciones entre hijos y ascendientes, a efectos del impuesto sobre sucesiones y donaciones.\n2. Para poder disfrutar de los beneficios que comporta la asimilación que establece el apartado 1, el acogimiento debe haberse acordado de conformidad con lo que establece la Ley 14/2010, de 27 de mayo, de los derechos y las oportunidades en la infancia y la adolescencia.","u":"#a6-82","c":"TÍTULO III. Impuesto sobre sucesiones y donaciones (artículo 631-1 - artículo 634-5) · CAPÍTULO IV. Disposiciones comunes aplicables a las adquisiciones por causa de muerte y a las adquisiciones lucrativas entre vivos"},{"n":"CAT","a":"634-4","t":"Tratamiento del género en las denominaciones referidas a personas.","x":"Se entiende que las denominaciones en género masculino referidas a personas incluyen mujeres y hombres, salvo que el contexto indique lo contrario.","u":"#a6-83","c":"TÍTULO III. Impuesto sobre sucesiones y donaciones (artículo 631-1 - artículo 634-5) · CAPÍTULO IV. Disposiciones comunes aplicables a las adquisiciones por causa de muerte y a las adquisiciones lucrativas entre vivos"},{"n":"CAT","a":"634-5","t":"Alcance de los conceptos de ascendientes y descendientes.","x":"Las referencias a los conceptos de ascendientes y descendientes se aplican indistintamente, y con los mismos efectos, a los que lo son por naturaleza y a los que lo son por adopción.","u":"#a6-84","c":"TÍTULO III. Impuesto sobre sucesiones y donaciones (artículo 631-1 - artículo 634-5) · CAPÍTULO IV. Disposiciones comunes aplicables a las adquisiciones por causa de muerte y a las adquisiciones lucrativas entre vivos"},{"n":"CAT","a":"681-1","t":"Obligación de envío telemático de los documentos autorizados por los notarios.","x":"En los plazos y las condiciones que se establezcan por reglamento, los notarios están obligados a enviar por vía telemática a la Agencia Tributaria de Cataluña los documentos a que se refieren los artículos 32.3 de la Ley 29/1987, de 18 de diciembre, del impuesto sobre sucesiones y donaciones, y 52 del texto refundido de la Ley del impuesto sobre transmisiones patrimoniales y actos jurídicos documentados, aprobado por el Real decreto legislativo 1/1993, de 24 de septiembre.","u":"#a6-109","c":"TÍTULO VIII. Obligaciones formales y normas de aplicación (artículo 681-1 - artículo 684-2) · CAPÍTULO I. Normas comunes al impuesto sobre transmisiones patrimoniales y actos jurídicos documentados y al impuesto sobre sucesiones y donaciones"},{"n":"CAT","a":"681-2","t":"Envío telemático de los documentos autorizados por los notarios.","x":"1. En relación con lo establecido por el artículo anterior, y con la finalidad de cumplir las obligaciones tributarias de los contribuyentes y facilitar el acceso telemático de los documentos en los registros públicos, los notarios con destino en Cataluña deben enviar por vía telemática, con la colaboración del Consejo General del Notariado, juntamente con la copia de las escrituras que autoricen, una declaración informativa notarial de los elementos básicos de las citadas escrituras, de conformidad con lo que dispone la legislación notarial. El Departamento competente en materia de hacienda ha de determinar los hechos imponibles a que se refiere la declaración informativa y debe establecer los procedimientos, la estructura y los plazos en que debe enviarse esta información.\n2. La presentación de los documentos de los hechos imponibles del impuesto sobre transmisiones patrimoniales y actos jurídicos documentados y del impuesto sobre sucesiones y donaciones no es necesaria, si el notario autorizante ha enviado previamente la declaración informativa de la escritura correspondiente.","u":"#a6-110","c":"TÍTULO VIII. Obligaciones formales y normas de aplicación (artículo 681-1 - artículo 684-2) · CAPÍTULO I. Normas comunes al impuesto sobre transmisiones patrimoniales y actos jurídicos documentados y al impuesto sobre sucesiones y donaciones"},{"n":"CAT","a":"681-3","t":"Acuerdos de valoración previa vinculante.","x":"1. De acuerdo con lo establecido por el artículo 91 de la Ley 58/2003, de 17 de diciembre, general tributario, los contribuyentes por el impuesto sobre sucesiones y donaciones y por el impuesto sobre transmisiones patrimoniales y actos jurídicos documentados pueden solicitar a la Administración tributaria que determine, con carácter previo y vinculante, la valoración de rentas, productos, bienes, gastos y otros elementos del hecho imponible, a los efectos de dichos impuestos.\n2. Los contribuyentes deben presentar la solicitud por escrito antes de que se produzca el hecho imponible y deben adjuntar una propuesta de valoración motivada, firmada por un técnico o técnica con la titulación adecuada según la naturaleza del bien valorado, en la que deben describirse de manera detallada el bien y sus características.\n3. La Administración puede comprobar los elementos de hecho y las circunstancias declaradas por los contribuyentes, a quienes puede requerir los documentos y los datos que considere pertinentes a los efectos de la identificación y la valoración correcta de los bienes.\n4. La Administración debe dictar el acuerdo de valoración por escrito indicando su carácter vinculante, el bien valorado y el impuesto en el que tiene efectos, en el plazo máximo de tres meses desde su solicitud. La falta de contestación de la Administración en el plazo indicado implica la aceptación de los valores propuestos por el contribuyente.\n5. El acuerdo de valoración tiene un plazo máximo de vigencia de dieciocho meses desde la fecha en que se dicta. La Administración tributaria debe aplicar al contribuyente los valores establecidos en este acuerdo, a menos que se modifique la legislación o que cambien de forma significativa las circunstancias económicas que lo fundamentan.\n6. En el supuesto de realización del hecho imponible con anterioridad a la finalización del plazo de tres meses mencionado en el apartado 4 sin que la Administración tributaria haya dictado el acuerdo de valoración, debe considerarse desistida la solicitud de valoración previa.\n7. Contra el acuerdo de valoración no puede interponerse ningún recurso, sin perjuicio de que los contribuyentes puedan hacerlo contra las liquidaciones que, si procede, se emitan con posterioridad.\n8. El Gobierno debe regular por reglamento las normas de procedimiento, las condiciones y los requisitos necesarios para cumplir lo establecido por este artículo.","u":"#a6-111","c":"TÍTULO VIII. Obligaciones formales y normas de aplicación (artículo 681-1 - artículo 684-2) · CAPÍTULO I. Normas comunes al impuesto sobre transmisiones patrimoniales y actos jurídicos documentados y al impuesto sobre sucesiones y donaciones"},{"n":"CAT","a":"682-1","t":"Obligación de declarar y autoliquidar.","x":"1. Los contribuyentes están obligados a presentar y suscribir la declaración del impuesto sobre sucesiones y donaciones, firmada por ellos mismos o por sus representantes, dentro de los plazos y en los términos y las condiciones que se determinen por reglamento.\n2. Al presentar la declaración a que se refiere el apartado 1, los contribuyentes deben determinar la deuda tributaria correspondiente, que deben ingresar en el lugar, la forma y los plazos que se determinen por reglamento.\n3. La presentación de los documentos comprensivos de los hechos imponibles del impuesto sobre sucesiones y donaciones, así como, si procede, el pago de la autoliquidación correspondiente, pueden hacerse por vía telemática. La presentación telemática solo es posible si el notario autorizante ha enviado previamente, también por vía telemática, la declaración informativa de la escritura correspondiente, de acuerdo con el artículo 681-2 y la normativa de despliegue reglamentario correspondiente.","u":"#a6-112","c":"CAPÍTULO II. Obligaciones formales y normas de aplicación en el impuesto sobre sucesiones y donaciones · Sección I. Obligaciones formales"},{"n":"CAT","a":"682-2","t":"Obligación de presentar otros documentos en las transmisiones por causa de muerte.","x":"1. En las transmisiones por causa de muerte, junto con la declaración y la autoliquidación a la que se refiere el artículo 682-1, el sujeto pasivo debe aportar los documentos que sean determinados por reglamento. En todo caso, si solicita la aplicación de las reducciones que establece la sección I del capítulo I del título III, el sujeto pasivo debe adjuntar los documentos que justifiquen el cumplimiento de los requisitos fijados para cada supuesto. Se pueden determinar por reglamento los documentos que como mínimo resulten exigibles a tal efecto.\n2. Sin perjuicio de la obligación del contribuyente de aportar la documentación a que se refiere el apartado 1, la Administración puede pedir, en ejercicio de sus facultades de comprobación e investigación, en el curso del correspondiente procedimiento de gestión o de inspección, cualquier otra documentación que estime necesaria.","u":"#a6-113","c":"CAPÍTULO II. Obligaciones formales y normas de aplicación en el impuesto sobre sucesiones y donaciones · Sección I. Obligaciones formales"},{"n":"CAT","a":"682-3","t":"Obligación de presentar otros documentos en las transmisiones lucrativas entre vivos.","x":"1. En las transmisiones lucrativas entre vivos, junto con la declaración y la autoliquidación a que se refiere el artículo 682-1, el sujeto pasivo, si solicita la aplicación de las reducciones que establece el capítulo II del título III, debe adjuntar los documentos que justifiquen el cumplimiento de los requisitos fijados para cada supuesto. Se pueden determinar por reglamento los documentos que como mínimo resulten exigibles a tal efecto.\n2. Sin perjuicio de la obligación del contribuyente de aportar la documentación a la que se refiere el apartado 1, la Administración puede pedir, en ejercicio de sus facultades de comprobación e investigación, en el curso del correspondiente procedimiento de gestión o de inspección, cualquier otra documentación que estime necesaria.","u":"#a6-114","c":"CAPÍTULO II. Obligaciones formales y normas de aplicación en el impuesto sobre sucesiones y donaciones · Sección I. Obligaciones formales"},{"n":"CAT","a":"682-4","t":"Incumplimiento de la obligación de presentar documentos.","x":"En el supuesto de que la autoliquidación a que se refiere el artículo 682-1 no vaya acompañada de todos los documentos exigidos por reglamento, se considera que se ha presentado de forma incompleta. La Administración tributaria, sin perjuicio de las sanciones que sean procedentes, debe requerir al obligado tributario que enmiende la omisión. Si los documentos no presentados son necesarios para verificar la procedencia de una reducción, la Administración debe advertir al contribuyente que, si no atiende el requerimiento, se denegará la aplicación de la reducción correspondiente.","u":"#a6-115","c":"CAPÍTULO II. Obligaciones formales y normas de aplicación en el impuesto sobre sucesiones y donaciones · Sección I. Obligaciones formales"},{"n":"CAT","a":"682-5","t":"Régimen supletorio.","x":"En todo aquello que no se regula en este capítulo en lo referente a las obligaciones formales con relación al impuesto sobre sucesiones y donaciones, así como en lo referente a los efectos del incumplimiento de tales obligaciones, se aplica la normativa estatal en esta materia.","u":"#a6-116","c":"CAPÍTULO II. Obligaciones formales y normas de aplicación en el impuesto sobre sucesiones y donaciones · Sección I. Obligaciones formales"},{"n":"CAT","a":"682-6","t":"Competencia.","x":"La competencia en materia de gestión, liquidación, inspección y recaudación del impuesto sobre sucesiones y donaciones corresponde a la Agencia Tributaria de Cataluña.","u":"#a6-117","c":"Sección II. Normas de aplicación del tributo · Subsección primera. Liquidación del impuesto"},{"n":"CAT","a":"682-7","t":"Plazo de resolución en los procedimientos de gestión tributaria propios.","x":"1. En los procedimientos de gestión tributaria relativos al impuesto sobre sucesiones y donaciones, el deber de notificación y el cómputo del plazo de resolución se rigen por las reglas que determina el artículo 104.2 de la Ley 58/2003, del 17 de diciembre, general tributaria.\n2. El plazo de resolución de los procedimientos de gestión tributaria propios del impuesto sobre sucesiones y donaciones es de doce meses.\n3. El plazo de resolución que establece el apartado 2 puede ampliarse, con el alcance y los requisitos que se determinen por reglamento, por un nuevo período de como máximo doce meses, si se produce alguna de las circunstancias siguientes:\na) Si las actuaciones revisten una especial complejidad.\nb) Si en el curso de las actuaciones se constata que ha habido ocultación de bienes por parte del obligado tributario.\nc) Si en el curso de las actuaciones se inicia un procedimiento de comprobación de valores.\n4. La especial complejidad a que se refiere la letra a del apartado 3 se determina atendiendo a las circunstancias siguientes:\na) El número de causahabientes o donatarios o la existencia de desavenencias entre ellos, si inciden en la tramitación del procedimiento.\nb) El número de bienes transmitidos respecto a los que los obligados tributarios soliciten la aplicación de la reducción correspondiente entre las que establecen los capítulos I y II del título III, especialmente en el caso de las participaciones en entidades y de la actividad empresarial o profesional del transmitente.\nc) La dispersión geográfica de los bienes o las actividades del transmitente, especialmente en caso de bienes situados fuera del territorio de Catalunya.\nd) Las otras circunstancias que se establezcan por reglamento.\n5. El acuerdo de ampliación a que se refiere el apartado 3 debe adoptarse en todo caso por medio de resolución motivada, que debe exponer los hechos e indicar los fundamentos de derecho.","u":"#a6-118","c":"Sección II. Normas de aplicación del tributo · Subsección primera. Liquidación del impuesto"},{"n":"CAT","a":"682-8","t":"Autoliquidaciones parciales a cuenta.","x":"1. Las personas interesadas en una sucesión hereditaria pueden hacer una autoliquidación parcial del impuesto sobre sucesiones y donaciones, con el único objeto de cobrar seguros sobre la vida, créditos del causante o haberes devengados y no percibidos por este, retirar bienes, valores, efectos o dinero del causante que se encuentren en depósito y otros supuestos análogos. La forma y el plazo de presentación de esta autoliquidación y los requisitos para que las personas interesadas puedan cobrar las cantidades o retirar los bienes en depósito deben regularse por reglamento.\n2. Las autoliquidaciones parciales tienen el carácter de ingresos a cuenta de la autoliquidación o liquidación definitiva correspondiente.","u":"#a6-119","c":"Sección II. Normas de aplicación del tributo · Subsección primera. Liquidación del impuesto"},{"n":"CAT","a":"682-9","t":"Pago del impuesto mediante la entrega de bienes culturales.","x":"El pago de la deuda tributaria por el impuesto de sucesiones y donaciones puede hacerse mediante la entrega de bienes culturales de interés nacional, bienes culturales de interés local y bienes muebles catalogados que hayan sido calificados e inscritos de acuerdo con la Ley 9/1993, de 30 de septiembre, del patrimonio cultural catalán; bienes integrantes del patrimonio histórico o cultural de otras comunidades autónomas que hayan sido calificados e inscritos de acuerdo con la normativa específica correspondiente, y bienes integrantes del patrimonio histórico español que hayan sido inscritos en el Inventario general de bienes muebles o en el Registro general de bienes de interés cultural, de acuerdo con el artículo 69.2 de la Ley 16/1985, de 25 de junio, del patrimonio histórico español.","u":"#a6-120","c":"Sección II. Normas de aplicación del tributo · Subsección segunda. Pago del impuesto"},{"n":"CAT","a":"682-10","t":"Aplazamiento y fraccionamiento del pago. Norma general.","x":"El aplazamiento y el fraccionamiento del pago del impuesto sobre sucesiones y donaciones se rigen por las normas que establece la normativa general sobre recaudación vigente en Cataluña, sin perjuicio de lo dispuesto en los artículos 682-11 a 682-13.","u":"#a6-121","c":"Sección II. Normas de aplicación del tributo · Subsección segunda. Pago del impuesto"},{"n":"CAT","a":"682-11","t":"Aplazamiento y fraccionamiento por los órganos de gestión.","x":"1. Los órganos de la Agencia Tributaria de Cataluña competentes en materia de gestión del impuesto sobre sucesiones y donaciones pueden acordar, a solicitud del contribuyente, un aplazamiento de hasta dos años del pago de las liquidaciones practicadas por causa de muerte, siempre y cuando el inventario de la herencia no comprenda suficiente dinero efectivo o bienes fácilmente realizables para pagar las cuotas liquidadas y siempre que el aplazamiento se solicite antes de que finalice el plazo reglamentario de pago. La concesión del aplazamiento implica la obligación de satisfacer el correspondiente interés de demora.\nEn los mismos supuestos y condiciones, se puede acordar el fraccionamiento del pago, en un máximo de cinco anualidades, siempre y cuando se constituya garantía que cubra el pago de la obligación tributaria principal y de los intereses de demora, más un 25 % de la suma de ambos conceptos.\nEn los supuestos a los que se refiere este apartado, a solicitud de la persona interesada, y siempre y cuando lo autorice la dirección general competente en materia de patrimonio, con el informe previo favorable del departamento o la entidad competente en función del uso del bien inmueble que se ofrece, los mencionados órganos de gestión pueden acordar que el pago se realice mediante bienes inmuebles constitutivos de la herencia.\n2. En las mismas condiciones que establece el apartado 1, y en los términos y con los requisitos que se fijen por reglamento, los órganos de gestión competentes pueden acordar el aplazamiento del pago de las liquidaciones practicadas por causa de muerte hasta que no se hayan conocido los causahabientes de la sucesión, siempre y cuando aporten un compromiso de constitución de aval.\n3. Los órganos de gestión a que se refiere el apartado 1 pueden conceder el aplazamiento y el fraccionamiento de las autoliquidaciones o liquidaciones practicadas por herencia o legado en nuda propiedad, en los términos y con las condiciones que se establezcan por reglamento.","u":"#a6-122","c":"Sección II. Normas de aplicación del tributo · Subsección segunda. Pago del impuesto"},{"n":"CAT","a":"682-12","t":"Fraccionamiento de la liquidación por seguros que se perciben en forma de renta.","x":"1. El pago del impuesto correspondiente a los seguros sobre la vida cuyo importe deba percibirse en forma de renta, tanto si el causante es el contratante del seguro como si se trata de un seguro colectivo, puede fraccionarse en el número de años de percepción de la pensión, si la renta es temporal, o en un número máximo de quince años, si la renta es vitalicia. Este fraccionamiento no comporta la constitución de ningún tipo de caución ni devenga ningún tipo de interés.\n2. El fraccionamiento a que se refiere el apartado 1 queda anulado, si el beneficiario ejerce el derecho de rescate, caso en que le son exigibles los pagos pendientes.\n3. En caso de que la pensión a que se refiere el apartado 1 se extinga durante el período de fraccionamiento del pago del impuesto, los pagos pendientes dejan de ser exigibles.\n4. El procedimiento para aplicar las disposiciones de este artículo se determina por reglamento.","u":"#a6-123","c":"Sección II. Normas de aplicación del tributo · Subsección segunda. Pago del impuesto"},{"n":"CAT","a":"682-13","t":"Otros supuestos especiales.","x":"En los términos y con las condiciones que se establezcan por reglamento, puede acordarse el fraccionamiento o el aplazamiento del pago de las autoliquidaciones y liquidaciones practicadas a raíz de la transmisión por herencia, legado o donación de los bienes a que hacen referencia las subsecciones de tercera a décima de la sección I del capítulo I y las subsecciones primera, segunda, tercera y quinta de la sección única del capítulo II del título III.","u":"#a6-124","c":"Sección II. Normas de aplicación del tributo · Subsección segunda. Pago del impuesto"}]};